window.studyBundle = {"data/catalog.json":{"title":"Finals","version":2,"subjects":[{"id":"finals","name":"Finals","locked":false,"materials":[{"id":"english-finals","title":"English","subtitle":"Question banks not ready yet","locked":false,"draft":false,"finalsEmpty":true,"week":"Week 16-18"},{"id":"medterm-finals","title":"Medical Terminology","subtitle":"Question banks not ready yet","locked":false,"draft":false,"finalsEmpty":true,"week":"Week 16-18"},{"id":"anatomy-finals","title":"Anatomy","subtitle":"Question banks not ready yet","locked":false,"draft":false,"finalsEmpty":true,"week":"Week 16-18"},{"id":"medphys-finals","title":"Medical Physics","subtitle":"Chapters 7–8 (draft)","locked":false,"draft":true,"comingSoon":false,"week":"Week 16-18","lectures":[{"id":"ch7","title":"Chapter 7: Atomic and Nuclear Physics","bank":"banks/medphys/finals/chapter-7-atomic-and-nuclear-physics.json","status":"ready","draft":true},{"id":"ch8","title":"Chapter 8: Electricity and Magnetism","bank":"banks/medphys/finals/chapter-8-electricity-and-magnetism.json","status":"ready","draft":true},{"id":"mixed-ch7","title":"Mixed Chapters","bank":"banks/medphys/finals/mixed-chapters.json","status":"ready","draft":true}],"formulas":{"gen":"FinalsFormulaGen","key":"medphys/finals","title":"Formulas · Finals","scope":"Chapter 7 · Atomic and Nuclear Physics","draft":true}},{"id":"studyskills-finals","title":"Study Skills","subtitle":"Lectures 1-14","locked":false,"draft":false,"comingSoon":false,"lectures":[{"id":"lec1","title":"Lecture 1 – Learning Styles","bank":"banks/studyskills/lecture-1-learning-styles.json","status":"ready","draft":false},{"id":"lec2","title":"Lecture 2 – Goals","bank":"banks/studyskills/lecture-2-goals-remake.json","status":"ready","draft":false},{"id":"lec3","title":"Lecture 3 – Time Management","bank":"banks/studyskills/lecture-3-time-management.json","status":"ready","draft":false},{"id":"lec4","title":"Lecture 4 – Writing and Presentation","bank":"banks/studyskills/lecture-4-writing-presentation-remake.json","status":"ready","draft":false},{"id":"lec5","title":"Lecture 5 – Teamwork and Small Group Learning","bank":"banks/studyskills/lecture-5-teamwork-and-small-group-learning.json","status":"ready","draft":false},{"id":"lec6","title":"Lecture 6 – Adult and Independent Learning","bank":"banks/studyskills/lecture-6-adult-independent-learning.json","status":"ready","draft":false},{"id":"lec7","title":"Lecture 7 – Tips for Good Study Habits","bank":"banks/studyskills/lecture-7-tips-for-studying.json","status":"ready","draft":false},{"id":"lec8","title":"Lecture 8 – Effective Note-Taking Strategies","bank":"banks/studyskills/lecture-8-note-taking-strategies.json","status":"ready","draft":false},{"id":"lec9","title":"Lecture 9 – Boosting Memory and Increasing Concentration","bank":"banks/studyskills/lecture-9-memory-concentration.json","status":"ready","draft":false},{"id":"lec10","title":"Lecture 10 – Strengthening Comprehension","bank":"banks/studyskills/lecture-10-comprehension.json","status":"ready","draft":false},{"id":"lec11","title":"Lecture 11 – Test Preparation and Taking Skills","bank":"banks/studyskills/lecture-11-test-prep.json","status":"ready","draft":false},{"id":"lec12","title":"Lecture 12 – Using Technology in Health Professions Education","bank":"banks/studyskills/lecture-12-tech-health.json","status":"ready","draft":false},{"id":"lec13","title":"Lecture 13 – Medical Student Assessment","bank":"banks/studyskills/lecture-13-medical-student-assessment.json","status":"ready","draft":false},{"id":"lec14","title":"Lecture 14 – Critical Thinking","bank":"banks/studyskills/lecture-14-critical-thinking.json","status":"ready","draft":false},{"id":"mixed-studyskills-lec5-10","title":"Mixed Study Skills – Lectures 5 to 10","bank":"banks/studyskills/mixed-5-10.json","status":"ready","draft":false}],"week":"Week 16-18"}]}]},"banks/medphys/finals/chapter-7-atomic-and-nuclear-physics.json":{"id":"chapter-7-atomic-and-nuclear-physics","subject":"Medical Physics","subjectId":"medphys","title":"Chapter 7: Atomic and Nuclear Physics","source":"Medical Physics question banks chapter-7-atomic-and-nuclear-physics (74)","formSize":74,"forms":["A"],"cards":[{"id":"ch7","title":"Chapter 7: Atomic and Nuclear Physics","cats":["Chapter 7: Electromagnetic Spectrum","Chapter 7: Photon","Chapter 7: Photoelectric Effect","Chapter 7: de Broglie Hypothesis","Chapter 7: Atomic Structure","Chapter 7: Nuclear Radius","Chapter 7: Radioactivity","Chapter 7: Half-Life","Chapter 7: Carbon Dating","Chapter 7: Fission and Fusion","Chapter 7: Dosimetry","Chapter 7: Radiation Detection","Chapter 7: Nuclear Reactions","Chapter 7: Photon and Nuclear Formulas","Chapter 7: Matter Waves","Chapter 7: Nuclear Structure","Chapter 7: Medical Applications"],"draft":true}],"bank":{"A":[{"id":"PHY70001","type":"mcq","cat":"Chapter 7: Electromagnetic Spectrum","q":"Which of the following correctly lists the regions of the electromagnetic spectrum in order of increasing wavelength?","options":["Gamma rays, X-rays, Ultraviolet, Visible, Infrared, Radio waves","Radio waves, Infrared, Visible, Ultraviolet, X-rays, Gamma rays","Gamma rays, X-rays, Infrared, Visible, Ultraviolet, Radio waves","Radio waves, Ultraviolet, Visible, Infrared, X-rays, Gamma rays"],"correct":0,"explain":"Increasing wavelength means going from the shortest wavelengths to the longest. Gamma rays have the shortest wavelengths, followed by X-rays, ultraviolet, visible, infrared, and finally radio waves with the longest wavelengths. The line Radio waves, Infrared, Visible, Ultraviolet, X-rays, Gamma rays reverses the order, listing from longest to shortest. The line Gamma rays, X-rays, Infrared, Visible, Ultraviolet, Radio waves places infrared before visible and ultraviolet, which is incorrect. The line Radio waves, Ultraviolet, Visible, Infrared, X-rays, Gamma rays mixes the order throughout."},{"id":"PHY70002","type":"mcq","cat":"Chapter 7: Electromagnetic Spectrum","q":"The visible portion of the electromagnetic spectrum spans which wavelength range?","options":["Approximately 300 nm to 600 nm","Approximately 400 nm to 700 nm","Approximately 500 nm to 800 nm","Approximately 200 nm to 500 nm"],"correct":1,"explain":"The visible spectrum ranges from about 400 nm at the violet end to about 700 nm at the red end. Violet light has the shortest wavelength in the visible range, and red light has the longest. The other ranges either shift the entire window or place the boundaries at the wrong values."},{"id":"PHY70003","type":"mcq","cat":"Chapter 7: Electromagnetic Spectrum","q":"Which statement correctly describes the relationship between the electric and magnetic fields in an electromagnetic wave?","options":["They are parallel to each other and to the direction of propagation","They are perpendicular to each other and to the direction of propagation","They are perpendicular to each other but parallel to the direction of propagation","They are parallel to each other but perpendicular to the direction of propagation"],"correct":1,"explain":"An electromagnetic wave consists of oscillating electric and magnetic fields that are perpendicular to each other and also perpendicular to the direction in which the wave travels. This transverse configuration is a defining property of all electromagnetic waves. The options that place either field parallel to the propagation direction or parallel to each other contradict this geometry."},{"id":"PHY70004","type":"mcq","cat":"Chapter 7: Photon","q":"A photon is best defined as:","options":["A negatively charged particle emitted by metals","A quantum of electromagnetic radiation","A neutral particle with negligible mass","A positively charged particle in the nucleus"],"correct":1,"explain":"A photon is the elementary amount, or quantum, of electromagnetic radiation. Einstein proposed in 1905 that light is quantized and exists in these discrete packets. A negatively charged particle emitted by metals describes an electron in the photoelectric effect. A neutral particle with negligible mass describes a neutrino. A positively charged particle in the nucleus describes a proton."},{"id":"PHY70005","type":"mcq","cat":"Chapter 7: Photon","q":"The energy E of a photon with frequency f is given by which expression?","options":["E = h / f","E = f / h","E = h × f","E = h + f"],"correct":2,"explain":"The energy of a photon is directly proportional to its frequency, with the constant of proportionality being Planck's constant h. The relation is E = h × f, where h = 6.63 × 10⁻³⁴ J·s. A higher frequency photon carries more energy. The other options either divide by frequency, divide by Planck's constant, or add the two quantities."},{"id":"PHY70006","type":"mcq","cat":"Chapter 7: Photon","q":"An x-ray photon has a frequency of 1.8 × 10¹⁸ s⁻¹. What is its energy? Take h = 6.63 × 10⁻³⁴ J·s.","options":["1.19 × 10⁻¹⁶ J","1.19 × 10⁻¹⁵ J","1.19 × 10⁻¹⁷ J","1.19 × 10⁻¹⁴ J"],"correct":1,"explain":"Using E = h × f, substitute h = 6.63 × 10⁻³⁴ J·s and f = 1.8 × 10¹⁸ s⁻¹. Then E = 6.63 × 10⁻³⁴ × 1.8 × 10¹⁸ = 11.93 × 10⁻¹⁶ J, which is 1.193 × 10⁻¹⁵ J (11.93 × 10⁻¹⁶ J and 1.193 × 10⁻¹⁵ J are the same value). The option 1.19 × 10⁻¹⁶ J is one power of ten too small, 1.19 × 10⁻¹⁷ J is two powers too small, and 1.19 × 10⁻¹⁴ J is one power too big."},{"id":"PHY70007","type":"mcq","cat":"Chapter 7: Photon","q":"The relationship between the frequency f, wavelength λ, and speed c of an electromagnetic wave is:","options":["f = λ / c","f = c × λ","f = c / λ","f = c + λ"],"correct":2,"explain":"For an electromagnetic wave traveling at the speed of light c, the frequency equals the speed divided by the wavelength: f = c / λ. This follows from the general wave equation v = f × λ with v replaced by c. The line f = λ / c inverts the ratio, the line f = c × λ multiplies the two quantities, and the line f = c + λ adds them."},{"id":"PHY70008","type":"mcq","cat":"Chapter 7: Photoelectric Effect","q":"The photoelectric effect occurs when:","options":["Photons eject electrons from a metal surface","Electrons emit photons while dropping a level","A heavy nucleus splits into two lighter ones","Two light nuclei combine into a heavier one"],"correct":0,"explain":"The photoelectric effect is the phenomenon in which photons of sufficient frequency strike a metal surface, collide with valence electrons, and give them enough energy to be liberated from the metal. The line Electrons emit photons while dropping a level describes photon emission by atoms, which is the reverse process. The line A heavy nucleus splits into two lighter ones describes nuclear fission, and the line Two light nuclei combine into a heavier one describes nuclear fusion."},{"id":"PHY70009","type":"mcq","cat":"Chapter 7: Photoelectric Effect","q":"The photoelectric equation relating the incident photon energy, the work function, and the maximum kinetic energy of the emitted electron is:","options":["h f = K_max - φ","h f = K_max + φ","h f = φ - K_max","h f = K_max × φ"],"correct":1,"explain":"The total energy of the incident photon hf is divided between the minimum energy needed to eject the electron from the metal, called the work function φ, and the maximum kinetic energy K_max that the ejected electron can carry away. This gives the photoelectric equation hf = K_max + φ. The line hf = K_max - φ subtracts the work function, the line hf = φ - K_max reverses the subtraction, and the line hf = K_max × φ multiplies the two terms."},{"id":"PHY70010","type":"mcq","cat":"Chapter 7: Photoelectric Effect","q":"The work function φ of a metal is:","options":["The maximum kinetic energy of the emitted electron","The minimum energy required to eject an electron","The total energy of the incident photon","The number of electrons emitted per second"],"correct":1,"explain":"The work function is the minimum amount of energy required to remove an electron from the surface of a particular metal. It is a property of the metal itself. In the photoelectric equation hf = K_max + φ, the work function is the threshold energy that must be overcome. The maximum kinetic energy is K_max, the total photon energy is hf, and the number of emitted electrons per second is the photocurrent."},{"id":"PHY70011","type":"mcq","cat":"Chapter 7: Photoelectric Effect","q":"In the photoelectric equation h f = K_max + φ, the quantity K_max represents:","options":["The minimum energy needed to eject an electron","The maximum kinetic energy of the emitted electron","The total energy carried by the incident photon","The energy lost as heat during the collision"],"correct":1,"explain":"K_max is the maximum kinetic energy that an emitted electron can have after the photon gives up the work function energy to free it from the metal. Some electrons lose additional energy in collisions before escaping, so they emerge with less than K_max, but none can exceed it. The work function φ is the minimum ejection energy, and hf is the total photon energy."},{"id":"PHY90033","type":"saq","cat":"Chapter 7: Photoelectric Effect","q":"Which effect liberates electrons from a metal surface?","answer":"Photoelectric effect","accept":["photoelectric effect"],"explain":"The photoelectric effect is liberation of electrons from a metal surface by sufficiently energetic light."},{"id":"PHY70012","type":"mcq","cat":"Chapter 7: de Broglie Hypothesis","q":"According to the de Broglie hypothesis, a moving particle:","options":["Has only particle nature, with no wave properties","Has both particle nature and wave nature","Has only wave nature, with no particle properties","Has neither particle nor wave properties"],"correct":1,"explain":"De Broglie proposed that any moving object or particle has dual nature, possessing both particle and wave characteristics. The wave associated with a moving particle is called a matter wave. This hypothesis extends the wave-particle duality that was already established for light to all material particles. The line Has only particle nature, with no wave properties denies the wave aspect. The line Has only wave nature, with no particle properties denies the particle aspect. The line Has neither particle nor wave properties denies both."},{"id":"PHY70013","type":"mcq","cat":"Chapter 7: de Broglie Hypothesis","q":"The de Broglie wavelength λ of a particle of mass m moving with velocity v is given by:","options":["λ = m v / h","λ = h / (m v)","λ = h × m × v","λ = h / (m + v)"],"correct":1,"explain":"The de Broglie wavelength is inversely proportional to the momentum p = mv of the particle, with the Planck constant as the constant of proportionality. The relation is λ = h / (m v), which can also be written as λ = h / p. A heavier or faster particle has a shorter de Broglie wavelength. The line λ = m v / h inverts the ratio, the line λ = h × m × v multiplies all three quantities, and the line λ = h / (m + v) adds mass and velocity in the denominator."},{"id":"PHY70014","type":"mcq","cat":"Chapter 7: de Broglie Hypothesis","q":"Matter waves are:","options":["Electromagnetic waves that carry energy but no rest mass","Moving-particle waves, not electromagnetic in nature","Longitudinal mechanical waves in a material medium","Standing waves that form inside the nucleus"],"correct":1,"explain":"Matter waves are the waves associated with moving particles, as proposed by de Broglie. They are explicitly not electromagnetic waves. They do not require a material medium and are not the same as the electromagnetic radiation described by Maxwell. The other options incorrectly classify matter waves as electromagnetic, mechanical, or nuclear standing waves."},{"id":"PHY70015","type":"mcq","cat":"Chapter 7: Atomic Structure","q":"Which statement correctly describes the structure of an atom?","options":["Mostly empty space with a small dense central nucleus","A solid sphere with electrons embedded throughout its volume","A large nucleus that fills nearly all of the atomic volume","A bare nucleus with no surrounding space or electrons"],"correct":0,"explain":"The atom consists mostly of empty space, with a very small and dense nucleus at the center where all of the positive charge and most of the mass are concentrated. Electrons occupy the empty space and revolve around the nucleus. The other options either fill the atom with solid material, make the nucleus too large, or deny the existence of the electron cloud."},{"id":"PHY70016","type":"mcq","cat":"Chapter 7: Atomic Structure","q":"Protons and neutrons are collectively called:","options":["Electrons","Nucleons","Nuclides","Isotopes"],"correct":1,"explain":"Nucleons is the collective term for the protons and neutrons that make up the nucleus. A nuclide refers to a specific type of nucleus characterized by its atomic number and mass number. Isotopes are nuclei with the same atomic number but different neutron numbers. Electrons are not part of the nucleus at all."},{"id":"PHY70017","type":"mcq","cat":"Chapter 7: Atomic Structure","q":"The atomic number Z of a nuclide represents:","options":["The total number of nucleons in the nucleus","The number of protons in the nucleus","The number of neutrons in the nucleus","The sum of protons and neutrons in the nucleus"],"correct":1,"explain":"The atomic number Z is defined as the number of protons in the nucleus. This number determines the chemical element. The total number of nucleons, which is the sum of protons and neutrons, is the mass number A. The number of neutrons is found by subtracting Z from A, giving N = A - Z."},{"id":"PHY70018","type":"mcq","cat":"Chapter 7: Atomic Structure","q":"The mass number A of a nuclide represents:","options":["The number of protons in the nucleus","The number of neutrons in the nucleus","The total number of nucleons in the nucleus","The number of electrons orbiting the nucleus"],"correct":2,"explain":"The mass number A is the total number of nucleons, which means the sum of protons and neutrons in the nucleus. It is not the same as the atomic number Z, which counts only protons. The number of neutrons is found from N = A - Z. The number of electrons in a neutral atom equals Z, not A."},{"id":"PHY70019","type":"mcq","cat":"Chapter 7: Atomic Structure","q":"The neutron number N of a nuclide is calculated as:","options":["N = A + Z","N = A - Z","N = Z - A","N = A × Z"],"correct":1,"explain":"The neutron number is the difference between the mass number and the atomic number: N = A - Z. Since the mass number counts all nucleons and the atomic number counts only protons, subtracting the two gives the number of neutrons. The line N = A + Z adds the two quantities, the line N = Z - A reverses the subtraction, and the line N = A × Z multiplies them."},{"id":"PHY70020","type":"mcq","cat":"Chapter 7: Atomic Structure","q":"Isotopes are nuclei that have:","options":["The same number of neutrons but different numbers of protons","The same number of protons but different numbers of neutrons","The same total number of nucleons but different elements","The same mass number but different atomic numbers"],"correct":1,"explain":"Isotopes are nuclei with the same atomic number Z, meaning the same number of protons, but different neutron numbers N. Because they have the same number of protons, they are the same chemical element. The line The same number of neutrons but different numbers of protons describes isotones. The line The same total number of nucleons but different elements describes isobars. The line The same mass number but different atomic numbers also describes isobars."},{"id":"PHY70021","type":"mcq","cat":"Chapter 7: Atomic Structure","q":"For light nuclides, which condition generally leads to stability?","options":["The neutron number is much larger than the proton number","The neutron number equals the proton number","The proton number is much larger than the neutron number","The neutron number is zero"],"correct":1,"explain":"For light nuclides, the stable configuration is N = Z, meaning the neutron number equals the proton number. A ratio of N/Z = 1 corresponds to stability in lighter elements. Deuterium, with one proton and one neutron, is stable under this rule, while tritium, with one proton and two neutrons, has an N/Z ratio of 2 and is radioactive. The other options describe configurations that lead to instability."},{"id":"PHY70022","type":"mcq","cat":"Chapter 7: Nuclear Radius","q":"The radius r of a nucleus with mass number A is given by which expression?","options":["r = (1.2 × 10⁻¹⁵ m) × A","r = (1.2 × 10⁻¹⁵ m) × A^(1/3)","r = (1.2 × 10⁻¹⁵ m) × A^(1/2)","r = (1.2 × 10⁻¹⁵ m) × A²"],"correct":1,"explain":"Measurements from high-energy electron scattering show that the nuclear radius varies with the cube root of the mass number: r = (1.2 × 10⁻¹⁵ m) × A^(1/3). The constant 1.2 × 10⁻¹⁵ m is an empirical value. The line r = (1.2 × 10⁻¹⁵ m) × A makes the radius proportional to A directly, the line r = (1.2 × 10⁻¹⁵ m) × A^(1/2) uses a square root, and the line r = (1.2 × 10⁻¹⁵ m) × A² uses a square."},{"id":"PHY70023","type":"mcq","cat":"Chapter 7: Nuclear Radius","q":"What is the approximate radius of a ⁶⁴Cu₂₉ nucleus? Take R₀ = 1.2 × 10⁻¹⁵ m.","options":["4.8 × 10⁻¹⁵ m","3.0 × 10⁻¹⁵ m","7.7 × 10⁻¹⁵ m","1.2 × 10⁻¹⁵ m"],"correct":0,"explain":"Using r = R₀ × A^(1/3) with A = 64, the cube root of 64 is 4. Substituting gives r = 1.2 × 10⁻¹⁵ × 4 = 4.8 × 10⁻¹⁵ m. The option 3.0 × 10⁻¹⁵ m uses A = 16, 7.7 × 10⁻¹⁵ m uses A = 256, and 1.2 × 10⁻¹⁵ m uses A = 1."},{"id":"PHY70024","type":"mcq","cat":"Chapter 7: Radioactivity","q":"Radioactivity is best defined as:","options":["The spontaneous decay of unstable atomic nuclei","The absorption of neutrons by stable nuclei","The emission of light from excited atoms","The collision of two nuclei at high speed"],"correct":0,"explain":"Radioactivity is the spontaneous process in which unstable atomic nuclei disintegrate into more stable nuclei, emitting energy and/or ionizing radiation such as alpha, beta, and gamma rays. The process is random and is not influenced by external conditions. The other options describe neutron capture, atomic emission spectra, and nuclear collisions, which are different phenomena."},{"id":"PHY70025","type":"mcq","cat":"Chapter 7: Radioactivity","q":"An alpha particle consists of:","options":["Two protons and one neutron","One proton and two neutrons","Two protons and two neutrons","One proton and one neutron"],"correct":2,"explain":"An alpha particle consists of two protons and two neutrons, which makes it identical to a helium-4 nucleus. It carries a positive charge of +2e and has a relatively large mass. The other options describe combinations that do not correspond to an alpha particle or to any common emitted particle."},{"id":"PHY70026","type":"mcq","cat":"Chapter 7: Radioactivity","q":"When a nucleus emits an alpha particle, what happens to its atomic number Z and mass number A?","options":["Z decreases by 2, and A decreases by 4","Z increases by 2, and A increases by 4","Z decreases by 4, and A decreases by 2","Z remains the same, and A decreases by 4"],"correct":0,"explain":"An alpha particle carries away two protons and two neutrons from the nucleus. Because the atomic number counts protons, Z decreases by 2. Because the mass number counts all nucleons, A decreases by 4. Charge and nucleon number are conserved overall when the alpha particle is included on the product side. The line Z increases by 2, and A increases by 4 would require the nucleus to gain nucleons rather than lose them. The line Z decreases by 4, and A decreases by 2 swaps the changes. The line Z remains the same, and A decreases by 4 does not remove the protons."},{"id":"PHY70027","type":"mcq","cat":"Chapter 7: Radioactivity","q":"When a nucleus undergoes beta minus decay, what happens to its atomic number Z and mass number A?","options":["Z decreases by 1, and A remains the same","Z increases by 1, and A remains the same","Z remains the same, and A increases by 1","Z decreases by 2, and A decreases by 4"],"correct":1,"explain":"In beta minus decay, a neutron converts into a proton while emitting an electron and an antineutrino. Because a proton is created, the atomic number Z increases by 1. The total number of nucleons does not change, so A remains the same. The line Z decreases by 1, and A remains the same describes beta plus decay. The line Z remains the same, and A increases by 1 does not match. The line Z decreases by 2, and A decreases by 4 describes alpha decay."},{"id":"PHY70028","type":"mcq","cat":"Chapter 7: Radioactivity","q":"When a nucleus undergoes beta plus decay, what happens to its atomic number Z and mass number A?","options":["Z increases by 1, and A remains the same","Z decreases by 1, and A remains the same","Z remains the same, and A decreases by 1","Z decreases by 2, and A decreases by 4"],"correct":1,"explain":"In beta plus decay, a proton converts into a neutron while emitting a positron and a neutrino. Because a proton is lost, the atomic number Z decreases by 1. The total number of nucleons does not change, so A remains the same. The line Z increases by 1, and A remains the same describes beta minus decay. The line Z decreases by 2, and A decreases by 4 describes alpha decay. The remaining line does not match beta plus."},{"id":"PHY70029","type":"mcq","cat":"Chapter 7: Radioactivity","q":"In beta decay, one type of nucleon converts into the other type. What is the consequence for the nucleon number?","options":["The nucleon number increases by 1","The nucleon number decreases by 1","The nucleon number remains unchanged","The nucleon number doubles"],"correct":2,"explain":"In beta decay, a neutron becomes a proton in beta minus decay, or a proton becomes a neutron in beta plus decay. In both cases, the total count of nucleons stays the same because one nucleon is simply changing type. The mass number A therefore remains unchanged. Only the atomic number Z changes, by plus one for beta minus or minus one for beta plus."},{"id":"PHY70030","type":"mcq","cat":"Chapter 7: Radioactivity","q":"Which statement correctly describes gamma radiation?","options":["A stream of helium nuclei with a positive charge","A stream of fast electrons with a negative charge","High-energy photons with no mass and no charge","A stream of neutral particles with a small mass"],"correct":2,"explain":"Gamma rays are high-energy photons (electromagnetic radiation). They have no rest mass and no electric charge, so they are not bent by electric or magnetic fields. A stream of helium nuclei with a positive charge describes alpha particles. A stream of fast electrons with a negative charge describes beta minus particles. A stream of neutral particles with a small mass describes neutrinos or neutrons, not gamma rays."},{"id":"PHY70031","type":"mcq","cat":"Chapter 7: Radioactivity","q":"Which comparison of the three types of nuclear radiation is correct?","options":["Alpha particles have the highest penetration and lowest ionizing power","Beta particles have the lowest penetration and highest ionizing power","Gamma rays have the highest penetration and lowest ionizing power","Gamma rays have the lowest penetration and highest ionizing power"],"correct":2,"explain":"Alpha particles are massive and carry a double positive charge, which gives them a very short range and the highest ionizing power. Beta particles are lighter and have intermediate range and ionizing power. Gamma rays are electromagnetic radiation with no charge and no rest mass, so they interact weakly and have the greatest penetrating power but the lowest ionizing power. The other options reverse these relationships."},{"id":"PHY70032","type":"mcq","cat":"Chapter 7: Radioactivity","q":"In a magnetic field, how do alpha, beta, and gamma radiations behave?","options":["All three are bent in the same direction","Alpha and beta bend in opposite directions, and gamma is not bent","Alpha and gamma bend in opposite directions, and beta is not bent","Beta and gamma bend in opposite directions, and alpha is not bent"],"correct":1,"explain":"Alpha particles carry a positive charge, and beta particles carry a negative charge, so they are deflected in opposite directions when passing through a magnetic field. Gamma rays are electrically neutral, so they pass through without being deflected at all. This difference in deflection is a standard way to distinguish the three types of radiation."},{"id":"PHY70033","type":"mcq","cat":"Chapter 7: Radioactivity","q":"The activity R of a radioactive sample is related to the number of radioactive nuclei N by which expression?","options":["R = N / λ","R = λ / N","R = λ × N","R = λ + N"],"correct":2,"explain":"The activity is the rate at which nuclei decay. Since each nucleus has a fixed probability per unit time of decaying, the total decay rate is the decay constant multiplied by the number of radioactive nuclei present: R = λ × N. This means a sample with more nuclei or a larger decay constant will have higher activity."},{"id":"PHY70034","type":"mcq","cat":"Chapter 7: Half-Life","q":"The half-life of a radioactive material is:","options":["The time required for the activity to double","The time required for half the nuclei to decay","The time required for all the nuclei to decay","The time required for a quarter of the nuclei to decay"],"correct":1,"explain":"The half-life T₁/₂ is the time it takes for half of the radioactive nuclei in a sample to decay, so the amount (and the activity) falls to one half. After two half-lives one quarter is left, after three one eighth. Activity doubling never happens in decay, all the nuclei never decay in one half-life, and a quarter decaying is not the definition."},{"id":"PHY70035","type":"mcq","cat":"Chapter 7: Half-Life","q":"The relationship between the half-life T₁/₂ and the decay constant λ is:","options":["T₁/₂ = λ / 0.693","T₁/₂ = 0.693 / λ","T₁/₂ = 0.693 × λ","T₁/₂ = λ + 0.693"],"correct":1,"explain":"The half-life and the decay constant are inversely related: T₁/₂ = ln 2 / λ = 0.693 / λ. A larger decay constant means the nuclei decay faster, so the half-life is shorter. The line T₁/₂ = λ / 0.693 inverts the ratio, T₁/₂ = 0.693 × λ multiplies instead of dividing, and T₁/₂ = λ + 0.693 adds the two."},{"id":"PHY70036","type":"mcq","cat":"Chapter 7: Half-Life","q":"The half-life of a radioactive material is 30 years. What is its decay constant?","options":["7.32 × 10⁻¹⁰ s⁻¹","7.32 × 10⁻⁹ s⁻¹","7.32 × 10⁻¹¹ s⁻¹","7.32 × 10⁻⁸ s⁻¹"],"correct":0,"explain":"First convert the half-life to seconds: 30 years × 3.156 × 10⁷ s/year = 9.467 × 10⁸ s. Then λ = 0.693 / T₁/₂ = 0.693 / (9.467 × 10⁸) = 7.32 × 10⁻¹⁰ s⁻¹. The other options place the decimal in the wrong position relative to this value."},{"id":"PHY70037","type":"mcq","cat":"Chapter 7: Half-Life","q":"A radioactive material has a half-life of 15 days. If you start with 1 g of the material, how much is left after two half-lives?","options":["0.50 g","0.25 g","0.125 g","0.0625 g"],"correct":1,"explain":"After one half-life, half of the original 1 g remains, which is 0.50 g. After a second half-life, half of that remaining amount decays, leaving 0.25 g. The line 0.50 g is the amount after one half-life, the line 0.125 g is after three, and the line 0.0625 g is after four half-lives."},{"id":"PHY70038","type":"mcq","cat":"Chapter 7: Half-Life","q":"The SI unit of activity is the becquerel, defined as:","options":["One joule per kilogram","One decay event per second","One gray multiplied by RBE","One curie divided by 3.70 × 10¹⁰"],"correct":1,"explain":"The becquerel is the SI unit of activity. One becquerel equals one nuclear decay event per second. The line One joule per kilogram defines the gray, the unit of absorbed dose. The line One gray multiplied by RBE defines the sievert, the unit of dose equivalent. The line One curie divided by 3.70 × 10¹⁰ expresses the inverse of the curie-to-becquerel conversion."},{"id":"PHY70039","type":"mcq","cat":"Chapter 7: Half-Life","q":"One curie is equal to how many becquerels?","options":["3.70 × 10⁸ Bq","3.70 × 10⁹ Bq","3.70 × 10¹⁰ Bq","3.70 × 10¹¹ Bq"],"correct":2,"explain":"The curie is an older unit of activity that equals 3.70 × 10¹⁰ decay events per second. Since one becquerel is one decay per second, the conversion is 1 Ci = 3.70 × 10¹⁰ Bq. The other options place the decimal one or two positions away from this value."},{"id":"PHY70040","type":"mcq","cat":"Chapter 7: Carbon Dating","q":"Carbon dating uses the radioactive isotope C-14, which has a half-life of approximately:","options":["5,730 years","573 years","57,300 years","57 years"],"correct":0,"explain":"Carbon-14 has a half-life of 5,730 years, which makes it suitable for dating historical and archaeological materials up to about 60,000 years old. The other values are either ten times shorter, ten times longer, or one hundred times shorter than the correct half-life."},{"id":"PHY70041","type":"mcq","cat":"Chapter 7: Carbon Dating","q":"While an organism is alive, the ratio of carbon-14 to carbon-12 in its tissues remains constant because:","options":["The tissue continually exchanges carbon with its surroundings","The half-life of carbon-14 slows down inside living tissue","The body produces carbon-14 by internal nuclear reactions","Carbon-12 decays into carbon-14 at the same rate"],"correct":0,"explain":"Living organisms constantly exchange carbon with their environment through processes such as respiration and feeding. This keeps the ratio of C-14 to C-12 at the atmospheric value of about 1 to 10¹². Once the organism dies, the exchange stops, and the C-14 begins to decay without replacement. The other options describe mechanisms that do not occur."},{"id":"PHY90041","type":"saq","cat":"Chapter 7: Carbon Dating","q":"Which carbon isotope is used in dating?","answer":"Carbon-14","accept":["C14","¹⁴C"],"explain":"Carbon dating uses the radioactive isotope carbon-14."},{"id":"PHY90042","type":"saq","cat":"Chapter 7: Carbon Dating","q":"What is the half-life of carbon-14 in years?","answer":"5730","accept":[],"explain":"Carbon-14 has a half-life of 5730 years."},{"id":"PHY70042","type":"mcq","cat":"Chapter 7: Fission and Fusion","q":"Nuclear fission is best described as:","options":["Two light nuclei joining into a single heavier nucleus","A heavy nucleus splitting and releasing energy","An electron jumping between atomic energy levels","A photon ejecting an electron from a metal surface"],"correct":1,"explain":"Nuclear fission occurs when a heavy nucleus, such as uranium or plutonium, absorbs a neutron and splits into two lighter nuclei. The process releases free neutrons, gamma rays, and a large amount of energy. The line Two light nuclei joining into a single heavier nucleus describes nuclear fusion. The line An electron jumping between atomic energy levels describes an atomic process. The line A photon ejecting an electron from a metal surface describes the photoelectric effect."},{"id":"PHY70043","type":"mcq","cat":"Chapter 7: Fission and Fusion","q":"Nuclear fusion is best described as:","options":["A heavy nucleus splitting apart into lighter nuclei","Two light nuclei joining into a heavier nucleus","A neutron converting into a proton plus electron","An atom absorbing a photon and losing an electron"],"correct":1,"explain":"Nuclear fusion occurs when two or more light nuclei combine to form a single heavier nucleus with a higher atomic number. This process releases energy and occurs naturally in stars and the sun. The line A heavy nucleus splitting apart into lighter nuclei describes nuclear fission. The line A neutron converting into a proton plus electron describes beta decay. The line An atom absorbing a photon and losing an electron describes the photoelectric effect."},{"id":"PHY70044","type":"mcq","cat":"Chapter 7: Dosimetry","q":"Absorbed dose is defined as:","options":["The rate at which nuclear transformations occur","The energy deposited by ionizing radiation per unit mass","The product of absorbed dose and a radiation weighting factor","The number of ion pairs produced in a detector per second"],"correct":1,"explain":"Absorbed dose is the energy given by ionizing radiation to a unit mass of absorbing material. It depends on the properties of the absorbing material. The SI unit is the gray, where 1 Gy equals 1 joule per kilogram. The line The rate at which nuclear transformations occur defines activity. The line The product of absorbed dose and a radiation weighting factor defines dose equivalent. The line The number of ion pairs produced in a detector per second describes a detector response rather than a dose."},{"id":"PHY70045","type":"mcq","cat":"Chapter 7: Dosimetry","q":"One gray of absorbed dose is equivalent to:","options":["One joule of energy absorbed per kilogram of material","One hundred joules of energy absorbed per kilogram of material","One joule of energy absorbed per gram of material","One thousand joules of energy absorbed per kilogram of material"],"correct":0,"explain":"The gray is defined as one joule of radiation energy absorbed per kilogram of absorbing material: 1 Gy = 1 J/kg. It is also equal to 100 rad, where one rad is 0.01 J/kg. The line One hundred joules of energy absorbed per kilogram of material describes 100 Gy. The line One joule of energy absorbed per gram of material describes a dose in J/g which is 1000 Gy. The line One thousand joules of energy absorbed per kilogram of material describes 1000 Gy."},{"id":"PHY70046","type":"mcq","cat":"Chapter 7: Dosimetry","q":"The dose equivalent is calculated as:","options":["Absorbed dose divided by the radiation weighting factor","Absorbed dose multiplied by the radiation weighting factor","Absorbed dose added to the radiation weighting factor","Absorbed dose minus the radiation weighting factor"],"correct":1,"explain":"The dose equivalent accounts for the biological effectiveness of different types of radiation. It is the product of the absorbed dose and a dimensionless radiation weighting factor, also called the quality factor or RBE. If the absorbed dose is in gray, the result is in sieverts. If the absorbed dose is in rad, the result is in rem."},{"id":"PHY70047","type":"mcq","cat":"Chapter 7: Dosimetry","q":"One sievert of dose equivalent is equal to how many rem?","options":["1 rem","10 rem","100 rem","1000 rem"],"correct":2,"explain":"The sievert is the SI unit of dose equivalent, and the rem is the older unit. The conversion is 1 Sv = 100 rem. This mirrors the relationship between the gray and the rad, where 1 Gy = 100 rad. Because the weighting factor is dimensionless, the conversion factor between Sv and rem is the same as that between Gy and rad."},{"id":"PHY70048","type":"mcq","cat":"Chapter 7: Dosimetry","q":"For X-rays and gamma rays, the radiation weighting factor QF is:","options":["1","3","10","20"],"correct":0,"explain":"The quality factor for X-rays and gamma rays is 1. This means that for these radiations, the absorbed dose in gray is numerically equal to the dose equivalent in sieverts. Beta particles also have a quality factor of approximately 1. Slow neutrons have a factor of about 3, fast neutrons up to 10, and alpha particles and heavy ions up to 20."},{"id":"PHY70049","type":"mcq","cat":"Chapter 7: Dosimetry","q":"A patient receives an absorbed dose of 0.02 Gy from X-rays. What is the equivalent dose in sieverts? Take QF = 1.","options":["0.002 Sv","0.02 Sv","0.2 Sv","2.0 Sv"],"correct":1,"explain":"The equivalent dose is the absorbed dose multiplied by the quality factor. For X-rays, QF equals 1, so the equivalent dose is 0.02 Gy × 1 = 0.02 Sv, which is 20 mSv. The other options place the decimal in the wrong position."},{"id":"PHY70050","type":"mcq","cat":"Chapter 7: Radiation Detection","q":"A Geiger-Muller counter operates by:","options":["Collecting ions formed when radiation ionizes gas","Measuring the temperature rise from absorbed radiation","Recording the light given off by a struck crystal","Detecting the deflection of particles by a magnet"],"correct":0,"explain":"The Geiger-Muller counter is a gas ionization counter. It consists of a metallic tube filled with a gas such as helium or argon, with a wire anode at the center and the tube wall as cathode. When radiation enters through a thin window, it ionizes the gas, and the resulting electrons and positive ions move toward the electrodes, producing a current pulse that is registered as a click or a count."},{"id":"PHY70051","type":"mcq","cat":"Chapter 7: Radiation Detection","q":"A drawback of the Geiger-Muller counter is that:","options":["It cannot detect alpha particles when they are present","It cannot identify the type or energy of the radiation","It requires liquid nitrogen to keep the gas cooled","It can only operate inside a perfect vacuum tube"],"correct":1,"explain":"Although the Geiger-Muller counter is sensitive and can detect alpha, beta, and gamma radiation, it does not provide information about the energy of the radiation or its type. All interactions produce the same type of output pulse. More sophisticated detectors are needed when energy discrimination or particle identification is required."},{"id":"PHY90040","type":"saq","cat":"Chapter 7: Radiation Detection","q":"Which counter uses gas ionization and high voltage?","answer":"GM counter","accept":["Geiger counter","GM Counter","Geiger-Muller counter"],"explain":"A GM counter is a gas ionization counter operating at high voltage."},{"id":"PHY70052","type":"mcq","cat":"Chapter 7: Nuclear Reactions","q":"In a fission reaction, a uranium-235 nucleus absorbs a neutron and splits. Which of the following is a possible pair of daughter nuclei?","options":["Xenon-140 and Strontium-94","Helium-4 and Radon-222","Deuterium and Tritium","Carbon-14 and Nitrogen-14"],"correct":0,"explain":"One common fission pathway for uranium-235 is the production of xenon-140 and strontium-94, along with two or three free neutrons and gamma rays. The line Helium-4 and Radon-222 describes an alpha decay product pair, not fission fragments. The line Deuterium and Tritium lists hydrogen isotopes involved in fusion. The line Carbon-14 and Nitrogen-14 lists carbon and nitrogen isotopes associated with beta decay and carbon dating."},{"id":"PHY70053","type":"mcq","cat":"Chapter 7: Nuclear Reactions","q":"Which of the following is a fusion reaction?","options":["²³⁵U₉₂ + n → ¹⁴⁰Xe₅₄ + ⁹⁴Sr₃₈ + 2n","²H₁ + ²H₁ → ³H₁ + ¹H₁ + 4.0 MeV","²³⁸U₉₂ → ²³⁴Th₉₀ + ⁴He₂","¹⁴C₆ → ¹⁴N₇ + e⁻ + ν"],"correct":1,"explain":"Fusion is the combination of two light nuclei into a heavier nucleus. The reaction ²H₁ + ²H₁ → ³H₁ + ¹H₁ is a fusion reaction between two deuterium nuclei. The line ²³⁵U₉₂ + n → ¹⁴⁰Xe₅₄ + ⁹⁴Sr₃₈ + 2n is a fission reaction. The line ²³⁸U₉₂ → ²³⁴Th₉₀ + ⁴He₂ is alpha decay, and the line ¹⁴C₆ → ¹⁴N₇ + e⁻ + ν is beta decay. These are all nuclear processes, but only the deuterium reaction is fusion."},{"id":"PHY70054","type":"matching","cat":"Chapter 7: Radioactivity","q":"Match each property to the type of nuclear radiation it describes.","leftItems":[{"id":"1","text":"Two protons and two neutrons bound together"},{"id":"2","text":"A fast-moving electron or positron"},{"id":"3","text":"High-energy electromagnetic radiation"},{"id":"4","text":"Carries a positive charge of plus two"},{"id":"5","text":"Carries a negative charge of minus one"},{"id":"6","text":"Carries no electric charge"},{"id":"7","text":"Greatest ionizing power and shortest range"},{"id":"8","text":"Intermediate ionizing power and intermediate range"},{"id":"9","text":"Lowest ionizing power and greatest penetrating power"}],"rightItems":[{"id":"A","text":"Alpha particle"},{"id":"B","text":"Beta particle"},{"id":"C","text":"Gamma ray"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"A","5":"B","6":"C","7":"A","8":"B","9":"C"},"explain":"Alpha particles are helium-4 nuclei, carrying two protons and two neutrons and a charge of plus two. Their large mass and double charge make them strongly ionizing but easily stopped, so they have the shortest range. Beta particles are fast electrons or positrons, carrying a single negative or positive charge, with intermediate mass, intermediate ionizing power, and intermediate range. Gamma rays are high-energy photons with no mass and no charge, so they interact weakly and have the lowest ionizing power but the greatest penetrating power."},{"id":"PHY70055","type":"matching","cat":"Chapter 7: Radioactivity","q":"Match each type of nuclear decay to its effect on the atomic number Z and the mass number A.","leftItems":[{"id":"1","text":"Alpha decay"},{"id":"2","text":"Beta minus decay"},{"id":"3","text":"Beta plus decay"}],"rightItems":[{"id":"A","text":"Z falls by two, A falls by four"},{"id":"B","text":"Z rises by one, A unchanged"},{"id":"C","text":"Z falls by one, A unchanged"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"In alpha decay, the nucleus emits two protons and two neutrons, so the atomic number decreases by two and the mass number decreases by four. In beta minus decay, a neutron becomes a proton, so the atomic number increases by one while the mass number stays the same because the total count of nucleons is unchanged. In beta plus decay, a proton becomes a neutron, so the atomic number decreases by one while the mass number again stays the same."},{"id":"PHY70056","type":"matching","cat":"Chapter 7: Dosimetry","q":"Match each unit of radiation measurement to its correct definition.","leftItems":[{"id":"1","text":"Becquerel"},{"id":"2","text":"Gray"},{"id":"3","text":"Sievert"},{"id":"4","text":"Curie"},{"id":"5","text":"Rad"},{"id":"6","text":"Rem"}],"rightItems":[{"id":"A","text":"One decay event per second"},{"id":"B","text":"One joule absorbed per kilogram of material"},{"id":"C","text":"Absorbed dose multiplied by the quality factor, in SI"},{"id":"D","text":"Three point seven times ten to the tenth decays per second"},{"id":"E","text":"One hundredth of a joule absorbed per kilogram"},{"id":"F","text":"The older unit equal to one hundredth of a sievert"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"The becquerel is the SI unit of activity and equals one decay event per second. The gray is the SI unit of absorbed dose and equals one joule per kilogram. The sievert is the SI unit of dose equivalent and equals the absorbed dose multiplied by the radiation weighting factor. The curie is the older unit of activity, equal to three point seven times ten to the tenth decays per second. The rad is the older unit of absorbed dose, equal to one hundredth of a joule per kilogram. The rem is the older unit of dose equivalent and equals one hundredth of a sievert."},{"id":"PHY90037","type":"saq","cat":"Chapter 7: Dosimetry","q":"What is the SI symbol for absorbed dose?","answer":"Gy","accept":[],"explain":"Absorbed dose is measured in gray, symbol Gy, where 1 Gy = 1 J/kg."},{"id":"PHY90038","type":"saq","cat":"Chapter 7: Dosimetry","q":"What is the SI symbol for dose equivalent?","answer":"Sv","accept":[],"explain":"Dose equivalent is measured in sievert, symbol Sv."},{"id":"PHY90039","type":"saq","cat":"Chapter 7: Dosimetry","q":"Which older unit symbol is used for dose equivalent?","answer":"rem","accept":[],"explain":"The older dose-equivalent unit is the rem, and 1 Sv = 100 rem."},{"id":"PHY70057","type":"matching","cat":"Chapter 7: Photon and Nuclear Formulas","q":"Match each formula to the quantity it defines or the relationship it expresses.","leftItems":[{"id":"1","text":"E = h × f"},{"id":"2","text":"f = c / λ"},{"id":"3","text":"λ = h / (m v)"},{"id":"4","text":"h f = K_max + φ"},{"id":"5","text":"r = R₀ A^(1/3)"},{"id":"6","text":"T₁/₂ = 0.693 / λ"}],"rightItems":[{"id":"A","text":"Relates the energy of a photon to its frequency"},{"id":"B","text":"Relates the frequency of light to its wavelength and speed"},{"id":"C","text":"Gives the de Broglie wavelength of a moving particle"},{"id":"D","text":"Relates incident photon energy, work function, and maximum kinetic energy"},{"id":"E","text":"Gives the radius of a nucleus from its mass number"},{"id":"F","text":"Relates the half-life of a radionuclide to its decay constant"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"The relation E = h × f gives the energy of a single photon from its frequency. The relation f = c / λ connects the frequency of an electromagnetic wave to its wavelength and to the speed of light. The relation λ = h / (m v) gives the de Broglie wavelength of a particle of mass m moving with velocity v. The photoelectric equation h f = K_max + φ relates the incident photon energy to the work function of the metal and the maximum kinetic energy of the emitted electron. The relation r = R₀ A^(1/3) gives the radius of a nucleus from its mass number. The relation T₁/₂ = 0.693 / λ links the half-life of a radionuclide to its decay constant."},{"id":"PHY90032","type":"saq","cat":"Chapter 7: Photon and Nuclear Formulas","q":"Which constant relates photon energy to frequency?","answer":"Planck constant","accept":["Planck","Planck's constant","planck constant","h"],"explain":"Photon energy is E = hf, where h is Planck constant."},{"id":"PHY70058","type":"mcq","cat":"Chapter 7: de Broglie Hypothesis","q":"A proton of mass 1.67 × 10⁻²⁷ kg moves at 1.3 × 10⁶ m/s. With h = 6.63 × 10⁻³⁴ J·s, what is its de Broglie wavelength?","options":["3.05 × 10⁻¹³ m","3.05 × 10⁻⁷ m","2.17 × 10⁻²¹ m","5.16 × 10⁻¹³ m"],"correct":0,"explain":"The de Broglie wavelength is λ = h / (m v). The momentum is (1.67 × 10⁻²⁷) × (1.3 × 10⁶) = 2.17 × 10⁻²¹ kg·m/s. Dividing h by that momentum gives 3.05 × 10⁻¹³ m. The line 3.05 × 10⁻⁷ m drops the 10⁶ in the speed. The line 2.17 × 10⁻²¹ m is the momentum itself, not the wavelength. The line 5.16 × 10⁻¹³ m does not come from h / (m v) with these values."},{"id":"PHY70059","type":"mcq","cat":"Chapter 7: de Broglie Hypothesis","q":"A 20 gram steel ball moves at 20 m/s. Why is its de Broglie wavelength of no practical size?","options":["λ = h / (m v) is about 1.7 × 10⁻³³ m, far below nuclear sizes.","λ = h m v is about 1.7 × 10⁻³ m, comparable to visible light.","λ = h / (m v) is about 1.7 × 10⁻¹⁰ m, comparable to an atom.","A macroscopic object has no de Broglie wavelength, because the relation applies only to electrons."],"correct":0,"explain":"With m = 0.020 kg and v = 20 m/s, m v = 0.40, so λ = h / (m v) is about 1.66 × 10⁻³³ m. That is far smaller than a nucleus, so the wave character is not seen. The line λ = h m v is about 1.7 × 10⁻³ m multiplies by momentum instead of dividing. The line λ = h / (m v) is about 1.7 × 10⁻¹⁰ m would require a much smaller momentum. The line A macroscopic object has no de Broglie wavelength denies the general relation."},{"id":"PHY70060","type":"mcq","cat":"Chapter 7: Radioactivity","q":"Uranium-238 emits one alpha particle and then one beta minus particle. What is the daughter?","options":["Protactinium-234","Thorium-234","Uranium-234","Radium-230"],"correct":0,"explain":"The alpha particle takes A from 238 to 234 and Z from 92 to 90, giving thorium-234. The following beta minus decay leaves A at 234 and raises Z from 90 to 91, giving protactinium-234. The line Thorium-234 stops after the alpha particle. The line Uranium-234 would require beta minus to restore Z to 92, which it does not. The line Radium-230 would require two alpha particles."},{"id":"PHY90035","type":"saq","cat":"Chapter 7: Radioactivity","q":"Which decay emits a helium nucleus?","answer":"Alpha decay","accept":["alpha decay","α decay"],"explain":"Alpha decay emits an alpha particle, which is a helium nucleus."},{"id":"PHY90036","type":"saq","cat":"Chapter 7: Radioactivity","q":"Which neutral particle has negligible mass in beta decay?","answer":"Neutrino","accept":["neutrino","ν"],"explain":"The neutrino is neutral, has negligible mass, and interacts weakly with matter."},{"id":"PHY70061","type":"mcq","cat":"Chapter 7: Nuclear Radius","q":"What is the ratio of the radii (R1:R2) of two nuclei whose mass numbers are 27 and 64?","options":["3:4","2:3","4:3","1:2"],"correct":0,"explain":"The nuclear radius is r = R0 × A^(1/3). The ratio R1/R2 = (A1/A2)^(1/3) = (27/64)^(1/3) = 3/4, so R1:R2 = 3:4. The line 2:3 uses an incorrect cube root. The line 4:3 reverses the ratio. The line 1:2 uses a different mass ratio."},{"id":"PHY90034","type":"saq","cat":"Chapter 7: Matter Waves","q":"Which waves are associated with moving particles?","answer":"Matter waves","accept":["matter waves","de Broglie waves"],"explain":"Matter waves are associated with moving particles and are not electromagnetic waves."},{"id":"PHY90043","type":"saq","cat":"Chapter 7: Medical Applications","q":"Which treatment uses radiation to destroy cancer cells?","answer":"Radiation therapy","accept":[],"explain":"Radiation therapy uses ionizing radiation to destroy cancer cells."},{"id":"PHY90044","type":"saq","cat":"Chapter 7: Nuclear Structure","q":"Which collective term denotes protons and neutrons?","answer":"Nucleons","accept":["nucleons"],"explain":"Protons and neutrons are collectively called nucleons. They form the nucleus."}]}},"banks/medphys/finals/chapter-8-electricity-and-magnetism.json":{"id":"chapter-8-electricity-and-magnetism","subject":"Medical Physics","subjectId":"medphys","title":"Chapter 8: Electricity and Magnetism","formSize":58,"forms":["A"],"bank":{"A":[{"id":"PHY80001","type":"mcq","cat":"Chapter 8: Static Electricity","q":"Which statement correctly describes the two types of electric charge and their interaction?","options":["There is one type of charge, and all charged bodies attract each other","There are two types, and like charges repel while opposite charges attract","There are two types, and like charges attract while opposite charges repel","There is one type of charge, and all charged bodies repel each other"],"correct":1,"explain":"Electric charge comes in two types, positive and negative. The fundamental rule is that like charges repel each other, while opposite charges attract each other. The options that describe only one type of charge or that reverse the attraction and repulsion rules do not match this behavior."},{"id":"PHY80002","type":"mcq","cat":"Chapter 8: Static Electricity","q":"The SI unit of electric charge is the:","options":["Volt","Ampere","Coulomb","Ohm"],"correct":2,"explain":"The SI unit of electric charge is the coulomb, abbreviated C. Typical charges in electrostatics experiments are on the order of a microcoulomb, where 1 μC equals 10⁻⁶ C. The volt is the unit of electric potential, the ampere is the unit of current, and the ohm is the unit of resistance."},{"id":"PHY80003","type":"mcq","cat":"Chapter 8: Static Electricity","q":"Electric charge is quantized in units of the electron charge. This means the total charge Q on a body is:","options":["Q = e / n, where n is any integer","Q = n e, where n is any integer","Q = n + e, where n is any integer","Q = n - e, where n is any integer"],"correct":1,"explain":"Quantization of charge means the charge on any body is an integer multiple of the elementary charge e, so Q = n e where n is a whole number. The elementary charge is the magnitude of the charge on one electron, about 1.602 × 10⁻¹⁹ C. The line Q = e / n, where n is any integer divides by n rather than multiplying. The line Q = n + e, where n is any integer adds rather than multiplies. The line Q = n - e, where n is any integer subtracts rather than multiplies."},{"id":"PHY80004","type":"mcq","cat":"Chapter 8: Static Electricity","q":"Two million electrons are transferred to a body. What is the total charge acquired by the body? Take e = 1.602 × 10⁻¹⁹ C.","options":["3.20 × 10⁻¹³ C","3.20 × 10⁻¹² C","3.20 × 10⁻¹⁴ C","3.20 × 10⁻¹¹ C"],"correct":0,"explain":"Using Q = n e, substitute n = 2 × 10⁶ and e = 1.602 × 10⁻¹⁹ C. Then Q = 2 × 10⁶ × 1.602 × 10⁻¹⁹ = 3.204 × 10⁻¹³ C. The other options place the decimal one, two, or three positions away from this value."},{"id":"PHY80005","type":"mcq","cat":"Chapter 8: Static Electricity","q":"One billion electrons are removed from a body. What is the total charge left on the body? Take e = 1.602 × 10⁻¹⁹ C.","options":["1.602 × 10⁻¹⁰ C","1.602 × 10⁻⁹ C","1.602 × 10⁻¹¹ C","1.602 × 10⁻⁸ C"],"correct":0,"explain":"Using Q = n e, substitute n = 1 × 10⁹ and e = 1.602 × 10⁻¹⁹ C. Then Q = 1 × 10⁹ × 1.602 × 10⁻¹⁹ = 1.602 × 10⁻¹⁰ C. Because electrons are removed, the body is left with a net positive charge of this magnitude. The other options place the decimal in the wrong position."},{"id":"PHY80006","type":"mcq","cat":"Chapter 8: Coulomb's Law","q":"Coulomb's law states that the electric force between two point charges is:","options":["Directly proportional to the sum of the charges and inversely proportional to the square of the distance","Directly proportional to the product of the charges and inversely proportional to the square of the distance","Directly proportional to the product of the charges and inversely proportional to the distance between them","Inversely proportional to the product of the charges and directly proportional to the distance between them"],"correct":1,"explain":"Coulomb's law states that the force between two charges is directly proportional to the product of the charges and inversely proportional to the square of the distance between them. This gives the expression F = k Q₁Q₂ / r². The line Directly proportional to the sum of the charges and inversely proportional to the square of the distance uses the sum instead of the product. The line Directly proportional to the product of the charges and inversely proportional to the distance between them leaves out the square on the distance. The line Inversely proportional to the product of the charges and directly proportional to the distance between them reverses both proportionalities."},{"id":"PHY80007","type":"mcq","cat":"Chapter 8: Coulomb's Law","q":"Which expression correctly gives the electric force F between two point charges Q₁ and Q₂ separated by a distance r?","options":["F = k Q₁ Q₂ r²","F = k Q₁ Q₂ / r²","F = k r² / (Q₁ Q₂)","F = k (Q₁ + Q₂) / r²"],"correct":1,"explain":"Coulomb's law is expressed as F = k Q₁Q₂ / r², where k is the Coulomb constant. The force is proportional to the product of the charges and inversely proportional to the square of the distance. The line F = k Q₁ Q₂ r² multiplies by r² instead of dividing. The line F = k r² / (Q₁ Q₂) inverts the whole expression. The line F = k (Q₁ + Q₂) / r² adds the charges instead of multiplying them."},{"id":"PHY80008","type":"mcq","cat":"Chapter 8: Coulomb's Law","q":"The Coulomb constant k for air is approximately:","options":["8.998 × 10⁹ N·m²/C²","6.63 × 10⁻³⁴ N·m²/C²","1.602 × 10⁻¹⁹ N·m²/C²","3.00 × 10⁸ N·m²/C²"],"correct":0,"explain":"The Coulomb constant for air is k = 8.998 × 10⁹ N·m²/C², often approximated as 9 × 10⁹ N·m²/C². The value 6.63 × 10⁻³⁴ is the Planck constant, 1.602 × 10⁻¹⁹ is the elementary charge, and 3.00 × 10⁸ is the speed of light in vacuum."},{"id":"PHY80009","type":"mcq","cat":"Chapter 8: Coulomb's Law","q":"Two charges of -3 μC and +6 μC are placed 50 cm apart in air. What is the magnitude of the electric force between them? Take k = 9 × 10⁹ N·m²/C².","options":["0.648 N","6.48 N","0.0648 N","64.8 N"],"correct":0,"explain":"Using F = k Q₁Q₂ / r², substitute Q₁ = 3 × 10⁻⁶ C, Q₂ = 6 × 10⁻⁶ C, and r = 0.5 m. Then F = 9 × 10⁹ × (3 × 10⁻⁶ × 6 × 10⁻⁶) / (0.5)² = 9 × 10⁹ × 18 × 10⁻¹² / 0.25 = 162 × 10⁻³ / 0.25 = 0.648 N. The other options shift the decimal by one or two positions."},{"id":"PHY80010","type":"mcq","cat":"Chapter 8: Coulomb's Law","q":"The force between a 30 μC charge and a 90 μC charge is 1.8 N. How far apart are they? Take k = 9 × 10⁹ N·m²/C².","options":["3.67 m","1.84 m","0.367 m","36.7 m"],"correct":0,"explain":"Rearranging F = k Q₁Q₂ / r² gives r² = k Q₁Q₂ / F. Substituting Q₁ = 30 × 10⁻⁶ C, Q₂ = 90 × 10⁻⁶ C, and F = 1.8 N gives r² = 9 × 10⁹ × 30 × 10⁻⁶ × 90 × 10⁻⁶ / 1.8 = 9 × 10⁹ × 2700 × 10⁻¹² / 1.8 = 24.3 / 1.8 = 13.5 m². Taking the square root gives r ≈ 3.67 m. The other options shift the decimal in the final result."},{"id":"PHY80011","type":"mcq","cat":"Chapter 8: Coulomb's Law","q":"If the distance between two point charges is doubled while the charges remain unchanged, the electric force between them becomes:","options":["Twice as large","Half as large","One quarter as large","Four times as large"],"correct":2,"explain":"Coulomb's law states that the force is inversely proportional to the square of the distance, F ∝ 1/r². If the distance is doubled, the force becomes F / 2² = F / 4, so the force is one quarter of its original value. The options that double or halve the force ignore the square dependence."},{"id":"PHY80012","type":"mcq","cat":"Chapter 8: Electric Field","q":"The electric field at a point in space is defined as:","options":["The force on a small positive test charge divided by the charge on that body","The charge on a small positive test body divided by the force acting on that body","The force on a small positive test charge multiplied by the charge on that body","The charge on a small positive test body multiplied by the force acting on that body"],"correct":0,"explain":"The electric field is defined as E = F / q, where F is the force on a small test charge q placed at the point of interest. The SI unit is the newton per coulomb (N/C). The field is a vector that points in the direction of the force on a positive charge. The line The charge on a small positive test body divided by the force acting on that body inverts the division. The line The force on a small positive test charge multiplied by the charge on that body multiplies the two quantities. The line The charge on a small positive test body multiplied by the force acting on that body also multiplies rather than taking the ratio."},{"id":"PHY80013","type":"mcq","cat":"Chapter 8: Electric Field","q":"The electric field at a distance r from a point charge Q is given by:","options":["E = k Q / r²","E = k Q² / r","E = k r² / Q","E = k Q / r"],"correct":0,"explain":"The electric field produced by a point charge is E = k Q / r², where k is the Coulomb constant. The field falls off with the square of the distance, just as the Coulomb force does. The line E = k Q² / r squares the charge and drops one power of r. The line E = k r² / Q inverts the expression. The line E = k Q / r leaves only one power of r in the denominator."},{"id":"PHY80014","type":"mcq","cat":"Chapter 8: Electric Field","q":"The SI unit of electric field is:","options":["The newton (N)","The joule per coulomb (J/C)","The newton per coulomb (N/C)","The volt per meter squared (V/m²)"],"correct":2,"explain":"The electric field is defined as force per unit charge, so its SI unit is the newton per coulomb, N/C. It can also be written as the volt per meter, V/m, because 1 N/C equals 1 V/m. The newton is the unit of force, the joule per coulomb is the unit of electric potential, and the volt per meter squared is not a standard unit for the field."},{"id":"PHY80015","type":"mcq","cat":"Chapter 8: Electric Field","q":"A point charge of +5 × 10⁻⁶ C is placed in an electric field of 4 × 10⁵ N/C. What is the force on the charge?","options":["2.0 N","0.20 N","20 N","200 N"],"correct":0,"explain":"The force on a charge in an electric field is F = qE. Substituting q = 5 × 10⁻⁶ C and E = 4 × 10⁵ N/C gives F = 5 × 10⁻⁶ × 4 × 10⁵ = 20 × 10⁻¹ = 2.0 N. The direction of the force is the same as the direction of the field because the charge is positive. The other options shift the decimal by one or two positions."},{"id":"PHY80016","type":"mcq","cat":"Chapter 8: Electric Field","q":"Electric field lines around a negatively charged sphere:","options":["Radiate outward away from the sphere","Extend inward toward the sphere from every direction","Form closed circles around the sphere","Form straight parallel lines that pass through the sphere"],"correct":1,"explain":"The direction of the electric field is defined as the direction of the force on a positive test charge. Around a negatively charged sphere, that force is attractive, so the field lines point inward toward the sphere. Outward-radiating lines are characteristic of a positive charge. Circular and parallel-line patterns do not represent the field of an isolated point charge."},{"id":"PHY80017","type":"mcq","cat":"Chapter 8: Electric Potential","q":"The electric potential V at a point is defined as:","options":["The work per unit charge in bringing a test charge from infinity to that point","The work per unit charge in taking a test charge from that point to infinity","The force per unit charge on a small test charge kept at that point in space","The product of the field and the charge on a test charge kept at that point"],"correct":0,"explain":"Electric potential is the work done per unit charge in bringing a small positive test charge from infinity to the point. It is expressed as V = W / q, and its SI unit is the volt, where 1 V = 1 J/C. The line The work per unit charge in taking a test charge from that point to infinity reverses the path. The line The force per unit charge on a small test charge kept at that point in space describes the electric field. The line The product of the field and the charge on a test charge kept at that point multiplies field and charge rather than giving the potential."},{"id":"PHY80018","type":"mcq","cat":"Chapter 8: Electric Potential","q":"The electric potential at a distance r from a point charge Q is given by:","options":["V = k Q r","V = k Q / r","V = k Q / r²","V = k r / Q"],"correct":1,"explain":"The electric potential from a point charge is V = k Q / r, where k is the Coulomb constant. The potential falls off as one over r, not as one over r squared. The line V = k Q r multiplies by r. The line V = k Q / r² uses the inverse-square form. The line V = k r / Q inverts the charge and distance."},{"id":"PHY80019","type":"mcq","cat":"Chapter 8: Electric Potential","q":"A potential difference of 10 V exists between two points. How much work is required to move a charge of 2 × 10⁻³ C between the points?","options":["2.0 × 10⁻² J","2.0 × 10⁻³ J","2.0 × 10⁻¹ J","2.0 × 10⁻⁴ J"],"correct":0,"explain":"Using V = W / q, rearrange to W = q V. Substituting q = 2 × 10⁻³ C and V = 10 V gives W = 2 × 10⁻³ × 10 = 2 × 10⁻² J. The other options place the decimal one or two positions away from the correct value."},{"id":"PHY80020","type":"mcq","cat":"Chapter 8: Electric Potential","q":"A potential difference of 10 V exists between two points, and 2.0 × 10⁻² J of work is required to move a charge between them. What is the magnitude of the charge?","options":["2.0 × 10⁻³ C","2.0 × 10⁻² C","2.0 × 10⁻¹ C","2.0 × 10⁻⁴ C"],"correct":0,"explain":"Rearranging V = W / q gives q = W / V. Substituting W = 2.0 × 10⁻² J and V = 10 V gives q = 2.0 × 10⁻² / 10 = 2.0 × 10⁻³ C. The other options place the decimal in the wrong position."},{"id":"PHY80021","type":"mcq","cat":"Chapter 8: Electric Potential","q":"One volt is equivalent to:","options":["One coulomb per joule","One joule per coulomb","One joule per second","One newton per coulomb"],"correct":1,"explain":"The volt is defined as one joule per coulomb, written 1 V = 1 J/C. This follows from the definition V = W / q, where W is the work in joules and q is the charge in coulombs. The line One coulomb per joule inverts the ratio. The line One joule per second is the watt. The line One newton per coulomb is the unit of electric field."},{"id":"PHY80022","type":"mcq","cat":"Chapter 8: Electric Current","q":"Electric current is defined as:","options":["The total amount of charge that has passed a given point in a conductor","The rate of flow of electric charge through a conductor per unit time","The potential difference that exists across the two ends of a conductor","The resistance offered by a conductor to the passage of electric charge"],"correct":1,"explain":"Electric current is the rate of flow of charge through a conductor, expressed as I = Q / T. If an amount of charge Q passes through a cross-section in time T, then the current is that charge divided by that time. The total charge is not the rate, the potential difference is the voltage, and the resistance is the opposition to current."},{"id":"PHY80023","type":"mcq","cat":"Chapter 8: Electric Current","q":"A charge of 100 C passes through a point in a conductor in 1 second. What is the current?","options":["1 A","10 A","100 A","0.01 A"],"correct":2,"explain":"Using I = Q / T, substitute Q = 100 C and T = 1 s. Then I = 100 / 1 = 100 A. The option 1 A uses a charge of 1 C, 10 A uses a charge of 10 C, and 0.01 A inverts the ratio."},{"id":"PHY80024","type":"mcq","cat":"Chapter 8: Ohm's Law","q":"Ohm's law states that, at constant temperature, the current through a conductor is:","options":["Directly proportional to the potential difference across it","Inversely proportional to the potential difference across it","Independent of the potential difference across it","Proportional to the square of the potential difference"],"correct":0,"explain":"Ohm's law states that the current through a conductor is directly proportional to the potential difference across it, provided the temperature is held constant. This is written as V = I R, or equivalently I = V / R. The constant of proportionality is the resistance. The other options describe inverse, absent, or squared dependence, none of which match Ohm's law."},{"id":"PHY80025","type":"mcq","cat":"Chapter 8: Ohm's Law","q":"In a circuit, a current of 2 mA passes through a wire when connected to a 5 V battery. What is the resistance of the wire?","options":["2500 Ω","250 Ω","25 Ω","25000 Ω"],"correct":0,"explain":"Using V = I R, rearrange to R = V / I. Substituting V = 5 V and I = 2 × 10⁻³ A gives R = 5 / (2 × 10⁻³) = 2500 Ω. The other options shift the decimal by one or two positions."},{"id":"PHY80026","type":"mcq","cat":"Chapter 8: Ohm's Law","q":"How much current passes through a wire of resistance 100 Ω when it is connected to a 5.5 V battery?","options":["55 mA","5.5 mA","550 mA","0.55 mA"],"correct":0,"explain":"Using I = V / R, substitute V = 5.5 V and R = 100 Ω. Then I = 5.5 / 100 = 0.055 A = 55 mA. The option 5.5 mA divides by 1000 instead of 100, 550 mA multiplies by 10, and 0.55 mA divides by 10000."},{"id":"PHY80027","type":"mcq","cat":"Chapter 8: Resistance and Resistivity","q":"The resistance R of a conducting wire is proportional to its length L and inversely proportional to its area of cross-section A. Which expression correctly represents this relationship?","options":["R = ρ A / L","R = ρ L A","R = ρ L / A","R = ρ / (L A)"],"correct":2,"explain":"The resistance of a wire is proportional to its length and inversely proportional to its cross-sectional area, so R = ρ L / A. The line R = ρ A / L swaps L and A. The line R = ρ L A multiplies length and area. The line R = ρ / (L A) puts both in the denominator."},{"id":"PHY80028","type":"mcq","cat":"Chapter 8: Resistance and Resistivity","q":"The resistivity ρ of a material is defined as:","options":["The resistance of a piece of the material of any size and shape","The resistance of a unit cube of the material from opposite faces","The product of the resistance and the cross-sectional area of a sample","The total length of a sample divided by its resistance"],"correct":1,"explain":"Resistivity is the resistance offered by a unit cube of the material from one face to the opposite face. It is an intrinsic property of the material. The line The resistance of a piece of the material of any size and shape describes resistance. The line The product of the resistance and the cross-sectional area of a sample is incomplete. The line The total length of a sample divided by its resistance is incomplete."},{"id":"PHY80029","type":"mcq","cat":"Chapter 8: Resistance and Resistivity","q":"The SI unit of resistivity is the:","options":["Ohm (Ω)","Ohm-meter (Ω·m)","Ohm per meter (Ω/m)","Ohm per square meter (Ω/m²)"],"correct":1,"explain":"The resistivity has SI unit ohm-meter, Ω·m, because it comes from rearranging R = ρ L / A to ρ = R A / L. The resistance is in ohms, the area in square meters, and the length in meters, so the unit becomes Ω·m²/m = Ω·m. The ohm is the unit of resistance, not resistivity."},{"id":"PHY80030","type":"mcq","cat":"Chapter 8: Resistance and Resistivity","q":"Which statement correctly distinguishes resistance from resistivity?","options":["Resistance is a property of the material, and resistivity depends on the size and shape of the object","Resistance depends on the size and shape of the object, and resistivity is a property of the material","Resistance depends on the material and temperature, and resistivity is a property of the size of the object","Resistance depends on the size of the object only, and resistivity is a property of its shape only"],"correct":1,"explain":"Resistance is a property of the object; it depends on the length and cross-sectional area of the particular sample. Resistivity is a property of the material; it is independent of the size and shape of the sample and depends only on the material and its temperature. The line Resistance is a property of the material, and resistivity depends on the size and shape of the object reverses these two descriptions. The other lines assign the wrong dependences to each quantity."},{"id":"PHY80031","type":"mcq","cat":"Chapter 8: Resistance and Resistivity","q":"A wire has a length of 20 m, an area of cross-section of 5 × 10⁻⁶ m², and a resistance of 30 Ω. What is the resistivity of the material?","options":["7.5 × 10⁻⁶ Ω·m","7.5 × 10⁻⁵ Ω·m","7.5 × 10⁻⁷ Ω·m","7.5 × 10⁻⁴ Ω·m"],"correct":0,"explain":"Rearranging R = ρ L / A gives ρ = R A / L. Substituting R = 30 Ω, A = 5 × 10⁻⁶ m², and L = 20 m gives ρ = 30 × 5 × 10⁻⁶ / 20 = 150 × 10⁻⁶ / 20 = 7.5 × 10⁻⁶ Ω·m. The other options shift the decimal by one or two positions."},{"id":"PHY80032","type":"mcq","cat":"Chapter 8: Resistance and Resistivity","q":"A tungsten filament has a resistivity of 6.0 × 10⁻⁸ Ω·m, a length of 0.1 m, and a resistance of 20 Ω. What is the area of the filament?","options":["3 × 10⁻¹⁰ m²","3 × 10⁻⁹ m²","3 × 10⁻⁸ m²","3 × 10⁻¹¹ m²"],"correct":0,"explain":"Rearranging R = ρ L / A gives A = ρ L / R. Substituting ρ = 6.0 × 10⁻⁸ Ω·m, L = 0.1 m, and R = 20 Ω gives A = 6.0 × 10⁻⁸ × 0.1 / 20 = 6.0 × 10⁻⁹ / 20 = 3 × 10⁻¹⁰ m². The other options shift the decimal by one or two positions."},{"id":"PHY80033","type":"mcq","cat":"Chapter 8: Resistance and Resistivity","q":"Two wires of the same length and cross-section are made of copper and iron. When the same potential difference is applied across each, different currents flow. This difference is due to the difference in their:","options":["Length","Area of cross-section","Resistivity","Applied voltage"],"correct":2,"explain":"Resistivity is the intrinsic property of a material that determines how much resistance a sample of a given size will have. Two wires of identical geometry have the same resistance only if their resistivities are equal. Copper and iron have different resistivities, so they have different resistances and different currents. Length, area, and voltage are all held the same in this comparison."},{"id":"PHY80034","type":"mcq","cat":"Chapter 8: Current Density","q":"Current density J is defined as:","options":["The total current in a conductor","Current per unit surface area of cross-section","The product of current and surface area","The resistance per unit length of a conductor"],"correct":1,"explain":"Current density is defined as the current per unit surface area of cross-section, written J = I / A, with SI unit A/m². It measures how concentrated the current is within a conductor. The line The total current in a conductor gives the total current. The line The product of current and surface area multiplies current and area. The line The resistance per unit length of a conductor describes a different quantity."},{"id":"PHY80035","type":"mcq","cat":"Chapter 8: Current Density","q":"The relationship between current density J and electric field E in a conductor with conductivity σ is:","options":["J = σ / E","J = σ × E","J = E / σ","J = σ + E"],"correct":1,"explain":"In a conductor, the current density is proportional to the electric field, with the constant of proportionality being the conductivity σ. This gives J = σ × E. Since conductivity is the reciprocal of resistivity, this relation is equivalent to E = ρ J. The line J = σ / E divides. The line J = E / σ inverts the ratio. The line J = σ + E adds the two quantities."},{"id":"PHY80036","type":"mcq","cat":"Chapter 8: Current Density","q":"The SI unit of current density is:","options":["The ampere per unit length of the conductor, A/m","The ampere per square meter of cross-section, A/m²","The ampere per cubic meter of the conductor, A/m³","The ampere per unit of charge delivered, A/C"],"correct":1,"explain":"Current density is current per unit area, so its unit is the ampere per square meter, A/m². The ampere alone is the unit of current, not current density. The other units divide by length, volume, or charge and do not match the definition J = I / A."},{"id":"PHY80037","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"Which of the following correctly describes the parts of a neuron and their functions?","options":["Signals are received by the axon and transmitted through the dendrites","Signals are received by the dendrites, propagated along the axon, and transmitted through a synapse","Signals are received by the synapse, propagated along the dendrites, and transmitted through the axon","Signals are received by the cell body, propagated along the synapse, and transmitted through the dendrites"],"correct":1,"explain":"A neuron has a main cell body, small attachments called dendrites, and a long tail called the axon. Signals are received by the dendrites, propagated along the axon, and then transmitted to another neuron or a muscle through a connection called a synapse. The other options swap these roles and therefore misassign the functions."},{"id":"PHY80039","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"During depolarization of a neuron, which ion moves into the cell and causes the membrane potential to rise?","options":["K⁺","Cl⁻","Na⁺","Ca²⁺"],"correct":2,"explain":"Depolarization is triggered when voltage-gated sodium channels open and Na⁺ ions rush into the cell. Because sodium carries a positive charge, the inside of the cell becomes less negative and eventually positive. K⁺ moves out of the cell during repolarization, Cl⁻ is a negative ion that is not the trigger, and Ca²⁺ plays a role at synapses rather than in the initial depolarization."},{"id":"PHY80040","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"During repolarization of a neuron, which change occurs?","options":["Na⁺ channels open and Na⁺ flows into the cell","Na⁺ channels close and K⁺ moves out of the cell","K⁺ channels close and Na⁺ moves out of the cell","Both Na⁺ and K⁺ channels remain fully open"],"correct":1,"explain":"Repolarization occurs when the sodium channels close, stopping the inward Na⁺ current, and the potassium channels open, allowing K⁺ to flow out of the cell. The loss of positive potassium ions restores the negative interior. The line Na⁺ channels open and Na⁺ flows into the cell describes depolarization. The line K⁺ channels close and Na⁺ moves out of the cell reverses the ion flow. The line Both Na⁺ and K⁺ channels remain fully open would prevent any return to the resting state."},{"id":"PHY80041","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"Hyperpolarization of a neuron occurs because:","options":["Na⁺ channels open again after the action potential","K⁺ channels stay open longer, so more K⁺ leaves the cell","Cl⁻ channels close and stop the inflow of negative charge","The cell body releases a burst of positive charge"],"correct":1,"explain":"Hyperpolarization happens because the potassium channels have slower kinetics than the sodium channels. They remain open a little longer than needed, so more K⁺ ions leave the cell than usual, and the membrane potential dips below the resting value. The line Na⁺ channels open again after the action potential would trigger another action potential. The line Cl⁻ channels close and stop the inflow of negative charge describes the opposite of what Cl⁻ does. The line The cell body releases a burst of positive charge is not a physiological mechanism."},{"id":"PHY80042","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"The refractory period of a neuron is:","options":["A brief interval when a new stimulus cannot fire it, or must be much stronger","A brief interval when the neuron fires at its maximum possible rate in response","A brief interval when the resting potential becomes more positive than usual","A brief interval when both the sodium and potassium channels remain open"],"correct":0,"explain":"The refractory period is a brief interval during which the cell cannot respond to a new stimulus, or can only respond to a much stronger one. This limits the maximum firing rate of the neuron and ensures that action potentials travel in one direction along the axon. Continuous firing, more positive resting potential, and permanently open channels are not descriptions of the refractory period."},{"id":"PHY80043","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"Which of the following correctly lists the three types of gated channels in nerve membranes?","options":["Chemical gated, thermal gated, and light gated","Chemical gated, mechanical gated, and voltage gated","Voltage gated, magnetic gated, and pressure gated","Mechanical gated, chemical gated, and sound gated"],"correct":1,"explain":"Nerve membranes contain three types of gated ion channels: chemically gated, mechanically gated, and voltage gated. Chemical gating responds to neurotransmitters, mechanical gating responds to physical deformation, and voltage gating responds to changes in membrane potential. The other options list channels that are not part of the standard set."},{"id":"PHY80044","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"The myelin sheath on an axon serves to:","options":["Prevent the axon from carrying any signal","Speed up the transmission of the action potential","Increase the leakage of ions across the membrane","Convert the electrical signal into a chemical one"],"correct":1,"explain":"The myelin sheath is an insulating layer that wraps around the axon and speeds up signal transmission by allowing the action potential to jump between the nodes of Ranvier in a process called saltatory conduction. It does not stop signaling, increase ion leakage, or convert the signal; conversion at the synapse is a separate process."},{"id":"PHY80045","type":"mcq","cat":"Chapter 8: Nerve Conduction","q":"The resting potential of a neuron arises mainly from:","options":["A perfectly uniform distribution of all the ions on both sides of the membrane","Ionic concentration gradients and selective permeability of the membrane to K⁺","The rapid permanent closing of all the ion channels in the membrane after firing","The complete absence of any charged particles on either side of the membrane"],"correct":1,"explain":"The resting potential arises from the ionic concentration gradients across the membrane and from the membrane's selective permeability, particularly to K⁺. The sodium-potassium exchange pump maintains these gradients by pumping Na⁺ out and K⁺ in. A uniform distribution, complete closure of channels, or absence of ions would all eliminate the potential."},{"id":"PHY80046","type":"mcq","cat":"Chapter 8: Magnetism","q":"A moving charge produces:","options":["An electric field only, with no magnetic field produced by the motion","A magnetic field only, with no electric field carried along with it","Both an electric field and a magnetic field around its path","Neither an electric field nor a magnetic field around its path"],"correct":2,"explain":"A moving charge carries its electric field with it and also produces a magnetic field because of its motion. The magnetic field of a current-carrying wire and the magnetic moment of a spinning electron in an atom are both consequences of moving charge. The options that mention only one field or neither field are incomplete."},{"id":"PHY80047","type":"mcq","cat":"Chapter 8: Magnetism","q":"The magnitude of the magnetic force on a charge q moving with velocity v through a magnetic field B is given by:","options":["F = q v B sin θ, where θ is the angle between the velocity and the magnetic field","F = q v B cos θ, where θ is the angle between the velocity and the magnetic field","F = q v B tan θ, where θ is the angle between the velocity and the magnetic field","F = q v B cot θ, where θ is the angle between the velocity and the magnetic field"],"correct":0,"explain":"The magnitude of the magnetic force is F = q v B sin θ, where θ is the angle between the velocity vector and the magnetic field vector. In vector form this is written F = q v × B. The force is maximum when the velocity is perpendicular to the field and zero when they are parallel. The options using cosine, tangent, or cotangent have the wrong dependence on the angle between velocity and field."},{"id":"PHY80048","type":"mcq","cat":"Chapter 8: Magnetism","q":"The direction of the magnetic force on a moving charged particle is:","options":["Parallel to the velocity and parallel to the magnetic field","Perpendicular to the velocity and perpendicular to the magnetic field","Parallel to the velocity and perpendicular to the magnetic field","Perpendicular to the velocity and parallel to the magnetic field"],"correct":1,"explain":"The magnetic force is always perpendicular to both the velocity of the charged particle and the magnetic field, because the force is the vector cross product F = q v × B. This perpendicularity is what causes a charged particle to move in a circular or helical path in a uniform magnetic field. The other options place the force parallel to at least one of the two vectors, which contradicts the cross-product definition."},{"id":"PHY80049","type":"mcq","cat":"Chapter 8: Magnetism","q":"The SI unit of magnetic field is the tesla, which is equivalent to:","options":["One newton per coulomb of charge placed in the field","One newton per ampere-meter of current and length","One joule per coulomb of charge moving in the field","One ampere per meter of the current-carrying conductor"],"correct":1,"explain":"The tesla is defined from the magnetic force equation as 1 T = 1 N / (A·m), that is, one newton per ampere-meter. This follows from B = F / (|q| v). The newton per coulomb is the unit of electric field, the joule per coulomb is the volt, and the ampere per meter is the unit of magnetic field strength in a different context."},{"id":"PHY80050","type":"mcq","cat":"Chapter 8: Magnetism","q":"One tesla is equal to how many gauss?","options":["10² G","10³ G","10⁴ G","10⁵ G"],"correct":2,"explain":"The gauss is a non-SI unit of magnetic field. The conversion is 1 tesla = 10⁴ gauss. This means a magnetic field of 1 T is the same as 10,000 G. The other options place the power of ten one or two positions away from the correct value."},{"id":"PHY80051","type":"mcq","cat":"Chapter 8: MRI","q":"MRI (Magnetic Resonance Imaging) produces images of the body using:","options":["Ionizing X-rays and a rotating detector","Strong magnetic fields and radio waves","High-frequency sound waves and a gel couplant","Gamma rays emitted by a radiotracer"],"correct":1,"explain":"MRI uses strong magnetic fields to align hydrogen nuclei in the body, then applies radio waves to disturb the alignment. When the nuclei relax, they emit signals that are detected and converted into detailed images. X-rays and gamma rays are ionizing and belong to other imaging modalities, and sound waves are used in ultrasound."},{"id":"PHY80052","type":"mcq","cat":"Chapter 8: MRI","q":"MRI scanners commonly operate at magnetic field strengths of:","options":["50 μT to 0.5 mT","1.5 T to 3 T","10 T to 30 T","0.5 T to 1.0 T"],"correct":1,"explain":"Clinical MRI scanners use magnetic fields of about 1.5 T to 3 T, which are thousands of times stronger than Earth's magnetic field of roughly 50 μT. A refrigerator magnet produces about 0.005 T, much weaker than an MRI magnet. The other options either fall well below the clinical range or exceed practical field strengths."},{"id":"PHY80053","type":"mcq","cat":"Chapter 8: MRI","q":"Which of the following is a key advantage of MRI over imaging methods that use ionizing radiation?","options":["It uses X-rays at low intensity","It does not use ionizing radiation","It requires no magnetic field","It produces images only of bones"],"correct":1,"explain":"MRI does not use ionizing radiation, which distinguishes it from X-ray and CT imaging. This makes it safer for repeated use and for imaging sensitive tissues. MRI relies on strong magnetic fields and radio waves, not on X-rays. It provides excellent soft-tissue contrast, including brain, spinal cord, muscles, and joints, rather than only bone."},{"id":"PHY80054","type":"mcq","cat":"Chapter 8: MRI","q":"Why are metallic objects not allowed in an MRI room?","options":["They reflect the radio waves used in imaging and create false echoes in the image","They block the hydrogen nuclei in the body from aligning with the strong field","They are attracted with great force by the strong magnetic field of the scanner","They emit gamma rays when they are placed inside the magnetic field of the scanner"],"correct":2,"explain":"The magnetic field of an MRI scanner is so strong that it can pull ferromagnetic objects toward the bore with great force, which creates a serious safety hazard. This is the primary reason metal objects are forbidden in the scanner room. Reflection of radio waves, blocking of hydrogen alignment, and emission of gamma rays are not the reasons for the restriction."},{"id":"PHY80055","type":"mcq","cat":"Chapter 8: Biomagnetism","q":"Biomagnetism refers to the fact that:","options":["The body generates weak magnetic fields from organ electrical activity","The body generates strong magnetic fields as strong as an MRI scanner","The body stores permanent magnetic material inside the cells of organs","The body produces detectable magnetic fields only while asleep at night"],"correct":0,"explain":"Biomagnetism is the phenomenon in which the human body naturally generates weak magnetic fields because of the electrical activity of organs such as the brain and heart. These fields are extremely small compared with an MRI magnet. The body does not contain permanent magnets and does not produce fields only during sleep."},{"id":"PHY80056","type":"mcq","cat":"Chapter 8: Biomagnetism","q":"Which pair correctly matches a body source of magnetic field with its measurement technique?","options":["Brain activity with magnetocardiography, and heart activity with magnetoencephalography","Brain activity with magnetoencephalography, and heart activity with magnetocardiography","Brain activity with electrocardiography, and heart activity with electromyography","Brain activity with electromyography, and heart activity with electrocardiography"],"correct":1,"explain":"Brain activity produces tiny magnetic fields measured by magnetoencephalography, abbreviated MEG. Heart activity produces magnetic fields measured by magnetocardiography, abbreviated MCG. The line Brain activity with magnetocardiography, and heart activity with magnetoencephalography swaps the two techniques. The other lines refer to techniques that measure electric potentials rather than magnetic fields."},{"id":"PHY80057","type":"matching","cat":"Chapter 8: Electricity Formulas","q":"Match each formula to the quantity it defines or the relationship it expresses.","leftItems":[{"id":"1","text":"Q = n e"},{"id":"2","text":"F = k Q₁ Q₂ / r²"},{"id":"3","text":"E = F / q"},{"id":"4","text":"V = W / q"},{"id":"5","text":"I = Q / T"},{"id":"6","text":"V = I R"},{"id":"7","text":"R = ρ L / A"}],"rightItems":[{"id":"A","text":"The quantization of charge in integer multiples of the elementary charge."},{"id":"B","text":"The electric force between two point charges separated by a distance."},{"id":"C","text":"The electric field as the force per unit charge."},{"id":"D","text":"The electric potential as the work per unit charge."},{"id":"E","text":"The electric current as the rate of flow of charge."},{"id":"F","text":"Ohm's law, relating voltage, current, and resistance."},{"id":"G","text":"The resistance of a wire in terms of its resistivity, length, and area."}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G"},"explain":"The relation Q = n e expresses quantization of charge. Coulomb's law F = k Q₁Q₂ / r² gives the force between two point charges. The definition E = F / q gives the electric field. The definition V = W / q gives the electric potential. The relation I = Q / T gives the electric current. Ohm's law V = I R relates voltage, current, and resistance. The relation R = ρ L / A gives the resistance of a wire from its resistivity, length, and cross-sectional area."},{"id":"PHY80058","type":"matching","cat":"Chapter 8: Nerve Conduction","q":"Match each phase of the neuronal action potential to its correct description.","leftItems":[{"id":"1","text":"Resting potential"},{"id":"2","text":"Depolarization"},{"id":"3","text":"Repolarization"},{"id":"4","text":"Hyperpolarization"},{"id":"5","text":"Refractory period"}],"rightItems":[{"id":"A","text":"The membrane potential is about -70 mV because of ionic gradients and selective K⁺ permeability."},{"id":"B","text":"Voltage-gated Na⁺ channels open and Na⁺ rushes into the cell, raising the membrane potential."},{"id":"C","text":"Na⁺ channels close and K⁺ moves out of the cell, restoring the negative interior."},{"id":"D","text":"K⁺ channels remain open longer, so the membrane potential dips below the resting value."},{"id":"E","text":"A brief interval during which a new action potential cannot be triggered or needs a much stronger stimulus."}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"The resting potential of about -70 mV is maintained by ionic concentration gradients and selective permeability, especially to K⁺. Depolarization occurs when voltage-gated Na⁺ channels open and Na⁺ enters the cell. Repolarization occurs when Na⁺ channels close and K⁺ leaves the cell, restoring the negative interior. Hyperpolarization occurs because K⁺ channels stay open longer, letting the potential dip below the resting value. The refractory period is the interval when a new action potential cannot be triggered, or requires a much stronger stimulus."},{"id":"PHY80060","type":"stepped","cat":"Chapter 8: Nerve Conduction","group":"channel-category-drill","groupOrder":1,"q":"Gated channels. At each step a channel type is named; choose the correct category for it, then continue.","steps":[{"id":"1","prompt":"Chemical gated channel. Which description fits?","options":["Opens when a neurotransmitter binds.","Opens when the membrane is stretched or deformed.","Opens when the membrane voltage changes.","Opens when the temperature rises."],"correct":0},{"id":"2","prompt":"Mechanical gated channel. Which description fits?","options":["Opens when the membrane is stretched or deformed.","Opens when a neurotransmitter binds.","Opens when the membrane voltage changes.","Opens when light strikes the membrane."],"correct":0},{"id":"3","prompt":"Voltage gated channel. Which description fits?","options":["Opens when the membrane voltage changes.","Opens when a neurotransmitter binds.","Opens when the membrane is stretched or deformed.","Opens when the ion concentration is equal."],"correct":0}],"explain":"Chemical gated channels open when a neurotransmitter binds. Mechanical gated channels open when the membrane is stretched or deformed. Voltage gated channels open when the membrane voltage changes. The other lines assign the wrong stimulus to that channel type."}]},"cards":[{"id":"ch8","title":"Chapter 8: Electricity and Magnetism","cats":["Chapter 8: Static Electricity","Chapter 8: Coulomb's Law","Chapter 8: Electric Field","Chapter 8: Electric Potential","Chapter 8: Electric Current","Chapter 8: Ohm's Law","Chapter 8: Resistance and Resistivity","Chapter 8: Current Density","Chapter 8: Nerve Conduction","Chapter 8: Magnetism","Chapter 8: MRI","Chapter 8: Biomagnetism","Chapter 8: Electricity Formulas"],"draft":true}]},"banks/medphys/finals/mixed-chapters.json":{"id":"mixed-chapters","subject":"Medical Physics","subjectId":"medphys","title":"Mixed Chapters","source":"Medical Physics question banks mixed-chapters: original versions of the 8 items that contain Chapter 7 content (removed or trimmed in the live bank)","formSize":8,"forms":["A"],"cards":[{"id":"mixed","title":"Mixed Chapters","cats":["Mixed Chapters: Cross-Chapter","Mixed Chapters: Linking and Short Answers"],"draft":true}],"bank":{"A":[{"id":"PHY90006","type":"matching","cat":"Mixed Chapters: Cross-Chapter","q":"Match each principle to the medical technology that relies on it.","leftItems":[{"id":"1","text":"Total internal reflection"},{"id":"2","text":"Thin-lens power"},{"id":"3","text":"Stimulated emission"},{"id":"4","text":"Radioactive half-life"},{"id":"5","text":"Ionizing radiation"}],"rightItems":[{"id":"A","text":"Trapped light steers a flexible scope"},{"id":"B","text":"Curvature bends rays to a focus"},{"id":"C","text":"Coherent beam seals or cuts tissue"},{"id":"D","text":"Fixed decay dates old carbon"},{"id":"E","text":"Charged beams destroy tumour cells"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Trapped light guides an endoscope. Lens curvature focuses corrective and instrumental rays. Stimulated emission gives the laser beam. Half-life clocks carbon dating. Ionizing beams treat tumours."},{"id":"PHY90007","type":"matching","cat":"Mixed Chapters: Cross-Chapter","q":"Match each physical quantity to its SI unit.","leftItems":[{"id":"1","text":"Viscosity"},{"id":"2","text":"Surface tension"},{"id":"3","text":"Lens power"},{"id":"4","text":"Activity"},{"id":"5","text":"Absorbed dose"},{"id":"6","text":"Dose equivalent"}],"rightItems":[{"id":"A","text":"pascal-second"},{"id":"B","text":"newton per metre"},{"id":"C","text":"dioptre"},{"id":"D","text":"becquerel"},{"id":"E","text":"gray"},{"id":"F","text":"sievert"},{"id":"G","text":"joule"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"Viscosity is pascal-second, surface tension newton per metre, lens power dioptre, activity becquerel, absorbed dose gray, and dose equivalent sievert. Joule is energy."},{"id":"PHY90008","type":"matching","cat":"Mixed Chapters: Cross-Chapter","q":"Match each formula to what it calculates.","leftItems":[{"id":"1","text":"E = hf"},{"id":"2","text":"λ = h/mv"},{"id":"3","text":"T½ = 0.693/λ"},{"id":"4","text":"n = c/v"},{"id":"5","text":"P = 1/f"},{"id":"6","text":"Q = πr⁴ΔP/8ηL"}],"rightItems":[{"id":"A","text":"Photon energy"},{"id":"B","text":"Matter wavelength"},{"id":"C","text":"Half-life"},{"id":"D","text":"Index of refraction"},{"id":"E","text":"Lens power"},{"id":"F","text":"Viscous tube flow"},{"id":"G","text":"Wave speed"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"E = hf is photon energy, λ = h/mv matter wavelength, T½ = 0.693/λ half-life, n = c/v refractive index, P = 1/f lens power, and the r⁴ form is viscous tube flow. Wave speed is v = λf."},{"id":"PHY90009","type":"matching","cat":"Mixed Chapters: Cross-Chapter","q":"Match each wave category to its examples.","leftItems":[{"id":"1","text":"Mechanical waves"},{"id":"2","text":"Electromagnetic waves"},{"id":"3","text":"Matter waves"}],"rightItems":[{"id":"A","text":"Sound and ultrasound"},{"id":"B","text":"Light, X-rays, gamma rays"},{"id":"C","text":"de Broglie association with moving particles"},{"id":"D","text":"Sound travelling through vacuum"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Mechanical waves include sound and ultrasound. Electromagnetic waves include light, X-rays, and gamma rays. Matter waves are the de Broglie association. Sound cannot cross vacuum."},{"id":"PHY90018","type":"saq","cat":"Mixed Chapters: Linking and Short Answers","q":"Which named relation gives a moving particle the wavelength h over mv?","answer":"de Broglie wavelength","accept":["de Broglie","De Broglie","de broglie","de-Broglie","De Broglie wavelength","de-Broglie wavelength","de Broglie's wavelength"],"explain":"The de Broglie relation λ = h / mv assigns a wavelength to a moving particle."},{"id":"PHY90019","type":"saq","cat":"Mixed Chapters: Linking and Short Answers","q":"In hf = Kmax + φ, which term is the minimum ejection energy?","answer":"Work function","accept":["work function","The function of work","function of work"],"explain":"The work function φ is the minimum energy needed to free an electron from the metal."},{"id":"PHY90025","type":"saq","cat":"Mixed Chapters: Linking and Short Answers","q":"Which term means the smallest discrete amount of a quantized quantity?","answer":"Quantum","accept":["quantum"],"explain":"A quantum is the elementary amount of a quantized quantity; quanta is the plural."},{"id":"PHY90031","type":"stepped","cat":"Mixed Chapters: Linking and Short Answers","q":"Ionizing radiation has two named medical applications. Type one at each step.","explain":"Radiation therapy destroys cancer cells with ionizing radiation. Dosimetry measures the dose absorbed by living tissue in medicine.","steps":[{"id":"1","type":"saq","prompt":"Type the treatment that uses ionizing radiation to destroy cancer cells.","answer":"Radiation therapy","accept":[]},{"id":"2","type":"saq","prompt":"Given Radiation therapy, type the medical measurement of dose absorbed by living tissue.","answer":"Dosimetry","accept":["Radiation dosimetry"]}]}]}},"banks/studyskills/lecture-1-learning-styles.json":{"id":"lecture-1-learning-styles","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 1 – Learning Styles","formSize":46,"forms":["A"],"bank":{"A":[{"id":"SSPT11000","type":"mcq","cat":"Learning Styles","q":"People with which of the following learning styles learn better when information is presented in a picture format?","options":["Auditory","Kinesthetic","Non-Verbal – Visual","Verbal – Visual"],"correct":2,"explain":"Non-verbal visual learners learn from picture format — videos, maps, charts, diagrams. Verbal-visual learners prefer written words."},{"id":"SSPT11001","type":"mcq","cat":"Learning Styles","q":"Which learning style primarily uses finger spelling?","options":["Auditory","Kinesthetic","Non-Verbal – Visual","Verbal – Visual"],"correct":1,"explain":"Finger spelling (tracing words with your finger to learn spelling) is listed among the KINESTHETIC study tools."},{"id":"SSPT11002","type":"mcq","cat":"Learning Styles","q":"Which learning style learns best by attending discussions and tutorials?","options":["Visual","Auditory","Kinesthetic","Non-verbal visual"],"correct":1,"explain":"Auditory learners learn best by listening — discussions and tutorials deliver information as speech."},{"id":"SSPT11003","type":"mcq","cat":"Learning Styles","q":"A student who prefers to see information presented in the form of pictures, diagrams, cartoons, or demonstrations is best described as having which type of learning style?","options":["Visual","Auditory","Kinesthetic","Verbal visual"],"correct":0,"explain":"Preferring pictures, diagrams, cartoons, or demonstrations defines a visual learner."},{"id":"SSPT11004","type":"mcq","cat":"Learning Styles","q":"Which statement best defines learning styles?","options":["The subjects students choose to study","The grades students receive in examinations","The length of time required to complete a course","The processes and techniques people use to learn"],"correct":3,"explain":"Learning styles are the processes and techniques people use to learn things (facts, skills, attitudes)."},{"id":"SSPT11005","type":"mcq","cat":"Learning Styles","q":"Which factors are included in a learner's learning style?","options":["Financial, social, and occupational factors","Physical, chemical, and environmental factors","Cognitive, affective, and physiological factors","Academic, athletic, and artistic factors only"],"correct":2,"explain":"A learning style encompasses cognitive, affective, and physiological factors — how a learner perceives, interacts with, and responds to the learning environment."},{"id":"SSPT11006","type":"mcq","cat":"Learning Styles","q":"Why is it important for learners to know their own learning style?","options":["It determines their final examination grade","It eliminates the need to attend classes","It guarantees that they will use only one learning method","It helps them seek learning situations that suit them"],"correct":3,"explain":"Knowing your style lets you seek situations and experiences that meet that style."},{"id":"SSPT11007","type":"mcq","cat":"Learning Styles","q":"Why is it useful for teachers to understand the learning styles of others?","options":["It allows them to replace all classroom activities","It allows them to avoid using teaching aids","It helps them teach and work in groups more effectively","It proves that all learners learn identically"],"correct":2,"explain":"Knowing how others learn helps you teach them and work in groups more effectively."},{"id":"SSPT11008","type":"mcq","cat":"Learning Styles","q":"Which learning style generally prefers pictures, diagrams, maps, and demonstrations?","options":["Kinesthetic","Auditory","Olfactory","Visual"],"correct":3,"explain":"Visual learners prefer to see information: pictures, diagrams, cartoons, maps, and demonstrations."},{"id":"SSPT11009","type":"mcq","cat":"Learning Styles","q":"Which behavior is characteristic of a visual learner?","options":["Avoiding all pictures, diagrams, cartoons, and demonstrations","Absorbing a long spoken lecture with very little effort","Preferring intense visuals combined with a long lecture","Being easily distracted when a lecture lacks visual aids"],"correct":3,"explain":"Visual learners are easily distracted without visual aids. They want pictures and diagrams, not avoid them; absorbing a talk effortlessly is auditory; intense visuals plus a lecture overwhelm them rather than please them."},{"id":"SSPT11010","type":"mcq","cat":"Learning Styles","q":"What is the main difference between verbal and non-verbal visual learners?","options":["Verbal visual learners prefer physical motion, whereas non-verbal visual learners prefer spoken sound","Verbal visual learners avoid printed pages, whereas non-verbal visual learners avoid drawn images","Verbal visual learners prefer tactile objects, whereas non-verbal visual learners prefer audible tones","Verbal visual learners prefer written words, whereas non-verbal visual learners prefer clear pictures"],"correct":3,"explain":"Both use the visual channel. Verbal visual = written words; non-verbal visual = pictures."},{"id":"SSPT11011","type":"mcq","cat":"Learning Styles","q":"Which study strategy is especially appropriate for a visual learner?","options":["Listen to lectures without looking at any materials","Use charts, maps, notes, and flashcards","Study only by walking around","Avoid writing down key ideas"],"correct":1,"explain":"Charts, maps, notes, and flashcards are core visual study tools; also sit near the front and use highlighters."},{"id":"SSPT11012","type":"mcq","cat":"Learning Styles","q":"Which characteristic is most typical of an auditory learner?","options":["Preferring diagrams over all spoken explanations","Preferring to hear information spoken","Remembering information only as written words","Learning primarily through touching objects"],"correct":1,"explain":"Auditory learners prefer to hear information spoken and can often absorb a lecture with little effort."},{"id":"SSPT11013","type":"mcq","cat":"Learning Styles","q":"Which study strategy is recommended for an auditory learner?","options":["Study only by drawing maps","Read study material aloud","Avoid discussions and tutorials","Use pictures without verbal explanation"],"correct":1,"explain":"Read assignments, directions, and new material out loud; record and replay; have test questions read aloud."},{"id":"SSPT11014","type":"mcq","cat":"Learning Styles","q":"Which activity is particularly suitable for supporting an auditory learner?","options":["Studying without any discussion","Joining a study group","Replacing all spoken material with diagrams","Avoiding tutorials"],"correct":1,"explain":"Join a study group, work with a study buddy, and attend discussions and tutorials — spoken, social channels."},{"id":"SSPT11015","type":"mcq","cat":"Learning Styles","q":"Which learning style prefers touch and motion as primary ways of taking in information?","options":["Visual","Verbal visual","Auditory","Kinesthetic"],"correct":3,"explain":"Kinesthetic learners prefer touch and motion as the primary mode for taking in information."},{"id":"SSPT11016","type":"mcq","cat":"Learning Styles","q":"Which activity best supports a kinesthetic learner?","options":["Memorizing diagrams without interaction","Avoiding movement while studying","Completing hands-on activities","Listening to a lecture without taking action"],"correct":2,"explain":"Hands-on work — touching, building, moving, acting out — supports kinesthetic learning."},{"id":"SSPT11017","type":"mcq","cat":"Learning Styles","q":"What should a kinesthetic learner do during a traditional lecture?","options":["Avoid recording any information","Write out important facts","Use only unrelated background music","Listen without participating in any way"],"correct":1,"explain":"During a traditional lecture, the kinesthetic learner should write out important facts."},{"id":"SSPT11018","type":"mcq","cat":"Learning Styles","q":"Which strategy is recommended for kinesthetic learners when studying for extended periods?","options":["Take frequent, short breaks","Remain completely still throughout study","Study continuously without moving","Avoid using flashcards"],"correct":0,"explain":"Take frequent but not long breaks; arrange flashcards in groups."},{"id":"SSPT11019","type":"mcq","cat":"Learning Styles","q":"Which statement best reflects the conclusion about learning styles?","options":["Be flexible in learning and adapt to different styles as you can","Each learner is purely one style and must never adapt to others","Styles cannot overlap, so only one method should ever be used","Use only your preferred style and ignore every other approach entirely"],"correct":0,"explain":"Be flexible and adapt to different styles as much as you can."},{"id":"SSPT11020","type":"mcq","cat":"Learning Styles","q":"Which statement about learners and learning styles is accurate?","options":["Every learner has only one permanent style that lasts for life","Learners cannot benefit at all from using different approaches","Most learners are mixed rather than purely one single style","Learning style is unrelated to any of a learner's preferences"],"correct":2,"explain":"No one is purely one style — learners are mixed."},{"id":"SSPT11021","type":"mcq","cat":"Learning Styles","q":"A student remembers information as clear pictures and benefits from videos, maps, and diagrams. Which type of learner is most likely?","options":["Verbal visual learner","Non-verbal visual learner","Kinesthetic learner","Auditory learner"],"correct":1,"explain":"Picture format + remembering clear pictures = non-verbal visual learner."},{"id":"SSPT11022","type":"mcq","cat":"Learning Styles","q":"A student prefers textbooks and written outlines and remembers written information mentally. Which type of learner is most likely?","options":["Verbal visual learner","Auditory learner","Non-verbal visual learner","Kinesthetic learner"],"correct":0,"explain":"Written format + remembering written words in the mind's eye = verbal visual learner."},{"id":"SSPT11023","type":"mcq","cat":"Learning Styles","q":"Which tool is recommended for discovering one's learning style?","options":["Physical fitness assessment","Handwriting speed test","Personality-free examination","Learning Styles Inventory"],"correct":3,"explain":"Discover your style by completing the Learning Styles Inventory."},{"id":"SSPT11024","type":"mcq","cat":"Learning Styles","q":"Which group includes most people?","options":["Most people are auditory learners","Most people are visual learners","Most people are purely kinesthetic learners","Most people have no identifiable style"],"correct":1,"explain":"Most people are visual learners."},{"id":"SSPT11025","type":"mcq","cat":"Learning Styles","q":"A visual learner who hears a new concept typically does which of the following?","options":["They store the words they hear only as spoken sounds","They turn the words they hear into mental pictures","They stand up and move before encoding any new idea","They ignore the words they hear and watch the board"],"correct":1,"explain":"Visual learners picture the words and concepts they hear as images."},{"id":"SSPT11026","type":"mcq","cat":"Learning Styles","q":"Which classroom placement tip is given specifically to visual learners?","options":["Sit at the back so the whole board is visible at once","Sit near the front of the classroom","Sit wherever the loudspeakers are strongest","Stand for the entire lecture"],"correct":1,"explain":"Visual tips begin with: sit near the front of the classroom."},{"id":"SSPT11027","type":"mcq","cat":"Learning Styles","q":"Which of the following is a listed study tip for visual learners?","options":["Color things and use highlighter pens","Avoid all written notes","Study only with loud background speech","Never draw a concept"],"correct":0,"explain":"Coloring, highlighters, drawing concepts, and writing key words are visual tips."},{"id":"SSPT11028","type":"mcq","cat":"Learning Styles","q":"Which auditory characteristic is easy to confuse with inattention?","options":["Preferring maps over speech","Often avoiding eye contact in order to concentrate","Needing intense visual slides in every minute of class","Refusing to join any spoken activity"],"correct":1,"explain":"Auditory learners often avoid eye contact to concentrate — easily mistaken for rudeness or inattention."},{"id":"SSPT11029","type":"mcq","cat":"Learning Styles","q":"Which statement about notes is most true of many auditory learners?","options":["They must copy every slide word for word or they learn nothing","They may not need careful notes to learn from a spoken lecture","They cannot learn unless the page is full of diagrams","They should never listen to a recording of the class"],"correct":1,"explain":"Auditory learners can absorb a lecture with little effort and may not need careful notes."},{"id":"SSPT11030","type":"mcq","cat":"Learning Styles","q":"Which extra check is recommended for auditory learners?","options":["Have your hearing checked on a regular basis","Have your colour vision checked every single week","Avoid sitting anywhere that lets you hear the speaker","Refuse all background music while you are studying"],"correct":0,"explain":"Sit where you can hear, and have your hearing checked regularly."},{"id":"SSPT11031","type":"mcq","cat":"Learning Styles","q":"Which set of motions is associated with kinesthetic learning?","options":["Hearing, jittering, walking, coloring, chewing, typing, and writing","Yo-yoing, jittering, walking, coloring, chewing, typing, and writing","Yo-yoing, jittering, walking, highlighting, chewing, typing, and writing","Yo-yoing, jittering, walking, coloring, chewing, typing, and outlining"],"correct":1,"explain":"Kinesthetic learners learn better while jittering, walking, yo-yoing, chewing, coloring, typing, or writing."},{"id":"SSPT11032","type":"mcq","cat":"Learning Styles","q":"Is chewing gum or rocking in a chair treated as acceptable for a kinesthetic learner?","options":["No — both are forbidden because they look informal","Yes — it is acceptable while reading or studying","Only chewing is allowed; rocking is not","Only if the instructor has left the room"],"correct":1,"explain":"Chewing gum, walking around, or rocking in a chair is acceptable while reading or studying."},{"id":"SSPT11033","type":"mcq","cat":"Learning Styles","q":"How should a kinesthetic learner use flashcards?","options":["They avoid flashcards and rely on spoken repetition","They read each flashcard once and then discard it","They group flashcards to show idea relationships","They view flashcards from afar and never handle them"],"correct":2,"explain":"Arrange flashcards in groups to show relationships between ideas — motion plus spatial structure."},{"id":"SSPT11034","type":"mcq","cat":"Learning Styles","q":"What is 'finger spelling' in the kinesthetic study tips?","options":["Signing an entire language instead of studying the written word","Tracing each word with your finger in order to learn spelling","Typing the word quickly without ever looking at the keys","Asking a study partner to write the word out for you"],"correct":1,"explain":"Trace words with your finger to learn spelling — a kinesthetic tool."},{"id":"SSPT11035","type":"mcq","cat":"Learning Styles","q":"Which tool is recommended for discovering your own learning style?","options":["The Cognitive, Affective, Physiological Factors (CAPF) inventory","The Visual, Aural, Read/Write, Kinesthetic (VARK) questionnaire","The Processes, Techniques, Facts, Attitudes (PTFA) inventory","The Perceive, Interact, Respond, Learn (PIRL) questionnaire"],"correct":1,"explain":"The source names only the VARK questionnaire as the discovery tool (vark-learn.com). The cognitive, affective, physiological factors describe a style, not an inventory; processes, techniques, facts, attitudes define learning; perceive, interact, respond, learn describe engagement — none is the named tool."},{"id":"SSPT11036","type":"matching","cat":"Learning Styles","q":"Match each learning style to how its learner learns best.","leftItems":[{"id":"1","text":"Visual"},{"id":"2","text":"Auditory"},{"id":"3","text":"Kinesthetic"}],"rightItems":[{"id":"A","text":"Learns best by seeing"},{"id":"B","text":"Learns best by hearing"},{"id":"C","text":"Learns best by feeling or experiencing"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Visual learns by seeing, auditory by hearing, kinesthetic by feeling or experiencing — the three-style overview."},{"id":"SSPT11037","type":"matching","cat":"Learning Styles","q":"Match each overlap of two or three learning styles to the preference label it carries.","leftItems":[{"id":"1","text":"Visual and Auditory overlap"},{"id":"2","text":"Visual and Kinesthetic overlap"},{"id":"3","text":"Auditory and Kinesthetic overlap"},{"id":"4","text":"All three styles overlap"}],"rightItems":[{"id":"A","text":"Loves YouTube"},{"id":"B","text":"Loves Instructors"},{"id":"C","text":"Loves Books (Needs Experienced Instructors)"},{"id":"D","text":"Legends"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Where visual and auditory overlap, learners love YouTube; visual and kinesthetic love instructors; auditory and kinesthetic love books and need experienced instructors; the centre of all three are legends."},{"id":"SSPT11038","type":"stepped","cat":"Learning Styles","q":"Visual learners split into two sub-types.","steps":[{"id":"1","prompt":"Which visual sub-type learns better when information is presented in a written format?","options":["Verbal visual","Non-verbal visual","Auditory","Kinesthetic"],"correct":0},{"id":"2","prompt":"Verbal visual learners benefit most from which set of visual aids?","options":["Projectors, outlines, textbooks, and class notes","Videos, maps, charts, diagrams, and illustrations","Discussions, tutorials, lectures, and recordings","Building, drawing, walking, and acting out stories"],"correct":0},{"id":"3","prompt":"Verbal visual learners prefer to work in quiet rooms how?","options":["Alone or with others","Alone only","With loud background music","While walking and chewing"],"correct":0}],"explain":"Verbal visual learners take written input (step 1), profit from projectors, outlines, textbooks, and class notes (step 2), and work in quiet rooms alone or with others (step 3) — unlike non-verbal visual learners, who prefer pictures and work alone."},{"id":"SSPT11039","type":"stepped","cat":"Learning Styles","q":"The other visual sub-type works differently.","steps":[{"id":"1","prompt":"Which visual sub-type learns better when information is presented in a picture format?","options":["Non-verbal visual","Verbal visual","Auditory","Kinesthetic"],"correct":0},{"id":"2","prompt":"Non-verbal visual learners benefit most from which set of visual aids?","options":["Videos, maps, charts, and diagrams","Projectors, outlines, textbooks, and class notes","Recording and replaying speech","Role-playing and manipulatives"],"correct":0},{"id":"3","prompt":"Non-verbal visual learners prefer to work in quiet rooms how?","options":["Alone only","Alone or with others","With a study buddy","While attending tutorials"],"correct":0},{"id":"4","prompt":"When remembering, what do non-verbal visual learners see?","options":["The pictures clearly","The written words by mind eyes","Spoken phrases replayed","Touched objects recalled"],"correct":0}],"explain":"Non-verbal visual learners take picture input (step 1), profit from videos, maps, charts, and diagrams (step 2), prefer quiet rooms alone (step 3), and recall by seeing the pictures clearly (step 4)."},{"id":"SSPT11040","type":"multi","cat":"Learning Styles","q":"Which of the following are characteristics of visual learners?","options":["Prefer to see pictures, diagrams, cartoons, or demonstrations","Picture the words and concepts they hear as images","Are easily distracted when a talk offers no pictures or charts","Feel overwhelmed when dense imagery accompanies a spoken talk","Can absorb a spoken lecture with very little effort","Like to have background music while they study","Prefer touch and motion as their primary input mode","Often avoid eye contact in order to concentrate"],"correct":[0,1,2,3],"explain":"Visual learners prefer pictures and diagrams, turn heard words into images, lose focus without visual support, and feel swamped by dense imagery plus speech; absorbing talks effortlessly, liking background music, avoiding eye contact, and preferring touch belong to auditory or kinesthetic learners."},{"id":"SSPT11041","type":"multi","cat":"Learning Styles","q":"Which of the following are characteristics of auditory learners?","options":["Prefer to hear information spoken rather than read it","Can absorb a lecture with very little effort","May read the material aloud to themselves","Like to have background music while they study","Prefer to see pictures, diagrams, or demonstrations","Are overwhelmed by intense imagery with a talk","Prefer touch and motion as primary input","Should write out important facts during a lecture"],"correct":[0,1,2,3],"explain":"Auditory learners favour spoken input, absorb lectures easily, may read aloud, and enjoy background music; preferring pictures, being swamped by imagery, and relying on touch or note-writing are visual or kinesthetic traits."},{"id":"SSPT11042","type":"multi","cat":"Learning Styles","q":"Which of the following are characteristics of kinesthetic learners?","options":["Prefer touch and motion as their primary input mode","Should write out important facts in a traditional lecture","Create study sheets linked to vivid examples","Find that role-playing helps them remember important ideas","May benefit by using manipulatives while learning","Prefer to hear information spoken rather than read it","Are easily distracted when a talk has no pictures","Like background music while they study"],"correct":[0,1,2,3,4],"explain":"Kinesthetic learners rely on touch and motion, write facts during lectures, link study sheets to vivid examples, use role-play, and gain from manipulatives; preferring spoken input, needing pictures, or liking background music are auditory or visual traits."},{"id":"SSPT11043","type":"stepped","cat":"Learning Styles","q":"Auditory learners have several study tips.","steps":[{"id":"1","prompt":"Where should an auditory learner sit in class?","options":["Where they can hear clearly","At the very back of the room","Near the window away from sound","Anywhere, as long as it is quiet"],"correct":0},{"id":"2","prompt":"After sitting where they can hear, what should an auditory learner do to learn spelling words?","options":["Record yourself spelling the words, then listen back","Trace each spelling word carefully with your finger","Draw a detailed picture of the word and then label it","Colour the entire word and use a fluorescent highlighter"],"correct":0},{"id":"3","prompt":"Besides recording spelling words to replay, how should an auditory learner deal with test questions?","options":["Have the test questions read out loud to them","Rewrite every test question in their own words","Convert each test question into a coloured diagram","Act out each test question as a short role-play"],"correct":0},{"id":"4","prompt":"Besides having test questions read aloud, whom should an auditory learner work with ongoing?","options":["A study buddy to review key information","A silent partner who never speaks","The instructor standing at the front","A computer reinforcing learning by touch"],"correct":0}],"explain":"Auditory learners sit where they can hear (step 1), record spelling words and replay them (step 2), have test questions read aloud (step 3), and work ongoing with a study buddy to review key information (step 4)."},{"id":"SSPT11044","type":"multi","cat":"Learning Styles","q":"Which of the following are study tips for visual learners?","options":["Write down key words, ideas, or instructions","Draw pictures to explain a concept, then explain them","Colour things and use highlighter pens","Avoid distractors during study times","Record yourself spelling words and listen to it","Rock in a chair or chew gum while studying","Attend discussions and tutorials regularly","Use a computer to learn through the sense of touch"],"correct":[0,1,2,3],"explain":"Visual tips include writing key words, drawing and explaining pictures, colouring with highlighters, and avoiding distractors; recording speech, rocking or chewing, attending tutorials, and touch-based computer use belong to auditory or kinesthetic learners."},{"id":"SSPT11045","type":"multi","cat":"Learning Styles","q":"Which of the following are study tips for kinesthetic learners?","options":["Take part in activities involving touching, building, moving, or drawing","Do hands-on work like art projects, walks, or acting out stories","Tap a pencil, shake a foot, or hold something while learning","Use a computer to reinforce learning through the sense of touch","Sit near the front of the classroom and watch the board","Read the assignments and the directions out loud to yourself","Colour your notes and use highlighter pens while studying","Have your hearing checked on a regular basis each term"],"correct":[0,1,2,3],"explain":"Kinesthetic tips centre on touching, building, moving, drawing, hands-on projects, fidgeting such as tapping or shaking, and touch-based computer use; sitting at the front, reading aloud, colouring notes, and hearing checks are visual or auditory tips."}]}},"banks/studyskills/lecture-2-goals-remake.json":{"id":"lecture-2-goals","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 2 – Goals","formSize":54,"forms":["A"],"bank":{"A":[{"id":"SSPT12000","type":"mcq","cat":"Goals","q":"'Something you want to achieve' is the definition of which of the following?","options":["Habit","Plan","Goal","Challenge"],"correct":2,"explain":"A goal is something you want to achieve; a habit is repeated behaviour, a plan is the route, a challenge is an obstacle."},{"id":"SSPT12001","type":"mcq","cat":"Goals","q":"Which of the following is a goal with an outcome that is based on a specific date / time?","options":["Fixed goals","Flexible goals","Condensed goals"],"correct":0,"explain":"A fixed goal's outcome is based on a specific date or time, a set deadline."},{"id":"SSPT12002","type":"mcq","cat":"Goals","q":"What type of goal is usually achieved over a period of 5 years?","options":["Short-term goal","Daily goal","Long-term goal"],"correct":2,"explain":"A long-term goal is usually achieved over about 5 years."},{"id":"SSPT12003","type":"mcq","cat":"Goals","q":"What does the 'S' in SMART goals stand for?","options":["Specific","Significant","Strategic"],"correct":0,"explain":"S = Specific, a named target, not a vague wish."},{"id":"SSPT12004","type":"mcq","cat":"Goals","q":"What does the 'M' in SMART goals stand for?","options":["Motivational","Measurable","Mandatory","Mysterious"],"correct":1,"explain":"M = Measurable, so you can count whether it happened."},{"id":"SSPT12005","type":"mcq","cat":"Goals","q":"What does the 'A' in SMART goals stand for?","options":["Abstract (Vague)","Ambitious (Lofty)","Action-Oriented (Attainable)","Automatic (Instinctive)"],"correct":2,"explain":"In SMART, A is Action-Oriented, also called Attainable. Abstract, Ambitious and Automatic are not the SMART reading of the letter A."},{"id":"SSPT12006","type":"mcq","cat":"Goals","q":"What does the 'R' in SMART goals stand for?","options":["Rigid (Stiff)","Realistic (Relevant)","Random (Chance)","Reserved (Held-back)"],"correct":1,"explain":"In SMART, R is Realistic, also called Relevant. Rigid, Random and Reserved are not the SMART reading of the letter R."},{"id":"SSPT12007","type":"mcq","cat":"Goals","q":"What does the 'T' in SMART goals stand for?","options":["Temporary","Theoretical","Trendy","Time-bound"],"correct":3,"explain":"T = Time-bound, meaning a deadline exists."},{"id":"SSPT12008","type":"mcq","cat":"Goals","q":"Which statement best defines goals?","options":["Vague wishes about the distant future with no real plan","Well-defined plans aimed at achieving a specific result","Grades awarded by an examiner rather than chosen by you","The subjects a student is forced to take against their will"],"correct":1,"explain":"Goals are well-defined plans aimed at a specific result. Vague distant wishes, examiner-awarded grades, and forced subjects are not the chosen, planned course of action that goals describe."},{"id":"SSPT12009","type":"mcq","cat":"Goals","q":"Besides being plans, goals are described as which of the following?","options":["Roadmaps for achieving what you want in life","Substitutes for attending class","Guarantees of a high Grade Point Average (GPA)","Personality types that cannot change"],"correct":0,"explain":"Goals are roadmaps for achieving what you want in life, a course of action you intend to pursue."},{"id":"SSPT12010","type":"mcq","cat":"Goals","q":"What do goals reflect?","options":["Only the college timetable","Only what other people expect","Your values and your priorities","Random interest with no hierarchy"],"correct":2,"explain":"Goals reflect your values and your priorities."},{"id":"SSPT12011","type":"mcq","cat":"Goals","q":"A plan for where you want to be five years from now is classified as a:","options":["Short-term goal","Medium-range goal","Long-term goal","Daily habit only"],"correct":2,"explain":"The five-year plan is a long-term goal: 'Five years from now, I will be…'"},{"id":"SSPT12012","type":"mcq","cat":"Goals","q":"A person without goals is compared to which image?","options":["A clock that keeps ticking with no direction or end","A sheep in the pasture living from day to day","A mountain peak too high for anyone to ever climb","A library whose empty shelves hold no books at all"],"correct":1,"explain":"The sheep image stands for a person without goals, drifting day to day. A directionless clock, an unclimbable mountain, and an empty library are not that comparison."},{"id":"SSPT12013","type":"mcq","cat":"Goals","q":"In SMART goals, the letter S stands for:","options":["Spontaneous","Specific","Seasonal","Silent"],"correct":1,"explain":"S is Specific, as in 'Complete 33 credits by May', not 'do better'."},{"id":"SSPT12014","type":"mcq","cat":"Goals","q":"In SMART goals, the letter M stands for:","options":["Motivational","Mysterious","Measurable","Maximum"],"correct":2,"explain":"M is Measurable, such as credits, GPA, and hours studied."},{"id":"SSPT12015","type":"mcq","cat":"Goals","q":"In the SMART list, A stands for Action-oriented, which is also glossed as:","options":["Abstract","Ambitious","Attainable","Avoidant"],"correct":2,"explain":"A is Action-Oriented, with Attainable in parentheses."},{"id":"SSPT12016","type":"mcq","cat":"Goals","q":"In the SMART list, R stands for Realistic, which is also glossed as:","options":["Random","Relevant","Rigid","Rare"],"correct":1,"explain":"R is Realistic, with Relevant in parentheses."},{"id":"SSPT12017","type":"mcq","cat":"Goals","q":"In SMART goals, the letter T stands for:","options":["Theoretical","Time-bound","Temporary only","Team-based"],"correct":1,"explain":"T is Time-bound, because a deadline turns a wish into a schedule."},{"id":"SSPT12018","type":"mcq","cat":"Goals","q":"Achieving a long-term goal is compared to:","options":["Winning a single lottery ticket","Building a pyramid","Waiting for motivation to arrive","Memorizing one quotation"],"correct":1,"explain":"Achieving a long-term goal is like building a pyramid: short-term base, medium middle, long-term peak."},{"id":"SSPT12019","type":"mcq","cat":"Goals","q":"In the goal pyramid, medium-range goals sit at approximately which horizon?","options":["Today only","1–2 years from now","10–20 years from now","The next 20 minutes"],"correct":1,"explain":"Medium-range = 1–2 years; long-term ≈ 5 years; short-term = daily and weekly."},{"id":"SSPT12020","type":"mcq","cat":"Goals","q":"Short-term goals are mainly:","options":["Five-year career titles","Daily and weekly habits and assignments","Retirement plans","Other people's expectations"],"correct":1,"explain":"Short-term goals are the daily and weekly habits and assignments that form the pyramid's foundation."},{"id":"SSPT12021","type":"mcq","cat":"Goals","q":"What happens once short-term goals are met, according to the goal pyramid?","options":["Mid-range goals follow more easily","Long-term goals become unnecessary","You should stop writing new goals","Study hours can drop to zero"],"correct":0,"explain":"Once short-term goals are met, mid-range goals follow more easily."},{"id":"SSPT12022","type":"mcq","cat":"Goals","q":"Which hint is given for keeping goals visible?","options":["Keep them only in your head so they stay fully private and unseen","Write them down and put them where you will see them every day","Tell no one about them and review them only once each entire year","Write them on an exam script only and hide them from daily view"],"correct":1,"explain":"The hint is to write goals where you will see them every day. Keeping them private in your head, reviewing once a year, or hiding them on an exam script are not that hint."},{"id":"SSPT12023","type":"mcq","cat":"Goals","q":"If a short-term goal is not working, you should:","options":["Abandon the long-term goal immediately","Change the short-term goal","Study in one 12-hour marathon to force it","Ignore the problem until the year ends"],"correct":1,"explain":"Change the short-term goal if it is not working; the long-term peak stays while the weekly block is redesigned."},{"id":"SSPT12024","type":"mcq","cat":"Goals","q":"Which statement matches the advice on how high to aim?","options":["Aim far below what you can do so you never miss a thing","Be realistic but aim higher than you think you can achieve","Aim only at what is already finished and never reach beyond it","Never write a single number inside any goal that you set"],"correct":1,"explain":"The advice is to be realistic yet aim higher than you think, so you surprise yourself. Aiming far below, aiming only at finished things, or refusing any number all contradict it."},{"id":"SSPT12025","type":"mcq","cat":"Goals","q":"'Make sure you understand the price of reaching your goals' means you should:","options":["Ignore the cost and hope that pure luck will eventually pay it","Know what time, effort, and trade-offs the goal will require","Pay another person money so they will hold the goal for you","Treat money as the only real price that exists anywhere in life"],"correct":1,"explain":"Understanding the price means knowing the time, effort and trade-offs a goal demands. Ignoring the cost, paying someone else to carry it, or treating money as the only price all miss it."},{"id":"SSPT12026","type":"mcq","cat":"Goals","q":"What should you do with obstacles to a five-year goal?","options":["Pretend that the obstacles simply do not exist and just ignore them forever","Recognize them, judge how much control you have, then avoid or eliminate them","List them once on paper and then never look at that list again","Treat every single obstacle as an unavoidable fate that you can never change"],"correct":1,"explain":"You should recognize obstacles, judge your control, then avoid or eliminate them. Pretending they vanish, listing them once, or treating them as fate all skip the active step."},{"id":"SSPT12027","type":"mcq","cat":"Goals","q":"Which study-habit cluster is listed as a powerful way to reach academic goals?","options":["One monthly marathon, starting after midnight, with no calendar and no weekly review of notes or textbook reading","20–25 hours a week outside class, in small bits of time, with most studying done before 10:00 p.m.","Zero hours outside class if the lecture was attended, relying on memory and never opening the textbook weekly","Only group work after 1:00 a.m., with no individual schedule, no office-hour visits, and no review before midnight"],"correct":1,"explain":"The habit cluster is 20–25 hours a week outside class, studied in small bits, mostly before 10:00 p.m. A monthly midnight marathon, zero outside hours, or only late group work are not it."},{"id":"SSPT12028","type":"mcq","cat":"Goals","q":"The opening quotation by J.C. Penney contrasts a stock clerk who has a goal with:","options":["A stock clerk who has no goal","A professor who has no students","A student who has no textbooks","A clock with no hands"],"correct":0,"explain":"'Give me a stock clerk with a goal and I'll give you a man who will make history. Give me a man with no goals and I'll give you a stock clerk.'"},{"id":"SSPT12029","type":"mcq","cat":"Goals","q":"Which of the following is an example of a short-term academic block on the goal pyramid?","options":["Owning a three-bedroom house with a pool and deck","Create a study schedule and go to every class","Financial independence at the very end of a career","A dream job at a high named salary only"],"correct":1,"explain":"Creating a study schedule and attending every class are short-term foundation blocks. The dream house, financial independence, and the salaried dream job sit higher on the life pyramid."},{"id":"SSPT12030","type":"mcq","cat":"Goals","q":"As the semester or year ends, what should happen to short-term and mid-range goals?","options":["They should be frozen forever","They should be replaced with new ones","They should be deleted and never rewritten","They should be converted into quotes only"],"correct":1,"explain":"Replace short-term and mid-range goals with new ones; the long-term peak can remain."},{"id":"SSPT12031","type":"mcq","cat":"Goals","q":"Dr. Boyce Watkins is quoted as saying the path to greatness is usually paved with:","options":["Perfect success on the very first try","Failure, after trying over and over again","One single lucky weekend of easy wins","Avoiding all feedback along the entire way"],"correct":1,"explain":"Watkins says the path to greatness is paved with failure after repeated trying. Perfect first attempts, one lucky weekend, or avoiding feedback all contradict that saying."},{"id":"SSPT12032","type":"mcq","cat":"Goals","q":"Which morning habit is listed first among the powerful habits?","options":["Get up at a different time each day to stay flexible","Get up at the same time every morning","Sleep until noon if the night was long","Skip mornings and study only after 10:00 p.m."],"correct":1,"explain":"Get up at the same time every morning, then keep a regular schedule."},{"id":"SSPT12033","type":"mcq","cat":"Goals","q":"Which tracking tool is recommended for assignments and appointments?","options":["Memory alone","A to-do list or appointment calendar","A motivational poster with no dates","Someone else's timetable only"],"correct":1,"explain":"Use a to-do list or appointment calendar for assignments and appointments."},{"id":"SSPT12034","type":"mcq","cat":"Goals","q":"Which human-contact habits are listed as supports for reaching goals?","options":["Avoid all instructors until the final exam, never forming a group or using office hours or skills class","Find a study partner, use office hours, attend study-skills class, and meet the instructor after the first exam","Only message classmates the night before the test, skipping office hours, the study skills class, and instructor meeting","Never form a group, shun office hours, skip the study skills class, and avoid the instructor after exams"],"correct":1,"explain":"The supporting habits are a study partner and groups, office-hour visits, the study skills class, and meeting the instructor after the first exam. Avoiding instructors, messaging only the night before, or never grouping are not these."},{"id":"SSPT12035","type":"mcq","cat":"Goals","q":"Why meet the instructor after the first exam?","options":["To argue the grade with no plan to change anything","To learn from mistakes and get feedback","To cancel the rest of the semester","To replace the long-term goal with a complaint"],"correct":1,"explain":"To learn from mistakes and get feedback."},{"id":"SSPT12036","type":"mcq","cat":"Goals","q":"For a goal to be realized, you must develop:","options":["Only a motivational quotation posted on the bedroom wall","An action plan and implementation intentions","A completely new personality that you do not yet have","A promise you write with no calendar behind it"],"correct":1,"explain":"A realized goal needs an action plan and implementation intentions. A quotation alone, a brand-new personality, or a promise with no calendar do not turn a goal into achieved work."},{"id":"SSPT12037","type":"mcq","cat":"Goals","q":"An action plan should specify which four points?","options":["Why other people should work, who to blame, which app to buy, and a motto","When, where, how, and for how long one is to act","Only the dream outcome and the feeling after success","The grade you want and nothing else"],"correct":1,"explain":"When, where, how, and for how long, closing the door that time opens for distraction."},{"id":"SSPT12038","type":"mcq","cat":"Goals","q":"In Pham and Taylor (1999), students who focused mental simulation on the outcome (seeing the high grade and the feeling) tended to:","options":["Study more and earn better grades","Study less and earn poorer grades","Need no action plan at all","Sleep through the midterm with no cost"],"correct":1,"explain":"The outcome group studied less and earned poorer grades, for fantasy of the trophy is not rehearsal of the work."},{"id":"SSPT12039","type":"mcq","cat":"Goals","q":"In the same study, students who focused mental simulation on the process (seeing themselves actually studying) tended to:","options":["Study more and earn better grades","Abandon the midterm","Need more outcome daydreaming","Perform worse than the outcome group"],"correct":0,"explain":"The process group studied more and earned better grades: picture the work, not the trophy."},{"id":"SSPT12040","type":"matching","cat":"Goals","q":"Match each personal task for keeping track of progress to its description.","leftItems":[{"id":"1","text":"Self-regulation"},{"id":"2","text":"Monitor progress"},{"id":"3","text":"Intermediate goals"},{"id":"4","text":"Timetable"}],"rightItems":[{"id":"A","text":"the individual's duty to modify the plan as necessary"},{"id":"B","text":"keeping an eye on how far you have come"},{"id":"C","text":"milestones set along the path"},{"id":"D","text":"used together with the action plan"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Self-regulation is the individual's duty to modify the plan as necessary. Monitoring progress means keeping an eye on how far you have come. Intermediate goals are milestones set along the path. A timetable is used together with the action plan."},{"id":"SSPT12041","type":"matching","cat":"Goals","q":"Match each mental-simulation term to its description.","leftItems":[{"id":"1","text":"Outcome simulation"},{"id":"2","text":"Process simulation"},{"id":"3","text":"Outcome group"},{"id":"4","text":"Process group"}],"rightItems":[{"id":"A","text":"visualizes the high grade and the feeling"},{"id":"B","text":"visualizes the studying that earns the grade"},{"id":"C","text":"studied less and earned poorer grades"},{"id":"D","text":"studied more and earned better grades"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Outcome simulation visualizes the high grade and the feeling; process simulation visualizes the studying that earns it. The outcome group studied less with poorer grades, while the process group studied more with better grades."},{"id":"SSPT12042","type":"stepped","cat":"Goals","q":"On the life pyramid, each reached goal builds toward the next.","steps":[{"id":"1","prompt":"The bachelor's-degree block at the base of the life pyramid carries which target GPA?","options":["4.55 GPA","4.5 GPA"],"correct":0},{"id":"2","prompt":"After the block carrying the 4.55 GPA, which block does the arrow point to next?","options":["Dream job","Dream house","Marriage and family","Financial independence"],"correct":0},{"id":"3","prompt":"After the dream job, the two-way arrow reaches one box and a lower box also appears; which option names the arrow box and the lower box?","options":["Financial independence and marriage and family","Dream house and financial independence","Marriage and family and dream house","Financial independence and dream house"],"correct":0}],"explain":"Step 1: the bachelor's-degree block carries a 4.55 GPA target. Step 2: the arrow from that block points to the dream job. Step 3: the job's two-way arrow reaches financial independence, and the lower box is marriage and family."},{"id":"SSPT12043","type":"mcq","cat":"Goals","q":"What is the stated purpose of setting goals?","options":["They give direction and focus on where you end up","They guarantee a high grade point average without effort","They replace the need for any action plan","They copy what other people expect of you"],"correct":0,"explain":"Setting goals gives direction and keeps you focused on where you want to end up. They do not guarantee grades without work, they do not replace an action plan, and they reflect your own values, not others' expectations."},{"id":"SSPT12044","type":"mcq","cat":"Goals","q":"Goals represent which of the following?","options":["A course of action you intend to pursue","A routine repeated without any intention","An outcome that arrives with no planning","A road that others have chosen for you"],"correct":0,"explain":"Goals represent a course of action you intend to pursue. They are not mindless routines, they do not arrive without planning, and they are roads you choose yourself, not ones others pick for you."},{"id":"SSPT12045","type":"mcq","cat":"Goals","q":"Which description matches a flexible goal?","options":["An outcome with no time limit attached","An outcome tied to a specific date or time","A daily or weekly habit and assignment","An outcome planned about five years ahead"],"correct":0,"explain":"A flexible goal has an outcome but no time limit. A specific date or time marks a fixed goal, daily and weekly habits are short-term, and five years ahead is long-term."},{"id":"SSPT12046","type":"mcq","cat":"Goals","q":"Per the goal reminders, what should you allow yourself to do?","options":["Dream about goals and hold the long-term one in mind","Forget the long-term goal and only chase daily wins","Hide every single goal so only you know them","Replace the long-term goal each and every single week"],"correct":0,"explain":"The reminders say to allow yourself to dream about your goals and keep the long-term one in mind. Forgetting it, hiding the goals, or replacing the long-term goal weekly all contradict that advice."},{"id":"SSPT12047","type":"mcq","cat":"Goals","q":"Besides waking at the same time each morning, which habit builds a routine?","options":["Establish a regular schedule for yourself","Change your wake time daily for flexibility","Skip scheduling and study only when motivated","Let the college set every hour for you"],"correct":0,"explain":"The habit is to establish a regular schedule for yourself, alongside getting up at the same time each morning. Varying your wake time, waiting for motivation, or letting the college schedule you all undermine that routine."},{"id":"SSPT12048","type":"mcq","cat":"Goals","q":"In the obstacles exercise, how much time and how many obstacles are you asked to write?","options":["Two minutes to write three possible obstacles","Three minutes to write two possible obstacles","Two minutes to write five possible obstacles","Three minutes to write three possible obstacles"],"correct":0,"explain":"The exercise asks for two minutes to write three possible obstacles that might block the five-year goal. Swapping the numbers, inflating the count, or changing the minutes all misstate the instruction."},{"id":"SSPT12049","type":"mcq","cat":"Goals","q":"Which of these is NOT listed as a semester short-term block?","options":["Meet with my advisor this semester","Find a tutor for my courses","Skip every class to save time","Review my notes every single week"],"correct":2,"explain":"Meeting the advisor, finding a tutor, and reviewing notes weekly are foundation blocks. Skipping every class is the opposite of the listed block 'go to every class', so it is not a short-term goal here."},{"id":"SSPT12050","type":"multi","cat":"Goals","q":"Which of these are medium-range blocks on the reminder pyramid?","options":["Complete 33 credits by May","Reach a 4.5 GPA by Fall","Choose the minor you want","Apply for summer training program","Buy a three-bedroom house with pool"],"correct":[0,1,2,3],"explain":"The medium-range blocks are 33 credits by May, a 4.5 GPA by Fall, choosing a minor, and applying for summer training. The three-bedroom house is a long-term life-pyramid dream, not a medium-range block."},{"id":"SSPT12051","type":"matching","cat":"Goals","q":"Match each goal type to its description.","leftItems":[{"id":"1","text":"Fixed"},{"id":"2","text":"Flexible"},{"id":"3","text":"Short-term"},{"id":"4","text":"Medium-range"},{"id":"5","text":"Long-term"}],"rightItems":[{"id":"A","text":"tied to a set date or time"},{"id":"B","text":"has an outcome but no deadline"},{"id":"C","text":"daily and weekly habits and tasks"},{"id":"D","text":"about one to two years out"},{"id":"E","text":"roughly a five-year horizon"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Fixed goals are tied to a set date or time; flexible goals have an outcome but no deadline; short-term goals are daily and weekly habits; medium-range goals sit about one to two years out; long-term goals span roughly five years."},{"id":"SSPT12052","type":"multi","cat":"Goals","q":"Which statements describe an action plan?","options":["State when, where, how, and how long to act","Accept that accomplishing your goals takes real time","Recognize that time opens doors for distraction","Assume a plan removes every difficulty at once"],"correct":[0,1,2],"explain":"An action plan states when, where, how and how long to act, accepts that goals take time, and recognizes time opens doors for distraction. Believing a plan erases difficulty at once is false."},{"id":"SSPT12053","type":"multi","cat":"Goals","q":"Which statements describe keeping track of progress?","options":["Treat the whole task as self-regulation","Monitor progress and modify the plan yourself","Set intermediate goals as milestones along the path","Pair a timetable with the action plan","Wait for the college to monitor your progress"],"correct":[0,1,2,3],"explain":"Keeping track means self-regulation: you monitor and modify the plan, set intermediate milestones, and pair a timetable with the action plan. Waiting for the college to monitor you is the opposite of self-regulation."}]}},"banks/studyskills/lecture-3-time-management.json":{"id":"lecture-3-time-management","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 3 – Time Management","formSize":78,"forms":["A"],"bank":{"A":[{"id":"SSPT13000","type":"mcq","cat":"Time Management","q":"Which quadrant has tasks that are Not Urgent and Important?","options":["Quadrant 1","Quadrant 2","Quadrant 3","Quadrant 4"],"correct":1,"explain":"Quadrant 2 = Not Urgent + Important: planning, prevention, preparation."},{"id":"SSPT13001","type":"mcq","cat":"Time Management","q":"What does 'urgent' mean?","options":["Tasks that you can safely postpone to any later time","Tasks connected only to your distant long-term goals","Tasks that demand your immediate attention right NOW","Tasks that serve your mission, values, and priorities"],"correct":2,"explain":"Urgent means it requires attention NOW."},{"id":"SSPT13002","type":"mcq","cat":"Time Management","q":"Which term means judging each task by its worth and its deadline?","options":["Scheduling","Planning","Priorities","Organization"],"correct":2,"explain":"Priorities = a value judgment on each task by its worth and its deadline."},{"id":"SSPT13003","type":"mcq","cat":"Time Management","q":"Which of the following is known as the enemy of time management?","options":["Setting goals","Procrastination","Prioritizing tasks","Self-evaluation"],"correct":1,"explain":"Procrastination is the enemy of time management."},{"id":"SSPT13004","type":"mcq","cat":"Time Management","q":"Which statement best defines time management?","options":["Completing as many separate tasks as you possibly can in a single day without any planning at all","Developing the processes and tools that increase your efficiency and productivity","Spending every single available hour of the entire week purely on academic work","Avoiding all of the activities that seem to require your immediate attention today"],"correct":1,"explain":"Time management = developing processes and tools that increase efficiency and productivity."},{"id":"SSPT13005","type":"mcq","cat":"Time Management","q":"Which statement best distinguishes an urgent activity from an important activity?","options":["Urgent activities tend to feel enjoyable, whereas important activities always feel quite difficult and demanding","Urgent activities are always important, while important activities are never ever urgent in any way","Urgent activities need immediate attention; important activities serve your mission, values, and priorities","Urgent activities are distant long-term goals, while important activities are mere daily interruptions"],"correct":2,"explain":"Urgent = immediate attention (a timing claim); important = contributes to priorities and values (a mission claim)."},{"id":"SSPT13006","type":"mcq","cat":"Time Management","q":"A critical assignment due today greatly affects a student's progress. Which quadrant?","options":["Quadrant I: Urgent and Important","Quadrant IV: Not Urgent and Not Important","Quadrant III: Urgent and Not Important","Quadrant II: Not Urgent and Important"],"correct":0,"explain":"Due today = urgent; major effect on progress = important → Quadrant I."},{"id":"SSPT13007","type":"mcq","cat":"Time Management","q":"Which activity is the best example of Quadrant II: Not Urgent and Important?","options":["Playing games during scheduled study time","Responding to a crisis that requires immediate action","Planning a study schedule before examinations begin","Answering an unimportant interruption immediately"],"correct":2,"explain":"Planning before exams is important but not pressing today, making it the classic Quadrant II activity."},{"id":"SSPT13008","type":"mcq","cat":"Time Management","q":"Why is Quadrant II called the heart of personal quality management?","options":["It consists mainly of entertainment and pure time-wasting activities with no real value","It lets people comfortably avoid all of their everyday responsibilities entirely","It holds every single urgent crisis that has to be solved right now immediately","It centers on planning, capacity building, prevention, and preparation"],"correct":3,"explain":"Quadrant II focuses on planning, capacity development, prevention, and preparation."},{"id":"SSPT13009","type":"mcq","cat":"Time Management","q":"What is likely to happen when a person consistently neglects Quadrant II activities?","options":["Every single task on the list will become less important","The person will manage to eliminate all interruptions permanently","The person will no longer have any need to prioritize tasks","Important activities may drift into Quadrant I as urgent crises"],"correct":3,"explain":"Neglected QII items get promoted into Quadrant I as urgent crises."},{"id":"SSPT13010","type":"mcq","cat":"Time Management","q":"Which is the most appropriate first priority when several tasks compete for attention?","options":["The task carrying the greatest value and the nearest deadline","The very task that your instructor happened to assign to you most recently of all","The easiest task to finish, regardless of how important it is","The task that you personally find the most enjoyable to do"],"correct":0,"explain":"First priority = greatest value + nearest deadline."},{"id":"SSPT13011","type":"mcq","cat":"Time Management","q":"Which combination represents the three key steps to good time management?","options":["Hourly meetings, continuous messaging, and task avoidance","Daily exercise, social media review, and spontaneous planning","Weekly schedule, daily to-do-list, and long-term planning","Crisis response, multitasking, and delaying difficult tasks"],"correct":2,"explain":"Weekly schedule + daily to-do list + long-term planning."},{"id":"SSPT13012","type":"mcq","cat":"Time Management","q":"What is the primary purpose of developing a weekly schedule?","options":["To completely replace any need for daily planning or lists","To make sure that every single minute is spent working","To give an overview of your committed time and free time","To keep a record of only the tasks left unfinished"],"correct":2,"explain":"A weekly schedule shows committed time against available time."},{"id":"SSPT13013","type":"mcq","cat":"Time Management","q":"What behavior is an early warning sign of time-management problems?","options":["Frequently asking teachers for extensions","Using a long-term plan to organize future work","Completing important tasks before their deadlines","Preparing a weekly schedule in advance"],"correct":0,"explain":"Regularly asking for extensions is an early warning sign."},{"id":"SSPT13014","type":"mcq","cat":"Time Management","q":"What is likely a consequence of procrastinating on an important academic task?","options":["More sleep and improved learning","Increased anxiety and poorer-quality work","Lower stress without any disadvantages","More time for completing the task carefully"],"correct":1,"explain":"Procrastination → increased anxiety and poorer-quality work."},{"id":"SSPT13015","type":"mcq","cat":"Time Management","q":"Which task belongs in Quadrant III: Urgent and Not Important?","options":["Carefully preparing your overall long-term academic study strategy for the whole term","Finishing a high-stakes critical assignment that is due today","An interruption needing attention now but serving no real priority","Casually playing a game when no deadline or benefit exists"],"correct":2,"explain":"QIII = urgent but does not support major priorities, the classic interruption."},{"id":"SSPT13016","type":"mcq","cat":"Time Management","q":"Which activity is the clearest example of Quadrant IV: Not Urgent and Not Important?","options":["Preventing future academic problems through careful forward planning","Completing a high-value critical task that is due today","Responding promptly to a serious and unexpected emergency","Spending study time on games and unnecessary chatting"],"correct":3,"explain":"Games and unnecessary chatting = neither deadline nor payoff = QIV."},{"id":"SSPT13017","type":"mcq","cat":"Time Management","q":"Which outcome is a direct benefit of effective time management?","options":["A firm guarantee that no urgent task will ever occur again","Less anxiety because of better preparation and clear prioritization","The rare ability to finish absolutely all tasks at once","The total and complete elimination of every single one of your daily responsibilities"],"correct":1,"explain":"Better preparation and prioritization reduce anxiety."},{"id":"SSPT13018","type":"mcq","cat":"Time Management","q":"A student wants to spend more time on important activities and reduce last-minute crises. Which strategy is best?","options":["Concentrate mainly on interruptions simply because they feel immediate","Schedule important activities early and review them each week","Delay starting any task until it finally becomes urgent","Wait until inner motivation arrives before touching important work"],"correct":1,"explain":"Plan important activities early and review them weekly, a deliberate QII investment."},{"id":"SSPT13019","type":"mcq","cat":"Time Management","q":"Which statement best defines Time Management?","options":["An inborn natural talent that only a fortunate few people are simply ever born with","The total number of hours that a single dedicated student spends studying each week","A clever and highly systematic method of dodging every single urgent and pressing task","The development of processes and tools that increase efficiency and productivity"],"correct":3,"explain":"TM = development of processes and tools that increase efficiency and productivity."},{"id":"SSPT13020","type":"mcq","cat":"Time Management","q":"Time management is also defined as the ability to:","options":["Work on the tasks that you personally enjoy the most each day","Get things done when they should be done","Memorize the entire college timetable by heart","Avoid deadlines by carefully renegotiating them each time"],"correct":1,"explain":"Get things done when they should be done: right task, right time."},{"id":"SSPT13021","type":"mcq","cat":"Time Management","q":"How does time management develop?","options":["It is a skill requiring steady work, a lifelong challenge for most","It simply happens on its own as a person grows older","It can be learned once early on and then forgotten forever","It stays permanently and totally fixed at exactly the same level for every single person"],"correct":0,"explain":"It is a skill that must be worked on, a life-long challenge for most people."},{"id":"SSPT13022","type":"mcq","cat":"Time Management","q":"In the matrix, 'urgent' activities are those requiring:","options":["Careful long-term planning","Permission from a supervisor","Immediate attention (NOW)","A written budget first"],"correct":2,"explain":"Urgent = immediate attention (NOW)."},{"id":"SSPT13023","type":"mcq","cat":"Time Management","q":"In the matrix, 'important' activities are those that:","options":["Tend to be the loudest and the most visible of all the daily tasks","Always appear right at the very top of your crowded and busy inbox","Can safely be handed off and delegated to just about anyone around","Contribute to your mission, your values, and your priorities"],"correct":3,"explain":"Important = contributes to your mission, values, and priorities."},{"id":"SSPT13024","type":"mcq","cat":"Time Management","q":"If an activity is urgent, does that automatically mean it is important?","options":["Yes, because a task being urgent proves that it is equally important","It does, provided a teacher personally assigned that particular task","No, an urgent activity can still contribute nothing to your mission","It does, during the busy weeks when formal examinations are being held"],"correct":2,"explain":"No, urgency is a timing claim; importance is a mission claim."},{"id":"SSPT13025","type":"mcq","cat":"Time Management","q":"Which items belong to Quadrant I (Urgent & Important)?","options":["Trivia, busy work, distractions, and time wasters such as chatting and pointless idle daily games","Crisis, pressing problems, and deadline-driven projects critical to your strategic priorities","Interruptions, some calls, some mails, some reports, some meetings, and many popular activities","Chatting, games, excessive TV, and other not-urgent not-important time-wasting daily pastimes"],"correct":1,"explain":"QI: crisis, pressing problems, deadline-driven projects critical to strategic priorities."},{"id":"SSPT13026","type":"mcq","cat":"Time Management","q":"Which items belong to Quadrant II (Not urgent & Important)?","options":["Preventing problems, strategy planning, relationship building, and recognizing new opportunities","Reacting to sudden crises, working long deadline-driven all-nighters, and constant daily firefighting","Fielding nonstop interruptions, taking some calls, and dealing with every single pressing matter","Indulging in trivia, busy work, distractions, and pointless chatting and games daily time wasters"],"correct":0,"explain":"QII: prevention, anticipation, strategy planning, relationship building, new opportunities."},{"id":"SSPT13027","type":"mcq","cat":"Time Management","q":"Which items belong to Quadrant III (Urgent & Not important)?","options":["Interruptions, some calls, some mails, some reports, some meetings, and pressing matters","Preventing problems, strategy planning, relationship building, and recognizing opportunities","Crisis, pressing problems, and deadline-driven projects critical to your strategic priorities","Trivia, busy work, distractions, and time wasters such as chatting and games and excessive TV"],"correct":0,"explain":"QIII: interruptions, some calls/mails/reports/meetings, pressing matters."},{"id":"SSPT13028","type":"mcq","cat":"Time Management","q":"Which items belong to Quadrant IV (Not urgent & Not important)?","options":["Confronting sudden crises and other pressing important problems head-on","Investing steady time in careful relationship-building activities","Trivia, busy work, distractions, and wasters like chat and games","Putting real effort into preventing your future important problems"],"correct":2,"explain":"QIV: trivia, busy work, distractions, time wasters (chatting and games)."},{"id":"SSPT13029","type":"mcq","cat":"Time Management","q":"Which quadrant is called 'the heart of the personal quality management'?","options":["Quadrant I: Urgent & Important","Quadrant II: Not urgent & Important","Quadrant III: Urgent & Not important","Quadrant IV: Not urgent & Not important"],"correct":1,"explain":"Quadrant II is 'the heart of the personal quality management'."},{"id":"SSPT13030","type":"mcq","cat":"Time Management","q":"To lead effectively, you need to spend more time in:","options":["Quadrant I: personally handling every crisis","Quadrant II: important but not urgent work","Quadrant III: answering every interruption","Quadrant IV: recovering from the week"],"correct":1,"explain":"Spend more time in Quadrant II, the Important but not Urgent quadrant."},{"id":"SSPT13031","type":"mcq","cat":"Time Management","q":"What happens when you do not spend enough time in Quadrant II?","options":["Your personal mission and your core values change all by themselves automatically","Many items move over into Quadrant I, and you are constantly handling crises","All of the Quadrant IV distraction items simply disappear forever on their own","Each and every one of your daily work tasks suddenly becomes thoroughly enjoyable"],"correct":1,"explain":"Items move into Quadrant I and you are constantly handling crises."},{"id":"SSPT13032","type":"mcq","cat":"Time Management","q":"Which is a real benefit of good time management?","options":["It promises you top grades in every course without any effort","It wipes out absolutely every single source of stress in life","It readies you for life's demands, which in turn lowers anxiety","It magically shortens the length of the academic semester for you"],"correct":2,"explain":"Better prepared for life's demands → decreases anxiety."},{"id":"SSPT13033","type":"mcq","cat":"Time Management","q":"Good time management helps you assign time to tasks:","options":["Equally across all tasks, regardless of their size (Equalizing)","In the order in which the tasks arrive, one after another (Sequencing)","In proportion to each task's true importance (Prioritizing)","According to how enjoyable or fun each task is (Favoring)"],"correct":2,"explain":"Assign time in proportion to each task's true importance (Prioritizing)."},{"id":"SSPT13034","type":"mcq","cat":"Time Management","q":"Which of the following is listed as an early warning sign of time management problems?","options":["Finishing every single assigned task well before its deadline","Keeping a tidy weekly schedule","Asking teachers for extensions regularly","Sleeping eight hours a night"],"correct":2,"explain":"Asking teachers for extensions regularly is on the warning-sign list."},{"id":"SSPT13035","type":"mcq","cat":"Time Management","q":"'Your grades don't reflect your ability' is an example of:","options":["Listed as an early warning sign of time management problems","Offered as proof that the recent examinations were simply unfair","Framed as a clear reason to change your major immediately","Stated as a fixed rule about the nature of intelligence"],"correct":0,"explain":"It is an early warning sign: the remedy starts with completing the Time Management Matrix."},{"id":"SSPT13036","type":"mcq","cat":"Time Management","q":"Procrastination may give immediate satisfaction, but it brings:","options":["Anxiety, reduced sleep, illness, lower grades, poorer work, rushed learning, and disappointment","Sharper and much deeper learning that comes from intense last-minute focused cramming sessions","Considerably more free relaxation time paired with markedly higher-quality finished academic work","Markedly stronger and far warmer personal relationships with all of your course instructors"],"correct":0,"explain":"The full bill: anxiety, reduced sleep, illness, lower grades, poorer work, less learning, disappointment."},{"id":"SSPT13037","type":"mcq","cat":"Time Management","q":"Setting priorities means making a value judgment on each task based on:","options":["Judged mainly by its overall length and its level of difficulty","Decided by whatever particular mood you happen to be in that day","Sorted strictly according to the alphabetical order of the task name","Weighed by its true worth and by when it must be completed"],"correct":3,"explain":"Worth and when it must be completed."},{"id":"SSPT13038","type":"mcq","cat":"Time Management","q":"Which tasks should be your #1 priority?","options":["The handful of tasks that you personally enjoy doing the most","The very easiest tasks, chosen mainly to build early momentum","The tasks that are worth the most and that are due soonest","The same tasks that most of your friends happen to be doing"],"correct":2,"explain":"Worth the most + due the soonest = #1 priority."},{"id":"SSPT13039","type":"mcq","cat":"Time Management","q":"Which of the following are the three key steps to good time management?","options":["Depending entirely on last-minute cramming, brief napping, and plain repetition","Making a weekly schedule, a daily to-do list, and a long-term plan","Forcing yourself to work harder, sleep much less, and skip meals","Repeating nothing but memorizing, thick highlighting, and endless rereading"],"correct":1,"explain":"Weekly schedule, daily to-do list, long-term plan."},{"id":"SSPT13040","type":"mcq","cat":"Time Management","q":"What is the purpose of developing a weekly schedule?","options":["To give a clear overview of your free and your committed time","To keep a careful record of the grades from every single quiz","To maintain a tidy list of the phone numbers of classmates","To track exactly how much of your pocket money is being spent"],"correct":0,"explain":"An overview of free and committed time."},{"id":"SSPT13041","type":"mcq","cat":"Time Management","q":"A call demands attention now but serves no mission or value. Which quadrant?","options":["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"],"correct":2,"explain":"Some calls and interruptions = urgent but not important = QIII."},{"id":"SSPT13042","type":"mcq","cat":"Time Management","q":"You plan next term's strategy and build a study partnership; nothing is due. Which quadrant?","options":["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"],"correct":1,"explain":"Strategy planning + relationship building, no deadline = QII."},{"id":"SSPT13043","type":"mcq","cat":"Time Management","q":"Two hours disappear into trivia, busy work, and chatting-and-games time wasters. Which quadrant absorbed the time?","options":["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"],"correct":3,"explain":"Trivia, busy work, chatting and games = QIV."},{"id":"SSPT13044","type":"mcq","cat":"Time Management","q":"A 42-hour week includes 21 hours of urgent and important work. What share is that?","options":["25%","33%","50%","75%"],"correct":2,"explain":"21 of 42 hours = 50% in Quadrant I."},{"id":"SSPT13045","type":"mcq","cat":"Time Management","q":"After listing your weekly tasks in the Urgent & Important matrix, what should you do next?","options":["Keep the completed matrix hidden away from all of your close and trusted colleagues","Put the first things first, then share and discuss with the colleague beside you","Cross out and delete every single task that you previously placed in the Quadrant I","Rewrite the whole filled-in matrix later on as a formal and structured written essay"],"correct":1,"explain":"Put first things first, then share and discuss with the colleague beside you."},{"id":"SSPT13046","type":"mcq","cat":"Time Management","q":"What is the purpose of writing a daily to-do list?","options":["To provide daily reminders to assure that key tasks are not forgotten","To sort and rank all of your classmates carefully by their latest exam grades","To take over and completely replace the need for a careful weekly schedule","To keep a private daily record of all your dreams and your shifting moods"],"correct":0,"explain":"Daily reminders so key tasks are not forgotten."},{"id":"SSPT13047","type":"mcq","cat":"Time Management","q":"What is the purpose of preparing a long-term plan?","options":["Commit to memory all the key dates needed for a single history exam","Step in to fully replace the daily to-do list for every given day","Allow you to dodge and avoid ever stopping to plan out the week","To promote your overall organization and careful future planning"],"correct":3,"explain":"Promotes overall organization and future planning."},{"id":"SSPT13048","type":"mcq","cat":"Time Management","q":"Time management is best described as a skill that:","options":["a motivated person can pick up quickly and then set aside","improves on its own as a person gains more years of experience","everyone must keep working on it in every area of their life","depends on a person's natural talent rather than on steady practice"],"correct":2,"explain":"Everyone must work on it in all areas: personal, academic, and work. It is a lifelong skill, not picked up once, not automatic with age, and not based on natural talent."},{"id":"SSPT13049","type":"mcq","cat":"Time Management","q":"Successful time management requires:","options":["Expensive specialist software and a quiet private office of your own","Permission from the dean","Self-evaluation and the desire to improve","A lighter course load"],"correct":2,"explain":"Self-evaluation and the desire to improve."},{"id":"SSPT13050","type":"mcq","cat":"Time Management","q":"Effective time management will ultimately require a person to:","options":["Make yourself do unwanted tasks at times you would rather not","Just wait for inner motivation to arrive on its own","Confine your effort to studying the subjects you already like best","Steer clear of and politely avoid every one of your unpleasant daily tasks"],"correct":0,"explain":"Do things you don't want to do when you don't want to do them, and push yourself; the pay-off is always worth the effort."},{"id":"SSPT13051","type":"mcq","cat":"Time Management","q":"Which early warning sign of TM problems involves the quality of submitted work?","options":["Turning in submitted work that falls below your own usual standard","Making a point of attending each and every lecture right on time","Wrapping up and finishing all of your assigned tasks well early","Recording and keeping every single commitment neatly inside a calendar"],"correct":0,"explain":"Submitting work below your usual standard is a listed warning sign."},{"id":"SSPT13052","type":"mcq","cat":"Time Management","q":"Which warning sign involves sacrificing things you like?","options":["Setting aside quiet hours each weekend purely for reading for pleasure and light fiction","Choosing to join and regularly attend a weekly peer study group with others together","Deciding to settle down and go to sleep early the night before exams well in advance","Having to let go of activities you enjoy because of a lack of time or low grades"],"correct":3,"explain":"Letting go of activities you enjoy due to lack of time or low grades is a warning sign."},{"id":"SSPT13053","type":"mcq","cat":"Time Management","q":"Urgent activities can take us away from:","options":["The very activities that let us carry out our mission or our vision","Our nightly sleep and our three daily meals, and little else","Our leisure time spent scrolling social media feeds and playing casual video games","Nothing, as urgency itself is seldom a true problem"],"correct":0,"explain":"Urgent activities steal time from mission- and vision-carrying activities."},{"id":"SSPT13054","type":"mcq","cat":"Time Management","q":"By definition, procrastination is:","options":["It is best understood as a completely harmless and innocent little habit","It is viewed as a clever and modern evidence-based study technique","It is described plainly as the true enemy of good time management","It is celebrated wrongly as the essential secret key to real creativity"],"correct":2,"explain":"'Procrastination: Enemy of Time Management.'"},{"id":"SSPT13055","type":"mcq","cat":"Time Management","q":"Good time management ultimately makes a person:","options":["A far more productive and successful person who enjoys a balanced life","A person left isolated and cut off from all friends and family","Someone wholly dependent on your instructor for every single decision made","An individual rendered completely immune to and unaffected by any deadline"],"correct":0,"explain":"A more productive, successful person with a more balanced life."},{"id":"SSPT13056","type":"matching","cat":"Time Management","q":"Match each quadrant to the activities the matrix places in it.","leftItems":[{"id":"1","text":"Quadrant I"},{"id":"2","text":"Quadrant II"},{"id":"3","text":"Quadrant III"},{"id":"4","text":"Quadrant IV"}],"rightItems":[{"id":"A","text":"Crisis, pressing problems, deadline projects, and meetings"},{"id":"B","text":"Prevention, planning, relationship building, and personal development"},{"id":"C","text":"Interruptions, some calls, some mails, and popular activities"},{"id":"D","text":"Trivia, some phone calls, excessive TV, and games"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Quadrant I holds crises, pressing problems, deadline projects and meetings; Quadrant II holds prevention, planning, relationships and personal development; Quadrant III holds interruptions, some calls and mails and popular activities; Quadrant IV holds trivia, some phone calls, excessive TV and games."},{"id":"SSPT13057","type":"matching","cat":"Time Management","q":"Match each quadrant to the result of living in it.","leftItems":[{"id":"1","text":"Quadrant I"},{"id":"2","text":"Quadrant II"},{"id":"3","text":"Quadrant III"},{"id":"4","text":"Quadrant IV"}],"rightItems":[{"id":"A","text":"Stress, burnout, and always putting out fires"},{"id":"B","text":"Vision, perspective, balance, control, and few crises"},{"id":"C","text":"Short-term focus and feeling victimized and out of control"},{"id":"D","text":"Irresponsibility, work not completed, and loss of your job"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Living in Quadrant I brings stress and burnout; Quadrant II brings vision, balance and control; Quadrant III brings short-term focus and feeling victimized; Quadrant IV brings irresponsibility and loss of your job."},{"id":"SSPT13058","type":"matching","cat":"Time Management","q":"Match each key step to its purpose.","leftItems":[{"id":"1","text":"Weekly schedule"},{"id":"2","text":"Daily to-do list"},{"id":"3","text":"Long-term plan"}],"rightItems":[{"id":"A","text":"Gives an overview of free and committed time"},{"id":"B","text":"Provides reminders so key tasks are not forgotten"},{"id":"C","text":"Promotes overall organization and future foresight"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"The weekly schedule gives an overview of free and committed time; the daily to-do list provides reminders so key tasks are not forgotten; the long-term plan promotes overall organization and future foresight."},{"id":"SSPT13059","type":"stepped","cat":"Time Management","q":"A student wants to define and develop this study skill.","steps":[{"id":"1","prompt":"It is the development of processes and what else?","options":["tools","rules","budgets","uniforms"],"correct":0},{"id":"2","prompt":"These processes and tools mainly increase efficiency and what?","options":["productivity","popularity","proximity","parity"],"correct":0},{"id":"3","prompt":"Because efficiency and productivity need steady work, time management is a what?","options":["a lifelong challenge","a one-time quick fix","an inborn natural talent","a fixed permanent trait"],"correct":0}],"explain":"Step 1: time management develops processes and tools. Step 2: these raise efficiency and productivity. Step 3: it is a skill worked on continuously, a lifelong challenge for most, not a one-time fix, inborn talent, or fixed trait."},{"id":"SSPT13060","type":"stepped","cat":"Time Management","q":"The matrix sorts every task along two axes.","steps":[{"id":"1","prompt":"The axis that demands attention NOW is called what?","options":["urgency","importance","priority","vision"],"correct":0},{"id":"2","prompt":"Urgency is a timing claim; the other axis, importance, is a claim about what?","options":["your mission and values","your inbox order","your mood today","your budget"],"correct":0},{"id":"3","prompt":"Since importance is a mission claim, can an urgent task fail to be important?","options":["yes, because urgency does not prove importance","no, because the two labels mean the same thing","it depends on who assigned the task","it depends on the exam calendar"],"correct":0}],"explain":"Step 1: the NOW axis is urgency. Step 2: importance is a mission and values claim, not inbox, mood, or budget. Step 3: because importance is a mission claim, an urgent task can be unimportant; the two labels are not identical and do not depend on who assigned it or the calendar."},{"id":"SSPT13061","type":"multi","cat":"Time Management","q":"Which of the following are among the seven key practices of Quadrant II?","options":["Improving communication with others","Better planning and organization","Watching excessive TV and games","Constantly putting out fires"],"correct":[0,1],"explain":"Improving communication and better planning are Quadrant II practices. Watching excessive TV is a Quadrant IV time waster, and constantly putting out fires is a Quadrant I result, not a practice."},{"id":"SSPT13062","type":"mcq","cat":"Time Management","q":"Which is named as the key practice of Quadrant II?","options":["Knowing what is important","Doing better preparation each term","Looking after and caring for yourself","Pursuing ongoing personal development"],"correct":0,"explain":"Knowing what is important is the key practice. Better preparation, caring for yourself, and personal development are also Quadrant II practices, but the slide names knowing what is important as the key one."},{"id":"SSPT13063","type":"multi","cat":"Time Management","q":"Which are listed as Quadrant II practices?","options":["Taking advantage of new opportunities","Caring for yourself","Fielding some mails and calls","Reacting to pressing problems"],"correct":[0,1],"explain":"Taking advantage of new opportunities and caring for yourself are Quadrant II practices. Fielding some mails and calls is Quadrant III, and reacting to pressing problems is Quadrant I."},{"id":"SSPT13064","type":"mcq","cat":"Time Management","q":"Living in Quadrant IV most likely leads to what?","options":["Irresponsibility and loss of your job","Vision, balance, and control","Stress and burnout","Feeling victimized and out of control"],"correct":0,"explain":"Living in Quadrant IV brings irresponsibility, work not completed, and loss of your job. Vision and balance come from Quadrant II, stress and burnout from Quadrant I, and feeling victimized from Quadrant III."},{"id":"SSPT13065","type":"mcq","cat":"Time Management","q":"Which is NOT one of the seven Quadrant II practices?","options":["Improving communication with others","Better preparation","Handling every crisis personally","Personal development"],"correct":2,"explain":"Handling every crisis personally is not a Quadrant II practice; it reflects living in Quadrant I. Improving communication, better preparation, and personal development are all listed practices."},{"id":"SSPT13066","type":"mcq","cat":"Time Management","q":"Good time management helps a student do what?","options":["Get the most out of their education","Avoid every single academic responsibility they hold","Skip long-term planning entirely","Rely fully on the instructor"],"correct":0,"explain":"Time management helps you get the most out of your education. It does not let you avoid responsibilities, skip planning, or rely fully on an instructor."},{"id":"SSPT13067","type":"mcq","cat":"Time Management","q":"Which early warning sign means work is turned in after its due time?","options":["Handing work in late","Forgetting commitments","Making excuses for undone work","Submitting below-standard work"],"correct":0,"explain":"Handing work in late is a warning sign about timing. Forgetting commitments, making excuses, and submitting below-standard work are also warning signs, but the timing one is handing work in late."},{"id":"SSPT13068","type":"mcq","cat":"Time Management","q":"Forgetting what you promised to do is an early warning sign of what?","options":["time management problems","practicing effective leadership skills","Quadrant II planning","procrastination relief"],"correct":0,"explain":"Forgetting commitments is an early warning sign of time management problems. It is not a mark of effective leadership, Quadrant II planning, or relief from procrastination."},{"id":"SSPT13069","type":"mcq","cat":"Time Management","q":"Often lacking enough time to finish a task signals what?","options":["a time management problem","a deeply balanced and calm life","strong future planning","low anxiety levels"],"correct":0,"explain":"Often not having enough time to complete a task signals a time management problem, not a balanced life, strong planning, or low anxiety."},{"id":"SSPT13070","type":"mcq","cat":"Time Management","q":"Offering reasons for why work was not done is a warning sign of what?","options":["time management problems","good prioritizing habits","effective weekly schedules","clear personal values"],"correct":0,"explain":"Making excuses for why work is not done is a warning sign of time management problems, not a sign of good prioritizing, effective schedules, or clear values."},{"id":"SSPT13071","type":"mcq","cat":"Time Management","q":"What should you complete to gauge how much you need this skill?","options":["the Time Management Matrix","a single daily to-do list","the college timetable","a long-term budget plan"],"correct":0,"explain":"You should take time to complete the Time Management Matrix to see how much you need to work on this skill. A daily list, the timetable, or a budget plan does not measure it."},{"id":"SSPT13072","type":"mcq","cat":"Time Management","q":"In the end, procrastination does what relative to helping you?","options":["hurts you more than it helps","helps you more than it hurts","neither truly helps nor really hurts you at all","its help outweighs any harm"],"correct":0,"explain":"In the end procrastination hurts you more than it helps you. It does not help more than hurt, is not neutral, and its help does not outweigh the harm."},{"id":"SSPT13073","type":"mcq","cat":"Time Management","q":"At any one time you may ideally have how many tasks to do?","options":["10","2","1","100"],"correct":0,"explain":"You may have about 10 tasks you ideally should work on, and it is impossible to do them all. One, two, or a hundred are not the number described."},{"id":"SSPT13074","type":"mcq","cat":"Time Management","q":"The pay-off of good time management is said to be what?","options":["always worth the effort","rarely worth the effort","a reward reserved for managers","a reward reserved for students"],"correct":0,"explain":"The pay-off of good time management is always worth the effort. It is not rarely worth it, nor a reward reserved for managers or for students alone."},{"id":"SSPT13075","type":"mcq","cat":"Time Management","q":"After sharing your matrix, the next step is to do what?","options":["discuss what each could do differently","carefully hide the matrix from all colleagues","delete every Quadrant I task","rewrite the matrix as an essay"],"correct":0,"explain":"The third step is to discuss together what each person could do differently to do more important activities. Hiding the matrix, deleting Quadrant I tasks, or rewriting it as an essay are not part of it."},{"id":"SSPT13076","type":"mcq","cat":"Time Management","q":"In the simple banner matrix, which item is listed under Quadrant I?","options":["Meetings","Preparation","Interruptions","Trivia"],"correct":0,"explain":"The banner matrix lists meetings under Quadrant I with crises and deadlines. Preparation is Quadrant II, interruptions Quadrant III, and trivia Quadrant IV."},{"id":"SSPT13077","type":"matching","cat":"Time Management","q":"Match each quadrant to the Urgent and Important combination that defines it.","leftItems":[{"id":"1","text":"Quadrant I"},{"id":"2","text":"Quadrant II"},{"id":"3","text":"Quadrant III"},{"id":"4","text":"Quadrant IV"}],"rightItems":[{"id":"A","text":"Urgent and Important"},{"id":"B","text":"Not urgent and Important"},{"id":"C","text":"Urgent and Not important"},{"id":"D","text":"Not urgent and Not important"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Quadrant I pairs with Urgent and Important; Quadrant II with Not urgent and Important; Quadrant III with Urgent and Not important; Quadrant IV with Not urgent and Not important."}]}},"banks/studyskills/lecture-4-writing-presentation-remake.json":{"id":"lecture-4-writing-and-presentation","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 4 – Writing and Presentation","formSize":65,"forms":["A"],"bank":{"A":[{"id":"SSPT14000","type":"mcq","cat":"Writing and Presentation","q":"What should the first slide of a presentation typically include?","options":["The title of the presentation alone, with no mention of the presenter's name, position, or affiliation","Title, your name, position, affiliation, and optionally additional information such as date or institution logo","The detailed body content of the presentation, omitting the title, the presenter's name, and the affiliation"],"correct":1,"explain":"Cover slide: title plus name, position, affiliation (with optional date or institution logo), not detailed content."},{"id":"SSPT14001","type":"mcq","cat":"Writing and Presentation","q":"Which of the following combinations is considered most readable for text?","options":["Light font on a light background (e.g., yellow on white)","Dark font on a light background (e.g., blue on white)","Dark font on a dark background (e.g., black on navy)"],"correct":1,"explain":"Dark font on light background gives the strongest, most readable contrast."},{"id":"SSPT14002","type":"mcq","cat":"Writing and Presentation","q":"Which of the following is a recommended way to end a presentation effectively?","options":["Stop speaking abruptly the instant your allotted time runs out, with no summary or closing remark","End with a strong closing slide that summarizes the key take-home messages for the audience to remember","Repeat the cover slide verbatim as the final screen so the talk closes on the title and name"],"correct":1,"explain":"End with a strong closing summarizing the key take-home messages; never end abruptly."},{"id":"SSPT14003","type":"mcq","cat":"Writing and Presentation","q":"Which statement best defines a presentation?","options":["A written examination paper that a student submits to the instructor for grading and marks","An informal, unstructured chat between two classmates recalling what was said in a previous lecture","A process of communicating knowledge, thoughts, ideas, and/or research results to specific audiences","A printed handout of reference notes photocopied and distributed to the class after the session ends"],"correct":2,"explain":"A presentation communicates knowledge, thoughts, ideas, and/or research results to specific audiences."},{"id":"SSPT14004","type":"mcq","cat":"Writing and Presentation","q":"The 'presentation circuit' consists of which four components?","options":["Presenter, audience, message, and the setting or context surrounding them","Slides, projector, podium, and the microphone or sound system in the room","Title, outline, body, and the list of references at the end","Writer, editor, reviewer, and the publisher who prints the final copy"],"correct":0,"explain":"Presenter and audience around a message, all inside a setting or context."},{"id":"SSPT14005","type":"mcq","cat":"Writing and Presentation","q":"Which academic tasks require the ability to write papers scientifically and professionally?","options":["Multiple-choice examinations, attendance registers, and oral quizzes","Assignments, research activities, scientific reports, and dissertations","Social media posts, personal text messages, and casual chat","Reading textbooks, listening to lectures, and watching videos"],"correct":1,"explain":"Assignments, research activities, scientific reports, and dissertations require scientific and professional writing."},{"id":"SSPT14006","type":"mcq","cat":"Writing and Presentation","q":"A successful person is described as one who is capable of:","options":["Standing and speaking continuously without a pause or break for a full hour on end","Memorizing the exact wording of each slide and reciting it back word for word","Deliberately avoiding the audience's eyes and reading from the notes held in the hand","Communicating his knowledge, experiences, and thoughts in a professional manner"],"correct":3,"explain":"A successful person communicates knowledge, experiences, and thoughts in a professional manner."},{"id":"SSPT14007","type":"mcq","cat":"Writing and Presentation","q":"What are the 3 P's of presentation?","options":["Plan, Prepare, Present","Practice, Perform, Publish","Plan, Print, Prove","Prepare, Pause, Perfect"],"correct":0,"explain":"The 3 P's are Plan, Prepare, Present."},{"id":"SSPT14008","type":"mcq","cat":"Writing and Presentation","q":"The reminder 'A person who is going nowhere normally gets there' is attached to which planning step?","options":["Locating the suitable resources","Collecting ideas and information","Setting your goal","Designing the background colors"],"correct":2,"explain":"It is paired with the step of setting your goal."},{"id":"SSPT14009","type":"mcq","cat":"Writing and Presentation","q":"Which set of actions belongs to the PLAN stage?","options":["Choosing the font, checking the spelling, designing the background, and thanking the audience at the end","Setting your goal, collecting ideas and information, locating suitable resources, and knowing your audience beforehand","Scanning the audience's eyes, diversifying the voice, synchronizing the hands, and smiling at the questioner","Handling nasty questions with humor, managing the time, hiding the accent, and thanking the audience"],"correct":1,"explain":"Plan covers goal, ideas, resources, and knowing your audience beforehand."},{"id":"SSPT14010","type":"mcq","cat":"Writing and Presentation","q":"In the three-part organization, 'Tell them what you told them' is which part?","options":["The opening","The message","The closing","The cover slide"],"correct":2,"explain":"The closing tells them what you told them."},{"id":"SSPT14011","type":"mcq","cat":"Writing and Presentation","q":"What should the OPENING of your talk do, according to the organization rule?","options":["Tell them what you are going to say","Tell the audience what you told them earlier","Invite the audience to pose nasty questions now","Show the audience the conclusion graph up front"],"correct":0,"explain":"The opening tells them what you are going to say."},{"id":"SSPT14012","type":"mcq","cat":"Writing and Presentation","q":"The first slide of a presentation must contain:","options":["The complete verbatim text of the whole talk, written out in full paragraphs on one screen","The title of the presentation and your name, position, and affiliation","The organization or institution logo alone, with no title, name, or affiliation shown","The full list of references and citations used, placed alone on the opening screen"],"correct":1,"explain":"Title plus name, position, and affiliation (with optional date or institution logo)."},{"id":"SSPT14013","type":"mcq","cat":"Writing and Presentation","q":"Your second slide should list:","options":["Every reference and citation written out in full on the slide","The closing thank-you message addressed to the audience and organizers","Complete paragraphs reproducing the introduction of the paper word for word","The objectives, agenda, or outline of your talk, main points only"],"correct":3,"explain":"Objectives or agenda, main points only; follow that order for the rest of the talk."},{"id":"SSPT14014","type":"mcq","cat":"Writing and Presentation","q":"The recommended slide count is:","options":["1–2 slides per minute of your presentation","Just 1 or 2 slides in total for the whole presentation, regardless of its length","Around 10 slides for each minute of your scheduled presentation time","As many slides as the presentation file can physically hold on the computer screen"],"correct":0,"explain":"Use 1–2 slides per minute."},{"id":"SSPT14015","type":"mcq","cat":"Writing and Presentation","q":"Good slide structure means writing:","options":["Complete, grammatically full sentences packed with as many descriptive words as possible","Full paragraphs copied word for word straight from the textbook onto the screen","In point form, key words and phrases only, 4–5 points per slide","At least twelve separate bullet points crammed onto each prepared slide"],"correct":2,"explain":"Point form, 4–5 points per slide, key words only; avoid wordiness."},{"id":"SSPT14016","type":"mcq","cat":"Writing and Presentation","q":"Why is showing one point at a time recommended?","options":["It significantly reduces the overall file size of the presentation stored on the computer","It helps the audience concentrate, prevents them from reading ahead, and keeps your talk focused","It quietly hides your weakest arguments and least-prepared points from the watching audience","It is a compulsory feature built into most presentation software programs"],"correct":1,"explain":"It helps concentration, prevents reading ahead, and keeps the talk focused."},{"id":"SSPT14017","type":"mcq","cat":"Writing and Presentation","q":"Which rule matches the advice on animation?","options":["Apply a different noisy animation to each slide, layer several effects, and change the style often","Load the deck with as much animation as possible, since more motion keeps the audience alert","Do not use distracting animation, avoid noisy effects, do not go overboard, and be consistent","Leave animation out and depend on static cuts, believing motion hurts focus"],"correct":2,"explain":"No distracting or noisy animation, do not overdo it, and be consistent."},{"id":"SSPT14018","type":"mcq","cat":"Writing and Presentation","q":"Using the Verdana font, content text should be no smaller than what size?","options":["12 point","24 point","32 point","40 point"],"correct":1,"explain":"Title about 40 pt, bullets about 32 pt, content no smaller than 24 pt."},{"id":"SSPT14019","type":"mcq","cat":"Writing and Presentation","q":"Which fonts are named as standard, readable choices for slides?","options":["Garamond, Century Gothic, Gill Sans, and Times","Times New Roman, Tahoma, Verdana, or Arial","Garamond Italic, Gill Sans Condensed, Century Gothic, and Times Bold","Verdana, Tahoma, Gill Sans, and Century Gothic"],"correct":1,"explain":"Times New Roman, Tahoma, Verdana, or Arial are the standard readable choices."},{"id":"SSPT14020","type":"mcq","cat":"Writing and Presentation","q":"Why should you NOT use all capital letters?","options":["The presentation software simply refuses to display text written in capital letters","Typing in capitals automatically shortens the total running time of the presentation","It makes text hard to read, conceals acronyms, and denies capitals for EMPHASIS","Using capitals affects the footer line but leaves the body of the slide unchanged"],"correct":2,"explain":"ALL CAPS is hard to read, conceals acronyms, and denies capitals for emphasis."},{"id":"SSPT14021","type":"mcq","cat":"Writing and Presentation","q":"Italics are properly used for:","options":["Italicize each bullet point on the slide so the list stands out","Quotes, highlighting thoughts or ideas, and titles of books, journals, or magazines","Apply italics to the headings and titles rather than to ordinary body text","Use italics for numbers and statistics rather than for ordinary words or phrases"],"correct":1,"explain":"Quotes, highlighted thoughts or ideas, and book, journal, or magazine titles."},{"id":"SSPT14022","type":"mcq","cat":"Writing and Presentation","q":"Which rule governs font color?","options":["Assign a brand-new, different color to each individual point or even each word","Place bright, vivid colors directly on a plain white background for maximum pop","Choose a font color that matches the background color exactly, blending them together","Use a font color that contrasts sharply with the background"],"correct":3,"explain":"Contrast sharply with the background: dark font on light background."},{"id":"SSPT14023","type":"mcq","cat":"Writing and Presentation","q":"What is advised about presentation backgrounds?","options":["Use light backgrounds and keep the same background consistently throughout","Choose dark, cluttered, busy backgrounds in order to add drama and intensity to the talk","Switch to a brand-new background on each slide to keep the audience alert","Believe that the choice of background has little effect on how readable the text is"],"correct":0,"explain":"Light backgrounds, the same background consistently throughout."},{"id":"SSPT14024","type":"mcq","cat":"Writing and Presentation","q":"Which set of combinations appears on the 'avoid such combinations' list?","options":["White on black, dark yellow on green, purple on blue, orange on green, red on green","Green on blue, dark yellow on green, blue on white, orange on green, red on green","Green on blue, dark yellow on green, purple on blue, orange on green, red on green","Green on blue, dark yellow on green, purple on blue, orange on green, dark text on a light background"],"correct":2,"explain":"Avoid green on blue, dark yellow on green, purple on blue, orange on green, and red on green, plus bright colors on white."},{"id":"SSPT14025","type":"mcq","cat":"Writing and Presentation","q":"Why are graphs recommended rather than just tables and words?","options":["Drawing a graph simply takes far less time than typing out the equivalent table","Data in graphs is easier to comprehend and retain, and trends are easier to visualize","A graph is allowed to skip its title because the axes explain the data on their own","Tables are discouraged and should not appear in a scientific presentation"],"correct":1,"explain":"Data in graphs is easier to comprehend and retain, and trends are easier to visualize; title every graph."},{"id":"SSPT14026","type":"mcq","cat":"Writing and Presentation","q":"In the faulty-graph example, which faults were called out?","options":["Minor gridlines unnecessary, font too small, colors illogical, title missing, shading distracting","Too few colors used, dull monochrome look, line plots instead of bars, months mislabeled, legend absent","Graph drawn too small, axes reversed, bold gridlines, over-long title, missing shading","Bars used instead of lines, colors too logical, font too large, no shading, title present"],"correct":0,"explain":"Unnecessary gridlines, too-small font, illogical colors, missing title, and distracting shading."},{"id":"SSPT14027","type":"mcq","cat":"Writing and Presentation","q":"About spelling and syntax, you are advised to:","options":["Rely on the audience to silently correct the spelling mistakes you leave on the screen","Bother to check the spelling after the presentation is over and the audience gone","Proofread your presentation before they see it, and asking a friend for help is OK","Ignore spelling, on the theory that the content is what really matters"],"correct":2,"explain":"Proofread before they see it; asking a friend for help is OK."},{"id":"SSPT14028","type":"mcq","cat":"Writing and Presentation","q":"Why is an effective and strong closing important?","options":["It reduces the total number of slides you show","Your audience is likely to remember your last words","It prevents the audience from asking more questions","It replaces the outline slide at the very end"],"correct":1,"explain":"The audience is likely to remember your last words: take-home messages, no abrupt ending."},{"id":"SSPT14029","type":"mcq","cat":"Writing and Presentation","q":"What is the purpose of the 'Questions' slide at the end of a presentation?","options":["Use the final screen to invite your audience to step forward and ask questions","Use the final screen to read out the complete list of references and citations","Use the final screen to display the title and your name one more time","Use the final screen to announce the topic and date of the next lecture"],"correct":0,"explain":"Invite your audience to ask questions and handle them well."},{"id":"SSPT14030","type":"mcq","cat":"Writing and Presentation","q":"'The mind starts working the minute you're born, and never stops until you get up to speak' humorously refers to:","options":["Audience boredom","Writer's block during essays","Presentation phobia","Time management failure"],"correct":2,"explain":"Presentation phobia, which can be healthy or unhealthy."},{"id":"SSPT14031","type":"mcq","cat":"Writing and Presentation","q":"Complete the key sentence about delivery: 'It is not WHAT we say, but…'","options":["how long we speak","HOW we say it","how many slides we show","how loudly we apologize"],"correct":1,"explain":"It is not WHAT we say, but HOW we say it."},{"id":"SSPT14032","type":"mcq","cat":"Writing and Presentation","q":"Which treatment is given for presentation phobia?","options":["Practice using colleagues, friends, or relatives as audiences, and breathe deeply before you stand","Avoid giving presentations for a full year, hoping the fear fades on its own","Rehearse the talk only in front of mirrors, steering clear of any live audience","Read every slide aloud word-for-word throughout the talk so that no mistake slips through"],"correct":0,"explain":"Practice repeatedly with friendly audiences, and take a couple of deep breaths before standing up."},{"id":"SSPT14033","type":"matching","cat":"Writing and Presentation","q":"Match each tip number to the advice it gives.","leftItems":[{"id":"1","text":"Tip 1"},{"id":"2","text":"Tip 2"},{"id":"3","text":"Tip 3"},{"id":"4","text":"Tip 4"}],"rightItems":[{"id":"A","text":"Get well dressed and arrive early to the stage"},{"id":"B","text":"Introduce yourself, as people buy people first"},{"id":"C","text":"Start a two-way conversation fed back by body language"},{"id":"D","text":"Scan the audience's eyes on a regular basis"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Tip 1 is dressing and arriving early, tip 2 introducing yourself, tip 3 commencing a two-way conversation, tip 4 scanning the audience's eyes."},{"id":"SSPT14034","type":"matching","cat":"Writing and Presentation","q":"Match each tip number to the advice it gives.","leftItems":[{"id":"1","text":"Tip 5"},{"id":"2","text":"Tip 6"},{"id":"3","text":"Tip 7"},{"id":"4","text":"Tip 8"}],"rightItems":[{"id":"A","text":"Behave naturally rather than stiffly or rehearsed"},{"id":"B","text":"Synchronize your gestures with your words"},{"id":"C","text":"Do not roam to and fro, which distracts listeners"},{"id":"D","text":"Diversify tone between loud, soft, fast and slow"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Tip 5 is being natural, tip 6 synchronizing hand movements with words, tip 7 limiting body movement, tip 8 diversifying the voice."},{"id":"SSPT14035","type":"matching","cat":"Writing and Presentation","q":"Match each tip number to the advice it gives.","leftItems":[{"id":"1","text":"Tip 9"},{"id":"2","text":"Tip 10"},{"id":"3","text":"Tip 11"},{"id":"4","text":"Tip 12"}],"rightItems":[{"id":"A","text":"Use a deliberate pause as a positive sound effect"},{"id":"B","text":"Drop self-importance and apologies that devalue the talk"},{"id":"C","text":"Skip hard technical terms unless you explain them"},{"id":"D","text":"Let listeners discover gaps instead of being told"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Tip 9 is using silence well, tip 10 avoiding bad habits, tip 11 explaining jargon, tip 12 letting the audience discover rather than be told."},{"id":"SSPT14036","type":"matching","cat":"Writing and Presentation","q":"Match each tip number to the advice it gives.","leftItems":[{"id":"1","text":"Tip 13"},{"id":"2","text":"Tip 14"},{"id":"3","text":"Tip 15"},{"id":"4","text":"Tip 16"}],"rightItems":[{"id":"A","text":"Keep to your allotted time and do not overrun"},{"id":"B","text":"Do not artificially mask the way you naturally sound"},{"id":"C","text":"Repeat unclear questions; if stumped, apologize with humor"},{"id":"D","text":"Smile, approach the questioner, defer or bounce it back"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Tip 13 is time management, tip 14 not hiding your accent, tip 15 handling questions well, tip 16 handling nasty questions."},{"id":"SSPT14037","type":"matching","cat":"Writing and Presentation","q":"Match each tip number to the advice it gives.","leftItems":[{"id":"1","text":"Tip 17"},{"id":"2","text":"Tip 18"},{"id":"3","text":"Tip 19"},{"id":"4","text":"Tip 20"}],"rightItems":[{"id":"A","text":"Face audience, do not block projection, know what is behind"},{"id":"B","text":"Use humor but do not overuse it"},{"id":"C","text":"Hold attention and avoid boring the audience"},{"id":"D","text":"Close by thanking the audience at the end"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Tip 17 is posture, tip 18 using humor in moderation, tip 19 maintaining attention, tip 20 thanking the audience."},{"id":"SSPT14038","type":"stepped","cat":"Writing and Presentation","q":"The Verdana font sizes form a descending ladder for slides.","steps":[{"id":"1","prompt":"What size does the ladder give a title?","options":["40 point","32 point","24 point","12 point"],"correct":0},{"id":"2","prompt":"Below the 40-point title, what size is for subtitles or bullets?","options":["32 point","24 point","12 point","40 point"],"correct":0},{"id":"3","prompt":"Below the 32-point bullets, content must be no smaller than what?","options":["24 point","12 point","32 point","40 point"],"correct":0},{"id":"4","prompt":"The smallest rung, not recommended for content, is what size?","options":["12 point","24 point","32 point","40 point"],"correct":0}],"explain":"Titles 40 pt, subtitles or bullets 32 pt, content no smaller than 24 pt, and 12 pt is not recommended for content."},{"id":"SSPT14039","type":"stepped","cat":"Writing and Presentation","q":"A finished talk follows a fixed slide order.","steps":[{"id":"1","prompt":"The opening slide is the cover; what must it carry?","options":["Title plus name, position and affiliation","The full reference list","The thank-you note","The conclusion graph"],"correct":0},{"id":"2","prompt":"After the cover, the second slide lists what?","options":["The objectives or agenda, main points only","Every citation in full","The closing summary","The questions prompt"],"correct":0},{"id":"3","prompt":"The body delivers the message; which slide comes right before Questions?","options":["The conclusion summarizing main points","The cover again","The agenda","The title only"],"correct":0},{"id":"4","prompt":"What is the last slide's purpose after the conclusion?","options":["Invite the audience to ask questions","Reprint the title","Read references","Announce next topic"],"correct":0}],"explain":"Cover first with title, name and affiliation, then the agenda of main points, then the message, then a conclusion summarizing points and suggesting future research, and finally a slide inviting questions."},{"id":"SSPT14040","type":"multi","cat":"Writing and Presentation","q":"Which are listed as bad habits that switch off the audience?","options":["Claiming to be the top expert in the field","Apologizing for having nothing important or being unprepared","Explaining difficult jargon to the audience","Scanning the audience's eyes on a regular basis"],"correct":[0,1],"explain":"Self-importance and apologizing are bad habits that devalue speaker and talk; explaining jargon and scanning eyes are good practices, not bad habits."},{"id":"SSPT14041","type":"multi","cat":"Writing and Presentation","q":"Which does the topic say happens to the body when you are nervous?","options":["Blood pressure changes","Adrenaline level increases","You turn red, shake, or perspire","Your voice becomes noticeably deeper"],"correct":[0,1,2],"explain":"Nervousness changes blood pressure, raises adrenaline, and makes you turn red, shake or perspire; a deeper voice is not mentioned."},{"id":"SSPT14042","type":"multi","cat":"Writing and Presentation","q":"Which are valid ways to handle a nasty question?","options":["Smile at the person asking","Make eye contact and move toward them","Throw the question back to them","Offer to answer privately afterward","Ignore the questioner and move on"],"correct":[0,1,2,3],"explain":"Smiling, approaching the questioner, bouncing the question back, or deferring to a private answer are all valid; ignoring the questioner is not advised."},{"id":"SSPT14043","type":"mcq","cat":"Writing and Presentation","q":"All of the following are intended outcomes except:","options":["Define what a presentation is","Plan and prepare a good presentation","List important tips for presenting","Recite each slide from memory"],"correct":3,"explain":"The aims are to define, plan, prepare and list tips for presentations; reciting slides from memory is not one of them."},{"id":"SSPT14044","type":"mcq","cat":"Writing and Presentation","q":"Writing and presenting information are highlighted as important skills especially for whom?","options":["A medical student and a health professional","Only seasoned researchers and professors","Just administrative and office staff","Exclusively journalists and editors"],"correct":0,"explain":"They matter for anyone, but the medical student and the health professional are stressed in particular."},{"id":"SSPT14045","type":"mcq","cat":"Writing and Presentation","q":"In what order does the topic say to develop the work?","options":["Write, then transform into a presentation, then present","Present, then write the essay, then edit it","Design slides, then write, then plan the talk","Plan the audience, then present, then write"],"correct":0,"explain":"Write an essay or assignment first, transform it into a presentation, then present it to the target audience."},{"id":"SSPT14046","type":"mcq","cat":"Writing and Presentation","q":"Why is a word-packed paragraph slide considered bad?","options":["The audience reads instead of listening to you","It makes the file size grow too large","It hides weak points from the viewers","It forces the speaker to memorize the text"],"correct":0,"explain":"A paragraph slide is hard to read and present, so the audience spends time reading rather than listening, even with the same number of points."},{"id":"SSPT14047","type":"mcq","cat":"Writing and Presentation","q":"Why is combining a small font with bold or italics discouraged?","options":["It makes the text very hard to read","It uses up the slide too quickly","It conflicts with the background color rule","It shortens the running time of the talk"],"correct":0,"explain":"Small type already strains readability, and adding bold or italics makes it worse, so the combination is not recommended."},{"id":"SSPT14048","type":"mcq","cat":"Writing and Presentation","q":"Where does the topic allow a small font size?","options":["In the footer line of a slide","In the main body bullet points","In the title of every slide","In the graph axis labels only"],"correct":0,"explain":"Small fonts are acceptable for a footer, such as a date or presenter name, but not for body content."},{"id":"SSPT14049","type":"mcq","cat":"Writing and Presentation","q":"What principle do the broken font styles illustrate?","options":["Never trade readability for visual style","Always prefer decorative script fonts","Use italics for every heading","Capitalize all text for emphasis"],"correct":0,"explain":"The same phrase shown in italic, capitals, script and bold caps all hurt legibility, teaching that readability must not be sacrificed for style."},{"id":"SSPT14050","type":"mcq","cat":"Writing and Presentation","q":"Beyond sharp contrast, how should color be used on slides?","options":["To reinforce structure and occasionally emphasize","As a fresh color for every single word","Only in the footer and not in body text","To match the background and blend fully"],"correct":0,"explain":"Color should reinforce the logic of the structure and emphasize a point only occasionally; a different color per word is discouraged."},{"id":"SSPT14051","type":"mcq","cat":"Writing and Presentation","q":"Why are bright colors on a white background a bad mix?","options":["They give low contrast and become unreadable","They make the file size too large","They hide the acronyms in the text","They conflict with the animation rule"],"correct":0,"explain":"Bright colors on white yield low contrast and are unreadable, unlike a dark font on a light background which reads well."},{"id":"SSPT14052","type":"mcq","cat":"Writing and Presentation","q":"What two rules govern graphs and charts?","options":["Always title them, and avoid complex ones","Never title them, and prefer complex ones","Use only tables, never graphs or charts","Shade every bar and add minor gridlines"],"correct":0,"explain":"Graphs should always carry a title and stay simple; complex graphs and distracting shading or gridlines are discouraged."},{"id":"SSPT14053","type":"mcq","cat":"Writing and Presentation","q":"Proofreading a presentation means checking which three things?","options":["Spelling, grammar and punctuation","Font, color and background","Title, agenda and references","Voice, posture and humor"],"correct":0,"explain":"Before the audience sees it, proofread for spelling, grammar and punctuation, and asking a friend for help is fine."},{"id":"SSPT14054","type":"mcq","cat":"Writing and Presentation","q":"A conclusion slide should do which two things?","options":["Summarize the main points and suggest future research","Reprint the title and list all references","Invite questions and thank the organizers","Show the agenda and play an animation"],"correct":0,"explain":"The conclusion slide summarizes the main points of the talk and suggests future avenues of research."},{"id":"SSPT14055","type":"mcq","cat":"Writing and Presentation","q":"Into which two kinds does the topic divide presentation phobia?","options":["Healthy phobia and unhealthy phobia","Mild phobia and severe phobia","Stage phobia and camera phobia","Voice phobia and eye phobia"],"correct":0,"explain":"Presentation phobia is split into a healthy form and an unhealthy form; the treatment is practice plus deep breaths."},{"id":"SSPT14056","type":"mcq","cat":"Writing and Presentation","q":"In the three-part organization, the MESSAGE part does what?","options":["Tell them, between the opening and closing","Tell them what you are going to say","Tell them what you already told them","Tell them to prepare the agenda"],"correct":0,"explain":"The message is the body that simply tells them, sitting between the opening (what you will say) and the closing (what you told them)."},{"id":"SSPT14057","type":"mcq","cat":"Writing and Presentation","q":"Which saying is remembered before you speak, prompting you to introduce yourself?","options":["People buy people first","Time is money always","Practice makes perfect only","The customer is right"],"correct":0,"explain":"Before speaking, introduce yourself, remembering that people buy people first, so the person connects before the content."},{"id":"SSPT14058","type":"mcq","cat":"Writing and Presentation","q":"Starting a talk is framed as beginning what, fed back through body language?","options":["A two-way conversation","A one-way lecture","A written report","A silent reading"],"correct":0,"explain":"You commence a two-way conversation; the audience feeds you back through their body language."},{"id":"SSPT14059","type":"mcq","cat":"Writing and Presentation","q":"If you are unsure of a question from the audience, what should you do?","options":["Ask for the question to be repeated","Ignore it and continue talking","Apologize profusely and sit down","Make up an answer immediately"],"correct":0,"explain":"When uncertain, ask for the question to be repeated; if you lack an answer, apologize with some humor rather than faking one."},{"id":"SSPT14060","type":"mcq","cat":"Writing and Presentation","q":"Which posture rule is given for the presenter?","options":["Face the audience unless pointing at something","Stand in front of the projection screen","Turn your back to read the slides","Pace to and fro across the whole stage"],"correct":0,"explain":"Do not block the projection, always face the audience unless pointing, and know what is behind you without looking."},{"id":"SSPT14061","type":"mcq","cat":"Writing and Presentation","q":"What is the advice about using humor in a presentation?","options":["Use it, but do not overuse it","Leave humor out and stay serious throughout","Add humor to most of your points","Use humor solely when answering nasty questions"],"correct":0,"explain":"A sense of humor helps, but it should be used in moderation and not overdone."},{"id":"SSPT14062","type":"mcq","cat":"Writing and Presentation","q":"How should a presenter handle what the audience does not know?","options":["Let them discover it, rather than being told","Tell them plainly that they lack the knowledge","Ignore the gap and move to the next slide","Apologize for the missing background information"],"correct":0,"explain":"Do not tell the audience they do not know; let them discover it themselves, which avoids putting them down."},{"id":"SSPT14063","type":"mcq","cat":"Writing and Presentation","q":"Which tip is matched correctly to its advice?","options":["Hand Movements: synchronize gestures with your words","Body Movements: synchronize gestures with your words","Voice: treat a deliberate pause as a positive effect","Silence: vary loudness, softness, speed and pace"],"correct":0,"explain":"Hand movements means syncing gestures with words, while body movements means not roaming; voice means varying tone, and silence means using a pause well."},{"id":"SSPT14064","type":"mcq","cat":"Writing and Presentation","q":"Writing a good paper is described as having how many steps?","options":["Ten","Three","Five","Twenty"],"correct":0,"explain":"The stated count is ten steps for writing a good paper; three, five and twenty are not given."}]}},"banks/studyskills/lecture-5-teamwork-and-small-group-learning.json":{"id":"lecture-5-teamwork-and-small-group-learning","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 5 - Teamwork and Small Group Learning","formSize":17,"forms":["A"],"bank":{"A":[{"id":"SSPT25000","type":"mcq","cat":"SS5_lec5","q":"Which description fits a small group?","options":["Two to four; independent study.","Eight to twelve; free discussion.","Fifteen to twenty; silent note-taking.","Four to six; oral recitations."],"correct":1,"explain":"A small group has eight to twelve learners, is teacher-facilitated and learner-centered, and uses free discussion."},{"id":"SSPT25001","type":"mcq","cat":"SS5_lec5","q":"Which ability defines effective teamwork?","options":["Cooperation and communication.","Shared goals and commitment.","Problem-solving and decision-making.","Mere physical placement."],"correct":0,"explain":"Teamwork is effective cooperation and communication with others toward a common goal. The other options describe a team, small-group skills, or mere placement."},{"id":"SSPT25002","type":"mcq","cat":"SS5_lec5","q":"Which statement about teams and groups is correct?","options":["A group counts as a team.","Teams and groups are identical.","Assignment alone creates a team.","Not every group forms a team."],"correct":3,"explain":"A team is a group of individuals, but a group becomes a team only when members cooperate toward a shared goal."},{"id":"SSPT25003","type":"mcq","cat":"SS5_lec5","q":"Which sequence shows the stages of team development?","options":["Forming, Storming, Norming, Performing","Forming, Norming, Storming, Performing","Storming, Forming, Norming, Performing","Norming, Forming, Storming, Performing"],"correct":0,"explain":"Team development proceeds from Forming to Storming, then Norming, then Performing."},{"id":"SSPT25004","type":"mcq","cat":"SS5_lec5","q":"Which stage has questions, structure, roles, trust, guidelines, and a directive tutor?","options":["Storming","Forming","Norming","Performing"],"correct":1,"explain":"Forming involves questions, clear structure, goals, roles, trust-building, guideline setting, and a directive tutor."},{"id":"SSPT25005","type":"mcq","cat":"SS5_lec5","q":"Which stage has frustration, disagreements, refocusing, conflict skills, and a directive tutor?","options":["Forming","Norming","Performing","Storming"],"correct":3,"explain":"Storming involves frustration, less polite disagreements, refocusing on goals, conflict-management skills, and a directive tutor."},{"id":"SSPT25006","type":"mcq","cat":"SS5_lec5","q":"Which stage has meaningful communication, ground rules, evaluation, productivity, and a participative tutor?","options":["Norming","Forming","Storming","Performing"],"correct":0,"explain":"Norming includes meaningful communication, return to ground rules, process evaluation, higher productivity, and a participative tutor."},{"id":"SSPT25007","type":"mcq","cat":"SS5_lec5","q":"Which stage has can-do attitude, helping behaviors, fluid roles, appreciated differences, and celebrated progress?","options":["Forming","Storming","Performing","Norming"],"correct":2,"explain":"Performing shows a can-do attitude, offers to help, fluid roles, appreciated differences, significant progress, and celebrated accomplishments."},{"id":"SSPT25008","type":"matching","cat":"SS5_lec5","q":"Sort each example into its correct category.","leftItems":[{"id":"1","text":"Start and finish on time."},{"id":"2","text":"More active student involvement."},{"id":"3","text":"Clinical rounds."},{"id":"4","text":"Mutual respect."}],"rightItems":[{"id":"A","text":"Ground rule"},{"id":"B","text":"Value of small groups"},{"id":"C","text":"Form of small-group learning"},{"id":"D","text":"Successful team characteristic"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Punctuality is a ground rule, active involvement is a value of small groups, clinical rounds are a form, and mutual respect is a team characteristic."},{"id":"SSPT25009","type":"matching","cat":"SS5_lec5","q":"Match each team-development stage to its main feeling.","leftItems":[{"id":"1","text":"Forming"},{"id":"2","text":"Storming"},{"id":"3","text":"Norming"},{"id":"4","text":"Performing"}],"rightItems":[{"id":"A","text":"Frustration or anger about progress or process."},{"id":"B","text":"Excitement, eagerness, high expectations, and some anxiety."},{"id":"C","text":"Satisfaction and attachment beyond the sum of parts."},{"id":"D","text":"Acceptance of others; constructive criticism is welcome."}],"correct_pairs":{"1":"B","2":"A","3":"D","4":"C"},"explain":"Forming brings excitement and anxiety, Storming brings frustration, Norming brings acceptance, and Performing brings satisfaction and attachment."},{"id":"SSPT25010","type":"mcq","cat":"SS5_lec5","q":"What defines a team?","options":["Group cooperating toward a goal.","Collection placed in one room.","Tutor delivering content to learners.","Individual completing complex tasks alone."],"correct":0,"explain":"A team is a group of people working cooperatively to achieve a common goal."},{"id":"SSPT25011","type":"mcq","cat":"SS5_lec5","q":"Why are teams useful for complex tasks?","options":["They exceed individual capacity.","They remove the need for shared goals.","They replace tutor guidance.","They prevent active involvement."],"correct":0,"explain":"Teams share goals, commitment, and skills to complete complex tasks beyond individual capacity."},{"id":"SSPT25012","type":"mcq","cat":"SS5_lec5","q":"Why should students understand teamwork?","options":["Teams are part of life.","Teams remove the need for roles.","Teams prevent member conflict.","Teams replace small-group discussion."],"correct":0,"explain":"Teams are part of everyone's life, so students need to function effectively as team members."},{"id":"SSPT25013","type":"mcq","cat":"SS5_lec5","q":"Which set contains only sample ground rules?","options":["On time, prepared, listening, shared responsibility.","Common purpose, prepared, listening, shared responsibility.","On time, field training, listening, shared responsibility.","On time, prepared, listening, measurable goals."],"correct":0,"explain":"Sample ground rules are punctuality, preparation, listening and understanding, and shared responsibility for group aims."},{"id":"SSPT25014","type":"mcq","cat":"SS5_lec5","q":"Which set contains only reasons that small-group learning is valuable?","options":["Attitudes, skills, involvement.","Common purpose, skills, involvement.","Attitudes, clinical rounds, involvement.","Attitudes, skills, mutual respect."],"correct":0,"explain":"Small-group learning develops positive attitudes, problem-solving and decision-making skills, and active involvement."},{"id":"SSPT25015","type":"mcq","cat":"SS5_lec5","q":"Which set contains only forms of small-group learning?","options":["PBL, field training, rounds, projects.","Ground rules, field training, rounds, projects.","PBL, common purpose, rounds, projects.","PBL, field training, rounds, measurable goals."],"correct":0,"explain":"Small groups are used in PBL classes, field training, clinical rounds, and research projects; PBL means Problem Based Learning."},{"id":"SSPT25016","type":"mcq","cat":"SS5_lec5","q":"Which set contains only characteristics of a successful team?","options":["Purpose, goals, leadership, respect.","On time, goals, leadership, respect.","Purpose, rounds, leadership, respect.","Purpose, goals, leadership, preparation."],"correct":0,"explain":"Successful teams have common purpose, measurable goals, effective leadership, and mutual respect."}]}},"banks/studyskills/lecture-6-adult-independent-learning.json":{"id":"ss-lec6-adult-il","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 6 – Adult and Independent Learning","formSize":46,"forms":["A"],"bank":{"A":[{"id":"SSPT26000","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What does pedagogy mean?","options":["Helping adults learn","Educating children","Leading adults","Supporting independence"],"correct":1,"explain":"Pedagogy means educating children. The word parts give ped as child and agogos as lead. Helping adults learn and leading adults describe andragogy. Supporting independence describes independent learning."},{"id":"SSPT26001","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What does andragogy mean?","options":["Educating children","Helping adults learn","Leading children","Supporting independence"],"correct":1,"explain":"Andragogy means helping adults learn. The word parts give andro as man or adult and agogos as lead. Educating children and leading children describe pedagogy. Supporting independence describes independent learning."},{"id":"SSPT26002","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What does pedagogy describe?","options":["Learner-centered education","Teacher-centered education","Independent learning","Dependent learning"],"correct":1,"explain":"Pedagogy describes teacher-centered education. Learner-centered education describes andragogy. Independent learning is a process, and dependent learning contrasts with independent learning."},{"id":"SSPT26003","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What does andragogy describe?","options":["Teacher-centered education","Learner-centered education","Independent learning","Dependent learning"],"correct":1,"explain":"Andragogy describes learner-centered education. Teacher-centered education relates to pedagogy. Independent learning is a process, and dependent learning contrasts with independent learning."},{"id":"SSPT26004","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What replaces teacher-centered education in higher education?","options":["Assessment-centered education","Experience-centered education","Learner-centered education","Feedback-centered education"],"correct":2,"explain":"Higher education shifts to learner-centered education. Assessment, experience, and feedback are principle-related terms, not the named educational approach."},{"id":"SSPT26005","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Progress is not in age, but in psychological and what?","options":["Emotional maturity","Intellectual maturity","Social maturity","Physical maturity"],"correct":1,"explain":"Progress is in psychological and intellectual maturity. Emotional, social, and physical maturity are not named."},{"id":"SSPT26006","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Adults need help seeing themselves as what?","options":["Teachers","Learners","Supervisors","Evaluators"],"correct":1,"explain":"Adults need assistance understanding themselves as learners. Teachers, supervisors, and evaluators describe educator roles, not the learner identity adults need to adopt."},{"id":"SSPT26007","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Medical students must find, judge, and use what?","options":["Goals","Knowledge","Problems","Strengths"],"correct":1,"explain":"Medical students depend on themselves in finding, judging, and using knowledge. Goals, problems, and strengths are handled by other adult-learning principles."},{"id":"SSPT26008","type":"matching","cat":"Lecture 6 – Adult and Independent Learning","q":"Match each adult-learning principle to its application.","leftItems":[{"id":"1","text":"Self-direction"},{"id":"2","text":"Life experience"},{"id":"3","text":"Goal focus"},{"id":"4","text":"Relevancy focus"}],"rightItems":[{"id":"A","text":"Confirm intended results"},{"id":"B","text":"Link to career"},{"id":"C","text":"Manage personal time"},{"id":"D","text":"Use prior knowledge"}],"correct_pairs":{"1":"C","2":"D","3":"A","4":"B"},"explain":"Self-direction means managing personal time. Life experience means using prior knowledge. Goal focus means confirming intended results. Relevancy focus means linking learning to a career."},{"id":"SSPT26009","type":"matching","cat":"Lecture 6 – Adult and Independent Learning","q":"Match each adult-learning principle to its application.","leftItems":[{"id":"1","text":"Motivation"},{"id":"2","text":"Participation"},{"id":"3","text":"Feedback"},{"id":"4","text":"Preferences"}],"rightItems":[{"id":"A","text":"Vary methods often"},{"id":"B","text":"Seek practical benefits"},{"id":"C","text":"Join group tasks"},{"id":"D","text":"Apply helpful comments"}],"correct_pairs":{"1":"B","2":"C","3":"D","4":"A"},"explain":"Motivation means seeking practical benefits. Participation means joining group tasks. Feedback means applying helpful comments. Preferences means varying methods often."},{"id":"SSPT26010","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the autonomy principle?","options":["Use earlier learning","Set personal goals","Seek practical benefit","Vary learning methods"],"correct":1,"explain":"Autonomy includes taking responsibility, setting goals, diagnosing needs, and managing time. Earlier learning, practical benefit, and varying methods belong to other adult-learning principles."},{"id":"SSPT26011","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the background-knowledge principle?","options":["Set personal goals","Request timely comments","Check planned outcomes","Use earlier learning"],"correct":3,"explain":"The background-knowledge principle means linking new material to earlier learning. Setting goals, requesting comments, and checking outcomes belong to other principles."},{"id":"SSPT26012","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the goal-oriented principle?","options":["Use earlier learning","Check planned outcomes","Seek practical benefit","Practice skills in groups"],"correct":1,"explain":"Goal-oriented adults clarify expectations and verify achievement. Earlier learning, practical benefit, and group practice belong to other principles."},{"id":"SSPT26013","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the relevancy principle?","options":["Use earlier learning","Request timely comments","Connect to career","Check planned outcomes"],"correct":2,"explain":"Relevancy-oriented adults connect learning to future professional roles and apply it practically. Earlier learning, comments, and outcome checks belong to other principles."},{"id":"SSPT26014","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the motivation principle?","options":["Check planned outcomes","Practice skills in groups","Use earlier learning","Seek practical benefit"],"correct":3,"explain":"Motivated adults seek practical benefit and challenge themselves for better outcomes. Planned outcomes, group practice, and earlier learning belong to other principles."},{"id":"SSPT26015","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the active-participation principle?","options":["Seek practical benefit","Practice in groups","Check planned outcomes","Use earlier learning"],"correct":1,"explain":"Active participants solve problems, question, share experiences, and practice skills in groups. Practical benefit, planned outcomes, and earlier learning belong to other principles."},{"id":"SSPT26016","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the feedback principle?","options":["Practice in groups","Request timely comments","Seek practical benefit","Vary methods used"],"correct":1,"explain":"Feedback principles call for seeking and using instructor and peer comments for development. Group practice, practical benefit, and varying methods belong to other principles."},{"id":"SSPT26017","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which action matches the learning-styles principle?","options":["Request timely comments","Check planned outcomes","Practice in groups","Vary methods used"],"correct":3,"explain":"Learning-style principles call for evaluating preferences and varying methods; medical students often use multiple styles. Comments, outcome checks, and group practice belong to other principles."},{"id":"SSPT26018","type":"stepped","cat":"Lecture 6 – Adult and Independent Learning","q":"Independent learning has five responsibilities.","steps":[{"id":"1","prompt":"Students take responsibility for identifying what?","options":["Learning styles","Assessment demands","Needs-to-know","Peer feedback"],"correct":2},{"id":"2","prompt":"After identifying needs-to-know, students search for what?","options":["Background knowledge","Relevant information","Learning styles","Assessment demands"],"correct":1},{"id":"3","prompt":"After searching for relevant information, students learn with what?","options":["Maximum guidance","Minimum supervision","Fixed methods","Teacher control"],"correct":1},{"id":"4","prompt":"While learning with minimum supervision, students solve what?","options":["Learning goals","Peer feedback","Assessment demands","Own problems"],"correct":3},{"id":"5","prompt":"After solving own problems, students assess what?","options":["Needs-to-know","Learning goals","Own learning","Peer feedback"],"correct":2}],"explain":"Step 1: identify needs-to-know. Step 2: search relevant information. Step 3: learn with minimum supervision. Step 4: solve own problems. Step 5: assess own learning. Learning styles, goals, feedback, and assessment demands are separate concepts."},{"id":"SSPT26019","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Independent learning is not what?","options":["Facilitating learning","Abandoning support","Supporting learners","Increasing responsibility"],"correct":1,"explain":"Independent learning is not abandoning support or placing all responsibility on students. It facilitates and supports learners while increasing their responsibility."},{"id":"SSPT26020","type":"matching","cat":"Lecture 6 – Adult and Independent Learning","q":"Match each term to its description.","leftItems":[{"id":"1","text":"Dependent learners"},{"id":"2","text":"Independent learners"},{"id":"3","text":"Pedagogy"}],"rightItems":[{"id":"A","text":"Rely on teachers"},{"id":"B","text":"Plan and reflect"},{"id":"C","text":"Lead children"},{"id":"D","text":"Support adults"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Dependent learners rely on teachers. Independent learners plan and reflect. Pedagogy means leading children. Supporting adults describes andragogy."},{"id":"SSPT26021","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Who do dependent learners think is responsible for learning?","options":["Themselves","The teacher","Their peers","Outside resources"],"correct":1,"explain":"Dependent learners think the teacher is responsible for all their learning. They also rely heavily on the teacher and do not plan or reflect. Themselves, peers, and resources are not the stated belief."},{"id":"SSPT26022","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Independent learners reflect on what?","options":["Teacher demands","Their progress","Peer feedback","Background knowledge"],"correct":1,"explain":"Independent learners reflect on their learning progress. Teacher demands, peer feedback, and background knowledge are separate concepts."},{"id":"SSPT26023","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which is a benefit of independent learning?","options":["Dependent learning","Time management","Teacher control","Fixed methods"],"correct":1,"explain":"Time management is listed as a benefit. Dependent learning, teacher control, and fixed methods conflict with independent learning and varied styles."},{"id":"SSPT26024","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which student action supports independent learning?","options":["Designing tasks","Self-assessing work","Evaluating progress","Supplying expertise"],"correct":1,"explain":"Students can self-assess their own work. Designing tasks, evaluating progress, and supplying expertise are teacher roles in independent learning."},{"id":"SSPT26025","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What does a facilitator do?","options":["Supervises learners","Motivates students","Evaluates progress","Supplies expertise"],"correct":1,"explain":"Facilitators motivate students, emphasize purpose and benefits, and design meaningful tasks. Supervising, evaluating progress, and supplying expertise are other teacher roles."},{"id":"SSPT26026","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Adult learning helps people learn what?","options":["What children need","What they want","What goals require","What feedback suggests"],"correct":1,"explain":"Adult learning helps adults learn what they want. Children are told what to learn. Goals and feedback are separate adult-learning principles."},{"id":"SSPT26027","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Applying eight principles helps adults do what?","options":["Teach children","Learn better","Depend on teachers","Attune to assessments"],"correct":1,"explain":"The eight principles help adults learn better. Teaching children describes pedagogy. Depending on teachers describes dependent learners. Attuning to assessments conflicts with motivation."},{"id":"SSPT26028","type":"stepped","cat":"Lecture 6 – Adult and Independent Learning","q":"Learner types differ in responsibility.","steps":[{"id":"1","prompt":"Dependent learners do not know what?","options":["Their teachers","Their strengths","Their peers","Their resources"],"correct":1},{"id":"2","prompt":"Independent learners know their strengths and weaknesses and do what?","options":["Rely on teachers","Take responsibility","Do not plan","Do not reflect"],"correct":1}],"explain":"Dependent learners do not know their strengths. Independent learners know their strengths and weaknesses and take responsibility. Relying on teachers, not planning, and not reflecting describe dependent learners."},{"id":"SSPT26029","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Dependent learners do not connect classroom learning to what?","options":["Peer feedback","Real world","Personal development","Background knowledge"],"correct":1,"explain":"Dependent learners do not connect classroom learning to the real world. Peer feedback, personal development, and background knowledge are separate concepts."},{"id":"SSPT26030","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"CME is pursued easily by which learners?","options":["Dependent learners","Independent learners","Goal-oriented learners","Relevancy-oriented learners"],"correct":1,"explain":"Independent learners easily pursue CME after graduation. Dependent learners rely on teachers. Goal orientation and relevancy are adult-learning principles, not the stated CME learner type."},{"id":"SSPT26031","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What does a feedback provider do?","options":["Supervises learning","Gives comments","Designs tasks","Supplies expertise"],"correct":1,"explain":"Feedback providers give comments on progress. Subject experts supply knowledge, supervisors oversee learning, and facilitators motivate and design tasks."},{"id":"SSPT26032","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Adults need help seeing themselves as learners and are what?","options":["Dependent","Independent","Assessment-focused","Single-style"],"correct":1,"explain":"Adults are independent learners. Dependent learners rely heavily on teachers. Assessment-focused and single-style approaches conflict with motivation and varied methods."},{"id":"SSPT26033","type":"stepped","cat":"Lecture 6 – Adult and Independent Learning","q":"Independent learning involves increasing responsibility.","steps":[{"id":"1","prompt":"What do students search for?","options":["Background knowledge","Relevant information","Learning styles","Teacher demands"],"correct":1},{"id":"2","prompt":"After searching for relevant information, students assess what?","options":["Own learning","Teacher demands","Learning styles","Background knowledge"],"correct":0}],"explain":"Step 1: Independent learning includes searching for relevant information. Step 2: It also includes assessing own learning. Background knowledge relates to experience, learning styles to preferences, and teacher demands to motivation."},{"id":"SSPT26034","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"How many adult-learning principles are listed?","options":["Six","Seven","Eight","Nine"],"correct":2,"explain":"There are eight principles for adult learning. Six, seven, and nine do not match the listed number."},{"id":"SSPT26035","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Independent learning makes learning what?","options":["Difficult","Enjoyable","Passive","Fixed"],"correct":1,"explain":"Independent learning makes learning enjoyable. Difficult, passive, and fixed conflict with active participation, support, and varied methods."},{"id":"SSPT26036","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which type of learners make decisions about their own learning?","options":["Dependent","Independent","Assessment-focused","Single-style"],"correct":1,"explain":"Independent learners make decisions about their own learning. Dependent learners rely on teachers. Assessment-focused and single-style approaches conflict with motivation and varied methods."},{"id":"SSPT26037","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Which quality supports becoming an independent learner?","options":["Dependence","Enthusiasm","Teacher control","Fixed methods"],"correct":1,"explain":"Enthusiasm supports becoming an independent learner. Dependence, teacher control, and fixed methods conflict with independence, facilitation, and varied learning styles."},{"id":"SSPT26038","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Independent learners ask for help from whom?","options":["Goals and resources","Peers and faculty","Strengths and weaknesses","Tasks and feedback"],"correct":1,"explain":"Independent learners ask for help from peers and faculty. Goals, resources, strengths, weaknesses, tasks, and feedback are learning objects, not people."},{"id":"SSPT26039","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What does a subject area expert supply?","options":["Supervision","Knowledge","Evaluation","Facilitation"],"correct":1,"explain":"Subject area experts supply knowledge. Supervision, evaluation, and facilitation are other teacher roles in independent learning."},{"id":"SSPT26040","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Independent learning moves from setting goals to achieving learning and what?","options":["Abandoning","Evaluating","Shifting","Controlling"],"correct":1,"explain":"Independent learning moves from setting goals to achieving learning and evaluating it. Abandoning, shifting, and controlling conflict with facilitation and responsibility."},{"id":"SSPT26041","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"In independent learning, teachers must have what?","options":["Absent support","Active roles","Total independence","Passive observation"],"correct":1,"explain":"Teachers must have active roles in independent learning. Absent support, total independence, and passive observation conflict with facilitation and support."},{"id":"SSPT26042","type":"matching","cat":"Lecture 6 – Adult and Independent Learning","q":"Match each adult-learning principle to its main idea.","leftItems":[{"id":"1","text":"Autonomous and self-directed"},{"id":"2","text":"Background knowledge"},{"id":"3","text":"Goal-oriented"},{"id":"4","text":"Relevancy-oriented"},{"id":"5","text":"Motivated"},{"id":"6","text":"Active participants"},{"id":"7","text":"Timely feedback"},{"id":"8","text":"Learning preferences"}],"rightItems":[{"id":"A","text":"Take responsibility, set goals, manage time"},{"id":"B","text":"Link new material to prior experience"},{"id":"C","text":"Clarify expectations and verify achievement"},{"id":"D","text":"Connect learning to future professional role"},{"id":"E","text":"Seek practical benefit and better outcomes"},{"id":"F","text":"Problem-solve, question, practice skills in groups"},{"id":"G","text":"Seek and use comments for personal development"},{"id":"H","text":"Vary methods; medical students use multiple styles"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G","8":"H"},"explain":"Autonomous means taking responsibility and managing time. Background knowledge means linking to prior experience. Goal-oriented means clarifying and verifying goals. Relevancy-oriented means connecting to future role. Motivated means seeking practical benefit. Active participants means problem-solving and practicing in groups. Timely feedback means using comments for development. Learning preferences means varying methods."},{"id":"SSPT26043","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"What changes as people progress from childhood to adulthood?","options":["Mode of learning","Physical maturity","Teacher control","Assessment focus"],"correct":0,"explain":"Their mode of learning changes. Progress is in psychological and intellectual maturity, not age. Teacher control and assessment focus are not the stated change."},{"id":"SSPT26044","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Learning is a long-term change in mental representations as a result of what?","options":["Experience","Maturity","Teacher demands","Fixed methods"],"correct":0,"explain":"Learning is a long-term change in mental representations (behaviors) as a result of experience. Maturity, teacher demands, and fixed methods are not the source."},{"id":"SSPT26045","type":"mcq","cat":"Lecture 6 – Adult and Independent Learning","q":"Learning cannot be said to occur unless there is a change in what?","options":["Behavior","Maturity","Goals","Values"],"correct":0,"explain":"Learning cannot be said to occur unless there is a change in Behavior. Maturity, goals, and values are not the required change."}]}},"banks/studyskills/lecture-7-tips-for-studying.json":{"id":"ss-lec7","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 7 – Tips for Good Study Habits","formSize":71,"forms":["A"],"bank":{"A":[{"id":"SSPT27000","type":"mcq","cat":"Tips for Good Study Habits","q":"What is the first study habit tip?","options":["Process information deeply","Highlight every line as you read","Save practice questions for night","Set a regular time to study"],"correct":0,"explain":"The first tip is to process information as deeply as possible. Highlighting while reading can become mindless. Saving practice for the night before is not advised. Setting a regular time is a study-atmosphere tip."},{"id":"SSPT27001","type":"mcq","cat":"Tips for Good Study Habits","q":"What does elaboration help you do?","options":["Use practice exams to guide studying","Link information to what you know","Formulate questions to maintain reading focus","Layer major concepts before smaller details"],"correct":1,"explain":"Elaboration helps memory by linking information to what you already know. Practice exams guide studying, questions maintain focus, and layering organizes concepts."},{"id":"SSPT27002","type":"mcq","cat":"Tips for Good Study Habits","q":"How should you organize studying by layering?","options":["Small details before big ideas","Major concepts, categories, then headings","Headings before the major categories","Subheadings before the overarching concepts"],"correct":1,"explain":"Layering means learning major concepts first, then big categories, then headings and subheadings. Details-first, headings-first, and subheadings-first reverse the order."},{"id":"SSPT27003","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you do with practice exams and questions from study aids?","options":["Save them for the night before the exam","Use them to guide your studying","Skip them when preparing for exams","Review them after the exam has ended"],"correct":1,"explain":"Practice exams and questions from study aids should guide studying while you study. They should not be saved for the night before the exam."},{"id":"SSPT27004","type":"mcq","cat":"Tips for Good Study Habits","q":"When studying practice questions, what should you examine?","options":["The right answers and the stem","The wrong answers and the stem","Both right and wrong answers","The title and the instructions"],"correct":2,"explain":"Look at both right and wrong answers for clues about what is important to study. The stem, title, or instructions do not give the same answer-pattern clues."},{"id":"SSPT27005","type":"mcq","cat":"Tips for Good Study Habits","q":"When should you highlight while reading?","options":["As you read each line quickly","After finishing a paragraph or section","Before opening the assigned textbook chapter","On the title and cover page"],"correct":1,"explain":"Highlight after finishing a paragraph or section, then think about the most important information and go back to highlight it. Line-by-line highlighting can become mindless."},{"id":"SSPT27006","type":"mcq","cat":"Tips for Good Study Habits","q":"What does formulating questions do while reading?","options":["It replaces careful reading.","It gives a purpose and helps focus.","It encourages mindless highlighting.","It prevents prediction of exam questions."],"correct":1,"explain":"Formulating questions is an active reading strategy. It gives a purpose for reading, raises curiosity, increases comprehension, and helps maintain focus."},{"id":"SSPT27007","type":"mcq","cat":"Tips for Good Study Habits","q":"When can you write questions for active reading?","options":["Before opening the chapter and after highlighting","While reading each section and after taking notes","Before, during, and after you read","After finishing a paragraph and before surveying"],"correct":2,"explain":"Write questions before you read, as you read, and after you read. The other options pair reading stages with highlighting, note-taking, or surveying and miss part of the active reading strategy."},{"id":"SSPT27008","type":"mcq","cat":"Tips for Good Study Habits","q":"What is the first step of SQ4R?","options":["Recite important information","Review information learned","Record information in notes","Survey the chapter"],"correct":3,"explain":"SQ4R starts with surveying the chapter. Reciting, reviewing, and recording are later steps."},{"id":"SSPT27009","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists the SQ4R steps in order?","options":["Survey, Read, Question, Record, Recite, Review","Survey, Question, Read, Recite, Record, Review","Survey, Question, Read, Record, Recite, Review","Survey, Question, Read, Record, Review, Recite"],"correct":2,"explain":"The order is Survey, Question, Read, Record, Recite, Review. Each wrong option swaps one step position, making the sequence incorrect."},{"id":"SSPT27010","type":"mcq","cat":"Tips for Good Study Habits","q":"What is the first essential strategy for textbook reading?","options":["Organized chapter system","Clear intention to understand","Inquisitive reading approach","Effective reading time management"],"correct":1,"explain":"The first essential strategy is a clear intention to understand what you read. Organized systems, inquisitiveness, and time management are other essential strategies."},{"id":"SSPT27011","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you relate new information to?","options":["Sensory codes for words","Long-term memory schemas","Textbook headings and subheadings","The glossary and index entries"],"correct":1,"explain":"Relate new information to existing schemas in long-term memory. Sensory codes, headings, and glossary or index entries are other reading or surveying tools."},{"id":"SSPT27012","type":"mcq","cat":"Tips for Good Study Habits","q":"Which textbook part lists the chapters and page numbers?","options":["Appendix","Glossary","Index","Table of contents"],"correct":3,"explain":"The table of contents lists chapters and page numbers. An appendix adds material, a glossary defines terms, and an index locates topics."},{"id":"SSPT27013","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you read carefully when surveying a chapter?","options":["End-of-chapter materials","Introductory material","Glossary definitions","Index entries"],"correct":1,"explain":"Read introductory material carefully. Headings, visuals, marginal notes, terminology, and end-of-chapter items are also surveyed, but the advice singles out introductory material."},{"id":"SSPT27014","type":"mcq","cat":"Tips for Good Study Habits","q":"How should you begin reading science textbooks?","options":["Read examples before any overview","Use thorough reading from the start","Begin with overview reading","Skip diagrams and charts"],"correct":2,"explain":"Begin with overview reading, then use thorough reading. Examples, terminology, mental images, recitation, diagrams, and larger concepts come later."},{"id":"SSPT27015","type":"mcq","cat":"Tips for Good Study Habits","q":"How long should pre-reading take?","options":["About two hours","About five minutes","About 10-15 minutes","The entire night"],"correct":2,"explain":"Pre-reading should involve basic skimming and take about 10-15 minutes. Two hours, five minutes, or the entire night do not match the stated time."},{"id":"SSPT27016","type":"mcq","cat":"Tips for Good Study Habits","q":"Where should you sit during class?","options":["Near talking friends","In the back row","While checking your phone","Where distractions are minimized"],"correct":3,"explain":"Sit where distractions will be minimized. Talking friends, the back row, and phone checking increase distractions."},{"id":"SSPT27017","type":"mcq","cat":"Tips for Good Study Habits","q":"When should you review notes after class?","options":["After one month","Within a day or two","Never again","During the exam"],"correct":1,"explain":"Briefly review notes within a day or two. Waiting a month, never reviewing, or reviewing during the exam does not follow the timing."},{"id":"SSPT27018","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you form for class?","options":["A constant talking habit","A daydreaming habit","A good listening habit","A phone checking habit"],"correct":2,"explain":"Form a good listening habit. Talking, daydreaming, and phone checking prevent listening."},{"id":"SSPT27019","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you avoid for studying?","options":["Using a clear desk","Using good lighting","Using a proper chair","Using your bed"],"correct":3,"explain":"Try not to use your bed for studying so it stays linked to relaxation. A clear desk, good lighting, and a proper chair support studying."},{"id":"SSPT27020","type":"mcq","cat":"Tips for Good Study Habits","q":"What should a study desk have on it?","options":["Many unrelated objects","Nothing except the subject","Snacks and drinks","Your phone and charger"],"correct":1,"explain":"The desk should have nothing on it except the subject you are studying. Unrelated objects, snacks, drinks, and phones create distractions."},{"id":"SSPT27021","type":"mcq","cat":"Tips for Good Study Habits","q":"Which items are listed as necessary for studying?","options":["Soft bed, good lighting, chair, books, supplies, clock, drink","Solid surface, good lighting, chair, books, supplies, clock, drink","Solid surface, good lighting, phone, books, supplies, clock, drink","Solid surface, good lighting, chair, books, supplies, clock, snacks"],"correct":1,"explain":"The listed items are a solid surface, good lighting, a chair, books, supplies, a clock, and a drink. A soft bed, a phone, and snacks replace required items."},{"id":"SSPT27022","type":"mcq","cat":"Tips for Good Study Habits","q":"Is your best friend the best study partner?","options":["The guaranteed best partner","Not necessarily the best partner","A partner identical to you","A person who avoids discussion"],"correct":1,"explain":"Your best friend is not necessarily your best study partner. A different partner may give a new perspective. A guaranteed choice, identical partner, and avoiding discussion do not match."},{"id":"SSPT27023","type":"mcq","cat":"Tips for Good Study Habits","q":"What should a real break include?","options":["Stay seated and stare","Check your phone the whole time","Get up and walk around","Keep reading without pause"],"correct":2,"explain":"Make sure a break is really a break. Get up, go outside, and walk around. Staying seated, checking the phone, or continuing to read does not make a real break."},{"id":"SSPT27024","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists everyday brain foods?","options":["Crisps, chocolate, soda, and candy","Breakfast, oranges, water, and eggs","Energy drinks and chocolate bars","Chips, cookies, juice, and soda"],"correct":1,"explain":"Everyday brain foods listed include breakfast, oranges, water, healthy snacks, eggs, fish, berries, raisins, chocolate/crisps, and nuts. The other sets are not the listed everyday brain-food set."},{"id":"SSPT27025","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you do if you cannot focus on reading?","options":["Sit and stare at the book","Do an easier task then retry","Give up for the day","Check your phone instead"],"correct":1,"explain":"Do something a bit easier or more enjoyable, then try again in 30 minutes. Sitting and staring, giving up, or checking the phone does not ease you back into studying."},{"id":"SSPT27026","type":"mcq","cat":"Tips for Good Study Habits","q":"What is a mind map?","options":["A long written list","A single paragraph","A table of numerical data","A diagram to organize info"],"correct":3,"explain":"A mind map is a diagram used to visually organize information. It is hierarchical and shows relationships among pieces of the whole. A list, paragraph, or numerical table is not a mind map."},{"id":"SSPT27027","type":"mcq","cat":"Tips for Good Study Habits","q":"Who are mind maps especially good for?","options":["The auditory learner","The visual learner","The kinesthetic learner","No particular learner"],"correct":1,"explain":"Mind maps are good for the visual learner. They are used to visualize, structure, and classify ideas. Auditory, kinesthetic, and no learner do not match the statement."},{"id":"SSPT27028","type":"mcq","cat":"Tips for Good Study Habits","q":"Which is a study technique?","options":["Study the easy subject first","Study where you usually sleep","Study difficult subject first","Ignore short waiting time gaps"],"correct":2,"explain":"Study difficult subjects first. Also use waiting time effectively and use a regular study area day after day. Easy-first, sleeping area, and ignored gaps go against the techniques."},{"id":"SSPT27029","type":"mcq","cat":"Tips for Good Study Habits","q":"Where should you study?","options":["Where you usually sleep","In a noisy social area","While using your phone","Where you will stay alert"],"correct":3,"explain":"Study where you will be alert. Do not study where you sleep, in noisy areas, or while using the phone. The library can also signal work mode."},{"id":"SSPT27030","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you hang on your door?","options":["A come in anytime sign","A phone is available sign","A do not disturb sign","A study after lunch sign"],"correct":2,"explain":"Hang a do not disturb sign on your door. A come in anytime sign, a phone is available sign, or a study after lunch sign would invite interruptions or delay study."},{"id":"SSPT27031","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists the keys to study?","options":["Time management, daydreaming, note taking, focus","Excuses, mind maps, note taking, focus","Time management, mind maps, note taking, focus","Time management, mind maps, phone use, focus"],"correct":2,"explain":"The keys are time management, mind maps, note taking, and concentration. Daydreaming, excuses, and phone use are distractions, not keys."},{"id":"SSPT27032","type":"stepped","cat":"Tips for Good Study Habits","q":"Use the SQ4R sequence.","steps":[{"id":"1","prompt":"What is the first SQ4R step?","options":["Scan","Skim","Survey","Summarize"],"correct":2},{"id":"2","prompt":"After Survey, what is the next SQ4R step?","options":["Question","Query","Quiz","Qualify"],"correct":0},{"id":"3","prompt":"After Question, what is the next SQ4R step?","options":["Review","Record","Read","Recite"],"correct":2},{"id":"4","prompt":"After Read, what is the next SQ4R step?","options":["Recite","Record","Review","Reflect"],"correct":1},{"id":"5","prompt":"After Record, what is the next SQ4R step?","options":["Review","Reflect","Recite","Read"],"correct":2},{"id":"6","prompt":"After Recite, what is the final SQ4R step?","options":["Reflect","Record","Read","Review"],"correct":3}],"explain":"SQ4R order is Survey, Question, Read, Record, Recite, Review. Survey is first; Question follows Survey; Read follows Question; Record follows Read; Recite follows Record; Review is final."},{"id":"SSPT27033","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you stop looking for?","options":["More free study time slots","Better study lighting options","A quieter study place","Excuses not to study"],"correct":3,"explain":"Stop looking for excuses not to study. Think about the end goal, your exam. Free time, lighting, and quieter places are useful adjustments, not excuses."},{"id":"SSPT27034","type":"mcq","cat":"Tips for Good Study Habits","q":"How can you use dead time?","options":["For extra sleep daily","More effectively for studying","For phone and messaging","Leave it unused"],"correct":1,"explain":"Think about dead time and use it more effectively for studying. Sleep, phone use, or leaving it unused does not use it effectively."},{"id":"SSPT27035","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you know to prepare well?","options":["The paper title","One sample question","The exam papers well","Nothing about exams"],"correct":2,"explain":"Know the exam papers and review mock exam papers. The paper title, one sample question, or no exam knowledge does not prepare you fully."},{"id":"SSPT27036","type":"mcq","cat":"Tips for Good Study Habits","q":"What is the key to study?","options":["Avoiding exam preparation","Learning to be a smart learner","Studying one single time","Ignoring time management rules"],"correct":1,"explain":"The key to study is learning to be a smart learner, especially with exam questions and exam papers. Avoiding preparation, studying once, or ignoring time management is the opposite."},{"id":"SSPT27037","type":"mcq","cat":"Tips for Good Study Habits","q":"What do questions and answers create?","options":["Extra confusion for the reader","More boredom during reading","Additional distraction during class","Memory cues or associations"],"correct":3,"explain":"Questions and answers create memory cues or associations to recall information later. They do not create confusion, boredom, or distraction."},{"id":"SSPT27038","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you do with notes after class?","options":["Leave them unchanged","Reorganize restate reformat","Throw them away","Read them once"],"correct":1,"explain":"Reorganize, restate, and reformat notes to process information at a deeper level. Leaving them unchanged, throwing them away, or reading them once does not deepen processing."},{"id":"SSPT27039","type":"mcq","cat":"Tips for Good Study Habits","q":"Why should you note your caffeine intake?","options":["Track hunger and snack timing","Take real breaks outside","Link the bed with relaxation","Balance alertness and sleep"],"correct":3,"explain":"Note caffeine intake so you can keep alert without becoming jittery and stop in time to sleep. Hunger, outdoor breaks, and bed-relaxation are separate study-habit tips."},{"id":"SSPT27040","type":"mcq","cat":"Tips for Good Study Habits","q":"Which situation illustrates using waiting time?","options":["Long continuous study blocks","Late night study sessions","Bus waits between classes","Ignored short time gaps"],"correct":2,"explain":"Use waiting time effectively, such as waiting for the bus or time between classes. Long blocks, late nights, or ignored gaps waste usable time."},{"id":"SSPT27041","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you agree with family about?","options":["No study time scheduled","Suitable study times","Phone time instead","Quiet time banned"],"correct":1,"explain":"Agree with family or friends about suitable study time. No scheduled study time, phone time, or banned quiet time would prevent studying."},{"id":"SSPT27042","type":"mcq","cat":"Tips for Good Study Habits","q":"What should good study habits help you remember?","options":["Study excuses","Study distractions","Phone contact numbers","Your predicted results"],"correct":3,"explain":"With good study habits, you should remember your predicted results. Excuses, distractions, and phone numbers are not the stated outcome."},{"id":"SSPT27043","type":"mcq","cat":"Tips for Good Study Habits","q":"Which approach divides learning into separate sessions?","options":["Timetable planning","Use of waiting time","Regular study time","Spaced studying"],"correct":3,"explain":"Spaced studying means learning across separate sessions. Timetable planning, use of waiting time, and regular study time are other ways to manage study time."},{"id":"SSPT27044","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists study techniques?","options":["Deep processing, waiting time, regular study area, library signal","Difficult subject first, mind maps, regular study area, library signal","Difficult subject first, waiting time, highlight sections, library signal","Difficult subject first, waiting time, regular study area, library signal"],"correct":3,"explain":"Study techniques include difficult subjects first, waiting time, regular study areas, and library signals. Deep processing, mind maps, and highlighting belong to other study tips."},{"id":"SSPT27045","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists how to get the best possible results?","options":["Predicted results, exam papers, study timetable","Smart learning, do-not-disturb sign, study timetable","Smart learning, exam papers, study timetable","Smart learning, exam papers, brain foods"],"correct":2,"explain":"The best-results advice is smart learning with exam papers, plus using time effectively by making a study timetable. Predicted results, do-not-disturb signs, and brain foods belong to other sections."},{"id":"SSPT27046","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists ways to use your time wisely?","options":["Do-not-disturb sign, exam timetable, dead time, mock papers","Study timetable, brain foods, dead time, mock papers","Study timetable, exam timetable, elaboration, mock papers","Study timetable, exam timetable, dead time, mock papers"],"correct":3,"explain":"Using time wisely includes study and exam timetables, dead time, and mock papers. Do-not-disturb signs, brain foods, and elaboration belong to other tips."},{"id":"SSPT27047","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists the first four study habit tips?","options":["Social studying, reading, lectures, study atmosphere","Processing, highlighting, lectures, study atmosphere","Processing, reading, lectures, study atmosphere","Processing, reading, brain foods, study atmosphere"],"correct":2,"explain":"The first four main tips are processing, reading, lectures, and study atmosphere. Social studying, highlighting, and brain foods are not first-level tips."},{"id":"SSPT27048","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists points for surveying a chapter?","options":["Copyright page, headings, visuals, end-of-chapter items","Introductory material, headings, visuals, the bibliography","Introductory material, headings, appendix, end-of-chapter items","Introductory material, headings, visuals, end-of-chapter items"],"correct":3,"explain":"Chapter surveying includes introductory material, headings, visuals, marginal notes, terminology, and end-of-chapter items. Copyright pages, bibliographies, and appendices belong to textbook surveying."},{"id":"SSPT27049","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists parts for surveying a textbook?","options":["Chapter headings, copyright page, glossary, index","Title page, chapter visuals, glossary, index","Title page, copyright page, end-of-chapter items, index","Title page, copyright page, glossary, index"],"correct":3,"explain":"Textbook surveying includes the title page, copyright page, table of contents, introductory information, appendix, glossary, references, and index. Chapter headings, visuals, and end-of-chapter items belong to chapter surveying."},{"id":"SSPT27050","type":"mcq","cat":"Tips for Good Study Habits","q":"What does liaising with classmates help you do?","options":["Gain a new perspective","Look up websites","Share and swap notes","Use an answering machine"],"correct":2,"explain":"Liaising with classmates helps you get, swap, or share notes. A new perspective comes from a different partner, websites are another help source, and answering machines relate to phone interruptions."},{"id":"SSPT27051","type":"mcq","cat":"Tips for Good Study Habits","q":"After Survey and Question, which set lists the 4 Rs in order?","options":["Record, Read, Recite, Review","Read, Recite, Record, Review","Read, Record, Recite, Review","Read, Record, Review, Recite"],"correct":2,"explain":"SQ4R begins with Survey and Question, then the 4 Rs are Read, Record, Recite, and Review. The wrong options place one R too early or too late."},{"id":"SSPT27052","type":"mcq","cat":"Tips for Good Study Habits","q":"What does liaise mean when classmates help each other?","options":["Link information to prior knowledge","Work together and exchange information","Stay with identical study partners","Visually organize information in a diagram"],"correct":1,"explain":"Liaise means to work together and exchange information. When classmates help each other, this includes getting, swapping, or sharing notes. Linking information describes elaboration, identical partners relates to study partners, and diagrams describe mind maps."},{"id":"SSPT27053","type":"mcq","cat":"Tips for Good Study Habits","q":"Which elaboration method reorganizes information?","options":["Use vivid visualization","Act out a needed situation","Reorganize with charts or diagrams","Link information to prior knowledge"],"correct":2,"explain":"Elaboration includes linking information to prior knowledge, reorganizing with charts, outlines, or diagrams, using vivid visualization, and acting out situations. This item tests the reorganizing method."},{"id":"SSPT27054","type":"mcq","cat":"Tips for Good Study Habits","q":"What do practice questions show you?","options":["How to layer major concepts","When to take a real break","Where to read or watch more","Why to use a mind map"],"correct":2,"explain":"Practice questions show where you need to read or watch more. Layering, breaks, and mind maps are other study-habit tips."},{"id":"SSPT27055","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you do after finishing a section?","options":["Use spaced studying","Predict exam questions","Liaise with classmates","Create memory cues"],"correct":1,"explain":"After finishing a section, predict possible exam questions, their wording, correct answers, and misleading answers. Spaced studying, liaising, and memory cues are other tips."},{"id":"SSPT27056","type":"stepped","cat":"Tips for Good Study Habits","q":"Use the pre-lecture preparation steps.","steps":[{"id":"1","prompt":"What should you pre-read before lecture?","options":["New words","Difficult points","Major concepts","Note plans"],"correct":2},{"id":"2","prompt":"After pre-reading major concepts, how long should skimming take?","options":["About 2-5 minutes","About 10-15 minutes","About 20-30 minutes","About 45-60 minutes"],"correct":1},{"id":"3","prompt":"After skimming for 10-15 minutes, what should you understand?","options":["New words","Difficult points","Note plans","Major concepts"],"correct":0},{"id":"4","prompt":"After understanding new words, what should you identify?","options":["Note plans","Difficult points","Major concepts","Basic skimming"],"correct":1},{"id":"5","prompt":"After identifying difficult points, what should you plan?","options":["Highlighting method","Break timing","Lecture seating","Note organization"],"correct":3}],"explain":"Pre-lecture preparation moves from major concepts to 10-15 minute skimming, new words, difficult points, and note organization. Other durations, later items, highlighting, breaks, and seating are not the asked step."},{"id":"SSPT27057","type":"stepped","cat":"Tips for Good Study Habits","q":"Use the after-lecture note steps.","steps":[{"id":"1","prompt":"What should you mark in notes after lecture?","options":["Your predicted examination results","Your everyday brain-food lists","Clear points, clarification needs","Library quiet-mind study signals"],"correct":2},{"id":"2","prompt":"After marking clear points and clarification needs, what should you cross-reference?","options":["Headings, visuals, marginal notes","Charts, outlines, or diagrams","Lectures, books, other aids","Glossary, index, appendix entries"],"correct":2}],"explain":"After class, mark clear points and clarification needs; predicted results, brain foods, and library signals are other tips. Then cross-reference notes with lectures, books, and aids; headings, charts, and glossary entries are other tools."},{"id":"SSPT27058","type":"stepped","cat":"Tips for Good Study Habits","q":"Use the science-textbook facts.","steps":[{"id":"1","prompt":"What does understanding science textbooks involve?","options":["Overview and thorough reading","Hands-on lab demonstrations","Charts, outlines, and diagrams","Terminology and mental images"],"correct":1},{"id":"2","prompt":"After hands-on lab demonstrations, what does the material use?","options":["Major concept categories","Declarative and procedural knowledge","Charts and mental images","Sensory memory codes"],"correct":1}],"explain":"Understanding science textbooks involves hands-on laboratory demonstrations, experiments, and observations. Science textbooks also use declarative and procedural knowledge. Major concepts, charts, and sensory codes are other tips."},{"id":"SSPT27059","type":"matching","cat":"Tips for Good Study Habits","q":"Match each social-studying helper to its purpose.","leftItems":[{"id":"1","text":"Classmate"},{"id":"2","text":"Different partner"},{"id":"3","text":"Website"}],"rightItems":[{"id":"A","text":"New perspective"},{"id":"B","text":"Swap notes"},{"id":"C","text":"Ask teacher"}],"correct_pairs":{"1":"B","2":"A","3":"C"},"explain":"Social studying includes swapping notes with classmates, gaining a new perspective from a different partner, and asking teachers or looking up websites."},{"id":"SSPT27060","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you track for body needs?","options":["Break and snack timing","Hunger and energy boosts","Caffeine and water intake","Meal and sleep planning"],"correct":1,"explain":"Track when you get hungry and what gives an energy boost so you can plan snacks and meal breaks. Break timing, caffeine and water, and meal or sleep planning are other body-needs points."},{"id":"SSPT27061","type":"mcq","cat":"Tips for Good Study Habits","q":"Why choose the right food and drink?","options":["To organize charts and diagrams","To aid concentration in exams","To create memory cue associations","To maintain focus while reading"],"correct":1,"explain":"Right food and drink aid concentration during exams. Organizing charts, memory cues, and reading focus are other study strategies."},{"id":"SSPT27062","type":"mcq","cat":"Tips for Good Study Habits","q":"Which task suits the evening for a morning person?","options":["Hardest material","Lab demonstrations","Rewriting charts","Mock exam answers"],"correct":2,"explain":"A morning person should study the hardest material in the morning and keep evenings for lower-attention tasks such as making flashcards or rewriting charts. Lab demonstrations and mock papers belong to other sections."},{"id":"SSPT27063","type":"mcq","cat":"Tips for Good Study Habits","q":"What should you do with mock exam papers?","options":["Save them for exam night","Stick them above tables","Review and redo answers","Predict misleading answers"],"correct":2,"explain":"Review mock exam papers and spend time redoing answers. Saving them for exam night, sticking timetables above tables, and predicting misleading answers are other tips."},{"id":"SSPT27064","type":"mcq","cat":"Tips for Good Study Habits","q":"Which set lists uses of mind maps?","options":["Visualize, organize, solve problems, make predictions, structure answers","Visualize, highlight, solve problems, make decisions, structure answers","Visualize, organize, wait for buses, make decisions, structure answers","Visualize, organize, solve problems, make decisions, structure answers"],"correct":3,"explain":"Mind maps are used to visualize, organize information, solve problems, support decision making, and help structure answers. Predictions, highlighting, and waiting time are other study topics."},{"id":"SSPT27065","type":"matching","cat":"Tips for Good Study Habits","q":"Match each essential reading strategy to its description.","leftItems":[{"id":"1","text":"Organized system"},{"id":"2","text":"Be inquisitive"},{"id":"3","text":"Include feedback"},{"id":"4","text":"Manage time"},{"id":"5","text":"Sensory coding"}],"rightItems":[{"id":"A","text":"Use a chapter method"},{"id":"B","text":"Raise curiosity"},{"id":"C","text":"Check progress"},{"id":"D","text":"Plan reading sessions"},{"id":"E","text":"Transform ordinary words"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Essential reading strategies include using an organized system, being inquisitive, including feedback, managing reading time, and encoding ordinary words into new sensory codes."},{"id":"SSPT27066","type":"matching","cat":"Tips for Good Study Habits","q":"Match each deep-processing tip to its purpose.","leftItems":[{"id":"1","text":"Elaboration"},{"id":"2","text":"Layering"},{"id":"3","text":"Practice questions"},{"id":"4","text":"Highlighting after a section"}],"rightItems":[{"id":"A","text":"Link new material to what you already know"},{"id":"B","text":"Learn major concepts before categories and headings"},{"id":"C","text":"Show where you need to read or review more"},{"id":"D","text":"Avoid mindless marking while reading line by line"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Elaboration links new information to existing knowledge. Layering starts with major concepts. Practice questions guide further study. Highlighting after a section prevents mindless marking."},{"id":"SSPT27067","type":"matching","cat":"Tips for Good Study Habits","q":"Match each SQ4R step to what it involves.","leftItems":[{"id":"1","text":"Survey"},{"id":"2","text":"Question"},{"id":"3","text":"Read"},{"id":"4","text":"Record"},{"id":"5","text":"Recite"},{"id":"6","text":"Review"}],"rightItems":[{"id":"A","text":"Skim headings and structure first"},{"id":"B","text":"Turn headings into questions"},{"id":"C","text":"Look for answers while reading"},{"id":"D","text":"Write the answers in your notes"},{"id":"E","text":"Say the answers aloud from memory"},{"id":"F","text":"Go back over the material later"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"SQ4R: Survey the structure, Question by turning headings into questions, Read to find answers, Record the answers, Recite from memory, and Review later."},{"id":"SSPT27068","type":"matching","cat":"Tips for Good Study Habits","q":"Match each study-atmosphere tip to its action.","leftItems":[{"id":"1","text":"Regular place"},{"id":"2","text":"Do not disturb sign"},{"id":"3","text":"Clear table"},{"id":"4","text":"Get off the phone"}],"rightItems":[{"id":"A","text":"Study in the same location so your mind associates it with work"},{"id":"B","text":"Signal others not to interrupt you"},{"id":"C","text":"Keep only the current subject materials on the desk"},{"id":"D","text":"Use the answering machine and avoid becoming a phone victim"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"A regular place builds a study association. A do not disturb sign blocks interruptions. A clear table removes distractions. Getting off the phone prevents constant interruptions."},{"id":"SSPT27069","type":"matching","cat":"Tips for Good Study Habits","q":"Match each key to study to its focus.","leftItems":[{"id":"1","text":"Time management"},{"id":"2","text":"Mind maps"},{"id":"3","text":"Note taking"},{"id":"4","text":"Concentration"}],"rightItems":[{"id":"A","text":"Plan when and how long you study"},{"id":"B","text":"Visually organize relationships among ideas"},{"id":"C","text":"Capture and reorganize lecture and textbook material"},{"id":"D","text":"Maintain focus and avoid daydreaming or interruptions"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"The four keys are time management (planning study time), mind maps (visual organization), note taking (from lectures and textbooks), and concentration (sustained focus)."},{"id":"SSPT27070","type":"matching","cat":"Tips for Good Study Habits","q":"Match each body-needs tip to its purpose.","leftItems":[{"id":"1","text":"Track hunger"},{"id":"2","text":"Note caffeine"},{"id":"3","text":"Plan breaks"},{"id":"4","text":"Choose brain foods"}],"rightItems":[{"id":"A","text":"Know when you need an energy boost and plan snacks"},{"id":"B","text":"Find the amount and timing that keeps you alert without jitteriness"},{"id":"C","text":"Get up, walk, and make the break a real break"},{"id":"D","text":"Support concentration and exam performance with suitable food and drink"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Track hunger to plan snacks, note caffeine timing and amount, take real breaks by moving, and choose brain foods that aid concentration."}]}},"banks/studyskills/lecture-8-note-taking-strategies.json":{"id":"ss-lec8-note-taking","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 8 – Effective Note-Taking Strategies","formSize":61,"forms":["A"],"bank":{"A":[{"id":"SSPT28000","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"How many note-taking options are outlined?","options":["Three","Four","Five","Seven"],"correct":2,"explain":"Five note-taking options are outlined: Cornell, Index Card, Two-Column, Three-Column, and Formal Outline. Three, four, and seven do not match the listed set."},{"id":"SSPT28001","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each note-taking system to one feature.","leftItems":[{"id":"1","text":"Cornell Note-Taking System"},{"id":"2","text":"Two-Column Note-Taking System"},{"id":"3","text":"Three-Column Note-Taking System"},{"id":"4","text":"Formal Outline Note-Taking System"}],"rightItems":[{"id":"A","text":"Main notes, cues, and summary sections"},{"id":"B","text":"Terms/questions on one side, notes/answers on the other"},{"id":"C","text":"One entry, plus paired information"},{"id":"D","text":"Main topic, subtopics, and indented details"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Cornell uses main notes, cues, and summary. Two-Column pairs terms or questions with notes or answers. Three-Column gives one entry paired information. Formal Outline uses main topics, subtopics, and indented details."},{"id":"SSPT28002","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"What is the goal of taking textbook notes?","options":["Reread, review, and summarize chapters","Record, reduce, and recite Cornell notes","Learn, rehearse, and review information","Label, date, and number lecture handouts"],"correct":2,"explain":"The goal is to learn, rehearse, and review textbook information. Rereading chapters, using the Five R's, and labeling handouts are other note-taking actions."},{"id":"SSPT28003","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Studying from notes is more efficient than what?","options":["Attending lectures","Rereading chapters","Using index cards","Reviewing handouts"],"correct":1,"explain":"Studying from notes is more efficient than rereading chapters. Attending lectures, using index cards, and reviewing handouts are not the stated comparison."},{"id":"SSPT28004","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which essential strategy for textbook note-taking comes first?","options":["Labeling notes by chapter and lecture","Understanding what you read","Experimenting with different forms","Using notes for feedback"],"correct":1,"explain":"Understanding what you read is the starting point. Labeling, experimenting, and using notes for feedback are also essential strategies, but not the first."},{"id":"SSPT28005","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Notes should be labeled by textbook chapter and what?","options":["Dates for pages","Numbers for handouts","The related lecture","Previous session notes"],"correct":2,"explain":"Label notes according to textbook chapter and the related lecture. Dating pages, numbering handouts, and previous session notes are other note-taking actions."},{"id":"SSPT28006","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which pair of actions is recommended before class?","options":["Skip assigned material and review previous notes","Read assigned material and ignore previous notes","Read assigned material and review previous notes","Review previous notes and write every word"],"correct":2,"explain":"Before class includes reading assigned material and reviewing previous notes. Skipping, ignoring notes, and writing every word are not recommended."},{"id":"SSPT28007","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"During class, what should students avoid writing?","options":["Key points, dates, and examples","Every word of the lecture","Definitions, formulas, and background information","Key terms, definitions, and examples"],"correct":1,"explain":"Students should avoid writing every word. Supporting information includes key points, dates, key terms, definitions, examples, formulas, and background."},{"id":"SSPT28008","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"After class, review notes, rewrite if needed, and do what?","options":["Read assigned material","Date each notebook page","Summarize the main points","Sit near the room front"],"correct":2,"explain":"After class includes reviewing notes, rewriting if needed, and summarizing main points. Reading, dating pages, and sitting near the front are before-class actions."},{"id":"SSPT28009","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which feature belongs to Cornell?","options":["Terms and answers are paired in columns","Items are compared across support columns","Cues, summary, and main points are together","Main topics use bullets and indentation"],"correct":2,"explain":"Cornell keeps main points, details, study cues, and summary together. Paired columns fit Two-Column, compared columns fit Three-Column, and bullets with indentation fit Formal Outline."},{"id":"SSPT28010","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In Cornell, where are headings and numbered entries written?","options":["Cues","Main notes","Summary","Recall column"],"correct":1,"explain":"Headings and numbered entries are written in the main notes area during class. Cues and the recall column are used for after-class review, and the summary is written at the bottom."},{"id":"SSPT28011","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In Cornell cues, after class write reminders, vocabulary, and what?","options":["Main notes","Date stamps","Study questions","Handout numbers"],"correct":2,"explain":"The cues section holds reminders, vocabulary words, and study questions after class. Main notes, date stamps, and handout numbers are not cue content."},{"id":"SSPT28012","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In Cornell notes, what is the bottom summary for?","options":["Writing every class detail","Highlighting the main points","Listing vocabulary words","Leaving space for dates"],"correct":1,"explain":"The bottom summary is for summarizing notes and highlighting main points. Every detail, vocabulary lists, and date space are not its purpose."},{"id":"SSPT28013","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each of the Five R's to its action.","leftItems":[{"id":"1","text":"Record"},{"id":"2","text":"Reduce"},{"id":"3","text":"Recite"},{"id":"4","text":"Reflect"},{"id":"5","text":"Review"}],"rightItems":[{"id":"A","text":"Write headings and numbered notes in the main column"},{"id":"B","text":"Write key words and questions in the recall column"},{"id":"C","text":"Cover notes and say cues from the other side"},{"id":"D","text":"Think about and work with information in new ways"},{"id":"E","text":"Use immediate and ongoing checking of the material"},{"id":"F","text":"Copy every word without shortening"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Record writes headings and numbered notes. Reduce writes key words and questions. Recite covers notes and says cues. Reflect works with information in new ways. Review uses immediate and ongoing checking."},{"id":"SSPT28014","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In the Two-Column system, what goes in the right column?","options":["Terms for definitions and questions for answers","Notes on terms and answers to questions","Dates for pages and numbers for handouts","Summaries for main points and cues for review"],"correct":1,"explain":"Two-Column places terms or questions on one side and notes or answers on the other. The right column holds notes about terms and answers. Dates, handouts, summaries, and cues belong to other actions."},{"id":"SSPT28015","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which content pair suits Two-Column notes?","options":["Pages and dates","Cues and summaries","Terms and definitions","Bullets and indentation"],"correct":2,"explain":"Two-Column notes pair terms with definitions, questions with answers, formulas with problem-solving, categories with lists, and concepts with facts or examples. Pages/dates, cues/summaries, and bullets/indentation fit other actions."},{"id":"SSPT28016","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In Three-Column notes, middle and right columns hold what?","options":["Dates for each handout","Two kinds of information","The lecture summary","Main notes from class"],"correct":1,"explain":"The middle and right columns hold two kinds of information for the left-column entry. Dates, lecture summaries, and main class notes do not fit."},{"id":"SSPT28017","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In Three-Column notes, a topic plus definition plus what?","options":["Facts or examples","Questions or answers","Applications or details","Cues or summaries"],"correct":2,"explain":"A topic or concept can be paired with a definition or description and applications or details. Facts/examples and questions/answers fit Two-Column, while cues/summaries fit Cornell."},{"id":"SSPT28018","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"When can formal outlines be used for note-taking?","options":["Before, during, or after exams","Before, after, or without notes","Before, during, or after reading","During, after, or without reading"],"correct":2,"explain":"Formal outlines are highly structured and show a skeleton of printed information. They can be used before, during, or after reading. Exams, note-free use, and reading-free use do not fit."},{"id":"SSPT28019","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each formal-outline lesson step to its placement.","leftItems":[{"id":"1","text":"Main topic"},{"id":"2","text":"First subtopic"},{"id":"3","text":"Details"}],"rightItems":[{"id":"A","text":"Starts with a single bullet point"},{"id":"B","text":"Is placed below and indented slightly right"},{"id":"C","text":"Is listed below the heading and indented"},{"id":"D","text":"Is written at the top"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"During a lesson, the main topic starts with a single bullet point. The first subtopic is placed below and indented slightly right. Details are listed below the heading and indented. Chapter number and title are written at the top when creating formal outlines."},{"id":"SSPT28020","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"When studying formal outlines, what follows adding clue words?","options":["Discard the outline","Copy every line","Repeat reciting steps","Skip accuracy checks"],"correct":2,"explain":"After adding clue words, repeat the reciting process. Discarding the outline, copying every line, and skipping accuracy checks are not recommended."},{"id":"SSPT28021","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"What is the goal of active listening?","options":["Interpret and analyze","Understand and learn","Relate to feelings","Enjoy and acknowledge"],"correct":1,"explain":"Active listening aims to understand and learn new information. Interpreting and analyzing fits critical listening, relating to feelings fits empathic listening, and enjoying and acknowledging fits appreciative listening."},{"id":"SSPT28022","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each kind of listening to its goal.","leftItems":[{"id":"1","text":"Active Listening"},{"id":"2","text":"Critical Listening"},{"id":"3","text":"Empathic Listening"},{"id":"4","text":"Appreciative Listening"}],"rightItems":[{"id":"A","text":"Understand and learn new information"},{"id":"B","text":"Interpret, examine, and analyze a message"},{"id":"C","text":"Relate to another person's feelings"},{"id":"D","text":"Enjoy and acknowledge a speaker and message"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Active listening learns new information. Critical listening interprets and analyzes messages. Empathic listening relates to feelings. Appreciative listening enjoys and acknowledges speakers."},{"id":"SSPT28023","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Effective notes lead to what at test time?","options":["More stress","Less stress","No review","More reading"],"correct":1,"explain":"Effective notes lead to less stress when test time comes. More stress, no review, and more reading do not match."},{"id":"SSPT28024","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Active listening is the first important step for what?","options":["Skipping note-taking","Textbook reading","Effective class notes","Post-exam review"],"correct":2,"explain":"Active listening is the first important step for effective note-taking during lectures. Skipping notes, textbook reading, and post-exam review do not match."},{"id":"SSPT28025","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which phase includes sitting near the front and center?","options":["During class","Before class","After class","During or after class"],"correct":1,"explain":"Sitting near the front and center is a before-class action. During class, after class, and combined phases do not match."},{"id":"SSPT28026","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which phase includes listening carefully for an overview?","options":["Before class","After class","During class","Before or after class"],"correct":2,"explain":"Listening carefully for an overview happens during class. Before class is preparation, after class is review, and combined phases do not match."},{"id":"SSPT28027","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which phase includes summarizing main points?","options":["Before class","During class","After class","During or before class"],"correct":2,"explain":"Summarizing main points happens after class. Before class is preparation, during class is note capture, and combined phases do not match."},{"id":"SSPT28028","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which Cornell section is used during class?","options":["Cues section","Main notes section","Summary segment","Recall column"],"correct":1,"explain":"The main notes section is used during class. Cues and the recall column are used after class, and the summary segment is written at the bottom."},{"id":"SSPT28029","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In the Five R's, which action means covering notes and saying cues?","options":["Record","Reduce","Recite","Reflect"],"correct":2,"explain":"Recite means covering notes and saying information from the cue side. Record writes notes, reduce writes cues, and reflect works with information."},{"id":"SSPT28030","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In the Five R's, which action writes key words and questions?","options":["Record","Recite","Review","Reduce"],"correct":3,"explain":"Reduce means writing key words and questions in the recall column. Record writes main notes, recite covers notes, and review checks material."},{"id":"SSPT28031","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which listening kind analyzes a speaker's message?","options":["Active Listening","Critical Listening","Empathic Listening","Appreciative Listening"],"correct":1,"explain":"Critical listening aims to understand, interpret, examine, and analyze a speaker's message. Active listening learns, empathic listening relates to feelings, and appreciative listening enjoys messages."},{"id":"SSPT28032","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which listening kind relates to feelings and emotions?","options":["Critical Listening","Active Listening","Appreciative Listening","Empathic Listening"],"correct":3,"explain":"Empathic listening aims to understand and relate to another person's feelings and emotions. Critical listening analyzes, active listening learns, and appreciative listening enjoys messages."},{"id":"SSPT28033","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which kind of listening aims at enjoyment and acknowledgment of a speaker and message?","options":["Critical Listening","Active Listening","Empathic Listening","Appreciative Listening"],"correct":3,"explain":"Appreciative listening aims to enjoy, appreciate, and acknowledge a speaker and message. Critical listening analyzes, active listening learns, and empathic listening relates to feelings."},{"id":"SSPT28034","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Why should you allow time in your study blocks?","options":["To ignore your notes","To copy full chapters","To work with notes","To discard the handouts"],"correct":2,"explain":"Study blocks should include time to work with your notes. Ignoring your notes, copying full chapters, and discarding handouts are not recommended."},{"id":"SSPT28035","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Before class, date each notebook page, and date and number what?","options":["Each textbook","Each handout","Each lecture","Each formula"],"correct":1,"explain":"Before class, date each notebook page, and date and number each handout. Textbooks, lectures, and formulas do not match."},{"id":"SSPT28036","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"During class, why should students maintain focus?","options":["To transcribe the full lecture","To identify important points","To date and number each handout","To recite from the recall column"],"correct":1,"explain":"During class, maintain focus to identify important information. Transcribing the full lecture, dating and numbering handouts, and reciting from the recall column are not the purpose of focus."},{"id":"SSPT28037","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which statement is part of the conclusion?","options":["Notes raise test stress","Listening is optional","Note-taking ends listening","Active listening comes first"],"correct":3,"explain":"Active listening is the first important step for effective note-taking during lectures. Notes reduce test stress, listening is not optional, and note-taking does not end listening."},{"id":"SSPT28038","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which is the correct order of the Five R's?","options":["Reduce, Record, Recite, Reflect, Review","Record, Reduce, Reflect, Recite, Review","Record, Reduce, Recite, Review, Reflect","Record, Reduce, Recite, Reflect, Review"],"correct":3,"explain":"The Five R's are ordered Record, Reduce, Recite, Reflect, Review. The other choices switch adjacent steps."},{"id":"SSPT28039","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which set names all five note-taking options?","options":["Cornell, Index Card, Two-Column, Four-Column, Formal Outline","Cornell, Index Card, Two-Column, Three-Column, Formal Outline","Cornell, Card File, Two-Column, Three-Column, Formal Outline","Cornell, Index Card, One-Column, Three-Column, Formal Outline"],"correct":1,"explain":"The five options are Cornell, Index Card, Two-Column, Three-Column, and Formal Outline. Four-Column, Card File, and One-Column do not match."},{"id":"SSPT28040","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each entry type to its usual placement.","leftItems":[{"id":"1","text":"Terms to define and questions to answer"},{"id":"2","text":"Explanations of terms and responses to questions"},{"id":"3","text":"Terms, questions, concepts, or problems"},{"id":"4","text":"Paired information types for one entry"},{"id":"5","text":"Headings and numbered entries"},{"id":"6","text":"Key words and study questions"}],"rightItems":[{"id":"A","text":"Left side of Two-Column"},{"id":"B","text":"Right side of Two-Column"},{"id":"C","text":"Left side of Three-Column"},{"id":"D","text":"Middle and right sides of Three-Column"},{"id":"E","text":"Main notes section of Cornell"},{"id":"F","text":"Cues section of Cornell"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"Two-Column places terms or questions on one side and notes or answers on the other. Three-Column gives one entry paired information. Cornell main notes hold headings and numbered entries; cues hold key words and study questions."},{"id":"SSPT28041","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each purpose to the note-taking system.","leftItems":[{"id":"1","text":"Review notes with cues and summary"},{"id":"2","text":"Pair terms or questions with answers"},{"id":"3","text":"Give one entry paired information"},{"id":"4","text":"Show a skeleton of printed information"}],"rightItems":[{"id":"A","text":"Cornell"},{"id":"B","text":"Two-Column"},{"id":"C","text":"Three-Column"},{"id":"D","text":"Formal Outline"},{"id":"E","text":"Index Card"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Cornell supports review with cues and summary. Two-Column pairs terms or questions with answers. Three-Column gives one entry paired information. Formal Outline shows a skeleton of printed information."},{"id":"SSPT28042","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each formal-outline creation element to its marker.","leftItems":[{"id":"1","text":"Chapter number and title"},{"id":"2","text":"Main heading"},{"id":"3","text":"Subheading"},{"id":"4","text":"Supporting detail"},{"id":"5","text":"Small detail"}],"rightItems":[{"id":"A","text":"Written at the top"},{"id":"B","text":"Roman numeral"},{"id":"C","text":"Capital letter"},{"id":"D","text":"Numeral and lowercase letter"},{"id":"E","text":"Numeral in parentheses"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Chapter number and title go at the top. Main headings use Roman numerals. Subheadings use capital letters. Supporting details use numerals and lowercase letters. Small details use numerals in parentheses."},{"id":"SSPT28043","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each advantage or trait to its method.","leftItems":[{"id":"1","text":"Organized, summarized, and easy to review"},{"id":"2","text":"Pull out major ideas and concepts"},{"id":"3","text":"Highly structured and logically organized"},{"id":"4","text":"Shows a skeleton of printed information"},{"id":"5","text":"Useful before, during, or after reading"}],"rightItems":[{"id":"A","text":"Cornell"},{"id":"B","text":"Formal Outline"},{"id":"C","text":"Two-Column"},{"id":"D","text":"Three-Column"},{"id":"E","text":"Index Card"}],"correct_pairs":{"1":"A","2":"A","3":"B","4":"B","5":"B"},"explain":"Cornell notes are organized, summarized, easy to review, and help pull out major ideas. Formal Outline notes are highly structured, show a skeleton of printed information, and can be used before, during, or after reading."},{"id":"SSPT28044","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each textbook note-taking strategy to its role.","leftItems":[{"id":"1","text":"Understanding what you read"},{"id":"2","text":"Labeling notes by chapter and lecture"},{"id":"3","text":"Experimenting with different forms"},{"id":"4","text":"Using notes for feedback"},{"id":"5","text":"Allowing time in study blocks"}],"rightItems":[{"id":"A","text":"Starting point"},{"id":"B","text":"Connects text and class"},{"id":"C","text":"Tries several methods"},{"id":"D","text":"Supports improvement"},{"id":"E","text":"Creates practice opportunity"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Understanding is the starting point. Labeling connects text and class. Experimenting tries several methods. Feedback supports improvement. Study blocks create practice opportunity."},{"id":"SSPT28045","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each action to its note-taking phase.","leftItems":[{"id":"1","text":"Read assigned material"},{"id":"2","text":"Review notes from previous session"},{"id":"3","text":"Sit near the front and center"},{"id":"4","text":"Begin each lecture on a new page"},{"id":"5","text":"Listen carefully for an overview"},{"id":"6","text":"Maintain focus to identify important information"}],"rightItems":[{"id":"A","text":"Before Class"},{"id":"B","text":"During Class"},{"id":"C","text":"After Class"}],"correct_pairs":{"1":"A","2":"A","3":"A","4":"A","5":"B","6":"B"},"explain":"Reading, reviewing previous notes, sitting near the front and center, and beginning each lecture on a new page are before class. Listening for an overview and maintaining focus are during class."},{"id":"SSPT28046","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each remaining action to its phase.","leftItems":[{"id":"1","text":"Date pages and number handouts"},{"id":"2","text":"Write supporting information, not every word"},{"id":"3","text":"Review new notes as soon as possible"},{"id":"4","text":"Rewrite notes if necessary"},{"id":"5","text":"Summarize main points of the lecture"}],"rightItems":[{"id":"A","text":"Before Class"},{"id":"B","text":"During Class"},{"id":"C","text":"After Class"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"C","5":"C"},"explain":"Dating pages and numbering handouts is before class. Writing supporting information is during class. Reviewing, rewriting, and summarizing are after class."},{"id":"SSPT28047","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which note-taking method uses the Five R's?","options":["Index Card Note-Taking System","Two-Column Note-Taking System","Cornell Note-Taking System","Formal Outline Note-Taking System"],"correct":2,"explain":"The Five R's belong to Cornell. Index Card, Two-Column, and Formal Outline are other note-taking options."},{"id":"SSPT28048","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each listening-process step to its description.","leftItems":[{"id":"1","text":"Reception"},{"id":"2","text":"Attention"},{"id":"3","text":"Perception"},{"id":"4","text":"Assignment of Meaning"},{"id":"5","text":"Response"}],"rightItems":[{"id":"A","text":"Auditory and visual stimuli"},{"id":"B","text":"Concentration, selectivity, motivation, and intent"},{"id":"C","text":"Understand or do not understand"},{"id":"D","text":"Interpret accurately and associate to schemas"},{"id":"E","text":"Feedback, question, paraphrase, interpret, apply, and output"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Reception involves auditory and visual stimuli. Attention involves concentration, selectivity, motivation, and intent. Perception is understanding or not understanding. Assignment of meaning interprets accurately and associates to schemas. Response produces feedback, questions, paraphrases, interpretations, applications, or output."},{"id":"SSPT28049","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each memory store to its listening step.","leftItems":[{"id":"1","text":"STM"},{"id":"2","text":"LTM"}],"rightItems":[{"id":"A","text":"Attention"},{"id":"B","text":"Assignment of Meaning"},{"id":"C","text":"Reception"},{"id":"D","text":"Response"}],"correct_pairs":{"1":"A","2":"B"},"explain":"STM is entered during Attention. LTM is entered during Assignment of Meaning. Reception and Response are other listening-process steps."},{"id":"SSPT28050","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Most study time is spent reading and working with what?","options":["Index card notes","Textbook information","Formal outline notes","Two-column notes"],"correct":1,"explain":"Most study time is spent reading and working with textbook information. Index card notes, formal outline notes, and two-column notes are other note-taking products."},{"id":"SSPT28051","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"How many sections does Cornell note-taking use?","options":["Two","Four","Three","Five"],"correct":2,"explain":"Cornell notes are divided into three sections: main notes, cues, and summary. Two, four, and five do not match."},{"id":"SSPT28052","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Listening holds verbal stimuli in what long enough to attach meaning?","options":["Long-term memory","Working memory","Schemas","Response output"],"correct":1,"explain":"Listening involves holding verbal stimuli in working memory long enough to attach meaning and interpret the speaker. Long-term memory, schemas, and output are other listening-process elements."},{"id":"SSPT28053","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"How is listening described?","options":["Passive","Random","Visual","Active"],"correct":3,"explain":"Listening is an active process that engages the listener in mental processes. Passive, random, and visual do not match."},{"id":"SSPT28054","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Better notes help remember concepts, develop skills, and ____.","options":["increase test stress","understand the topic","copy chapter sentences","date notebook pages"],"correct":1,"explain":"Better notes help remember concepts, develop meaningful learning skills, and gain a better understanding of a topic. Increasing test stress, copying chapter sentences, and dating notebook pages are not benefits."},{"id":"SSPT28055","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"In the Cornell layout, how wide is the cues section?","options":["2.5 inches","6 inches","12 inches","18 inches"],"correct":0,"explain":"The cues section is 2.5 inches wide. The notes section is 6 inches. Twelve and eighteen inches do not match either section."},{"id":"SSPT28056","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"The Two-Column Note taking System is a modified version of which system?","options":["Cornell Note taking System","Three-Column Note taking System","Formal Outline Note taking System","Index Card Note taking System"],"correct":0,"explain":"Two-Column is a modified version of Cornell notes. Three-Column, Formal Outline, and Index Card are other systems."},{"id":"SSPT28057","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"The Three-Column Note taking System is a modified version of which system?","options":["Two-Column Note taking System","Cornell Note taking System","Formal Outline Note taking System","Index Card Note taking System"],"correct":0,"explain":"Three-Column is a modified version of two-column notes. Cornell, Formal Outline, and Index Card are other systems."},{"id":"SSPT28058","type":"stepped","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Steps for studying from formal outlines","steps":[{"id":"1","prompt":"What is the first action when studying formal outlines?","options":["Read one line or item at a time and explain by reciting","Review the full outline page and mark key headings first","Write a short summary at the bottom of the outline","Copy every main heading into a separate notebook"],"correct":0},{"id":"2","prompt":"After reading one line and explaining by reciting, what comes next?","options":["Check accuracy or completeness","Add clue words to the right of the lines","Repeat the reciting process","Discard the outline"],"correct":0},{"id":"3","prompt":"After checking accuracy or completeness, what is the next step?","options":["Add clue words to the right of the lines or items","Write a new set of numbered questions beside each line","Move every subtopic into a separate column on the page","Highlight only the Roman numerals and capital letters"],"correct":0},{"id":"4","prompt":"After adding clue words, what is the final step?","options":["Repeat the process of reciting from the outline","Check the accuracy of each clue word one more time","Create a second outline using only the clue words","Review the chapter title and main headings again"],"correct":0}],"explain":"Study formal outlines by reading one line or item at a time and explaining by reciting, then checking accuracy or completeness, adding clue words to the right, and repeating the reciting process. Other actions do not match the sequence."},{"id":"SSPT28059","type":"mcq","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Which list names supporting information to write during class?","options":["Key points, background information, dates, key terms, definitions, examples, formulas","Key points, background information, dates, key terms, definitions, examples, handout numbers","Key points, background information, dates, key terms, summaries, examples, formulas","Key points, previous notes, dates, key terms, definitions, examples, formulas"],"correct":0,"explain":"Supporting information includes key points, background information, dates, key terms, definitions, examples, and formulas. Handout numbers, summaries, and previous notes belong to other phases."},{"id":"SSPT28060","type":"matching","cat":"Lecture 8 – Effective Note-Taking Strategies","q":"Match each content pair to the system that uses it.","leftItems":[{"id":"1","text":"Formulas with steps and problem-solving examples"},{"id":"2","text":"A category with the list of items in it"},{"id":"3","text":"Concepts with facts, explanations, and examples"},{"id":"4","text":"A math problem with steps and the explanation or rule"},{"id":"5","text":"A topic with textbook information and lecture information"}],"rightItems":[{"id":"A","text":"Two-Column system"},{"id":"B","text":"Three-Column system"},{"id":"C","text":"Cornell system"},{"id":"D","text":"Formal Outline system"}],"correct_pairs":{"1":"A","2":"A","3":"A","4":"B","5":"B"},"explain":"Two-Column pairs formulas with steps and examples, categories with lists, and concepts with facts or explanations. Three-Column pairs a math problem with steps and the rule, and a topic with textbook plus lecture information. Cornell and Formal Outline use other structures."}]}},"banks/studyskills/lecture-9-memory-concentration.json":{"id":"study-skills-lec9-memory-concentration","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 9 - Boosting Memory and Increasing Concentration","formSize":30,"forms":["A"],"bank":{"A":[{"id":"SSPT29000","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which main skill do the ten tips aim to improve?","options":["Concentration","Encoding","Retrieval","Self-motivation"],"correct":0,"explain":"The ten tips are mainly for concentration. Encoding and retrieval belong to memory processing, and self-motivation is mentioned with goal setting."},{"id":"SSPT29001","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each information-processing model part to its role.","leftItems":[{"id":"1","text":"Sensory input"},{"id":"2","text":"Short-term memory (STM)"},{"id":"3","text":"Rehearsal pathway"},{"id":"4","text":"Feedback loop"},{"id":"5","text":"Long-term memory (LTM)"},{"id":"6","text":"Retrieval pathway"}],"rightItems":[{"id":"A","text":"Receives incoming stimuli"},{"id":"B","text":"Has limited capacity and a trap door"},{"id":"C","text":"Moves practice and learning along"},{"id":"D","text":"Links to self-quizzing and an inactive route"},{"id":"E","text":"Stores schemas, unlimited capacity, imprinting"},{"id":"F","text":"Calls saved material back for review"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"Sensory input enters STM, which has limited capacity and a trap door. Rehearsal moves practice and learning to LTM, while retrieval calls saved material back for review. Feedback links to self-quizzing and the inactive path."},{"id":"SSPT29002","type":"saq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"How many kinds of encoding transmit information to LTM?","answer":"4","accept":["Four"],"explain":"Linguistic, visual, motor, and semantic encoding are the four kinds. Each kind transmits a different type of information to LTM."},{"id":"SSPT29003","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each encoding type to the information it transmits.","leftItems":[{"id":"1","text":"Linguistic encoding"},{"id":"2","text":"Visual encoding"},{"id":"3","text":"Motor encoding"},{"id":"4","text":"Semantic encoding"}],"rightItems":[{"id":"A","text":"Verbal information"},{"id":"B","text":"Image information"},{"id":"C","text":"Muscle memory information"},{"id":"D","text":"Emotional information and experiences"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Linguistic encoding transmits verbal information, and visual encoding transmits image information. Motor encoding transmits muscle memory, while semantic encoding transmits emotional information and episodic memory to LTM."},{"id":"SSPT29004","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each encoding type to its alternate name.","leftItems":[{"id":"1","text":"Linguistic encoding"},{"id":"2","text":"Visual encoding"},{"id":"3","text":"Motor encoding"}],"rightItems":[{"id":"A","text":"Auditory label"},{"id":"B","text":"Imaginal label"},{"id":"C","text":"Physical or kinesthetic label"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Linguistic encoding is also called auditory coding. Visual encoding is imaginal coding, and motor encoding is physical or kinesthetic coding."},{"id":"SSPT29005","type":"multi","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which resources suit visual learners?","options":["Diagrams","Taped class sessions","Colors","Printed materials"],"correct":[0,2,3],"explain":"Visual learners use diagrams, color, printed materials, charts, and images. Taped class sessions suit auditory learners."},{"id":"SSPT29006","type":"multi","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which strategies help auditory learners?","options":["Listening to notes","Creating manipulatives","Reading notes aloud","Teaching a partner"],"correct":[0,2,3],"explain":"Auditory learners benefit from listening, reading notes aloud, and teaching partners. Manipulatives suit tactile or kinesthetic learners."},{"id":"SSPT29007","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each learning style to its main channel.","leftItems":[{"id":"1","text":"Visual learners"},{"id":"2","text":"Auditory learners"},{"id":"3","text":"Tactile/kinesthetic learners"}],"rightItems":[{"id":"A","text":"Charts and images"},{"id":"B","text":"Recordings and read-aloud notes"},{"id":"C","text":"Hands-on practice"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Visual learners use charts and images. Auditory learners use recordings and read-aloud notes. Tactile/kinesthetic learners use hands-on practice."},{"id":"SSPT29008","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each learning style to a suitable strategy.","leftItems":[{"id":"1","text":"Visual learners"},{"id":"2","text":"Auditory learners"},{"id":"3","text":"Tactile/kinesthetic learners"}],"rightItems":[{"id":"A","text":"Use charts and images"},{"id":"B","text":"Tape class sessions"},{"id":"C","text":"Create hands-on notes"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Visual learners can use charts and images. Auditory learners can tape class sessions. Tactile/kinesthetic learners can create hands-on notes."},{"id":"SSPT29009","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip advises choosing a fixed amount of study time?","options":["Prepare to Concentrate","Vary Your Study Activities","Intend to Concentrate","Take Regular Study Breaks"],"correct":2,"explain":"Intend to Concentrate means setting a specified study time. Knowing the duration helps maintain focus."},{"id":"SSPT29010","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip says to gather texts, notes, pens, and guides first?","options":["Prepare to Concentrate","Intend to Concentrate","Use Concentration Promoting Activities","Eat Regular, Well-Balanced Meals"],"correct":0,"explain":"Prepare to Concentrate means having everything needed for the task. Texts, notes, pens, and study guides should be ready."},{"id":"SSPT29011","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Use Concentration Promoting Activities recommends which action?","options":["Rewriting and summarizing notes","Choosing a fixed study time","Switching subjects periodically","Taking a five-minute pause"],"correct":0,"explain":"This tip includes rewriting and organizing notes. It also includes diagrams, graphs, study guides, and summaries."},{"id":"SSPT29012","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip suggests changing subjects when focus fades?","options":["Use Concentration Promoting Activities","Vary Your Study Activities","Devise a Specific Study Plan for Studying and Learning","Take Regular Study Breaks"],"correct":1,"explain":"Vary Your Study Activities helps when one subject is hard to sustain. Changing subjects can restore focus."},{"id":"SSPT29013","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip advises using one place only for schoolwork?","options":["Vary Your Study Activities","Devise a Specific Study Plan for Studying and Learning","Study in a Non-Distracting Environment","Take Regular Study Breaks"],"correct":2,"explain":"Study in a Non-Distracting Environment means choosing one place for studying. That place should be used only for schoolwork."},{"id":"SSPT29014","type":"multi","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"What should a study place remove?","options":["Visual distractions","Study goals","Auditory distractions","Balanced meals"],"correct":[0,2],"explain":"A non-distracting study place removes visual and auditory distractions. Goals and meals are handled by other tips."},{"id":"SSPT29015","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Devise a Specific Study Plan for Studying and Learning includes which practice?","options":["Using a textbook reading strategy","Setting a fixed study time limit","Switching subjects when focus fades","Taking a five-minute study pause"],"correct":0,"explain":"A step-by-step plan makes concentrating easier. It also includes a textbook reading strategy."},{"id":"SSPT29016","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"What does a step-by-step study plan make easier?","options":["Concentrating","Sleeping at night","Eating meals","Taking breaks"],"correct":0,"explain":"A step-by-step plan makes it easier to concentrate. It also supports using a textbook reading strategy."},{"id":"SSPT29017","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip links food choices, less sugar, and no stimulants to grades?","options":["Get Plenty of Sleep at Night","Set Daily, Weekly, Monthly, and Semester Goals","Eat Regular, Well-Balanced Meals","Take Regular Study Breaks"],"correct":2,"explain":"Eat Regular, Well-Balanced Meals supports concentration and grades. It advises avoiding excess sugar and caffeine and not taking stimulants."},{"id":"SSPT29018","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each study-health factor to its advice.","leftItems":[{"id":"1","text":"Healthier diets"},{"id":"2","text":"Excess sugar and caffeine"},{"id":"3","text":"Stimulants"}],"rightItems":[{"id":"A","text":"Lead to better grades"},{"id":"B","text":"Should be limited"},{"id":"C","text":"Should not be taken"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Students with healthier diets earn higher grades. Excess sugar and caffeine should be limited, and stimulants should not be taken."},{"id":"SSPT29019","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip warns that staying tired harms attention?","options":["Eat Regular, Well-Balanced Meals","Take Regular Study Breaks","Intend to Concentrate","Get Plenty of Sleep at Night"],"correct":3,"explain":"Get Plenty of Sleep at Night protects concentration. Fighting off sleepiness negatively affects attention."},{"id":"SSPT29020","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"What negatively affects concentration?","options":["Taking regular breaks","Setting semester goals","Fighting off sleepiness","Varying subjects"],"correct":2,"explain":"Fighting off sleepiness negatively affects concentration. Adequate sleep at night supports attention."},{"id":"SSPT29021","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip recommends targets across several time periods?","options":["Set Daily, Weekly, Monthly, and Semester Goals","Take Regular Study Breaks","Devise a Specific Study Plan for Studying and Learning","Prepare to Concentrate"],"correct":0,"explain":"Set Daily, Weekly, Monthly, and Semester Goals gives a sense of progress. Seeing movement toward goals supports concentration and self-motivation."},{"id":"SSPT29022","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip treats wandering attention as normal and suggests a short pause?","options":["Set Daily, Weekly, Monthly, and Semester Goals","Vary Your Study Activities","Take Regular Study Breaks","Intend to Concentrate"],"correct":2,"explain":"Take Regular Study Breaks accepts that concentration will wander. A short planned pause helps attention return."},{"id":"SSPT29023","type":"saq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"How many minutes is the suggested study break?","answer":"5","accept":["5 minutes","5.","5 minutes.","Five","Five.","Five minutes","Five minutes."],"explain":"The suggested break is five minutes. It is taken when concentration normally wanders."},{"id":"SSPT29024","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each concentration tip to its action.","leftItems":[{"id":"1","text":"Intend to Concentrate"},{"id":"2","text":"Prepare to Concentrate"},{"id":"3","text":"Use Concentration Promoting Activities"},{"id":"4","text":"Vary Your Study Activities"},{"id":"5","text":"Study in a Non-Distracting Environment"},{"id":"6","text":"Devise a Specific Study Plan for Studying and Learning"},{"id":"7","text":"Eat Regular, Well-Balanced Meals"},{"id":"8","text":"Get Plenty of Sleep at Night"},{"id":"9","text":"Set Daily, Weekly, Monthly, and Semester Goals"},{"id":"10","text":"Take Regular Study Breaks"}],"rightItems":[{"id":"A","text":"Choose time limit"},{"id":"B","text":"Gather needed supplies"},{"id":"C","text":"Rewrite, summarize notes"},{"id":"D","text":"Switch subjects periodically"},{"id":"E","text":"Pick one quiet place"},{"id":"F","text":"Follow step-by-step reading strategy"},{"id":"G","text":"Limit sugar, caffeine, stimulants"},{"id":"H","text":"Avoid tiredness"},{"id":"I","text":"Track progress steadily"},{"id":"J","text":"Pause five minutes"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G","8":"H","9":"I","10":"J"},"explain":"Each tip is paired with its main action, from setting a time limit to taking a five-minute pause. Together the pairs summarize the ten concentration tips."},{"id":"SSPT29025","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which tip uses conscious self-talk about a set study time?","options":["Intend to Concentrate","Prepare to Concentrate","Take Regular Study Breaks","Vary Your Study Activities"],"correct":0,"explain":"Intend to Concentrate asks you to state a fixed study period. The self-talk form is a promise to concentrate for a number of minutes."},{"id":"SSPT29026","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which part ends the information-processing model by supplying final results?","options":["The output","The trap door","The feedback loop","The rehearsal path"],"correct":0,"explain":"The output is the model endpoint, and outcomes are its final results. The other parts are stores or pathways."},{"id":"SSPT29027","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"What is saved in long-term memory when a student transfers received information into them?","options":["Schemas","Sensory stimuli","Short-term trap-door items","Inactive-path feedback"],"correct":0,"explain":"When a student transfers information he received into schemas, this schema will be saved in long-term memory of the information-processing model. Sensory stimuli, trap-door items, and inactive-path feedback are other parts of the model."},{"id":"SSPT29028","type":"mcq","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Which feature of long-term memory appears on the info-processing model chart alongside schemas and unlimited capacity?","options":["Imprinting","Limited capacity","Trap door","Sensory input"],"correct":0,"explain":"The long-term memory box on the chart lists schemas, unlimited capacity, and imprinting. Limited capacity and the trap door belong to short-term memory; sensory input is the entry stage."},{"id":"SSPT29029","type":"matching","cat":"Lecture 9 - Boosting Memory and Increasing Concentration","q":"Match each LTM feature from the model chart to its description.","leftItems":[{"id":"1","text":"Schemas"},{"id":"2","text":"Unlimited capacity"},{"id":"3","text":"Imprinting"}],"rightItems":[{"id":"A","text":"Organized knowledge structures that store transferred information"},{"id":"B","text":"No fixed limit on the amount that can be held"},{"id":"C","text":"Lasting mark or encoding of information into memory"},{"id":"D","text":"Temporary holding area with a trap door"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Schemas are the organized structures into which transferred information is saved. Unlimited capacity means no fixed limit. Imprinting refers to the lasting encoding of information. The trap-door description belongs to short-term memory."}]}},"banks/studyskills/lecture-10-comprehension.json":{"id":"study-skills-lec10-comprehension","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 10 - Strengthening Comprehension","formSize":32,"forms":["A"],"bank":{"A":[{"id":"SSPT210000","type":"stepped","cat":"Lecture 10 - Strengthening Comprehension","q":"How is comprehension defined?","steps":[{"id":"1","prompt":"Comprehension is the goal or purpose for what?","options":["Reading","Writing","Speaking","Listening"],"correct":0},{"id":"2","prompt":"Because comprehension is the goal of reading, it constructs meaning through interaction with what?","options":["Written language","Spoken commands","Numerical data","Visual art"],"correct":0},{"id":"3","prompt":"Since comprehension uses written language, it is understanding beyond what?","options":["Knowing","Reading","Writing","Speaking"],"correct":0},{"id":"4","prompt":"Because comprehension is understanding beyond knowing, it results from what?","options":["Active engagement with text","A product of reading alone","Rapid word recognition","Memorized terminology lists"],"correct":0}],"explain":"Comprehension is the goal of reading and simultaneously extracts and constructs meaning from written language. It is understanding beyond knowing, produced by active involvement with text."},{"id":"SSPT210001","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Why is comprehension important?","options":["It leads to better achievement","It removes need for notes","It guarantees faster reading speed","It replaces vocabulary learning"],"correct":0,"explain":"Comprehension leads to better achievement. Without it, readers cannot fully understand content."},{"id":"SSPT210002","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Without comprehension skills, readers cannot do what?","options":["Fully understand the content","Learn new terminology lists","Ask questions while reading","Highlight important concepts only"],"correct":0,"explain":"Without comprehension skills, readers cannot fully understand content. Active engagement strategies are therefore needed."},{"id":"SSPT210003","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"What is the main problem with comprehension?","options":["Lacking strategies to engage with text","Reading too many chapters too quickly","Knowing too much prior background information","Using diagrams and printed study materials"],"correct":0,"explain":"The main problem is lacking strategies to actively engage with text. Active engagement helps readers understand it."},{"id":"SSPT210004","type":"multi","cat":"Lecture 10 - Strengthening Comprehension","q":"Which actions improve comprehension?","options":["Be patient with the reading process","Stay with a paragraph until understood","Learn the terminology used in text","Expand your vocabulary regularly over time","Avoid elaborative rehearsal techniques while reading"],"correct":[0,1,2,3],"explain":"Improving comprehension includes patience, staying with material, learning terminology, and expanding vocabulary. Avoiding rehearsal contradicts active learning."},{"id":"SSPT210005","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Readers should avoid hurrying during what?","options":["The reading process","The note-taking process","The summary process","The rehearsal process"],"correct":0,"explain":"Be patient means do not rush the reading process. Hurrying can weaken comprehension."},{"id":"SSPT210006","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Readers should stay with a paragraph until what?","options":["They fully comprehend it","The entire chapter ends","All words are memorized","The summary is written"],"correct":0,"explain":"Stay with a paragraph or section until you comprehend it. This prevents superficial reading."},{"id":"SSPT210007","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Which strategy focuses on specialized words?","options":["Learn the field terminology","Expand the general vocabulary","Enter the writer's head","Use rehearsal techniques often"],"correct":0,"explain":"Learning terminology targets field-specific words. Expanding vocabulary builds general word knowledge."},{"id":"SSPT210008","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Which strategy builds general word knowledge?","options":["Expand the general vocabulary","Learn the field terminology","Stay with paragraphs closely","Activate background knowledge early"],"correct":0,"explain":"Expanding vocabulary builds general word knowledge. Terminology focuses on field-specific words."},{"id":"SSPT210009","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Which strategy asks readers to adopt the author's viewpoint?","options":["Enter the writer's head","Learn field terminology well","Expand general vocabulary widely","Use rehearsal techniques actively"],"correct":0,"explain":"Getting into the writer's head means adopting the author's viewpoint. It supports deeper comprehension."},{"id":"SSPT210010","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"When should readers use elaborative rehearsal and active learning?","options":["As they read","After sleeping well","Before writing notes","During study breaks"],"correct":0,"explain":"Elaborative rehearsal and active learning techniques are used as you read. They help build comprehension."},{"id":"SSPT210011","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Readers are encouraged to feel what about learning?","options":["Excited","Anxious","Confused","Troubled"],"correct":0,"explain":"The strategy is to become excited about what you learn. Positive engagement supports comprehension."},{"id":"SSPT210012","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"What does a topic name?","options":["The subject of a paragraph","The point the author develops","The sentence stating main idea","The details supporting a topic"],"correct":0,"explain":"The topic is the subject of a paragraph. It can be named in one word or one phrase."},{"id":"SSPT210013","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"What does the main idea tell?","options":["The point the author develops","The subject of a paragraph","The sentence stating topic clearly","The details supporting text claims"],"correct":0,"explain":"The main idea tells the point the author intends to develop. It is expressed by the topic sentence when present."},{"id":"SSPT210014","type":"matching","cat":"Lecture 10 - Strengthening Comprehension","q":"Match each paragraph element to its role.","leftItems":[{"id":"1","text":"Topic"},{"id":"2","text":"Main idea"},{"id":"3","text":"Topic sentence"}],"rightItems":[{"id":"A","text":"Subject of paragraph"},{"id":"B","text":"Point author develops"},{"id":"C","text":"Umbrella for supporting details"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"The topic names the subject, and the main idea states the developed point. The topic sentence acts like an umbrella for supporting details."},{"id":"SSPT210015","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Which statement about a topic sentence is correct?","options":["It expresses the main idea","It omits the usual topic","It lists every supporting detail","It replaces the paragraph subject"],"correct":0,"explain":"A topic sentence expresses the main idea and usually includes the topic. It is broad enough to include supporting details, but it does not list every detail."},{"id":"SSPT210016","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Why is a topic sentence like an umbrella?","options":["It is broad enough to include supporting details","It names only the subject of a paragraph","It appears only as the final paragraph sentence","It develops the whole paragraph for the author"],"correct":0,"explain":"The umbrella image means the topic sentence is broad enough to include supporting details. It expresses the main idea and usually includes the topic."},{"id":"SSPT210017","type":"matching","cat":"Lecture 10 - Strengthening Comprehension","q":"Match each topic-sentence location to its frequency.","leftItems":[{"id":"1","text":"Most common"},{"id":"2","text":"Next most common"},{"id":"3","text":"Least common"}],"rightItems":[{"id":"A","text":"First sentence"},{"id":"B","text":"Last sentence"},{"id":"C","text":"Middle of paragraph"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Topic sentences most often appear first. They next often appear last, and least often appear in the middle."},{"id":"SSPT210018","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"If a main idea is implied, what should a reader do?","options":["Formulate the overall big picture","Skip the paragraph entirely now","Copy the chapter title only","Choose the closing sentence instead"],"correct":0,"explain":"When a main idea is implied, it is not directly stated in one sentence. The reader should formulate a sentence expressing the overall big picture or main point."},{"id":"SSPT210019","type":"saq","cat":"Lecture 10 - Strengthening Comprehension","q":"How many organizational patterns are named?","answer":"7","accept":["7","7.","7 patterns","7 patterns.","Seven","Seven.","Seven patterns","Seven patterns."],"explain":"Seven organizational patterns are named. They include chronological, process, comparison or contrast, definition, examples, cause/effect, and whole/parts."},{"id":"SSPT210020","type":"multi","cat":"Lecture 10 - Strengthening Comprehension","q":"Which items are organizational patterns?","options":["Chronological time order","Process step order","Comparison or contrast","Definition meaning pattern","Topic sentence pattern"],"correct":[0,1,2,3],"explain":"Chronological, process, comparison or contrast, and definition are patterns. A topic sentence expresses a main idea."},{"id":"SSPT210021","type":"multi","cat":"Lecture 10 - Strengthening Comprehension","q":"Which additional items are organizational patterns?","options":["Examples list pattern","Cause/effect link pattern","Whole/parts structure pattern","Background knowledge activation"],"correct":[0,1,2],"explain":"Examples, cause/effect, and whole/parts complete the seven patterns. Background knowledge is a comprehension-enhancing action."},{"id":"SSPT210022","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"What should readers activate to enhance comprehension?","options":["Background knowledge","Reading rate","Chapter material","Organizational patterns"],"correct":0,"explain":"Readers activate background knowledge and make associations or connections with text. This engagement supports comprehension."},{"id":"SSPT210023","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Which reader action is called SQ4Rs?","options":["Asking questions at all stages","Highlighting important concepts while reading","Reviewing the table of contents","Summarizing after one reading session"],"correct":0,"explain":"SQ4Rs means asking questions before, during, and after reading. Highlighting, reviewing contents, and summarizing once are different actions."},{"id":"SSPT210024","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Awareness of purpose and text features guides what decision?","options":["Reading rate","Terminology list","Paragraph topic","Chapter summary"],"correct":0,"explain":"This awareness helps readers decide their reading rate. Purpose and text features affect how fast one should read."},{"id":"SSPT210025","type":"stepped","cat":"Lecture 10 - Strengthening Comprehension","q":"What comes next in a pre-reading survey?","steps":[{"id":"1","prompt":"Which action is done first?","options":["Read introduction, review contents","Review chapter summary first","Answer study questions first","Highlight concepts while reading"],"correct":0},{"id":"2","prompt":"After reading the introduction and table of contents, what gives overall topic direction?","options":["Chapter title and subtitles","Focus questions at start","Last paragraph or summary","End-of-chapter review material"],"correct":0},{"id":"3","prompt":"After chapter title and subtitles, what indicates what to look for?","options":["Focus questions at start","First chapter paragraph openings","Tables of contents lists","Final chapter summary endings"],"correct":0},{"id":"4","prompt":"After focus questions, what reveals the opening subject?","options":["First chapter paragraph or introduction","Last paragraph or chapter summary","End-of-chapter study review materials items","Chapter title and subtitle lists"],"correct":0},{"id":"5","prompt":"After first paragraph or introduction, what condenses key takeaway?","options":["Last paragraph or summary","Focus questions at start","Table of contents list","End-of-chapter review aids"],"correct":0},{"id":"6","prompt":"After last paragraph or summary, what provides review aids?","options":["End-of-chapter study questions","Chapter title and subtitles","Introduction and table contents","Focus questions at start"],"correct":0}],"explain":"The survey gives a brief summary before reading. It moves from introduction and contents to titles, focus questions, openings, summaries, and end-of-chapter aids."},{"id":"SSPT210026","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Which statement about focus questions is true?","options":["Many textbooks include them","Few textbooks include them","Textbooks often hide them","Questions often end chapters"],"correct":0,"explain":"Many, but not all, textbooks include focus questions. Reviewing them shows what to look for."},{"id":"SSPT210027","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"What should readers do during reading review?","options":["Take notes, highlight concepts","Complete pre-reading survey first","Formulate implied main ideas","Activate background knowledge early"],"correct":0,"explain":"Reading review means taking notes or highlighting important concepts. It happens while engaging with the text."},{"id":"SSPT210028","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"What does post-reading review identify?","options":["Learned takeaways and unclear concepts","Topic sentence locations in texts","Chapter titles and subtitle lists","Organizational patterns per each chapter"],"correct":0,"explain":"Post-reading review identifies learned concepts and important takeaways. It also reveals concepts that are not fully comprehended."},{"id":"SSPT210029","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"Why identify unclear concepts after reading?","options":["To spend more time reviewing them","To skip the chapter summary now","To avoid active engagement during reading","To reduce vocabulary learning over time"],"correct":0,"explain":"Identifying unclear concepts lets readers spend more time reviewing them. This strengthens comprehension."},{"id":"SSPT210030","type":"mcq","cat":"Lecture 10 - Strengthening Comprehension","q":"When identifying the topic of a paragraph, what should a reader ask?","options":["In one word or one phrase, what is the paragraph about?","Which sentence lists every supporting detail?","Where does the topic sentence always appear?","How many organizational patterns does the chapter use?"],"correct":0,"explain":"The slide prompts readers to ask, “In one word or one phrase; what is the paragraph about?” This identifies the topic. The other options refer to main idea, location, or organizational patterns."},{"id":"SSPT210031","type":"matching","cat":"Lecture 10 - Strengthening Comprehension","q":"Match each comprehension concept to its main function.","leftItems":[{"id":"1","text":"Topic"},{"id":"2","text":"Main idea"},{"id":"3","text":"Topic sentence"},{"id":"4","text":"Organizational patterns"},{"id":"5","text":"SQ4Rs"},{"id":"6","text":"Pre-reading survey"}],"rightItems":[{"id":"A","text":"Names the subject of a paragraph"},{"id":"B","text":"States the point the author develops"},{"id":"C","text":"Expresses the main idea and covers supporting details"},{"id":"D","text":"Shows how ideas are arranged in the text"},{"id":"E","text":"Asks questions before, during, and after reading"},{"id":"F","text":"Gives a brief overview before full reading"},{"id":"G","text":"Decides how fast to read"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"Topic names the subject, main idea states the developed point, and the topic sentence expresses that idea while covering supporting details. Organizational patterns show text structure, SQ4Rs means asking questions at all stages, and a pre-reading survey gives a brief overview first."}]}},"banks/studyskills/lecture-11-test-prep.json":{"id":"ss-lec11-test-prep","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 11 – Test Preparation and Taking Skills","formSize":58,"forms":["A"],"bank":{"A":[{"id":"SSPT211000","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What is the key to success and high scores on tests?","options":["Good preparation","More knowledge","Wild guessing","Peer competition"],"correct":0,"explain":"Good preparation for tests is the key for success and high scores. Having more knowledge than you think does not guarantee doing well without good preparation."},{"id":"SSPT211001","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which question type is used in the SCFHS SLE?","options":["Multiple-choice","Short-answer","Clinical cases","Stem and lead-in"],"correct":0,"explain":"MCQs is the type of questions used in SCFHS SLE. Short-answer questions, clinical case scenarios, and stem and lead-in are parts or other types of questions."},{"id":"SSPT211002","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What is the main reason capable students are not successful?","options":["Exam stress","Poor preparation","Peer competition","Lack of sleep"],"correct":0,"explain":"The main reason capable students are not successful is exam stress and anxiety. Poor preparation, peer competition, and lack of sleep are causes of stress, not the main reason for failure itself."},{"id":"SSPT211003","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which factors cause exam stress and lead to anxiety and panic?","options":["Poor preparation","Negative thoughts","Peer competition","Lack of sleep","Think positively","Join a study group"],"correct":[0,1,2,3],"explain":"Causes of stress include poor preparation, negative thoughts and fear of failing, peer competition, and not enough sleep the night before. Thinking positively and joining a study group are preparation strategies."},{"id":"SSPT211004","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What happens when you panic?","options":["Memory is inhibited","Focus decreases","Easily confused","Think positively","Join a group","Budget time"],"correct":[0,1,2],"explain":"When you panic, your memory is inhibited, your ability to focus decreases, and you become easily confused. The other options are test-taking or preparation strategies."},{"id":"SSPT211005","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What is the key to deal with exam stress, anxiety, and panic?","options":["Good preparation","Scanning test","Wild guessing","Peer competition"],"correct":0,"explain":"The key to deal with exam stress, anxiety, and panic is good preparation. Scanning the test is a test-taking tip, while wild guessing and peer competition are not solutions."},{"id":"SSPT211006","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which actions are recommended to 'Study Well'?","options":["Attend classes","Review notes","Check handouts","Answer questions","Link with teachers","Join a group","Skip tough ones"],"correct":[0,1,2,3,4,5],"explain":"Studying well includes attending all classes, reviewing notes, checking handouts and summaries, answering as much questions as you can, linking with teachers, and joining a study group. Skipping tough ones is a test-taking strategy."},{"id":"SSPT211007","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What should you do the day and night before the test?","options":["Sleep early and well","Wake up very early","Do some workout","Review forgotten info"],"correct":0,"explain":"The day and night before the test, you should think positively, review notes, review easily forgotten info, sleep early and sleep well, and prepare stationery. Waking up early and working out are for the day of the test."},{"id":"SSPT211008","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Why is a good breakfast recommended on the day of the test?","options":["Serves as fuel","Helps you relax","Fixes attention","Tracks revisits"],"correct":0,"explain":"Having a good breakfast is recommended because it is your brain's fuel for the exam. Working out helps you relax, underlining fixes attention, and certainty marking tracks revisits."},{"id":"SSPT211009","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Who should you avoid being around on the day of the test?","options":["Anxious colleagues","Your teachers","Lab assistants","Study groups"],"correct":0,"explain":"On the day of the test, don't be around pessimistic or anxious colleagues. Teachers, lab assistants, and study groups are not mentioned as people to avoid."},{"id":"SSPT211010","type":"stepped","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"A student follows the 5-day test preparation plan in reverse order.","steps":[{"id":"1","prompt":"What is the main task for Day 5?","options":["Read and highlight","Use mnemonics","Rewrite briefly","Answer questions"],"correct":0},{"id":"2","prompt":"After reading and highlighting on Day 5, what is the main task for Day 4?","options":["Use mnemonics","Read and highlight","Rewrite briefly","Answer questions"],"correct":0},{"id":"3","prompt":"After using mnemonics on Day 4, what is the main task for Day 3?","options":["Rewrite briefly","Read and highlight","Use mnemonics","Answer questions"],"correct":0},{"id":"4","prompt":"After rewriting briefly on Day 3, what is the main task for Day 2?","options":["Answer questions","Read and highlight","Use mnemonics","Rewrite briefly"],"correct":0},{"id":"5","prompt":"After answering questions on Day 2, what is the main task for Day 1?","options":["Review notes","Read and highlight","Use mnemonics","Rewrite briefly"],"correct":0},{"id":"6","prompt":"After reviewing notes on Day 1, what do you go over just before the test?","options":["Difficult information","Rewritten notes","Practice questions","Mnemonic methods"],"correct":0}],"explain":"Day 5: read and highlight. Day 4: mnemonics. Day 3: rewrite briefly. Day 2: answer questions. Day 1: review notes and go over difficult information just before the test."},{"id":"SSPT211011","type":"stepped","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"A student applies general test taking tips 1 through 7 during a paper exam.","steps":[{"id":"1","prompt":"Tip 1: what do you do with the instructions?","options":["Read them carefully","Scan the whole test","Budget your time","Answer all questions"],"correct":0},{"id":"2","prompt":"After reading instructions carefully, why scan the whole paper test (Tip 2)?","options":["Budget time per question","Fix your attention","Track what needs review","Have review time"],"correct":0},{"id":"3","prompt":"After scanning to budget time, what does Tip 4 advise when you can answer instantly?","options":["Answer and move on","Skip and save it","Leave it blank","Listen to invigilators"],"correct":0},{"id":"4","prompt":"After answering instantly, how do you handle a tough question on paper (Tip 5)?","options":["Skip and save it","Answer and move on","Leave it blank","Read the axes"],"correct":0},{"id":"5","prompt":"After skipping tough questions, what does certainty marking (Tip 6) do?","options":["Track what needs review","Fix your attention","Circle qualifying words","Cross out negatives"],"correct":0},{"id":"6","prompt":"After tracking what needs review, what is the rule if you run out of time (Tip 7)?","options":["Never leave them blank","Plan to finish early","Scan the whole test","Budget your time"],"correct":0},{"id":"7","prompt":"After deciding never to leave blanks, what does Tip 3 advise overall?","options":["Budget your time","Answer and move on","Skip the tough ones","Circle qualifying words"],"correct":0}],"explain":"Tip 1 read instructions. Tip 2 scan to budget time per question. Tip 3 budget your time. Tip 4 answer instantly and move on. Tip 5 skip tough ones until easier questions done. Tip 6 certainty marking tracks revisits. Tip 7 never leave blanks."},{"id":"SSPT211012","type":"stepped","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"A student applies general test taking tips 8 through 14 to analyze question features.","steps":[{"id":"1","prompt":"What does Tip 8 say to do before answering?","options":["Read and understand it","Read all the options","Decide the answer","Underline key data"],"correct":0},{"id":"2","prompt":"After understanding the question, why underline key data (Tip 9)?","options":["Fix your attention","Budget time per question","Track what needs review","Have review time"],"correct":0},{"id":"3","prompt":"After underlining to fix attention, what do qualifying words do (Tip 10)?","options":["Alter the statement","Reverse the meaning","Make it positive","Track what needs review"],"correct":0},{"id":"4","prompt":"After noticing qualifying words alter the statement, what do negative prefixes do (Tip 11)?","options":["Reverse the meaning","Alter the statement","Make it positive","Budget time per question"],"correct":0},{"id":"5","prompt":"After reversing meaning with prefixes, what does a double negative mean (Tip 12)?","options":["Common","Never","Except","Few"],"correct":0},{"id":"6","prompt":"After understanding double negatives, what to read first in a graph question (Tip 13)?","options":["Title and axes","Stem and lead-in","Lead-in and options","Positive and negative"],"correct":0},{"id":"7","prompt":"After reading the title and axes, why plan to finish early (Tip 14)?","options":["Time for review","Budget time per question","Track what needs review","Fix your attention"],"correct":0}],"explain":"Tip 8: Understand the question first. Tip 9: Underline to fix attention. Tip 10: Qualifying words alter statements. Tip 11: Negative prefixes reverse meaning. Tip 12: Double negatives mean positive. Tip 13: Read graph title and axes first. Tip 14: Finish early for review time."},{"id":"SSPT211013","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What characterizes Simple (Recall) MCQs?","options":["Direct questions","Higher cognition","Indirect questions","Case scenarios"],"correct":0,"explain":"Simple (Recall) MCQs ask about knowledge recall or recognition and are direct questions. Cognitive MCQs require higher functions, are indirect, and are based on case scenarios."},{"id":"SSPT211014","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Cognitive MCQs are based on what?","options":["A case or problem","Knowledge recall","Direct questions","A simple stem"],"correct":0,"explain":"Cognitive MCQs require higher cognitive functions and are based on a case scenario (a clinical case) or a problem that needs solving. Simple recall and direct questions describe Simple MCQs."},{"id":"SSPT211015","type":"matching","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Match MCQ structure parts to their definitions.","leftItems":[{"id":"1","text":"Stem"},{"id":"2","text":"Lead-in"},{"id":"3","text":"Options"}],"rightItems":[{"id":"A","text":"Clinical case scenario"},{"id":"B","text":"The question asked"},{"id":"C","text":"4 choices including correct"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"The stem is the clinical case scenario. The lead-in is the question asked. The options are the 4 choices including the correct answer."},{"id":"SSPT211016","type":"stepped","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"A student chooses between 'above down' and 'down up' approaches for an MCQ.","steps":[{"id":"1","prompt":"When use the 'Above down' approach?","options":["When prepared well","When no time left","When stem complex","When English poor"],"correct":0},{"id":"2","prompt":"After deciding to use 'Above down' because you prepared well, what is the first step?","options":["Read the stem","Read the options","Read the lead-in","Guess the answer"],"correct":0},{"id":"3","prompt":"After reading the stem in 'Above down', what do you underline in it?","options":["Positive and negative","Title and axes","Qualifying words","Lead-in and options"],"correct":0},{"id":"4","prompt":"After underlining key data, when do you figure out the correct answer?","options":["Before seeing options","At first glance","Before leaving test","While eating breakfast"],"correct":0},{"id":"5","prompt":"After figuring out the answer, when is the 'Down up' approach recommended instead?","options":["When stem complex","When stem simple","When ample time","When high prep"],"correct":0},{"id":"6","prompt":"When the stem is complex and you use 'Down up', what to read first?","options":["Lead-in and options","Stem and key data","Title and axes","Positive and negative"],"correct":0}],"explain":"'Above down' is used when prepared well, starting with the stem, underlining key data, and figuring out the answer before seeing options. 'Down up' is used for complex stems, starting with the lead-in and options."},{"id":"SSPT211017","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"According to MCQ Tip 3, when change an answer?","options":["When absolutely sure","At first glance","Before seeing options","Before leaving test"],"correct":0,"explain":"MCQ Tip 3 advises not to second guess yourself. Only change answers if you are absolutely sure the current answer is incorrect."},{"id":"SSPT211018","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What does Tip 4 for answering MCQs advise to avoid?","options":["Patterns and middle dumping","Reading all options","Eliminating choices","Deciding beforehand"],"correct":0,"explain":"MCQ Tip 4 advises to avoid patterns and avoid middle dumping. Reading options, eliminating choices, and deciding beforehand are other recommended tips."},{"id":"SSPT211019","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What defines 'Educated guessing'?","options":["Using your judgment","Having no knowledge","At first glance","Before leaving test"],"correct":0,"explain":"Educated guessing is made using judgment and a particular level of knowledge and is therefore more likely to be correct. Wild guessing is based on no knowledge."},{"id":"SSPT211020","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What defines 'Wild guessing'?","options":["Having no knowledge","Using your judgment","At first glance","Before leaving test"],"correct":0,"explain":"Wild guessing is made based on no knowledge or information. Educated guessing uses judgment and knowledge."},{"id":"SSPT211021","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What do Short Answer Questions (SAQs) test?","options":["Synthesizing the answer","Knowledge recall","Higher cognition","Choosing options"],"correct":0,"explain":"SAQs require the examinee to provide information, not to choose it. They test the examinees' ability to synthesize or create (write) the answer."},{"id":"SSPT211022","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which are recommended tips for answering SAQs?","options":["Formulate first","Clear handwriting","Focused and brief","Technical language","Follow the order","Underestimate examiner","Leave answers blank"],"correct":[0,1,2,3,4],"explain":"SAQ tips include formulating first, clear handwriting, being focused, using technical language, and following order. You should not underestimate the examiner or leave answers blank."},{"id":"SSPT211023","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"According to SAQ Tip 5, what if order matters?","options":["Follow it","Cross it out","Circle it","Underline it"],"correct":0,"explain":"SAQ Tip 5 states that if order matters, then follow it."},{"id":"SSPT211024","type":"matching","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Match computerized test strategies to their actions.","leftItems":[{"id":"1","text":"Positive goal"},{"id":"2","text":"Software commands"},{"id":"3","text":"Incorrect feedback"},{"id":"4","text":"Tensing up"}],"rightItems":[{"id":"A","text":"Intention to do well"},{"id":"B","text":"Understand interface"},{"id":"C","text":"Do not rush next"},{"id":"D","text":"Use relaxation"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"A positive goal shows intention to do well. Understand software commands to use the interface. Do not rush if feedback is incorrect. Use relaxation if tensing up."},{"id":"SSPT211025","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What to do before leaving a computerized test?","options":["Jot down concerns","Answer too quickly","Move to next question","Underestimate examiner"],"correct":0,"explain":"Before leaving the test, jot down (highlight) any questions that concerned or confused you."},{"id":"SSPT211026","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What should you prepare the night before?","options":["Your stationery","Rewritten notes","Practice questions","Title and axes"],"correct":0,"explain":"The night before the test, prepare your stationery for the exam along with sleeping early and reviewing notes."},{"id":"SSPT211027","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What does Tip 6 ('Certainty marking') do?","options":["Track what needs revisiting","Budget your time","Fix your attention","Have review time"],"correct":0,"explain":"Certainty marking helps you keep track of what needs to get answered or revisited."},{"id":"SSPT211028","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which word is a 'Qualifying Word'?","options":["Always","Stem","Lead-in","Options"],"correct":0,"explain":"Qualifying words include Always, Never, Except, Only, and others that alter the statement's meaning. Stem, lead-in, and options are parts of an MCQ."},{"id":"SSPT211029","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What do negative prefixes do to meaning?","options":["Reverse the meaning","Alter the statement","Make it positive","Track what needs review"],"correct":0,"explain":"Negative words and prefixes change the meaning to the opposite."},{"id":"SSPT211030","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"In an MCQ, what is the 'Lead-in'?","options":["The question asked","The clinical case","The four choices","The correct answer"],"correct":0,"explain":"The Lead-in is a question, like: Which of the following is...?"},{"id":"SSPT211031","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What to do before reading MCQ options (Tip 5)?","options":["Decide the answer","Read all options","Eliminate choices","Guess it"],"correct":0,"explain":"MCQ Tip 5 advises trying to decide the answer before reading the options."},{"id":"SSPT211032","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What to eliminate at first glance (MCQ Tip 2)?","options":["Incorrect choices","The question stem","Qualifying words","Key data points"],"correct":0,"explain":"MCQ Tip 2 advises eliminating choices you know are incorrect at 1st glance."},{"id":"SSPT211033","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"According to SAQ Tip 6, what not to do?","options":["Underestimate examiner","Technical language","Focused and brief","Clear handwriting"],"correct":0,"explain":"SAQ Tip 6 states: Don't underestimate the examiner."},{"id":"SSPT211034","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What keeps a focused mind on computer tests?","options":["Concentration tactics","Wild guessing","Middle dumping","Peer competition"],"correct":0,"explain":"Use concentration strategies to keep a focused mind and deal with distractors during computerized tests."},{"id":"SSPT211035","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"On the day of the test, why do some workout?","options":["It helps you relax","It is brain fuel","It fixes attention","It tracks revisits"],"correct":0,"explain":"Doing some workout on the day of the test helps you relax. Breakfast is brain fuel, underlining fixes attention, and certainty marking tracks revisits."},{"id":"SSPT211036","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"If you don't know the answer to a question, what should you do?","options":["Guess it","Leave it blank","Cross it out","Circle it"],"correct":0,"explain":"Your goal is to collect marks. Don't leave any question unanswered. If you don't know the answer, guess it."},{"id":"SSPT211037","type":"matching","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Match each MCQ strategy to its action.","leftItems":[{"id":"1","text":"Read all options"},{"id":"2","text":"Eliminate choices"},{"id":"3","text":"Avoid second guessing"},{"id":"4","text":"Avoid patterns"},{"id":"5","text":"Decide first"}],"rightItems":[{"id":"A","text":"Do before selecting"},{"id":"B","text":"Remove incorrect ones"},{"id":"C","text":"Change only if sure"},{"id":"D","text":"Prevent middle dumping"},{"id":"E","text":"Figure out beforehand"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"},"explain":"Read all options before selecting. Eliminate incorrect ones instantly. Avoid second guessing by changing only if sure. Avoid patterns like middle dumping. Decide the answer before reading options."},{"id":"SSPT211038","type":"matching","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Match each SAQ strategy to its action.","leftItems":[{"id":"1","text":"Formulate first"},{"id":"2","text":"Clear handwriting"},{"id":"3","text":"Focused and brief"},{"id":"4","text":"Technical language"},{"id":"5","text":"Follow order"},{"id":"6","text":"Respect examiner"}],"rightItems":[{"id":"A","text":"Think before writing"},{"id":"B","text":"Make it legible"},{"id":"C","text":"Get straight to point"},{"id":"D","text":"Use proper terms"},{"id":"E","text":"Obey the sequence"},{"id":"F","text":"Do not underestimate"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"Formulate the answer before writing. Use clear handwriting to make it legible. Be focused and get straight to the point. Use technical terminology. Follow the sequence if order matters. Respect the examiner by not underestimating them."},{"id":"SSPT211039","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"If instructions are spoken by invigilators, what should you do?","options":["Listen attentively","Scan the whole test","Budget your time","Skip tough ones"],"correct":0,"explain":"Tip 1 states to read instructions carefully, and if spoken by invigilators, listen attentively to them."},{"id":"SSPT211040","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What should you do when you see a qualifying word?","options":["Circle it","Cross it out","Underline it","Skip it"],"correct":0,"explain":"When you see a qualifying word, circle it to fix attention on it. Crossing out is for double negatives, and underlining is for key data."},{"id":"SSPT211041","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which are common negative prefixes or words?","options":["un","non","dis","not","except","false"],"correct":[0,1,2,3],"explain":"Common negative prefixes and words include un, non, dis, and not. 'Except' is a qualifying word, and 'false' is a true/false qualifier, not a prefix."},{"id":"SSPT211043","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Cognitive MCQs are based on which items?","options":["A clinical case","A Math problem","The capital city","2 benefits","Knowledge recall","Direct questions"],"correct":[0,1],"explain":"Cognitive MCQs are based on a case scenario (a clinical case) or a problem that needs solving (Math or Physics problem). The other options describe Simple MCQs or SAQs."},{"id":"SSPT211044","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which conditions favor the 'above down' approach?","options":["You have time","You prepared well","Stem is simple","You lack time","Stem is complex","English is poor"],"correct":[0,1,2],"explain":"The 'above down' approach is used when you have time, prepared well, and the stem is simple and easily readable. The other conditions favor the 'down up' approach."},{"id":"SSPT211045","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which conditions favor the 'down up' approach?","options":["You lack time","Poor preparation","Stem is complex","English is poor","You have time","You prepared well"],"correct":[0,1,2,3],"explain":"The 'down up' approach is used when you don't have time, did not prepare well, the stem is complex, or you are not good at English. Having time and preparing well favor 'above down'."},{"id":"SSPT211046","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which describe Short Answer Questions (SAQs)?","options":["Provide information","Synthesize answer","Knowledge recall","Indirect questions","Case scenarios","Direct questions"],"correct":[0,1],"explain":"SAQs require the examinee to provide information and test the ability to synthesize or create the answer. The other options describe Simple or Cognitive MCQs."},{"id":"SSPT211047","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which are essential strategies for computerized tests?","options":["Use MCQ strategies","Do not rush","Discuss with lab","Skip tough ones","Leave blank","Second guess"],"correct":[0,1,2],"explain":"Essential strategies include using multiple-choice strategies, not answering too quickly, and discussing skills with the lab assistant or instructor. Skipping, leaving blank, and second guessing are not recommended."},{"id":"SSPT211048","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"According to the conclusion, test preparation prevents what?","options":["Anxiety and panic","Qualifying words","Negative prefixes","Middle dumping"],"correct":0,"explain":"Test preparation makes test taking easy and prevents test anxiety and panic."},{"id":"SSPT211049","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Tips for which test types are important for any test taker?","options":["MCQs and SAQs","Stem and lead-in","Title and axes","Positive and negative"],"correct":0,"explain":"Tips for taking MCQs and SAQs tests are important for any test taker."},{"id":"SSPT211050","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Test taking skills are important for whom?","options":["Everyone in education","Lab assistants","Anxious colleagues","Invigilators"],"correct":0,"explain":"Test taking skills are important for everyone in education."},{"id":"SSPT211051","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which actions belong to the day of the test?","options":["Wake up early","Do some workout","Have breakfast","Attend early","Quick review","Sleep early","Prepare stationery"],"correct":[0,1,2,3,4],"explain":"Day of the test actions include waking up early, working out, having breakfast, attending early, and quick review. Sleeping early and preparing stationery belong to the night before."},{"id":"SSPT211052","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which actions belong to the day and night before the test?","options":["Think positively","Review notes","Review forgotten info","Sleep early","Prepare stationery","Wake up early","Do some workout"],"correct":[0,1,2,3,4],"explain":"Day and night before actions include thinking positively, reviewing notes, reviewing easily forgotten info, sleeping early, and preparing stationery. Waking up early and working out are for the day of the test."},{"id":"SSPT211053","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Without good preparation, what happens even if you have more knowledge than you think?","options":["You will not do well","Memory is inhibited","Become confused","Focus decreases"],"correct":0,"explain":"You most probably have more knowledge than what you think you do. But, without good preparation you will not do well on tests. The other options are results of panic."},{"id":"SSPT211054","type":"mcq","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"What is a key constraint for online exams regarding skipping questions?","options":["No back to previous","Skip tough ones","Answer easy first","Leave them blank"],"correct":0,"explain":"In an online exam, there is no back to previous question, unlike a paper exam where you can skip tough ones and return to them later."},{"id":"SSPT211055","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which words from the first group are listed as 'Qualifying Words'?","options":["Always","Never","Including","All","Because","Must","Stem","Lead-in"],"correct":[0,1,2,3,4,5],"explain":"Qualifying words include Always, Never, Including, All, Because, and Must. Stem and Lead-in are parts of an MCQ structure."},{"id":"SSPT211056","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which words from the second group are listed as 'Qualifying Words'?","options":["Weak","Strong","Positive","Negative","Except","More than","Options","Cues"],"correct":[0,1,2,3,4,5],"explain":"Qualifying words include Weak, Strong, Positive, Negative, Except, and More than. Options and Cues are parts of test structures."},{"id":"SSPT211057","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which words from the third group are listed as 'Qualifying Words'?","options":["Less than","True","False","Superior","Inferior","Few","Summary","Record"],"correct":[0,1,2,3,4,5],"explain":"Qualifying words include Less than, True, False, Superior, Inferior, and Few. Summary and Record are note-taking terms."},{"id":"SSPT211058","type":"multi","cat":"Lecture 11 - Test Preparation and Taking Skills","q":"Which words from the fourth group are listed as 'Qualifying Words'?","options":["Only","Absolutely","Always","Never","Except","All","Main notes","Recall"],"correct":[0,1,2,3,4,5],"explain":"Qualifying words include Only and Absolutely, along with others like Always, Never, Except, and All. Main notes and Recall are Cornell note-taking terms."}]}},"banks/studyskills/lecture-12-tech-health.json":{"id":"ss-lec12-tech-health","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 12 – Using Technology in Health Professions Education","formSize":46,"forms":["A"],"bank":{"A":[{"id":"SSPT212000","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"What is the best place to start searching for credible, peer-reviewed, scholarly research for academic papers?","options":["Regular Google search","Wikipedia","Digital Library","Google Scholar"],"correct":2,"explain":"The Digital Library is the best place to start because it gives access to subscribed, credible, peer-reviewed, evidence-based research. Google is generic, Wikipedia is anyone-edited, and Scholar, while scholarly, is still outranked by the Library."},{"id":"SSPT212001","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Why is regular Google not recommended for research information?","options":["It is generic, with all kinds, not just credible info","It is a broad search of scholarly literature and sources","It is an open site edited by anyone without expertise","It is a subscribed source of credible and peer-reviewed research"],"correct":0,"explain":"Google is a generic site giving all kinds of information, not just medical, research, evidence-based, scholarly, or necessarily credible information, so there are many links to pick through, and it always links to Wikipedia. The other options describe Scholar, Wikipedia, and the Library."},{"id":"SSPT212002","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Why should Wikipedia NOT be cited as a reference source?","options":["Anyone can edit it, even without topic knowledge","It is a generic all-kinds not-credible web site","It broadly searches the scholarly literature and sources","It subscribes to the credible and peer-reviewed databases"],"correct":0,"explain":"Wikipedia can be added to and edited by anyone, even if they know nothing about the topic, so it must not be cited; find and cite the original source instead. The other options describe Google, Scholar, and the Library."},{"id":"SSPT212003","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"When evaluating a source, what does the 'When' question refer to?","options":["The date the resource was produced","The author and any credentials listed","The abstract, the facts, or opinions","The information source and reference list"],"correct":0,"explain":"'When' asks when the resource was produced: the copyright date for books, the publication date for articles, and the created or last-updated date for websites. The other options are the Who, What, and Where points."},{"id":"SSPT212004","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each top-level domain to the kind of site it marks.","leftItems":[{"id":"1","text":".edu"},{"id":"2","text":".k-12"},{"id":"3","text":".com"},{"id":"4","text":".gov"},{"id":"5","text":".mil"},{"id":"6","text":".org"},{"id":"7","text":".net"}],"rightItems":[{"id":"A","text":"Higher learning"},{"id":"B","text":"Elementary and secondary schools"},{"id":"C","text":"For-profit enterprise sites"},{"id":"D","text":"Public administration bodies"},{"id":"E","text":"Armed forces sites"},{"id":"F","text":"Nonprofit general groups"},{"id":"G","text":"Interlinked digital systems"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G"},"explain":".edu = higher education; .k-12 = elementary and secondary schools; .com = commercial; .gov = government agency; .mil = military; .org = general noncommercial organization; .net = computer network. The right-hand labels are root-free synonyms so no pair can be matched by shared letters; the standard glosses are kept here."},{"id":"SSPT212005","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"What does the 'P' in the PICOT search acronym stand for?","options":["Preferred procedure","Patient population","Published date","Primary source"],"correct":1,"explain":"PICOT stands for Patient population, Intervention, Comparison, Outcome, and Time frame. P represents the patient population."},{"id":"SSPT212006","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"In the PICOT acronym, what does 'I' represent?","options":["Internet source","Intervention or issue of interest","Index term","Institutional affiliation"],"correct":1,"explain":"In PICOT, I stands for intervention or issue of interest."},{"id":"SSPT212007","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"When formulating a PICOT search, which combination is recommended to start with?","options":["P + C, or T + C, or P + C + T","P + O, or P + I, or P + I + O","O + C, or T + O, or O + C + T","I + C, or T + I, or I + C + T"],"correct":1,"explain":"A PICOT search should include P + O, or P + I, or P + I + O; C and/or T are added only to reduce the retrieval number if it is too high. Every option here lists two 2-element plus one 3-element combination, so all four are the same length and shape and the correct one is neither longest nor shortest."},{"id":"SSPT212008","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"What is the term for using someone else's words without giving them credit?","options":["Theft","Fair use","Plagiarism","Copyright"],"correct":2,"explain":"Using someone else's words without credit is plagiarism. Taking without permission is theft. Fair use lets teachers and students use portions of works. Copyright is the legal right controlling copying and use."},{"id":"SSPT212009","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Under the 'Fair Use' concept, who is allowed to use portions of copyrighted works without permission?","options":["Commercial publishers","Teachers and students","Government agencies only","Anyone on the internet"],"correct":1,"explain":"The 'Fair Use' concept lets teachers and students use portions of copyrighted works without permission."},{"id":"SSPT212010","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"For a multimedia project, what is the maximum limit for copying music under Fair Use guidelines?","options":["10% but no more than 30 seconds","10% or up to three full minutes","10% or up to one thousand words","50% of the original recorded track"],"correct":0,"explain":"For multimedia projects, Fair Use limits for music are 10% but no more than 30 seconds. Video clips are 10% or 3 minutes, and text is 10% or 1000 words."},{"id":"SSPT212011","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each technology use in health professions education to its role.","leftItems":[{"id":"1","text":"Simulation & Virtual Reality (VR)"},{"id":"2","text":"Increased Access"},{"id":"3","text":"Personalized Learning"},{"id":"4","text":"Digital Learning Platforms"}],"rightItems":[{"id":"A","text":"A safe controlled environment to practice procedures and make mistakes without real-world consequences"},{"id":"B","text":"Makes education reachable for those in remote areas or with limited resources"},{"id":"C","text":"Adaptive technologies tailor educational content to each student's needs, aiding uptake and retention"},{"id":"D","text":"Online tools offer distance flexibility and supplement traditional teaching with video lectures, quizzes, and forums"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Simulation & VR provides a safe controlled environment to practice procedures and make mistakes without real-world consequences. Increased Access makes education reachable for remote or limited-resource learners. Personalized Learning tailors content to each student. Digital Learning Platforms add distance flexibility with video, quizzes, and forums."},{"id":"SSPT212012","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"What is a challenge of integrating technology into health professions education?","options":["Unreliable internet and devices can disrupt learning","Increased access for remote or limited learners","Adaptive tools tailor content to each learner","Digital platforms provide flexible distance learning options"],"correct":0,"explain":"Technical difficulties are a challenge: not everyone has reliable internet or devices, and problems disrupt learning. The other three are benefits (access, personalized learning, platforms), so they are not challenges."},{"id":"SSPT212013","type":"stepped","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Steps for evaluating a source.","steps":[{"id":"1","prompt":"What does the 'Who' evaluation point check?","options":["The author's listed name and credentials","The publication date of the resource","The overall purpose of the resource","The reference list of the author"],"correct":0},{"id":"2","prompt":"What does the 'What' evaluation point check?","options":["Whether abstract or full, fact or opinion","The author and credentials listed set","The information source and reference list","The production or copyright date shown"],"correct":0},{"id":"3","prompt":"What does the 'Where' evaluation point check?","options":["Where the author got the information","The author identity and credentials list","The abstract completeness or opinion type","The resource purpose and intended audience"],"correct":0}],"explain":"Who checks the author and whether credentials are listed. What checks whether it is an abstract or a complete article, and whether it is research based on facts or someone's opinion. Where checks where the author got the information and whether a list of sources is provided. Each step's options are six words and share one shape, so no correct option is the longest."},{"id":"SSPT212014","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Which top-level domain represents a computer network?","options":[".net",".mil",".k-12",".edu"],"correct":0,"explain":"The .net top-level domain represents a computer network."},{"id":"SSPT212015","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"What is the correct sequence to access the Saudi Digital Library (SDL) from the Ibn Sina Website?","options":["E-Services, Students services, Banner, login, SDL link","Banner, E-Services, Students services, SDL link, login","Students services, E-Services, Banner, login, SDL link","E-Services, Banner, Students services, login, SDL link"],"correct":0,"explain":"The correct sequence is: Ibn Sina Website -> E-Services -> Students services -> Banner -> login -> Click on Saudi Digital Library (SDL) link."},{"id":"SSPT212016","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Why should search terms in a database be specific and use medical terms?","options":["To use medical terms, not commonly used ones","To build the clinical question with PICOT format","To apply the limiters that narrow your search","To start from the subscribed peer-reviewed database sources"],"correct":0,"explain":"If results are hard to find, the search terms may not be specific enough; use the medical terms and not commonly used terms. The other options describe PICOT, the limiters, and the Library, which are different steps."},{"id":"SSPT212017","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"What does 'Personalized Learning' as a benefit of technology refer to?","options":["Adaptive tools tailor content to each learner","Safe controlled student practice without real-world consequences","Increased access for remote or limited learners","Digital platforms provide flexible distance learning options"],"correct":0,"explain":"Personalized learning means adaptive technologies tailor educational content to each learner's needs, enhancing uptake and retention. The other options are the simulation, access, and platform benefits, not personalized learning."},{"id":"SSPT212018","type":"multi","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Which of the following are protected by copyright?","options":["Literary works","Computer software","Musical works","Dramatic works","Sound recordings","Wikipedia articles"],"correct":[0,1,2,3,4],"explain":"Copyright protects literary works, computer software, musical works, dramatic works, and sound recordings. Wikipedia articles are not among the protected categories."},{"id":"SSPT212019","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"What is the primary purpose of limiting a database search to 'Abstracts'?","options":["To quickly determine if an article fits needs","To read the complete full text of articles","To find only the most recent literature published","To access only the articles that are free"],"correct":0,"explain":"Limiting to abstracts lets you quickly determine whether a specific article will fit your needs. The other options are the purposes of the full-text, recent-years, and free-article limiters."},{"id":"SSPT212020","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"In the PICOT acronym, what does 'C' stand for?","options":["Clinical diagnosis of the patient","Comparison intervention or issue","Case study of one patient","Control group only in trials"],"correct":1,"explain":"In PICOT, C stands for comparison intervention or issue of interest."},{"id":"SSPT212021","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"In the PICOT acronym, what does 'T' stand for?","options":["Treatment plan","Time frame","Theory","Trial"],"correct":1,"explain":"In PICOT, T stands for time frame."},{"id":"SSPT212022","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"For a multimedia project, what is the maximum limit for copying text under Fair Use guidelines?","options":["10% or up to 1000 words","10% or up to three minutes","50% of the entire book","100 words from the text"],"correct":0,"explain":"For multimedia projects, the Fair Use limit for text is 10% or 1000 words."},{"id":"SSPT212023","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"For a multimedia project, what is the maximum limit for copying video clips under Fair Use guidelines?","options":["10% or up to three minutes","10% or up to 30 seconds","50% of the whole video file","10% or up to one minute"],"correct":0,"explain":"For multimedia projects, the Fair Use limit for video clips is 10% or three minutes."},{"id":"SSPT212024","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each multimedia Fair Use limit to its category.","leftItems":[{"id":"1","text":"Video clips"},{"id":"2","text":"Music"},{"id":"3","text":"Text"}],"rightItems":[{"id":"A","text":"10% or three minutes"},{"id":"B","text":"10% but no more than 30 seconds"},{"id":"C","text":"10% or 1000 words"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Fair Use limits for multimedia projects are: Video clips (10% or three minutes), Music (10% but no more than 30 seconds), and Text (10% or 1000 words)."},{"id":"SSPT212025","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Which of the following is NOT a recommended step when accessing the Saudi Digital Library?","options":["Click on the E-Services menu","Go to the Students services page","Log in with your user name and password","Pay a fee directly through Google search"],"correct":3,"explain":"Accessing SDL involves E-Services, Students services, Banner, and logging in. Paying a fee directly through Google is not a step."},{"id":"SSPT212026","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each tool for locating literature to how it is described.","leftItems":[{"id":"1","text":"Digital Library"},{"id":"2","text":"Google"},{"id":"3","text":"Google Scholar"},{"id":"4","text":"Wikipedia"}],"rightItems":[{"id":"A","text":"Subscribed databases of credible, peer-reviewed, evidence-based research for papers and projects"},{"id":"B","text":"Generic site giving all kinds of information, not just medical or credible"},{"id":"C","text":"Broadly searches academic papers, theses, books, and abstracts across many disciplines"},{"id":"D","text":"Edited by anyone, useful for overview, but cite the original source instead"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"The Digital Library gives subscribed databases of credible, peer-reviewed, evidence-based research for papers and projects. Google is a generic site with all kinds of information. Google Scholar broadly searches academic papers, theses, books, and abstracts. Wikipedia is edited by anyone, so cite the original source instead."},{"id":"SSPT212027","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"When evaluating a source, checking the 'copyright date' for books or 'publication date' for articles answers which evaluation question?","options":["Who","What","Where","When"],"correct":3,"explain":"Checking the copyright or publication date answers the 'When' evaluation question."},{"id":"SSPT212028","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Taking something, including text and pictures from the Internet, without permission is considered what?","options":["Theft","Plagiarism","Fair use","Public domain"],"correct":0,"explain":"Taking something without permission is theft. Using someone else's words without giving credit is plagiarism."},{"id":"SSPT212029","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Which of the following is a challenge of using technology in health professions education?","options":["Training needs and resistance to change arise","Increased access for remote or limited learners","Adaptive tools tailor content to each learner","Safe controlled student practice without real-world consequences"],"correct":0,"explain":"Training and adaptation is a challenge: educators and students may need training, and some resist changing traditional methods. The other three are benefits (access, personalized learning, simulation), not challenges."},{"id":"SSPT212030","type":"stepped","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Expand each letter of the PICOT acronym.","steps":[{"id":"1","prompt":"In [[P]]ICOT, what does P stand for?","options":["Patient population","Procedure performed","Publication date","Primary source"],"correct":0},{"id":"2","prompt":"In P[[I]]COT, what does I stand for?","options":["Intervention or issue of interest","Index term inside the record","Institutional home of the author","Internet source of the data"],"correct":0},{"id":"3","prompt":"In PI[[C]]OT, what does C stand for?","options":["Comparison intervention or issue of interest","Clinical diagnosis defining the patient group","Case characteristics of an individual patient","Control condition used for the comparison arm"],"correct":0},{"id":"4","prompt":"In PIC[[O]]T, what does O stand for?","options":["Outcome","Output","Overview","Observation"],"correct":0},{"id":"5","prompt":"In PICO[[T]], what does T stand for?","options":["Time frame","Treatment plan","Theory test","Trial period"],"correct":0}],"explain":"P = patient population. I = intervention or issue of interest. C = comparison intervention or issue of interest. O = outcome. T = time frame. Each step's distractors expand the same letter but give a wrong meaning, so the underlined position is the only cue to which letter is asked."},{"id":"SSPT212031","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each PICOT search expression to its role.","leftItems":[{"id":"1","text":"P + O"},{"id":"2","text":"P + I"},{"id":"3","text":"P + I + O"},{"id":"4","text":"C and/or T"}],"rightItems":[{"id":"A","text":"Required search elements"},{"id":"B","text":"Add-on to cut the retrieval number"}],"correct_pairs":{"1":"A","2":"A","3":"A","4":"B"},"explain":"The search should include P + O, P + I, or P + I + O; C and/or T may be added to reduce the retrieval number when it is too high. The three core sets share one role, so they all map to the same right box."},{"id":"SSPT212033","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each database limiter to why you would use it.","leftItems":[{"id":"1","text":"Full Text"},{"id":"2","text":"Abstracts"},{"id":"3","text":"Most recent years"},{"id":"4","text":"Free articles"}],"rightItems":[{"id":"A","text":"Read the entire piece end to end"},{"id":"B","text":"Screen quickly for fit before committing"},{"id":"C","text":"Limit to the newest published work"},{"id":"D","text":"Show only items costing nothing"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Limiters refine and narrow a search. Full Text: read the whole article. Abstracts: quickly determine if a specific article will fit your needs. Most recent years: when you need recent literature. Free articles: most database articles cost money, so check this for only free ones. The right labels are root-free so no pair is matched by shared letters."},{"id":"SSPT212034","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each post-search situation to what you do next.","leftItems":[{"id":"1","text":"Skipped the subscribed collections"},{"id":"2","text":"Used the subscribed collections"},{"id":"3","text":"An item is now in hand"}],"rightItems":[{"id":"A","text":"Critically appraise the origin"},{"id":"B","text":"Trust the source and move ahead"},{"id":"C","text":"Read and confirm relevance"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"After finding something: if you did not use the Library's databases, evaluate the source; if you did, you should be good to go. Then read and evaluate the information to see if it is what you need. Right labels avoid the left roots so no pair is solvable by shared letters."},{"id":"SSPT212035","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Which set lists the elements shown in the sample reference?","options":["Author, year, title, journal, volume, pages, retrieval","Author, year, title, journal, edition, pages, retrieval","Author, year, editor, journal, volume, pages, retrieval","Author, year, title, publisher, volume, pages, retrieval"],"correct":0,"explain":"The sample reference shows author, year, article title, journal, volume, page range, and a retrieval line. It lists no editor, no edition, and no publisher, so those three swaps are wrong."},{"id":"SSPT212036","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"In source evaluation, what does the 'Why' point ask?","options":["The purpose the resource serves","The author and listed credentials","The abstract, facts, or opinions","The information source and list"],"correct":0,"explain":"The 'Why' point asks the purpose, that is why the resource exists. The other options are the Who, What, and Where evaluation points."},{"id":"SSPT212037","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"On what basis should you choose which database to use?","options":["The kind of results you want","The total count of resources listed","The top-level domain of the site","The copyright date of the books"],"correct":0,"explain":"You decide on a database based on the results you want. Resource count, top-level domain, and copyright date are lecture facts but not the stated choice criterion."},{"id":"SSPT212038","type":"stepped","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Fix the search terms step by step.","steps":[{"id":"1","prompt":"When results are hard to find because terms are not specific, what should the search switch to?","options":["Medical terms, not common ones","Common words and not medical","The copyright date of books","The top-level domain of sites"],"correct":0},{"id":"2","prompt":"Applying medical terms, which search string matches the hand-hygiene example?","options":["Propanols OR disinfectants OR soaps AND hand washing","hand foam or gel sanitizers AND hand washing","Propanols AND disinfectants OR soaps AND hand washing","soap OR sanitizer AND hand washing foam gel"],"correct":0}],"explain":"Step 1: switch to medical terms, not common words; copyright dates and domains are evaluation points. Step 2: the medical string is Propanols OR disinfectants OR soaps AND hand washing; the foam, gel, and sanitizer wording is the common-term version."},{"id":"SSPT212039","type":"stepped","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Use the PICOT format.","steps":[{"id":"1","prompt":"PICOT helps you formulate what?","options":["A clinical question","A database limit","A reference format","A top-level domain"],"correct":0},{"id":"2","prompt":"After formulating a clinical question, PICOT guides the search for evidence in what manner?","options":["Quicker and more efficient","Slower and less credible","Broadly across many disciplines","Only through Wikipedia edits"],"correct":0}],"explain":"Step 1: PICOT formulates a clinical question. Step 2: it guides the search for evidence quicker and more efficiently. Limits, reference formats, and domains are other lecture topics, not PICOT's purpose."},{"id":"SSPT212040","type":"stepped","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Build the PICOT sentence frame.","steps":[{"id":"1","prompt":"The PICOT sentence frame begins by introducing the patient population with which word?","options":["In","For","Among","Within"],"correct":0},{"id":"2","prompt":"After the patient population is introduced with In, the intervention is added using which phrase?","options":["how does","what is","why will","when did"],"correct":0},{"id":"3","prompt":"After the intervention follows how does, the comparison is added using which phrase?","options":["compared to","instead of","rather than","along with"],"correct":0},{"id":"4","prompt":"After the comparison follows compared to, the outcome is added using which verb?","options":["influence","change","affect","improve"],"correct":0},{"id":"5","prompt":"After the outcome follows influence, the time frame is added using which preposition?","options":["over","during","within","across"],"correct":0}],"explain":"The frame reads: In (P), how does (I) compared to (C) influence (O) over (T). Step 1 opens with In. Step 2 adds how does. Step 3 adds compared to. Step 4 adds influence. Step 5 adds over. The other words are same-type connectives not used in this frame."},{"id":"SSPT212041","type":"stepped","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Define copyright in two parts.","steps":[{"id":"1","prompt":"Copyright is the legal right of which pair to control the copying and use of creative works?","options":["Author or artist","Teacher or student","Publisher or university","Agency or military"],"correct":0},{"id":"2","prompt":"Copyright is the legal right of an author or artist to control what two actions regarding creative works?","options":["Copying and use","Editing and citing","Searching and limiting","Evaluating and referencing"],"correct":0}],"explain":"Step 1: the right belongs to an author or artist. Step 2: it controls the copying and use of their creative works. Teachers and students hold fair-use rights; publishers and universities are Scholar's sources; agencies and military are domain types. Editing, searching, and evaluating are other lecture actions."},{"id":"SSPT212042","type":"multi","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Which statements match what students may copy?","options":["One hard copy for personal use","Not for public or commercial use","Students must cite their source","Many hard copies for public use","Hard copies without citing source","Copies allowed for commercial use"],"correct":[0,1,2],"explain":"Students may make one hard copy for personal or educational use, never for public or commercial use, and must cite the source. Many copies, no citation, and commercial use all conflict with these rules."},{"id":"SSPT212043","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Technological enhancements provide what kind of ways to teach and learn?","options":["Innovative","Traditional","Adaptive","Controlled"],"correct":0,"explain":"Hands-on training is paired with innovative ways to teach and learn. Traditional describes conventional education, adaptive describes tailored content, and controlled describes the practice environment, not the innovative ways."},{"id":"SSPT212044","type":"matching","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Match each integration verb to what it affects.","leftItems":[{"id":"1","text":"Increases"},{"id":"2","text":"Enhances"},{"id":"3","text":"Improves"}],"rightItems":[{"id":"A","text":"Accessibility"},{"id":"B","text":"Interaction"},{"id":"C","text":"The overall learning experience"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Integrating technology increases accessibility, enhances interaction, and improves the overall learning experience; these are the three stated effects of integration."},{"id":"SSPT212045","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"For research, which order lists the tools from least to most preferred?","options":["Google, Scholar, Library","Scholar, Google, Library","Library, Scholar, Google","Google, Library, Scholar"],"correct":0,"explain":"Google is not the best place, Scholar is better, and the Library is even better, so least to most preferred is Google, Scholar, Library. The other orders reverse or swap these steps."},{"id":"SSPT212046","type":"mcq","cat":"Lecture 12 – Using Technology in Health Professions Education","q":"Scholar draws its articles from academic publishers, universities, and what else?","options":["other web sites","Wikipedia site editors","government agency sites","military network sites"],"correct":0,"explain":"Scholar pulls peer-reviewed papers, theses, books, abstracts, and articles from academic publishers, universities, and other web sites. Wikipedia, government agencies, and military branches are other lecture topics, not Scholar's providers."}]}},"banks/studyskills/lecture-13-medical-student-assessment.json":{"id":"msa-lec13","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 13 – Medical Student Assessment","formSize":43,"forms":["A"],"bank":{"A":[{"id":"MSA13001","type":"mcq","cat":"MT_lec13","q":"The word 'assess' comes from the Latin verb 'assidere', which means what?","options":["To sit with","To judge strictly","To measure progress","To grade formally"],"correct":0,"explain":"'Assess' comes from 'assidere', meaning 'to sit with'. Judging strictly, measuring progress, and grading formally are not its meaning."},{"id":"MSA13002","type":"mcq","cat":"MT_lec13","q":"Student assessment gains learning information and forms what?","options":["Value judgments","Financial budgets","Curriculum plans","Teacher reviews"],"correct":0,"explain":"Assessment forms value judgments concerning learning progress. Budgets, curriculum plans, and teacher reviews are not part of the definition."},{"id":"MSA13003","type":"mcq","cat":"MT_lec13","q":"The phrase 'steering effect of assessment' refers to which concept?","options":["Assessment drives learning","Assessment replaces instruction","Assessment is a necessary evil","Assessment is only for grading"],"correct":0,"explain":"The steering effect means assessment drives learning. It does not replace instruction; 'necessary evil' is a separate remark, and 'only for grading' is false."},{"id":"MSA13004","type":"mcq","cat":"MT_lec13","q":"Planning for student assessment must start with and go parallel to planning for what?","options":["Instruction","Graduation ceremonies","Student housing","Extracurricular activities"],"correct":0,"explain":"Assessment planning runs parallel to instruction planning. Ceremonies, housing, and activities are not the stated parallel."},{"id":"MSA13005","type":"matching","cat":"MT_lec13","q":"Match each assessment type to its primary design purpose.","leftItems":[{"id":"1","text":"Norm-referenced assessment"},{"id":"2","text":"Criterion-referenced assessment"}],"rightItems":[{"id":"A","text":"Absolute achievement of a clearly defined domain"},{"id":"B","text":"Relative standing among a known group"}],"correct_pairs":{"1":"B","2":"A"},"explain":"Norm-referenced assessment gauges relative standing among a known group. Criterion-referenced assessment gauges absolute achievement of a defined domain."},{"id":"MSA13006","type":"multi","cat":"MT_lec13","q":"Which of the following are functions of student assessment?","options":["Certifying competence","Aiding student motivation","Replacing teacher instruction","Aiding in relative ranking of students"],"correct":[0,1,3],"explain":"Functions include certifying competence, aiding motivation, and aiding relative ranking. Replacing instruction is not a function; assessment parallels instruction."},{"id":"MSA13007","type":"mcq","cat":"MT_lec13","q":"Placement assessment is used to decide what?","options":["Entry level","Exit grade","Final rank","Knowledge gap"],"correct":0,"explain":"Placement decides the entry level. Exit grade and final rank belong to summative use; the knowledge gap belongs to formative feedback."},{"id":"MSA13008","type":"mcq","cat":"MT_lec13","q":"Placement assessment is an entry exam to avoid what?","options":["Instruction duplication","Competence certification","Course grade granting","Knowledge gap bridging"],"correct":0,"explain":"Placement is an entry exam to avoid duplicated instruction. Certification and grades are summative; gap bridging is formative."},{"id":"MSA13009","type":"mcq","cat":"MT_lec13","q":"Formative assessment is best described as which of the following?","options":["Assessment For Learning","Assessment Of Learning","Assessment Against Learning","Assessment Without Learning"],"correct":0,"explain":"Formative assessment is 'Assessment For Learning'. 'Of Learning' is summative; 'Against' and 'Without' are not used."},{"id":"MSA13010","type":"mcq","cat":"MT_lec13","q":"Formative assessment is best described as which pattern?","options":["Continuous, no marks","Periodic, marks allocated","Continuous, marks allocated","Periodic, no marks"],"correct":0,"explain":"Formative assessment is continuous and informal with no marks. Periodic with marks is summative; the mixed patterns match neither type."},{"id":"MSA13012","type":"mcq","cat":"MT_lec13","q":"Summative assessment is primarily done to achieve what?","options":["Certify competence or grant grades","Discover gaps in knowledge during instruction","Avoid duplication of instruction","Provide immediate feedback for improvement"],"correct":0,"explain":"Summative assessment certifies competence or grants grades. Discovering gaps and giving feedback are formative; avoiding duplication is placement."},{"id":"MSA13013","type":"mcq","cat":"MT_lec13","q":"Knowledge (Cognition) is primarily assessed through which method?","options":["Written paper-and-pencil tests","Practical and clinical exams","Observation and Likert scales","Self and peer assessment"],"correct":0,"explain":"Knowledge is assessed by written paper-and-pencil tests. Practical clinical exams assess skills; observation and Likert scales assess attitudes; self and peer are carriers."},{"id":"MSA13014","type":"matching","cat":"MT_lec13","q":"Match each paper-and-pencil test category to its examples.","leftItems":[{"id":"1","text":"Selection-Type"},{"id":"2","text":"Supply-Type"}],"rightItems":[{"id":"A","text":"Short-Answer, Short Essay, Long Essay, Modified Essay"},{"id":"B","text":"MCQ, True/False, Matching"}],"correct_pairs":{"1":"B","2":"A"},"explain":"Selection-Type tests include MCQ, True/False, and Matching. Supply-Type tests include Short-Answer, Short Essay, Long Essay, and Modified Essay."},{"id":"MSA13015","type":"mcq","cat":"MT_lec13","q":"What makes MCQs the most common written-test item?","options":["They show who learned","They measure creation well","They are simple to make","They rule out guessing"],"correct":0,"explain":"MCQs are most common because they show who has learned and who has not. They are hard to construct, weak at measuring creation, and open to guessing."},{"id":"MSA13016","type":"multi","cat":"MT_lec13","q":"Which are recognized problems with MCQs?","options":["They are hard to construct","They miss problem-solving and creation","They let guessing affect scores","They are ineffective for knowledge"],"correct":[0,1,2],"explain":"MCQ problems are that they are hard to construct, weak at problem-solving and creation, and vulnerable to guessing. They are effective for assessing knowledge."},{"id":"MSA13017","type":"mcq","cat":"MT_lec13","q":"Skills are assessed through which type of exam?","options":["Performance","Paper-and-pencil","Norm-referenced","Likert-scale"],"correct":0,"explain":"Skills use practical and clinical performance exams. Paper-and-pencil tests assess knowledge; norm-referencing compares students; Likert scales rate attitudes."},{"id":"MSA13018","type":"matching","cat":"MT_lec13","q":"Match each performance exam task type to its example.","leftItems":[{"id":"1","text":"Extended Response"},{"id":"2","text":"Restricted Response"}],"rightItems":[{"id":"A","text":"OSCE and OSPE"},{"id":"B","text":"Long Case Examinations"}],"correct_pairs":{"1":"B","2":"A"},"explain":"Extended Response tasks include Long Case Examinations. Restricted Response tasks include OSCE and OSPE."},{"id":"MSA13019","type":"multi","cat":"MT_lec13","q":"Which tools belong to skills assessment?","options":["Rating scale","Checklist","Scoring rubric","Likert scale"],"correct":[0,1,2],"explain":"Skills scoring tools are the rating scale, checklist, and scoring rubric. The Likert scale rates attitudes, not skills."},{"id":"MSA13020","type":"mcq","cat":"MT_lec13","q":"Which domain of learning is the most difficult to assess?","options":["Attitudes","Knowledge","Skills"],"correct":0,"explain":"Attitudes are the most difficult domain to assess. Knowledge and skills are the other two assessed domains and are comparatively easier."},{"id":"MSA13021","type":"mcq","cat":"MT_lec13","q":"Assessment of attitudes uses observation and specific rating scales called what?","options":["Likert scales","Rubric scales","Norm scales","Checklist scales"],"correct":0,"explain":"Attitude rating scales are called Likert scales. Rubrics and checklists score skills; norm-referencing compares students and is not an attitude scale."},{"id":"MSA13022","type":"mcq","cat":"MT_lec13","q":"What does 'self-assessment' mean?","options":["Students judge their own performance","Students judge peers' performance","Teachers judge student performance","A national body judges all students"],"correct":0,"explain":"Self-assessment means students judge their own performance. Judging peers is peer-assessment; teachers give home-made exams; a national body assesses students nationwide."},{"id":"MSA13023","type":"mcq","cat":"MT_lec13","q":"What does 'peer-assessment' mean?","options":["Students judge one another's performance","Students judge their own performance","Teachers judge student performance","Learners judge via Likert scales"],"correct":0,"explain":"Peer-assessment means students judge one another's performance. Judging your own is self-assessment; teachers give home-made exams; Likert scales rate attitudes."},{"id":"MSA13024","type":"multi","cat":"MT_lec13","q":"Which are characteristics of a good assessment?","options":["Validity","Reliability","Educational impact","Cost","Guessing","Motivation"],"correct":[0,1,2,3],"explain":"The characteristics are validity, reliability, educational impact, cost, and acceptability. Guessing is an MCQ problem and motivation is a function, not a quality characteristic."},{"id":"MSA13025","type":"mcq","cat":"MT_lec13","q":"Which factor completes the utility formula: Validity × Reliability × Educational Impact × Cost × ?","options":["Acceptability","Fairness","Motivation","Guessing"],"correct":0,"explain":"The utility formula multiplies validity, reliability, educational impact, cost, and acceptability. Fairness is named alongside the characteristics but is not a factor; motivation and guessing are not."},{"id":"MSA13026","type":"mcq","cat":"MT_lec13","q":"Feedback is information about reactions to a performance, used as a basis for what?","options":["Improvement","Punishment","Grading only","Ranking"],"correct":0,"explain":"Feedback is used as a basis for improvement. It is an educational tool, not meant for punishment, grading only, or ranking."},{"id":"MSA13027","type":"multi","cat":"MT_lec13","q":"Which are traits of effective feedback?","options":["Be immediate","Be specific","Be personal","Be general"],"correct":[0,1],"explain":"Effective feedback is immediate and specific. It must not be personal, and 'general' contradicts 'specific'."},{"id":"MSA13029","type":"mcq","cat":"MT_lec13","q":"Which is an example of a Supply-Type paper-and-pencil test?","options":["Essay","MCQ","True/False","Matching"],"correct":0,"explain":"Essay questions (short, long, or modified) are Supply-Type. MCQ, True/False, and Matching are Selection-Type."},{"id":"MSA13030","type":"mcq","cat":"MT_lec13","q":"OSCE and OSPE are examples of which type of performance exam task?","options":["Restricted Response","Extended Response","Paper-and-pencil","Self-assessment"],"correct":0,"explain":"OSCE and OSPE are Restricted Response tasks. Extended Response is exemplified by Long Case Examinations; paper-and-pencil assesses knowledge; self-assessment is a carrier."},{"id":"MSA13032","type":"matching","cat":"MT_lec13","q":"Match each assessment carrier to its description.","leftItems":[{"id":"1","text":"Home-made exams"},{"id":"2","text":"National bodies"},{"id":"3","text":"Self-assessment"},{"id":"4","text":"Peer-assessment"}],"rightItems":[{"id":"A","text":"Institution teachers prepare and run them"},{"id":"B","text":"A country-wide agency tests every student"},{"id":"C","text":"Learners judge their own work"},{"id":"D","text":"Learners judge classmates' work"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"},"explain":"Home-made exams are run by institution teachers. National bodies are country-wide agencies. Self-assessment is learners judging their own work; peer-assessment is learners judging classmates' work."},{"id":"MSA13033","type":"mcq","cat":"MT_lec13","q":"In formative assessment, what is the central function?","options":["Feedback","Granting grades","Relative ranking","Certifying competence"],"correct":0,"explain":"In formative assessment, feedback is the central function. Granting grades, ranking, and certifying competence are summative functions."},{"id":"MSA13034","type":"mcq","cat":"MT_lec13","q":"Summative marks go to the students and to whom?","options":["The school","The nation","The tutors","The parents"],"correct":0,"explain":"Summative marks are reported to the students and the school. The nation, tutors, and parents are not the stated recipients."},{"id":"MSA13035","type":"saq","cat":"MT_lec13","q":"The Latin verb 'assidere', from which 'assess' comes, means to do what?","answer":"to sit with","accept":[],"explain":"The Latin verb 'assidere' means 'to sit with'."},{"id":"MSA13036","type":"matching","cat":"MT_lec13","q":"Sort each feature into its assessment type.","leftItems":[{"id":"1","text":"Assessment FOR learning"},{"id":"2","text":"Occurs after instruction"},{"id":"3","text":"Feedback is the central function"},{"id":"4","text":"Periodic and formal with marks allocated"},{"id":"5","text":"Continuous and informal with no marks"}],"rightItems":[{"id":"A","text":"Formative"},{"id":"B","text":"Summative"},{"id":"C","text":"Placement"}],"correct_pairs":{"1":"A","2":"B","3":"A","4":"B","5":"A"},"explain":"Formative is assessment FOR learning, occurs during instruction, makes feedback central, and is continuous and informal with no marks. Summative occurs after instruction and is periodic and formal with marks. Placement is an entry exam and fits none of these."},{"id":"MSA13037","type":"matching","cat":"MT_lec13","q":"Match each learning domain to how it is assessed.","leftItems":[{"id":"1","text":"Knowledge"},{"id":"2","text":"Skills"},{"id":"3","text":"Attitudes"}],"rightItems":[{"id":"A","text":"Written paper-and-pencil tests"},{"id":"B","text":"Practical and clinical performance exams"},{"id":"C","text":"Observation and Likert scales"},{"id":"D","text":"Self and peer assessment"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Knowledge is assessed by written paper-and-pencil tests; skills by practical and clinical performance exams; attitudes, the hardest domain, by observation and Likert scales. Self and peer assessment are carriers, not a domain method."},{"id":"MSA13038","type":"multi","cat":"MT_lec13","q":"Which items are named as ways to assess learners?","options":["Portfolios","Workplace","OSCE","Norm-referencing"],"correct":[0,1,2],"explain":"The methods list includes portfolios, workplace-based assessment, and OSCE, alongside paper-and-pencil tests, MCQs, clinical exams, observations, rating scales, checklists, self- and peer-assessment, and OSPE. Norm-referencing is a comparison standard, not a method."},{"id":"MSA13039","type":"mcq","cat":"MT_lec13","q":"Effective feedback should focus on both strengths and what?","options":["Weaknesses","Grades","Rankings","Penalties"],"correct":0,"explain":"Effective feedback focuses on both strengths and weaknesses. Grades, rankings, and penalties are not the stated counterpart to strengths."},{"id":"MSA13040","type":"stepped","cat":"MT_lec13","q":"The five planning questions each target a different aspect.","steps":[{"id":"1","prompt":"Which question is answered by 'knowledge, skills, and attitudes'?","options":["What","How","Why","When","Who"],"correct":0},{"id":"2","prompt":"Besides What, which question is answered by 'written or performance-based methods'?","options":["What","How","Why","When","Who"],"correct":1},{"id":"3","prompt":"Besides How, which question is answered by 'Assessment of Learning versus Assessment for Learning'?","options":["What","How","Why","When","Who"],"correct":2},{"id":"4","prompt":"Besides Why, which question is answered by 'summative, ongoing, and formative timing'?","options":["What","How","Why","When","Who"],"correct":3},{"id":"5","prompt":"Besides When, which question is answered by 'school, national body, or self'?","options":["What","How","Why","When","Who"],"correct":4}],"explain":"Step 1: 'knowledge, skills, attitudes' answers What. Step 2: 'written or performance-based' answers How. Step 3: 'of-learning vs for-learning' answers Why. Step 4: 'summative, ongoing, formative' answers When. Step 5: 'school, national body, self' answers Who."},{"id":"MSA13041","type":"multi","cat":"MT_lec13","q":"Which are also functions of student assessment?","options":["Granting grades and upgrading","Aiding retention and transfer","Aiding student self-assessment","Aiding evaluation of instruction","Duplicating instruction"],"correct":[0,1,2,3],"explain":"Further functions are granting grades and upgrading, aiding retention and transfer, aiding self-assessment, and aiding evaluation of instructional effectiveness. Duplicating instruction is what placement avoids, not a function."},{"id":"MSA13042","type":"mcq","cat":"MT_lec13","q":"What is the only way to know whether students have learned?","options":["Assess them","Take attendance","Trust self-reports","Review the syllabus"],"correct":0,"explain":"The only way to know whether students learned is to assess them. Attendance, self-reports, and syllabus review do not prove learning."},{"id":"MSA13043","type":"mcq","cat":"MT_lec13","q":"Assessment is sometimes characterized as what?","options":["A necessary evil","An optional extra","A teaching substitute","A mere formality"],"correct":0,"explain":"Assessment is called a necessary evil. It is not optional, does not substitute for teaching, and is more than a formality."},{"id":"MSA13044","type":"stepped","cat":"MT_lec13","q":"Compare the two main functional assessment types in detail.","steps":[{"id":"1","prompt":"At which point does formative assessment occur?","options":["During instruction","After instruction","Before the course begins","Only at graduation"],"correct":0},{"id":"2","prompt":"During-instruction assessment is designed to give feedback mainly to do what?","options":["Identify areas for improvement","Certify competence for a grade","Grant the final course mark","Rank learners across the nation"],"correct":0},{"id":"3","prompt":"Besides giving feedback to identify improvement, during-instruction assessment checks understanding so the teacher can do what?","options":["Bridge the knowledge gaps","Award summative marks","Issue a completion certificate","Replace the entry exam"],"correct":0},{"id":"4","prompt":"After bridging knowledge gaps, which formats are used in this during-instruction type?","options":["Open- and closed-ended quizzes","Only extended long-case examinations","Only national licensing board papers","Only workplace-based portfolio logs"],"correct":0},{"id":"5","prompt":"Unlike the open- and closed-ended quizzes of the during-instruction type, the after-instruction type is called which phrase?","options":["Assessment Of Learning","Assessment For Learning","Assessment Against Learning","Assessment Without Learning"],"correct":0},{"id":"6","prompt":"Assessment Of Learning evaluates achievement at which point?","options":["End or middle of a unit","The very first week of all teaching","Each daily activity during class","Before any instruction is delivered"],"correct":0},{"id":"7","prompt":"After the end-or-middle evaluation, this type is composed of tasks covering what?","options":["Different domains of learning","Only rote cognitive recall","Only psychomotor skill drills","Only class attendance records"],"correct":0}],"explain":"Formative occurs during instruction, gives feedback to identify improvement, bridges knowledge gaps, and uses open- and closed-ended quizzes. Summative is Assessment Of Learning, set at the end or middle of a unit, and built from tasks covering different domains."},{"id":"MSA13045","type":"mcq","cat":"MT_lec13","q":"Besides a basis for improvement, feedback is also described as what?","options":["An educational tool","A necessary evil","A steering effect","An entry exam"],"correct":0,"explain":"Feedback is a very important educational tool. The necessary evil and the steering effect describe assessment itself, and an entry exam describes placement, not feedback."},{"id":"MSA13046","type":"mcq","cat":"MT_lec13","q":"With no student assessment, what is absent?","options":["Proof of learning","A necessary evil","A steering effect","An entry exam"],"correct":0,"explain":"Without assessment there is no proof that learning occurred. The necessary evil, the steering effect, and the entry exam are other lecture points, not the missing evidence."}]}},"banks/studyskills/lecture-14-critical-thinking.json":{"id":"ss-lec14-critical-thinking","subject":"Study Skills","subjectId":"study_skills","title":"Lecture 14 - Critical Thinking","formSize":38,"forms":["A"],"bank":{"A":[{"id":"SSPT214000","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"What is the way that the mind makes sense of the world?","options":["Thinking","Memorizing","Observing","Listening"],"correct":0,"explain":"Thinking is the way that the mind makes sense of the world."},{"id":"SSPT214001","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Thinking is classified as what kind of function?","options":["A higher cognitive function","A basic sensory function","A purely emotional function","A physical motor function"],"correct":0,"explain":"Thinking is a higher cognitive function."},{"id":"SSPT214002","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which type of thinking proceeds on the assumption that there is one single best solution to any problem?","options":["Convergent thinking","Divergent thinking","Creative thinking","Critical thinking"],"correct":0,"explain":"Convergent thinking assumes there is one single best solution to any problem."},{"id":"SSPT214003","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Convergent thinking assumes the solution can be arrived at on the basis of what?","options":["Existing knowledge","Future predictions","Emotional intuition","Random guessing"],"correct":0,"explain":"Convergent thinking assumes the solution can be arrived at on the basis of existing knowledge."},{"id":"SSPT214004","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which type of thinking is associated with the ability to create or construct something new, novel, or unusual?","options":["Divergent or creative thinking","Convergent or logical thinking","Critical or analytical thinking","Deductive or inductive reasoning"],"correct":0,"explain":"Divergent or creative thinking is associated with creating or constructing something new, novel, or unusual."},{"id":"SSPT214005","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Divergent thinking looks for new relationships and associations to do what?","options":["Describe and interpret the nature of things, events, and situations","Determine the single best solution to any complex problem based on existing knowledge","Judge information according to established personal, professional, or social rules","Separate a whole into its functional parts to discover relationships"],"correct":0,"explain":"Divergent thinking looks for new relationships and associations to describe and interpret the nature of things, events, and situations."},{"id":"SSPT214006","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"What does it mean to be critical of a text?","options":["Question the information and opinions in the text to evaluate or judge its worth overall","Criticize the author in an exclusively negative manner without evaluating the content","Accept all information and opinions as absolute truth without questioning","Ignore the opinions presented in the text and focus only on isolated facts"],"correct":0,"explain":"To be critical of a text means you question the information and opinions in the text to evaluate or judge its worth overall."},{"id":"SSPT214007","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Being critical does NOT mean what?","options":["Criticizing in an exclusively negative manner","Evaluating the overall worth of information","Questioning opinions presented in a text","Judging the general value of a text"],"correct":0,"explain":"To be critical does not mean to criticize in an exclusively negative manner."},{"id":"SSPT214008","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Critical thinking is described as what kind of process?","options":["A self-directed process","A teacher-directed process","A purely emotional process","A random cognitive process"],"correct":0,"explain":"Critical thinking is a self-directed process by which we take deliberate steps to think at the highest level of quality."},{"id":"SSPT214009","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"In critical thinking, deliberate steps are taken to think at what level?","options":["The highest level of quality","The most basic level of recall","The fastest level of processing","The most emotional level of response"],"correct":0,"explain":"Critical thinking involves taking deliberate steps to think at the highest level of quality."},{"id":"SSPT214010","type":"stepped","cat":"Lecture 14 - Critical Thinking","q":"Critical thinking involves identifying and analyzing problems. What else does it require?","steps":[{"id":"1","prompt":"After identifying and analyzing problems, what must a critical thinker do?","options":["Seek and evaluate relevant information","Ignore irrelevant information quickly","Accept the first solution available","Rely solely on existing knowledge"],"correct":0},{"id":"2","prompt":"After seeking and evaluating relevant information, what is the goal?","options":["Reach an appropriate conclusion","Reach a quick conclusion","Avoid making any conclusion","Accept existing conclusions"],"correct":0}],"explain":"Critical thinking is the ability to identify and analyze problems as well as seek and evaluate relevant information in order to reach an appropriate conclusion."},{"id":"SSPT214011","type":"stepped","cat":"Lecture 14 - Critical Thinking","q":"Why is critical thinking important for Health Professions Education Students?","steps":[{"id":"1","prompt":"What must Health Professions Education Students do?","options":["Make complex decisions","Memorize large volumes","Avoid asking questions","Rely on convergent thinking"],"correct":0},{"id":"2","prompt":"Besides making complex decisions, what else must they do?","options":["Adapt to new situations","Study in one location","Use fixed methods","Work independently only"],"correct":0},{"id":"3","prompt":"What ongoing requirement do they have?","options":["Continuously update knowledge and skills","Complete all coursework requirements as quickly as possible","Follow established clinical protocols without any deviation","Memorize textbook content verbatim for all future exams"],"correct":0}],"explain":"Health Professions Education Students must make complex decisions, adapt to new situations, and continuously update their knowledge and skills, making critical thinking integral."},{"id":"SSPT214012","type":"multi","cat":"Lecture 14 - Critical Thinking","q":"Which of the following are listed as critical thinking skills in the lecture?","options":["Analyzing","Applying Standards","Discriminating","Information Seeking","Memorizing verbatim"],"correct":[0,1,2,3],"explain":"The critical thinking skills listed are Analyzing, Applying Standards, Discriminating, Information Seeking, Logical Reasoning, and Predicting. Memorizing verbatim is not a critical thinking skill."},{"id":"SSPT214013","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which critical thinking skill involves separating or breaking a whole into parts to discover their nature, functional, and relationships?","options":["Analyzing","Applying Standards","Discriminating","Predicting"],"correct":0,"explain":"Analyzing involves separating or breaking a whole into parts to discover their nature, functional, and relationships."},{"id":"SSPT214014","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"The quotes 'I studied it piece by piece' and 'I sorted things out' are associated with which critical thinking skill?","options":["Analyzing","Applying Standards","Logical Reasoning","Predicting"],"correct":0,"explain":"These quotes are associated with Analyzing, which involves breaking a whole into parts."},{"id":"SSPT214015","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which critical thinking skill involves judging according to established personal, professional, or social rules or criteria?","options":["Applying Standards","Analyzing","Discriminating","Information Seeking"],"correct":0,"explain":"Applying Standards means judging according to established personal, professional, or social rules or criteria."},{"id":"SSPT214016","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which critical thinking skill involves recognizing differences and similarities among things or situations and distinguishing carefully as to category or rank?","options":["Discriminating","Analyzing","Predicting","Logical Reasoning"],"correct":0,"explain":"Discriminating involves recognizing differences and similarities among things or situations and distinguishing carefully as to category or rank."},{"id":"SSPT214017","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"The quotes 'I rank ordered the various...' and 'I grouped things together' are associated with which critical thinking skill?","options":["Discriminating","Analyzing","Applying Standards","Information Seeking"],"correct":0,"explain":"These quotes are associated with Discriminating, which involves distinguishing carefully as to category or rank."},{"id":"SSPT214018","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which critical thinking skill involves searching for evidence, facts, or knowledge by identifying relevant sources?","options":["Information Seeking","Logical Reasoning","Analyzing","Predicting"],"correct":0,"explain":"Information Seeking involves searching for evidence, facts, or knowledge by identifying relevant sources."},{"id":"SSPT214019","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Gathering objective, subjective, historical, and current data from relevant sources is part of which critical thinking skill?","options":["Information Seeking","Applying Standards","Discriminating","Logical Reasoning"],"correct":0,"explain":"Gathering objective, subjective, historical, and current data is part of Information Seeking."},{"id":"SSPT214020","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which critical thinking skill involves drawing inferences or conclusions that are supported in or justified by evidence?","options":["Logical Reasoning","Predicting","Analyzing","Information Seeking"],"correct":0,"explain":"Logical Reasoning involves drawing inferences or conclusions that are supported in or justified by evidence."},{"id":"SSPT214021","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"The quotes 'I deduced from the information that...' and 'My rationale for the conclusion was...' are associated with which critical thinking skill?","options":["Logical Reasoning","Predicting","Analyzing","Applying Standards"],"correct":0,"explain":"These quotes are associated with Logical Reasoning, which involves drawing inferences or conclusions supported by evidence."},{"id":"SSPT214022","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which critical thinking skill involves envisioning a plan and its consequences?","options":["Predicting","Analyzing","Discriminating","Information Seeking"],"correct":0,"explain":"Predicting involves envisioning a plan and its consequences."},{"id":"SSPT214023","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"The quotes 'I envisioned the outcome would be...' and 'I was prepared for...' are associated with which critical thinking skill?","options":["Predicting","Logical Reasoning","Applying Standards","Analyzing"],"correct":0,"explain":"These quotes are associated with Predicting, which involves envisioning a plan and its consequences."},{"id":"SSPT214024","type":"multi","cat":"Lecture 14 - Critical Thinking","q":"Which of the following are listed as barriers to thinking critically?","options":["Misunderstanding","Lack of detailed knowledge","Wanting to know the answers without having to ask questions","Gathering information from multiple sources"],"correct":[0,1,2],"explain":"The barriers listed are misunderstanding, lack of detailed knowledge, and wanting to know the answers without having to ask questions. Gathering information is a critical thinking practice, not a barrier."},{"id":"SSPT214025","type":"stepped","cat":"Lecture 14 - Critical Thinking","q":"Misunderstanding is a barrier to critical thinking. What causes it?","steps":[{"id":"1","prompt":"What differences can cause misunderstanding?","options":["Language or cultural differences","Age or gender differences","Educational level differences","Professional experience differences"],"correct":0},{"id":"2","prompt":"What lack can cause misunderstanding?","options":["Lack of awareness of the processes involved","Lack of sufficient study time allocated for the subject","Lack of intrinsic motivation to engage with the material","Lack of adequate physical resources or study materials"],"correct":0},{"id":"3","prompt":"What misconception causes misunderstanding?","options":["Thinking critical thinking means making negative comments","Thinking critical thinking requires verbatim memorization of facts","Thinking critical thinking is too difficult for most students","Thinking critical thinking is unnecessary for basic comprehension"],"correct":0}],"explain":"Misunderstanding can arise due to language or cultural differences, a lack of awareness of the processes involved, or a misunderstanding that critical thinking means making negative comments."},{"id":"SSPT214026","type":"stepped","cat":"Lecture 14 - Critical Thinking","q":"Lack of detailed knowledge is a barrier to critical thinking. What does this mean?","steps":[{"id":"1","prompt":"What type of knowledge is the problem?","options":["Superficial knowledge","Excessive knowledge","Outdated knowledge","Specialized knowledge"],"correct":0},{"id":"2","prompt":"What does superficial knowledge mean?","options":["Not having read deeply enough around the subject","Having read too much material without any real focus","Having memorized isolated facts without understanding context","Having practical experience only without theoretical background"],"correct":0}],"explain":"Lack of detailed knowledge refers to superficial knowledge, meaning not having read deeply enough around the subject."},{"id":"SSPT214027","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Critical thinking is aimed at achieving what in any situation?","options":["The best possible outcomes","The fastest possible conclusions","The most negative criticisms","The simplest possible solutions"],"correct":0,"explain":"Critical thinking is aimed at achieving the best possible outcomes in any situation."},{"id":"SSPT214028","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"To achieve the best possible outcomes, what must critical thinking involve?","options":["Gathering and evaluating information from as many different sources","Relying on a single authoritative source of information exclusively","Avoiding asking questions to save time and reach conclusions faster","Accepting superficial knowledge as sufficient for complex decision making"],"correct":0,"explain":"To achieve the best possible outcomes, critical thinking must involve gathering and evaluating information from as many different sources."},{"id":"SSPT214029","type":"matching","cat":"Lecture 14 - Critical Thinking","q":"Match each critical thinking skill to its description.","leftItems":[{"id":"1","text":"Analyzing"},{"id":"2","text":"Applying Standards"},{"id":"3","text":"Discriminating"},{"id":"4","text":"Information Seeking"},{"id":"5","text":"Logical Reasoning"},{"id":"6","text":"Predicting"}],"rightItems":[{"id":"A","text":"Separating or breaking a whole into parts"},{"id":"B","text":"Judging according to established rules or criteria"},{"id":"C","text":"Recognizing differences and similarities among things"},{"id":"D","text":"Searching for evidence and gathering data from sources"},{"id":"E","text":"Drawing inferences or conclusions supported by evidence"},{"id":"F","text":"Envisioning a plan and its consequences"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"},"explain":"Analyzing breaks a whole into parts. Applying Standards judges by rules. Discriminating recognizes differences. Information Seeking gathers data. Logical Reasoning draws supported inferences. Predicting envisions plans and consequences."},{"id":"SSPT214030","type":"stepped","cat":"Lecture 14 - Critical Thinking","q":"Identify the barriers to thinking critically.","steps":[{"id":"1","prompt":"Which barrier arises due to language or cultural differences, or a lack of awareness of the processes involved?","options":["Misunderstanding","Lack of detailed knowledge","Wanting answers without questions","Overanalyzing the text"],"correct":0},{"id":"2","prompt":"Which barrier refers to superficial knowledge, meaning not having read deeply enough around the subject?","options":["Lack of detailed knowledge","Misunderstanding","Wanting answers without questions","Gathering too much data"],"correct":0},{"id":"3","prompt":"Which barrier involves wanting to know the answers without doing what?","options":["Having to ask questions","Reading the textbook","Listening to lectures","Taking notes"],"correct":0}],"explain":"The three barriers are misunderstanding (due to language/culture or process awareness), lack of detailed knowledge (superficial reading), and wanting to know answers without asking questions."},{"id":"SSPT214031","type":"stepped","cat":"Lecture 14 - Critical Thinking","q":"Match the quotes to their critical thinking skills.","steps":[{"id":"1","prompt":"Which skill is associated with the quote: 'I studied it piece by piece'?","options":["Analyzing","Applying Standards","Discriminating","Predicting"],"correct":0},{"id":"2","prompt":"Which skill is associated with the quote: 'I judged it according to...'?","options":["Applying Standards","Analyzing","Logical Reasoning","Information Seeking"],"correct":0},{"id":"3","prompt":"Which skill is associated with the quote: 'I deduced from the information that...'?","options":["Logical Reasoning","Predicting","Discriminating","Analyzing"],"correct":0}],"explain":"'I studied it piece by piece' is Analyzing. 'I judged it according to...' is Applying Standards. 'I deduced from the information that...' is Logical Reasoning."},{"id":"SSPT214032","type":"matching","cat":"Lecture 14 - Critical Thinking","q":"Match each type of thinking to its definition.","leftItems":[{"id":"1","text":"Convergent thinking"},{"id":"2","text":"Divergent or Creative Thinking"},{"id":"3","text":"Critical Thinking"}],"rightItems":[{"id":"A","text":"Assumes one single best solution based on existing knowledge"},{"id":"B","text":"Ability to create or construct something new, novel, or unusual"},{"id":"C","text":"Self-directed process to think at the highest level of quality"}],"correct_pairs":{"1":"A","2":"B","3":"C"},"explain":"Convergent thinking assumes one best solution. Divergent thinking creates something new. Critical thinking is a self-directed process for high-quality thought."},{"id":"SSPT214033","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Understanding anything is possible only through which mental activity?","options":["Thinking","Analyzing","Predicting","Seeking"],"correct":0,"explain":"There is no way to understand anything except through thinking. Analyzing, predicting, and seeking are specific critical-thinking skills, not the universal way the mind understands."},{"id":"SSPT214034","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Critical thinking is described as the key to what?","options":["Resolving problems","Making negative comments","Avoiding questions","Envisioning plans"],"correct":0,"explain":"Critical thinking is the key to resolving problems. Making negative comments is a misunderstanding barrier; avoiding questions is a barrier; envisioning plans is the predicting skill."},{"id":"SSPT214035","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Critical thinking is integral to all of what?","options":["The student demands","The thinking barriers","The thinking skills","The thinking types"],"correct":0,"explain":"Critical thinking is integral to all the things health profession students must do: making complex decisions, adapting to new situations, and updating knowledge and skills. Barriers, skills, and types are other categories."},{"id":"SSPT214036","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Which skill matches 'I knew I needed to lookup/study...' and 'I kept searching for data.'?","options":["Information Seeking","Logical Reasoning","Predicting","Discriminating"],"correct":0,"explain":"These quotes match information seeking, which searches for evidence and data. Logical reasoning draws conclusions, predicting envisions plans, and discriminating ranks or groups."},{"id":"SSPT214037","type":"mcq","cat":"Lecture 14 - Critical Thinking","q":"Critical thinking is described as having what?","options":["Many skills to be practiced","Only one single best solution","No barriers to thinking critically","Exclusively negative comments to make"],"correct":0,"explain":"Critical thinking has many skills to be practiced. One best solution describes convergent thinking; barriers do exist; negative comments are a misunderstanding."}]}},"banks/studyskills/mixed-5-10.json":{"id":"mixed-studyskills-lec5-10","subject":"Study Skills","subjectId":"study_skills","title":"Mixed Study Skills – Lectures 5 to 10","formSize":46,"forms":["A"],"bank":{"A":[{"id":"SSPT2X000","type":"matching","cat":"SSPT2_5-10","q":"Match each adult learning principle to its application examples.","explain":"Principles 1-4 with their tips.","leftItems":[{"id":"1","text":"Adults are autonomous and self-directed"},{"id":"2","text":"Adults bring a wealth of background knowledge"},{"id":"3","text":"Adults are goal-oriented"},{"id":"4","text":"Adults are relevancy-oriented"}],"rightItems":[{"id":"A","text":"Take responsibility, set own goals, diagnose needs, manage time"},{"id":"B","text":"Let teachers know background, identify causal connections, associate with known"},{"id":"C","text":"Ask what to expect and how it meets goals, keep eyes on goals, verify achievement"},{"id":"D","text":"Ask how applied in future role, make connections to goals, commit to apply practically"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X001","type":"matching","cat":"SSPT2_5-10","q":"Match remaining adult learning principles to application examples.","explain":"Principles 5-8 with tips.","leftItems":[{"id":"1","text":"Adults are intrinsically and extrinsically motivated"},{"id":"2","text":"Adults learn best when active participants"},{"id":"3","text":"Adults learn more effectively with timely constructive feedback"},{"id":"4","text":"Adults have different learning preferences/styles"}],"rightItems":[{"id":"A","text":"Determine practical benefits, challenge self, do not just attune to assessment"},{"id":"B","text":"Engage in problem-solving, questioning, sharing; actively participate in groups; practice skills"},{"id":"C","text":"Seek feedback from teachers and peers; reflect on strengths/weaknesses for development"},{"id":"D","text":"Evaluate preferences, vary methods, medical students prefer multiple styles"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X002","type":"matching","cat":"SSPT2_5-10","q":"Match Forming stage elements.","explain":"Forming feelings, behaviors, tasks, tutor.","leftItems":[{"id":"1","text":"Feelings in Forming"},{"id":"2","text":"Behaviors in Forming"},{"id":"3","text":"Team Tasks in Forming"},{"id":"4","text":"Tutor in Forming"}],"rightItems":[{"id":"A","text":"Excited and eager, high positive expectations, some anxiety"},{"id":"B","text":"Lots of questions reflecting excitement and uncertainty"},{"id":"C","text":"Create team with clear structure, goals, and roles to build trust"},{"id":"D","text":"Setup guidelines, Directive"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X003","type":"matching","cat":"SSPT2_5-10","q":"Match Storming stage elements.","explain":"Storming feelings, behaviors, tasks, tutor.","leftItems":[{"id":"1","text":"Feelings in Storming"},{"id":"2","text":"Behaviors in Storming"},{"id":"3","text":"Team Tasks in Storming"},{"id":"4","text":"Tutor in Storming"}],"rightItems":[{"id":"A","text":"Frustration or anger with the team's progress or process"},{"id":"B","text":"Less polite, Disagreements"},{"id":"C","text":"Calling for the team to refocus on its goals; developing task-related and conflict management skills"},{"id":"D","text":"Manage conflict, Still Directive"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X004","type":"matching","cat":"SSPT2_5-10","q":"Match Norming stage elements.","explain":"Norming feelings, behaviors, tasks, tutor.","leftItems":[{"id":"1","text":"Feelings in Norming"},{"id":"2","text":"Behaviors in Norming"},{"id":"3","text":"Team Tasks in Norming"},{"id":"4","text":"Tutor in Norming"}],"rightItems":[{"id":"A","text":"Increasing acceptance of others; constructive criticism possible and welcomed"},{"id":"B","text":"More meaningful communication; refocus on ground rules and practices"},{"id":"C","text":"Increase in productivity; appropriate time for evaluation of processes and productivity"},{"id":"D","text":"Participative; help group move to perform stage"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X005","type":"matching","cat":"SSPT2_5-10","q":"Match Performing stage elements.","explain":"Performing feelings, behaviors, tasks.","leftItems":[{"id":"1","text":"Feelings in Performing"},{"id":"2","text":"Behaviors in Performing"},{"id":"3","text":"Team Tasks in Performing"}],"rightItems":[{"id":"A","text":"Satisfaction in progress; attached to the team as greater than the sum of its parts"},{"id":"B","text":"Can-do attitude; offers to assist; roles more fluid; differences appreciated"},{"id":"C","text":"Significant progress towards goals; accomplishments measured and celebrated"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X006","type":"matching","cat":"SSPT2_5-10","q":"Match definitions related to team and teamwork.","explain":"Key definitions.","leftItems":[{"id":"1","text":"What is a team?"},{"id":"2","text":"What is teamwork?"},{"id":"3","text":"Team vs group"}],"rightItems":[{"id":"A","text":"A group of people who work together cooperatively to achieve a common goal"},{"id":"B","text":"The ability to cooperate and communicate effectively with others to achieve a common goal"},{"id":"C","text":"A team is a group of individuals, but a group of individuals is not necessarily a team"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X007","type":"matching","cat":"SSPT2_5-10","q":"Match small group definition and importance.","explain":"Small group details.","leftItems":[{"id":"1","text":"Small Group definition"},{"id":"2","text":"Why important 1"},{"id":"3","text":"Why important 2"},{"id":"4","text":"Why important 3"}],"rightItems":[{"id":"A","text":"Group of eight to 12 learners facilitated by a teacher; learner-centered free discussion"},{"id":"B","text":"Developing positive and informed attitudes to collaborative work"},{"id":"C","text":"Developing skills in problem-solving, teamwork, evaluating and decision-making"},{"id":"D","text":"Providing opportunity for more active involvement"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X008","type":"matching","cat":"SSPT2_5-10","q":"Match independent learning process steps.","explain":"What students take increasing responsibility for.","leftItems":[{"id":"1","text":"1- Identify needs-to-know"},{"id":"2","text":"2- Search for information"},{"id":"3","text":"3- Learn with minimum supervision"},{"id":"4","text":"4- Solve own problems"},{"id":"5","text":"5- Assess own learning"}],"rightItems":[{"id":"A","text":"Identifying their own needs-to-know"},{"id":"B","text":"Searching for relevant information and gaining knowledge on their own"},{"id":"C","text":"Learning on their own with minimum supervision"},{"id":"D","text":"Actively seeking ways to solve their own problems and difficulties"},{"id":"E","text":"Assessing their own learning to see if needs-to-know are met"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"}},{"id":"SSPT2X009","type":"matching","cat":"SSPT2_5-10","q":"Match pedagogy and andragogy.","explain":"Definitions and etymology.","leftItems":[{"id":"1","text":"Pedagogy"},{"id":"2","text":"Andragogy"}],"rightItems":[{"id":"A","text":"Educating children; Ped (child) + agogos (lead) = Leading Children"},{"id":"B","text":"Helping adults learn; Andro (adult) + agogos (lead) = Leading Adults"}],"correct_pairs":{"1":"A","2":"B"}},{"id":"SSPT2X010","type":"matching","cat":"SSPT2_5-10","q":"Match study habit tips for deep processing.","explain":"Elaboration, layering, practice exams.","leftItems":[{"id":"1","text":"Use elaboration"},{"id":"2","text":"Organize by layering"},{"id":"3","text":"Use practice exams/questions"}],"rightItems":[{"id":"A","text":"Link to what you already know, reorganize with charts/outlines, vivid visualization, act out"},{"id":"B","text":"Learn major concepts first, then categories, then headings and sub-headings"},{"id":"C","text":"Use questions to show where you need to read more; look at right and wrong answers"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X011","type":"matching","cat":"SSPT2_5-10","q":"Match each SQ4R step to its purpose.","explain":"Survey gets the overview. Question turns headings into questions. Read looks for answers paragraph by paragraph. Record uses notetaking. Recite recalls from memory. Review consolidates later.","leftItems":[{"id":"1","text":"1- Survey"},{"id":"2","text":"2- Question"},{"id":"3","text":"3- Read"},{"id":"4","text":"4- Record"},{"id":"5","text":"5- Recite"},{"id":"6","text":"6- Review"}],"rightItems":[{"id":"A","text":"Skim headings, introduction, summary and visuals to get the big picture"},{"id":"B","text":"Turn headings into questions that guide reading"},{"id":"C","text":"Read the information one paragraph at a time while looking for answers"},{"id":"D","text":"Select a form of notetaking to record the information"},{"id":"E","text":"Close the book and recite the important information from memory in your own words"},{"id":"F","text":"Return to the material periodically to consolidate retention"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"}},{"id":"SSPT2X012","type":"matching","cat":"SSPT2_5-10","q":"Match note-taking phases detailed.","explain":"Before, during, after actions.","leftItems":[{"id":"1","text":"1- Before Class actions"},{"id":"2","text":"2- During Class actions"},{"id":"3","text":"3- After Class actions"}],"rightItems":[{"id":"A","text":"Read assigned material; review previous notes; sit near front center; new page; date each page and handouts"},{"id":"B","text":"Listen carefully for overview of main topics; maintain focus; not write every word; write supporting info, key points, definitions, examples"},{"id":"C","text":"Review new notes as soon as possible; rewrite if necessary; summarize main points"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X013","type":"matching","cat":"SSPT2_5-10","q":"Match each of the Five R's of Cornell notes to its action.","explain":"Record writes notes in the right column. Reduce writes cues in the left. Recite covers the right and recalls from the left. Reflect works with the information in new ways. Review uses immediate and ongoing review.","leftItems":[{"id":"1","text":"1- Record"},{"id":"2","text":"2- Reduce"},{"id":"3","text":"3- Recite"},{"id":"4","text":"4- Reflect"},{"id":"5","text":"5- Review"}],"rightItems":[{"id":"A","text":"Write headings and numbered notes in the right column"},{"id":"B","text":"Write key words and questions in the left recall column"},{"id":"C","text":"Cover the right column and recall from the left column"},{"id":"D","text":"Think about and work with the information in new ways"},{"id":"E","text":"Use immediate and ongoing review"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"}},{"id":"SSPT2X014","type":"matching","cat":"SSPT2_5-10","q":"Match five note-taking options with uses.","explain":"Systems and when to use.","leftItems":[{"id":"1","text":"Cornell"},{"id":"2","text":"Index Card"},{"id":"3","text":"Two-Column"},{"id":"4","text":"Three-Column"},{"id":"5","text":"Formal Outline"}],"rightItems":[{"id":"A","text":"Organizes notes with main points, details, study cues, and summary in one place"},{"id":"B","text":"For individual terms or concepts on cards"},{"id":"C","text":"Terms/questions left, notes right; for terms and definitions, questions and answers, formulas and examples"},{"id":"D","text":"Modified two-column; left terms/questions, middle and right two kinds of information; for math problem + steps + explanation"},{"id":"E","text":"Hierarchical structure; begin with main topic bullet, subtopics indented; for clear levels of information"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"}},{"id":"SSPT2X015","type":"matching","cat":"SSPT2_5-10","q":"Match encoding kinds with alternate names and what transmitted.","explain":"Four encodings.","leftItems":[{"id":"1","text":"Linguistic encoding"},{"id":"2","text":"Visual encoding"},{"id":"3","text":"Motor encoding"},{"id":"4","text":"Semantic encoding"}],"rightItems":[{"id":"A","text":"Transmits verbal information; also known as auditory coding"},{"id":"B","text":"Transmits visual, image information; also known as imaginal coding"},{"id":"C","text":"Transmits muscle memory information; also known as physical or kinesthetic coding"},{"id":"D","text":"Transmits emotional information, experiences and episodic memory"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X016","type":"matching","cat":"SSPT2_5-10","q":"Match notes on processing information into the memory system.","explain":"Schemas are saved in long-term memory when information is transferred into them. The rehearsal pathway moves information from short-term to long-term memory. The retrieval pathway regains information from long-term memory.","leftItems":[{"id":"1","text":"Schemas"},{"id":"2","text":"Rehearsal pathway"},{"id":"3","text":"Retrieval pathway"}],"rightItems":[{"id":"A","text":"Saved in long-term memory once information is transferred into them"},{"id":"B","text":"Moves information from short-term memory to long-term memory"},{"id":"C","text":"Regains information from long-term memory"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X017","type":"matching","cat":"SSPT2_5-10","q":"Match learning styles with how they remember best.","explain":"Visual, auditory, tactile tips.","leftItems":[{"id":"1","text":"Visual learners"},{"id":"2","text":"Auditory learners"},{"id":"3","text":"Tactile/kinesthetic learners"}],"rightItems":[{"id":"A","text":"Use notes, diagrams, color, printed materials, charts, study guides, images"},{"id":"B","text":"Remember best by listening and taking notes, review notes out loud, study partners teaching each other, consider taping"},{"id":"C","text":"Benefit by touch and feeling; create the notes, charts, hands-on activities, benefit by using manipulatives"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X018","type":"matching","cat":"SSPT2_5-10","q":"Match all 10 concentration tips with key actions.","explain":"Full list of tips.","leftItems":[{"id":"1","text":"1. Intend to Concentrate"},{"id":"2","text":"2. Prepare to Concentrate"},{"id":"3","text":"3. Use Concentration Promoting Activities"},{"id":"4","text":"4. Vary Your Study Activities"},{"id":"5","text":"5. Study in a Non-Distracting Environment"},{"id":"6","text":"6. Devise a Specific Study Plan"},{"id":"7","text":"7. Eat Regular Well Balanced Meals"},{"id":"8","text":"8. Get Plenty of Sleep at Night"},{"id":"9","text":"9. Set Daily, Weekly, Monthly, and Semester Goals"},{"id":"10","text":"10. Take Regular Study Breaks"}],"rightItems":[{"id":"A","text":"Specified time for study; consciously tell yourself “I will concentrate for ___ minutes”"},{"id":"B","text":"Have everything you need: texts, notes, pens, study guides"},{"id":"C","text":"Rewrite and organize notes; create diagrams, graphs, study guides; summarize the material"},{"id":"D","text":"If difficulty focusing on one subject long, vary the subjects you study"},{"id":"E","text":"Find one place, use that place only for studying; remove visual and auditory distractions"},{"id":"F","text":"Step-by-step plan makes it easier to concentrate; use a textbook reading strategy"},{"id":"G","text":"Students with healthier diets earn higher grades; avoid too much sugar and caffeine; don’t take stimulants"},{"id":"H","text":"Fighting off sleepiness negatively affects concentration"},{"id":"I","text":"Easier to concentrate and self-motivate when you see yourself moving toward your goals"},{"id":"J","text":"When concentration wanders, take five minutes break"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G","8":"H","9":"I","10":"J"}},{"id":"SSPT2X019","type":"matching","cat":"SSPT2_5-10","q":"Match comprehension definitions and importance.","explain":"What is comprehension and why important.","leftItems":[{"id":"1","text":"Comprehension is"},{"id":"2","text":"Comprehension is also"},{"id":"3","text":"Why important"},{"id":"4","text":"Main problem with comprehension"}],"rightItems":[{"id":"A","text":"The goal or purpose for reading; process of simultaneously extracting and constructing meaning through interaction with written language"},{"id":"B","text":"Understanding beyond knowing; not a product of reading but result of active engagement between reader and text"},{"id":"C","text":"Leads to better achievement; without it unable to fully understand the content"},{"id":"D","text":"Lack the strategies to actively engage with the text so that they can understand it"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X020","type":"matching","cat":"SSPT2_5-10","q":"Match essential strategies that improve comprehension.","explain":"Be patient and do not rush. Stay with a section until it is understood. Learn the terminology. Expand vocabulary. Understand the writer's perspective. Use elaborative rehearsal and active techniques. Become excited about the material.","leftItems":[{"id":"1","text":"Pace of reading"},{"id":"2","text":"Persistence with material"},{"id":"3","text":"Key terms"},{"id":"4","text":"Vocabulary growth"},{"id":"5","text":"Author perspective"},{"id":"6","text":"Active techniques"},{"id":"7","text":"Engagement with content"}],"rightItems":[{"id":"A","text":"Be patient and do not rush the reading process"},{"id":"B","text":"Stay with a paragraph or section until it is comprehended"},{"id":"C","text":"Learn the terminology"},{"id":"D","text":"Expand vocabulary"},{"id":"E","text":"Get into the writer's head"},{"id":"F","text":"Use elaborative rehearsal and active learning techniques while reading"},{"id":"G","text":"Become excited about what is learned"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G"}},{"id":"SSPT2X021","type":"matching","cat":"SSPT2_5-10","q":"Match main idea and topic sentence points.","explain":"Increasing comprehension paragraph by paragraph.","leftItems":[{"id":"1","text":"The topic"},{"id":"2","text":"The main idea"},{"id":"3","text":"The topic sentence"},{"id":"4","text":"Topic sentence like"},{"id":"5","text":"Most common location of topic sentence"},{"id":"6","text":"Next most common"},{"id":"7","text":"Least common"},{"id":"8","text":"Implied main ideas"}],"rightItems":[{"id":"A","text":"The subject of a paragraph; ask in one word or phrase what the paragraph is about"},{"id":"B","text":"Tells the main point the author intends to develop in the paragraph"},{"id":"C","text":"Expresses the main idea and usually includes the topic"},{"id":"D","text":"An umbrella broad enough to include supporting details"},{"id":"E","text":"The first sentence"},{"id":"F","text":"The last sentence"},{"id":"G","text":"In the middle of the paragraph"},{"id":"H","text":"Some paragraphs have implied main ideas; not directly stated in one sentence"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G","8":"H"}},{"id":"SSPT2X022","type":"matching","cat":"SSPT2_5-10","q":"Match seven organizational patterns.","explain":"Organizational patterns for comprehension.","leftItems":[{"id":"1","text":"1"},{"id":"2","text":"2"},{"id":"3","text":"3"},{"id":"4","text":"4"},{"id":"5","text":"5"},{"id":"6","text":"6"},{"id":"7","text":"7"}],"rightItems":[{"id":"A","text":"Chronological"},{"id":"B","text":"Process"},{"id":"C","text":"Comparison or contrast"},{"id":"D","text":"Definition"},{"id":"E","text":"Examples"},{"id":"F","text":"Cause/Effect"},{"id":"G","text":"Whole/Parts"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G"}},{"id":"SSPT2X023","type":"matching","cat":"SSPT2_5-10","q":"Match actions readers take to enhance comprehension.","explain":"Activate background knowledge and make connections. Ask questions before, during and after reading. Use awareness of purpose, text forms and features to decide reading rate.","leftItems":[{"id":"1","text":"Prior knowledge"},{"id":"2","text":"Questioning"},{"id":"3","text":"Purpose and text features"}],"rightItems":[{"id":"A","text":"Activate background knowledge and make associations or connections with the text"},{"id":"B","text":"Ask questions before, during and after reading"},{"id":"C","text":"Use awareness of purpose, text forms and features to decide reading rate"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X024","type":"matching","cat":"SSPT2_5-10","q":"Match pre-reading survey elements.","explain":"Pre-reading survey steps.","leftItems":[{"id":"1","text":"First thing in pre-reading survey"},{"id":"2","text":"Chapter title and subtitles"},{"id":"3","text":"Focus questions"},{"id":"4","text":"Chapter introductions and first paragraphs"},{"id":"5","text":"Last paragraph or summary"},{"id":"6","text":"End-of-chapter material"}],"rightItems":[{"id":"A","text":"Read the introduction and review the table of contents"},{"id":"B","text":"Provide overall idea of the topic and reading direction and focus"},{"id":"C","text":"Help provide focus and indicate what to look for"},{"id":"D","text":"First paragraph usually provides an introduction to what the chapter will be about"},{"id":"E","text":"Provides a condensed explanation of what the chapter was about including most important take away"},{"id":"F","text":"Study questions or other study materials to get better idea of important ideas"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"}},{"id":"SSPT2X025","type":"matching","cat":"SSPT2_5-10","q":"Match post-reading review actions.","explain":"Take notes or highlight important concepts. Identify what has been learned and what still needs more review.","leftItems":[{"id":"1","text":"During reading review"},{"id":"2","text":"After reading review"}],"rightItems":[{"id":"A","text":"Take notes or highlight important concepts"},{"id":"B","text":"Identify what has been learned and the important take-aways; also identify what is still not fully understood"}],"correct_pairs":{"1":"A","2":"B"}},{"id":"SSPT2X026","type":"matching","cat":"SSPT2_5-10","q":"Match study atmosphere tips.","explain":"Know where you learn best.","leftItems":[{"id":"1","text":"Silence or noise"},{"id":"2","text":"Same place or variety"},{"id":"3","text":"Position"},{"id":"4","text":"Avoid bed"}],"rightItems":[{"id":"A","text":"Absolute silence or a bit of noise"},{"id":"B","text":"Same place every day or variety helps"},{"id":"C","text":"Sitting at a desk, on the couch, walking around, writing on large white board"},{"id":"D","text":"Try not to use your bed for studying so you can connect it only with relaxation"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X027","type":"matching","cat":"SSPT2_5-10","q":"Match the checklist before beginning to study.","explain":"Have a plan, eat, take a break, manage caffeine, and drink water.","leftItems":[{"id":"1","text":"1- Planning"},{"id":"2","text":"2- Nutrition"},{"id":"3","text":"3- Rest interval"},{"id":"4","text":"4- Stimulant management"},{"id":"5","text":"5- Fluid intake"}],"rightItems":[{"id":"A","text":"Have a plan"},{"id":"B","text":"Eat"},{"id":"C","text":"Take a break"},{"id":"D","text":"Manage caffeine intake"},{"id":"E","text":"Drink water"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"}},{"id":"SSPT2X028","type":"matching","cat":"SSPT2_5-10","q":"Match different forms of small groups.","explain":"PBL classes, field training, clinical rounds, and research projects.","leftItems":[{"id":"1","text":"Problem-based learning stands for"},{"id":"2","text":"Practical placement"},{"id":"3","text":"Ward-based teaching"},{"id":"4","text":"Investigative work"}],"rightItems":[{"id":"A","text":"Groups in PBL (Problem Based Learning) classes"},{"id":"B","text":"Field training"},{"id":"C","text":"Clinical rounds"},{"id":"D","text":"Research projects"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X029","type":"matching","cat":"SSPT2_5-10","q":"Match sample ground rules for small-group sessions.","explain":"Start and finish on time, come prepared, listen and understand each other, and share responsibility for the process and aims.","leftItems":[{"id":"1","text":"Punctuality"},{"id":"2","text":"Preparation"},{"id":"3","text":"Mutual understanding"},{"id":"4","text":"Shared duty"}],"rightItems":[{"id":"A","text":"Start and finish on time"},{"id":"B","text":"Come prepared for the discussion"},{"id":"C","text":"The shared aim is to listen and understand each other"},{"id":"D","text":"Everyone has some responsibility for the process and the achievement of group aims"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X030","type":"matching","cat":"SSPT2_5-10","q":"Match IL is / isn’t.","explain":"Independent learning is and isn’t.","leftItems":[{"id":"1","text":"IL isn’t"},{"id":"2","text":"IL is"}],"rightItems":[{"id":"A","text":"Simply abandoning responsibility for learning entirely on the students"},{"id":"B","text":"Supporting students to learn increasingly on their own"}],"correct_pairs":{"1":"A","2":"B"}},{"id":"SSPT2X031","type":"matching","cat":"SSPT2_5-10","q":"Match each step in processing information into the memory system to its role.","explain":"Sensory input receives stimuli. Short-term memory has limited capacity. Rehearsal path transfers information via learning and practice. Feedback loop uses self-quizzing. Long-term memory holds schemas with unlimited capacity. Retrieval path regains information for output.","leftItems":[{"id":"1","text":"Sensory Input"},{"id":"2","text":"Short-Term Memory"},{"id":"3","text":"Rehearsal Path"},{"id":"4","text":"Feedback Loop"},{"id":"5","text":"Long-Term Memory"},{"id":"6","text":"Long-Term Memory Retrieval Path"}],"rightItems":[{"id":"A","text":"Receives sensory stimuli"},{"id":"B","text":"Temporary store with limited capacity"},{"id":"C","text":"Learning and practice path that transfers information"},{"id":"D","text":"Self-quizzing that strengthens storage"},{"id":"E","text":"Stores schemas with unlimited capacity and imprinting"},{"id":"F","text":"Review path that regains information for outcomes"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F"}},{"id":"SSPT2X032","type":"matching","cat":"SSPT2_5-10","q":"Match additional elements in the memory processing system.","explain":"Inactive path does not lead to storage. Trap door allows exit from short-term memory without transfer. Output produces outcomes. Schemas are the structures saved in long-term memory.","leftItems":[{"id":"1","text":"Inactive path"},{"id":"2","text":"Trap door"},{"id":"3","text":"Output"},{"id":"4","text":"Schemas"}],"rightItems":[{"id":"A","text":"Path that does not lead to long-term storage"},{"id":"B","text":"Exit from short-term memory without transfer"},{"id":"C","text":"Produces outcomes after retrieval"},{"id":"D","text":"Structures in which transferred information is saved in long-term memory"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X033","type":"matching","cat":"SSPT2_5-10","q":"Match the notes on processing information into the memory system.","explain":"Transferring information into schemas saves it in long-term memory. The rehearsal pathway moves information from short-term to long-term memory. The retrieval pathway regains information from long-term memory.","leftItems":[{"id":"1","text":"Information transferred into schemas"},{"id":"2","text":"Rehearsal pathway"},{"id":"3","text":"Retrieval pathway"}],"rightItems":[{"id":"A","text":"Saved in long-term memory"},{"id":"B","text":"Transfers information from short-term to long-term memory"},{"id":"C","text":"Regains information from the long-term memory"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X034","type":"matching","cat":"SSPT2_5-10","q":"Match elaboration techniques used for deep processing of information.","explain":"Techniques to make information meaningful and memorable.","leftItems":[{"id":"1","text":"Connect to prior knowledge"},{"id":"2","text":"Reorganize with visual tools"},{"id":"3","text":"Create mental pictures"},{"id":"4","text":"Role-play the use"}],"rightItems":[{"id":"A","text":"Link new information to what is already known so it becomes meaningful"},{"id":"B","text":"Reorganize using charts, outlines or diagrams"},{"id":"C","text":"Use vivid visualization of the content"},{"id":"D","text":"Act out a situation in which the information would be needed"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X035","type":"matching","cat":"SSPT2_5-10","q":"Match the steps of studying by layering.","explain":"Order of learning from broad to specific.","leftItems":[{"id":"1","text":"1- Start with overarching ideas"},{"id":"2","text":"2- Move to major groupings"},{"id":"3","text":"3- Finish with finer structure"}],"rightItems":[{"id":"A","text":"Learn the major, overarching concepts first"},{"id":"B","text":"Then learn the big categories under those major concepts"},{"id":"C","text":"Follow up with the major headings, sub-headings, etc."}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X036","type":"matching","cat":"SSPT2_5-10","q":"Match how practice exams should guide studying.","explain":"Using practice questions before the exam night.","leftItems":[{"id":"1","text":"Timing of use"},{"id":"2","text":"What the results reveal"},{"id":"3","text":"What to examine carefully"}],"rightItems":[{"id":"A","text":"Use them to guide studying rather than saving them until the night before"},{"id":"B","text":"They show where more reading or watching is needed"},{"id":"C","text":"Examine both correct and incorrect answers for clues about important points"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X037","type":"matching","cat":"SSPT2_5-10","q":"Match advice on highlighting while reading.","explain":"Avoid mindless highlighting.","leftItems":[{"id":"1","text":"Preferred timing"},{"id":"2","text":"Risk of highlighting too early"},{"id":"3","text":"Post-section action"}],"rightItems":[{"id":"A","text":"Highlight only after finishing a paragraph or section"},{"id":"B","text":"Highlighting while reading easily becomes mindless"},{"id":"C","text":"Pause to identify the most important information, then go back and highlight it; also generate possible exam questions"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X038","type":"matching","cat":"SSPT2_5-10","q":"Match the role of formulating questions during reading.","explain":"Active reading through self-generated questions.","leftItems":[{"id":"1","text":"Main benefit"},{"id":"2","text":"Memory effect"},{"id":"3","text":"When questions are written"}],"rightItems":[{"id":"A","text":"Gives purpose, raises curiosity, improves comprehension and keeps focus"},{"id":"B","text":"The questions together with their answers become memory cues for later recall"},{"id":"C","text":"Write them before reading, while reading, and after reading"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X039","type":"matching","cat":"SSPT2_5-10","q":"Match situations suited to two-column notes.","explain":"Typical pairings used in two-column format.","leftItems":[{"id":"1","text":"Vocabulary items"},{"id":"2","text":"Self-testing prompts"},{"id":"3","text":"Worked problems"},{"id":"4","text":"Grouped content"},{"id":"5","text":"Core ideas with support"}],"rightItems":[{"id":"A","text":"Terms paired with their definitions"},{"id":"B","text":"Questions paired with their answers"},{"id":"C","text":"Formulas, steps or equations paired with worked examples"},{"id":"D","text":"A category paired with the list of items that belong to it"},{"id":"E","text":"Main concepts paired with facts, explanations or examples"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E"}},{"id":"SSPT2X040","type":"matching","cat":"SSPT2_5-10","q":"Match situations suited to three-column notes.","explain":"Typical three-part layouts.","leftItems":[{"id":"1","text":"Mathematical work"},{"id":"2","text":"Cross-source topic"},{"id":"3","text":"Concept with application"}],"rightItems":[{"id":"A","text":"A math problem, the steps needed to solve it, and the explanation or rule"},{"id":"B","text":"A topic or concept, the textbook information, and the lecture information"},{"id":"C","text":"A topic or concept, its definition or description, and its applications or details"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X041","type":"matching","cat":"SSPT2_5-10","q":"Match steps for building a formal outline.","explain":"How to structure notes in outline form.","leftItems":[{"id":"1","text":"1- Opening entry"},{"id":"2","text":"2- Next level down"},{"id":"3","text":"3- Supporting details"}],"rightItems":[{"id":"A","text":"Start with a single bullet and write the main topic"},{"id":"B","text":"Place the first subtopic below it, indented slightly to the right"},{"id":"C","text":"List any details under the heading, indented further to the right"}],"correct_pairs":{"1":"A","2":"B","3":"C"}},{"id":"SSPT2X042","type":"matching","cat":"SSPT2_5-10","q":"Match the process of studying from a formal outline.","explain":"Active review using an outline.","leftItems":[{"id":"1","text":"1- Initial pass"},{"id":"2","text":"2- Verification step"},{"id":"3","text":"3- Enhancement step"},{"id":"4","text":"4- Repetition"}],"rightItems":[{"id":"A","text":"Read one line or item at a time and explain it by reciting"},{"id":"B","text":"Check whether the recitation was accurate and complete"},{"id":"C","text":"Add clue words to the right of the lines or items"},{"id":"D","text":"Repeat the recitation process from the outline"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D"}},{"id":"SSPT2X043","type":"matching","cat":"SSPT2_5-10","q":"Match what active listening requires.","explain":"Nature of listening during lectures.","leftItems":[{"id":"1","text":"Character of the process"},{"id":"2","text":"Memory demand"}],"rightItems":[{"id":"A","text":"An active process that engages multiple mental activities"},{"id":"B","text":"Holding verbal stimuli in working memory long enough to attach meaning and interpret what is said"}],"correct_pairs":{"1":"A","2":"B"}},{"id":"SSPT2X044","type":"matching","cat":"SSPT2_5-10","q":"Match strategies for effective textbook reading.","explain":"Approaches that improve understanding and retention of textbook material.","leftItems":[{"id":"1","text":"Starting mindset"},{"id":"2","text":"Overall method"},{"id":"3","text":"Questioning attitude"},{"id":"4","text":"Connection to existing knowledge"},{"id":"5","text":"Time control"},{"id":"6","text":"Spacing of reviews"},{"id":"7","text":"Feedback element"},{"id":"8","text":"Encoding step"}],"rightItems":[{"id":"A","text":"Begin with a clear intention to understand what is read"},{"id":"B","text":"Use an organized system for reading textbook chapters"},{"id":"C","text":"Remain inquisitive throughout"},{"id":"D","text":"Relate new information to existing schemas in long-term memory"},{"id":"E","text":"Manage textbook reading time effectively"},{"id":"F","text":"Use spaced practice or spaced studying"},{"id":"G","text":"Include some form of feedback while studying"},{"id":"H","text":"Encode ordinary words into new sensory codes"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G","8":"H"}},{"id":"SSPT2X045","type":"matching","cat":"SSPT2_5-10","q":"Match advice specific to reading science textbooks.","explain":"Recommended sequence and actions for science material.","leftItems":[{"id":"1","text":"Opening approach"},{"id":"2","text":"Follow-up approach"},{"id":"3","text":"Examples"},{"id":"4","text":"Terminology"},{"id":"5","text":"Memory aids"},{"id":"6","text":"Verbal practice"},{"id":"7","text":"Visuals"},{"id":"8","text":"Broader links"}],"rightItems":[{"id":"A","text":"Begin with overview reading"},{"id":"B","text":"Then move to thorough reading"},{"id":"C","text":"Read and examine the examples carefully"},{"id":"D","text":"Memorize terminology and be able to define the terms"},{"id":"E","text":"Create mental images that serve as memory cues"},{"id":"F","text":"Explain the information by reciting it"},{"id":"G","text":"Study diagrams and charts carefully"},{"id":"H","text":"Associate the information to larger concepts and schemas"}],"correct_pairs":{"1":"A","2":"B","3":"C","4":"D","5":"E","6":"F","7":"G","8":"H"}}]}}};
